window.__gnCourses.A1 = {"level":"A1","name":"Acceso","units":[{"n":1,"gn":"Mba'éichapa","es":"Saludos y sonidos","days":[{"title":"Saludar y despedirse","grammar":{"points":[{"id":"a1u01d1.p1","form":"Mba'éichapa? · Iporã","gloss":"¿Cómo estás? · Bien","connect":[{"pos":"Al llegar: es saludo y pregunta a la vez","rule":"{Mba'éichapa}?"},{"pos":"Con reiko, «¿cómo andás?»","rule":"{Mba'éichapa} reiko?"},{"pos":"Para responder y devolver la pregunta","rule":"{Iporã}, ha nde?"}],"examples":[{"gn":"Rosa: {Mba'éichapa}, Juan?\nJuan: {Iporã}, ha nde?","es":"Rosa: Hola, Juan, ¿cómo estás?\nJuan: Bien, ¿y vos?","parts":[["mba'e","qué"],["-icha","como"],["-pa","pregunta"],["iporã","bien"],["ha","y"],["nde","vos"]]},{"gn":"{Mba'éichapa} reiko, Ana?","es":"¿Cómo andás, Ana?","parts":[["mba'éichapa","¿cómo?"],["reiko","(vos) estás, andás"]]}],"watch":{"note":"Mba'éichapa lleva tilde en la é, porque el acento va ahí. Sin la tilde, el acento iría en la última vocal.","bad":"Mba'eichapa?","good":"Mba'éichapa?"}},{"id":"a1u01d1.p2","form":"Jajotopáta","gloss":"Nos vemos","connect":[{"pos":"Al irte, a cualquier hora","rule":"{Jajotopáta}"},{"pos":"Para decir cuándo: ko pyhare, «esta noche»","rule":"{Jajotopáta} ko pyhare"},{"pos":"Para responder a una despedida","rule":"{Jajotopáta}, Rosa."}],"examples":[{"gn":"{Jajotopáta}, Rosa.","es":"Nos vemos, Rosa.","parts":[["ja-","nosotros (con vos)"],["jo-","uno al otro"],["topa","encontrar"],["-ta","futuro"]]},{"gn":"{Jajotopáta} ko ka'aru.","es":"Nos vemos esta tarde.","parts":[["jajotopáta","nos vemos"],["ko","esta"],["ka'aru","tarde"]]}],"watch":{"note":"La -ta del final no se lleva el acento: queda en la a de topa. Como ya no es la última vocal, se escribe: topáta.","bad":"Jajotopata","good":"Jajotopáta"}}],"compare":{"intro":"Tres frases del primer día: una para llegar, otra para responder y otra para irte.","forms":[{"form":"Mba'éichapa?","tag":"Saludo · al llegar","mark":"dot","gn":"{Mba'éichapa}, Rosa?","es":"Hola, Rosa, ¿cómo estás?"},{"form":"Iporã, ha nde?","tag":"Respuesta · bien, ¿y vos?","mark":"dot","gn":"{Iporã}, ha nde?","es":"Bien, ¿y vos?"},{"form":"Jajotopáta","tag":"Despedida · al irte","mark":"dot","gn":"{Jajotopáta}, Rosa.","es":"Nos vemos, Rosa."}],"check":{"id":"a1u01d1.c1","kind":"choice","area":"grammar","label":"Elegí la frase","q":"(^Llegás^ a la ronda de tereré.)\nVos: (   )","options":["Jajotopáta, Rosa.","Mba'éichapa, Rosa?","Iporã, ha nde?"],"answer":2,"why":["Jajotopáta es para irte, y recién llegás.","Llegás, así que saludás: Mba'éichapa, Rosa?","Iporã, ha nde? responde a un saludo, y nadie te preguntó nada todavía."]}},"drill":[{"id":"a1u01d1.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: ^Mba'éichapa^, Juan?\nJuan: (   ), ha nde?","options":["Iporã","Jajotopáta","Reiko","Mba'éichapa"],"answer":1,"why":["Rosa pregunta cómo está Juan, y él responde Iporã, «bien». Después le devuelve la pregunta: ha nde?","Jajotopáta es para despedirse, y Rosa recién saluda.","reiko es «andás», hablando de vos, como en Mba'éichapa reiko? Juan tiene que decir cómo está él: Iporã.","Mba'éichapa es la pregunta de Rosa. Juan tiene que responderla: Iporã."]},{"id":"a1u01d1.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Mba'éichapa reiko?\nJuan: Iporã, ha (   )?\nRosa: ^Iporã^.","options":["che","pa","nde","maitei"],"answer":3,"why":["che es «yo». Juan ya dijo cómo está; ahora pregunta por Rosa, y ella responde.","-pa marca la pregunta, pero va pegada a una palabra, como en Mba'éichapa. Sola no pregunta nada.","ha nde? es «¿y vos?»: Juan le devuelve la pregunta a Rosa, y ella responde Iporã.","maitei es un saludo, «hola». Con maitei, Juan no pregunta por Rosa."]},{"id":"a1u01d1.d3","kind":"choice","area":"grammar","label":"Elegí la frase","q":"(Juan ^se va^ de la ronda.)\nJuan: (   )","options":["Mba'éichapa reiko?","Jajotopáta, Rosa.","Iporã, ha nde?","Mba'éichapa, Rosa?"],"answer":2,"why":["Mba'éichapa reiko? pregunta cómo está alguien. Se dice al llegar, no al irse.","Juan se va, así que se despide: Jajotopáta, «nos vemos».","Iporã, ha nde? responde a un saludo, y nadie le preguntó nada a Juan.","Mba'éichapa es para saludar al llegar, y Juan se va."]},{"id":"a1u01d1.d4","kind":"choice","area":"grammar","label":"Elegí la palabra","q":"(Rosa se va. Ella y Juan se vuelven a ver ^esta tarde^.)\nRosa: Jajotopáta ko (   ), Juan.","options":["pyhare","nde","pyhareve","ka'aru"],"answer":4,"why":["ko pyhare es «esta noche», y se vuelven a ver a la tarde.","nde es «vos», como en ha nde? No dice cuándo se van a ver.","pyhareve es «la mañana»: ko pyhareve sería «esta mañana». Y se vuelven a ver a la tarde.","Se vuelven a ver a la tarde: ko ka'aru. Jajotopáta ko ka'aru es «nos vemos esta tarde»."]},{"id":"a1u01d1.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" reiko?","tiles":["mba'e","icha","pa"],"bank":[2,0,1],"hint":"-icha y -pa son sufijos: van después de mba'e. ¿Cuál cierra la pregunta?","full":"Mba'éicha{pa} reiko?","es":"¿Cómo andás?","explain":"mba'e («qué») + -icha («como») + -pa (pregunta) = Mba'éichapa. Ni -icha ni -pa se llevan el acento: queda en la e de mba'e. Como ya no es la última vocal, se escribe é."},{"id":"a1u01d1.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" ko ka'aru, Rosa.","tiles":["ja","jo","topáta"],"bank":[1,2,0],"hint":"ja- y jo- son prefijos: van antes de topáta. ¿Cuál va primero?","full":"{Jajo}topáta ko ka'aru, Rosa.","es":"Nos vemos esta tarde, Rosa.","explain":"ja- («nosotros», con vos) + jo- («uno al otro») + topáta (topa, «encontrar», con -ta, el futuro) = Jajotopáta. Con ko ka'aru, «esta tarde», queda «nos vemos esta tarde»."}],"exam":[{"id":"a1u01d1.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: Mba'éichapa reiko?\nJuan: _Iporã, ha nde?_","options":["Hola, ¿cómo estás?","Nos vemos, ¿y vos?","Bien, ¿y vos?","Bien, ¿y yo?"],"answer":3,"explain":"Lo subrayado es la respuesta de Juan. Iporã es «bien», y ha nde? le devuelve la pregunta a Rosa: «¿y vos?». «Hola, ¿cómo estás?» es lo que dijo Rosa, «nos vemos» sería Jajotopáta, y «¿y yo?» no va, porque nde es «vos»."},{"id":"a1u01d1.e2","kind":"choice","area":"grammar","label":"Qué significa","q":"(Rosa se va de la casa de Juan.)\nRosa: _Jajotopáta ko pyhare_, Juan.","options":["Nos vemos esta noche, Juan.","Nos vimos anoche, Juan.","Buenas noches, Juan, ¿cómo estás?","Nos vemos esta tarde, Juan."],"answer":1,"explain":"Jajotopáta es «nos vemos»: la -ta habla de lo que va a pasar, no de anoche. Ko pyhare es «esta noche»; «esta tarde» sería ko ka'aru. Y Rosa se va, así que no saluda: se despide."},{"id":"a1u01d1.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana se va de la ronda.)\nAna: ","after":", Juan.","tiles":["ja","jo","topáta"],"bank":[2,1,0],"full":"(Ana se va de la ronda.)\nAna: Jajotopáta, Juan.","es":"Ana: Nos vemos, Juan.","explain":"ja- («nosotros», con vos) va primero y después jo- («uno al otro»). Al final va topáta: topa («encontrar») con -ta, el futuro. Todo junto: Jajotopáta, «nos vemos»."}]},"words":{"es":"La ronda de tereré","intro":"En el patio, la familia toma tereré. Tocá cada palabra: saludos, despedidas, momentos del día y personas.","sound":{"focus":"Las vocales orales","letters":["a","e","i","o","u","y"],"note":"a, e, i, o, u suenan como en castellano, y la y es la sexta vocal: decí i con la lengua hacia atrás, como para u. Sin tilde (é) ni tilde nasal (~), el acento va en la última vocal: terere suena como el tereré del castellano, que sí necesita tilde. Si va antes, en una vocal oral, se escribe la tilde: Mba'éichapa, jarýi.","pairs":[["ka'a","yerba","ka'i","mono"],["pira","pez","pire","piel"],["pire","piel","piru","flaco"],["po","mano","py","pie"]]},"words":[{"id":"maitei","gn":"Maitei","es":"Hola, saludos","note":"Un saludo cordial."},{"id":"mbaeichapa","gn":"Mba'éichapa?","es":"Hola, ¿cómo estás?","parts":[["mba'e","qué"],["-icha","como"],["-pa","pregunta"]],"note":"Mucha gente también saluda en castellano, con «¿Qué tal?»."},{"id":"ipora","gn":"Iporã","es":"Bien","note":"Muy bien: Iporãiterei."},{"id":"jajotopata","gn":"Jajotopáta","es":"Nos vemos","parts":[["ja-","nosotros (con vos)"],["jo-","uno al otro"],["topa","encontrar"],["-ta","futuro"]],"note":"Palabra por palabra: «nos vamos a encontrar»."},{"id":"pyhareve","gn":"pyhareve","es":"la mañana","note":"Mba'éichapa nde pyhareve? es «buen día». Ojo: pyhare es «la noche»."},{"id":"kaaru","gn":"ka'aru","es":"la tarde","note":"Mba'éichapa nde ka'aru? es «buenas tardes»."},{"id":"jaryi","gn":"jarýi","es":"abuela","note":"Lleva tilde: el acento va en la ý, no en la última vocal."},{"id":"karai","gn":"karai","es":"señor","note":"Para una señora: kuñakarai."}],"spell":["mbaeichapa","jajotopata","pyhareve","jaryi"],"check":{"id":"a1u01d1.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"A la mañana, saludás: Mba'éichapa nde (   )?","options":["pihareve","pyharebe","piharebe","pyhareve"],"answer":4,"explain":"Se escribe pyhareve. La primera vocal es la y, la sexta vocal: pihareve y piharebe la cambian por i. Y la b sola no es una letra del guaraní: acá va v."}},"skill":{"kind":"listening","es":"Respuesta rápida","situation":"En la parada del colectivo, una vecina saluda a un hombre.","ask":"¿Cuál es la mejor respuesta?","item":{"id":"a1u01d1.r1","kind":"choice","area":"listening","label":"Respuesta rápida","q":"¿Cuál es la mejor respuesta?","options":["Iporã, ha nde?","Jajotopáta ko ka'aru.","Iporã, ha che?"],"answer":1,"why":["Ella pregunta cómo está. Él responde Iporã, «bien», y le devuelve la pregunta: ha nde?, «¿y vos?».","Jajotopáta ko ka'aru es «nos vemos esta tarde»: sirve para irse, no para responder a un saludo.","ha che? es «¿y yo?»: así no le devuelve la pregunta a la vecina. Para eso va ha nde?, «¿y vos?»."],"script":["Narrador: En la parada del colectivo. ¿Qué responde el hombre?","Mujer: Mba'éichapa reiko?","Narrador: 1","Hombre: Iporã, ha nde?","Narrador: 2","Hombre: Jajotopáta ko ka'aru.","Narrador: 3","Hombre: Iporã, ha che?"]},"audio":[["N","En la parada del colectivo. ¿Qué responde el hombre?","En la parada del colectivo. ¿Qué responde el hombre?"],["F","Mba'éichapa reiko?","¿Cómo andás?"],["N","1","1"],["M","Iporã, ha nde?","Bien, ¿y vos?"],["N","2","2"],["M","Jajotopáta ko ka'aru.","Nos vemos esta tarde."],["N","3","3"],["M","Iporã, ha che?","Bien, ¿y yo?"]]}},{"title":"Pronombres: ñande y ore","grammar":{"points":[{"id":"a1u01d2.p1","form":"che · nde · ha'e","gloss":"yo · vos · él, ella","connect":[{"pos":"Yo, el que habla","rule":"{che} añe'ẽ"},{"pos":"Vos, el que escucha","rule":"{nde} reñe'ẽ"},{"pos":"Él o ella, otra persona","rule":"{ha'e} oñe'ẽ"},{"pos":"Sin pronombre, como en castellano: el verbo ya dice quién","rule":"{a}ñe'ẽ guaraníme"}],"examples":[{"gn":"{Che} añe'ẽ guaraníme.","es":"Yo hablo guaraní.","parts":[["che","yo"],["a-","yo"],["ñe'ẽ","hablar"],["guarani","guaraní"],["-me","en"]]},{"gn":"Iporã, ha {nde}?","es":"Bien, ¿y vos?","parts":[["iporã","bien"],["ha","y"],["nde","vos"]]},{"gn":"{Ha'e} oñe'ẽ guaraníme.","es":"Él (o ella) habla guaraní.","parts":[["ha'e","él, ella"],["o-","él, ella"],["ñe'ẽ","hablar"],["guarani","guaraní"],["-me","en"]]}],"watch":{"note":"El verbo también cambia con la persona. Con che, este verbo empieza con a-: añe'ẽ. Oñe'ẽ es la forma de ha'e.","bad":"Che oñe'ẽ guaraníme.","good":"Che añe'ẽ guaraníme."}},{"id":"a1u01d2.p2","form":"ñande · ore · peẽ · ha'ekuéra","gloss":"nosotros con vos · nosotros sin vos · ustedes · ellos, ellas","connect":[{"pos":"Nosotros, con el que escucha","rule":"che + nde = {ñande}"},{"pos":"Nosotros, sin el que escucha","rule":"che + ha'e = {ore}"},{"pos":"Ustedes: vos y otros","rule":"nde + ha'e = {peẽ}"},{"pos":"Ellos, ellas","rule":"ha'e + -kuéra = {ha'ekuéra}"},{"pos":"El ja- de Jajotopáta se vuelve ña- delante de un verbo nasal, como ñe'ẽ","rule":"{ja}jotopáta · {ña}ñe'ẽ"}],"examples":[{"gn":"{Ñande} ñañe'ẽ guaraníme.","es":"Nosotros (con vos) hablamos guaraní.","parts":[["ñande","nosotros, con vos"],["ña-","nosotros (con vos)"],["ñe'ẽ","hablar"],["guarani","guaraní"],["-me","en"]]},{"gn":"{Ore} roñe'ẽ guaraníme.","es":"Nosotros (sin vos) hablamos guaraní.","parts":[["ore","nosotros, sin vos"],["ro-","nosotros (sin vos)"],["ñe'ẽ","hablar"],["guarani","guaraní"],["-me","en"]]},{"gn":"{Peẽ} peñe'ẽ guaraníme.","es":"Ustedes hablan guaraní.","parts":[["peẽ","ustedes"],["pe-","ustedes"],["ñe'ẽ","hablar"],["guarani","guaraní"],["-me","en"]]},{"gn":"{Ha'ekuéra} oñe'ẽ guaraníme.","es":"Ellos (o ellas) hablan guaraní.","parts":[["ha'e","él, ella"],["-kuéra","plural"],["o-","ellos"],["ñe'ẽ","hablar"],["guarani","guaraní"],["-me","en"]]}],"watch":{"note":"No uses ñande para todo «nosotros». Ana le cuenta a una turista que ella y su familia hablan guaraní: la turista no está en el grupo, así que va ore.","bad":"(A una turista:) Ñande ñañe'ẽ guaraníme.","good":"(A una turista:) Ore roñe'ẽ guaraníme."}}],"compare":{"intro":"El castellano dice «nosotros» para todo; el guaraní mira si el que escucha está en el grupo.","forms":[{"form":"ñande","tag":"nosotros, con vos","mark":"dot","gn":"{Ñande} ñañe'ẽ guaraníme.","es":"Nosotros (con vos) hablamos guaraní."},{"form":"ore","tag":"nosotros, sin vos","mark":"dot","gn":"{Ore} roñe'ẽ guaraníme.","es":"Nosotros (sin vos) hablamos guaraní."},{"form":"«nosotros»","tag":"castellano: sirve para los dos","mark":"dot","gn":"che + nde = {ñande} · che + ha'e = {ore}","es":"yo + vos = nosotros · yo + él (o ella) = nosotros"}],"check":{"id":"a1u01d2.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana y su hermano hablan guaraní. Ana se lo cuenta ^a una vecina nueva^: «(   ) guaraníme.»","options":["Ñande ñañe'ẽ","Ore roñe'ẽ","Ha'ekuéra oñe'ẽ"],"answer":2,"why":["Ñande sumaría a la vecina, que es la que escucha. Pero ella no está en el grupo.","Ana habla de ella y de su hermano, y la vecina queda afuera: ore.","Ha'ekuéra es «ellos»: dejaría afuera a Ana, que también habla guaraní."]}},"drill":[{"id":"a1u01d2.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana habla de ^ella misma^: «(   ) añe'ẽ guaraníme.»","options":["Nde","Che","Ha'e","Ore"],"answer":2,"why":["Nde es «vos», el que escucha. Ana habla de ella misma.","Ana habla de ella misma: che, «yo». Y añe'ẽ es la forma de che.","Ha'e es otra persona, «él» o «ella». Con ha'e, el verbo sería oñe'ẽ.","Ore es «nosotros, sin vos». Ana habla solo de ella."]},{"id":"a1u01d2.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis habla de ^su mamá^: «(   ) oñe'ẽ guaraníme.»","options":["Che","Nde","Ha'ekuéra","Ha'e"],"answer":4,"why":["Che es «yo», Luis mismo, pero él habla de su mamá. Con che, además, el verbo sería añe'ẽ.","Nde es «vos», la persona a la que Luis le habla. Él habla de su mamá.","Ha'ekuéra es «ellos», varias personas. La mamá es una sola.","Luis habla de otra persona, su mamá: ha'e, «ella». Oñe'ẽ es la forma de ha'e."]},{"id":"a1u01d2.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana y Luis hablan guaraní. Ana se lo dice ^a Luis^: «(   ) guaraníme.»","options":["Ñande ñañe'ẽ","Ore roñe'ẽ","Che añe'ẽ","Ha'ekuéra oñe'ẽ"],"answer":1,"why":["Ana habla de ella y de Luis, que es el que escucha: ñande lo incluye.","Ore deja afuera al que escucha, y Luis está en el grupo.","Che añe'ẽ habla solo de Ana. Ella habla de los dos.","Ha'ekuéra es «ellos», otras personas: dejaría afuera a Ana y a Luis."]},{"id":"a1u01d2.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Un señor les pregunta a Ana y a Luis qué idioma hablan. Ana le contesta ^al señor^: «(   ) guaraníme.»","options":["Ñande ñañe'ẽ","Ore roñe'ẽ","Peẽ peñe'ẽ","Ha'ekuéra oñe'ẽ"],"answer":2,"why":["Ñande sumaría al señor, que es el que escucha, y él no está en el grupo.","Ana habla de ella y de Luis, y el señor que escucha queda afuera: ore.","Peẽ es «ustedes»: nunca incluye al que habla, y Ana habla de ella y de Luis.","Ha'ekuéra es «ellos»: dejaría afuera a Ana, que también habla guaraní."]},{"id":"a1u01d2.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Nde ","after":" guaraníme.","tiles":["re","ñe'ẽ"],"bank":[1,0],"hint":"Fijate en añe'ẽ y oñe'ẽ: ¿dónde va la parte que dice quién?","full":"Nde {reñe'ẽ} guaraníme.","es":"Vos hablás guaraní.","explain":"Con nde, «vos», este verbo lleva re- al principio: re + ñe'ẽ = reñe'ẽ, «hablás». El castellano marca la persona al final (hablás); el guaraní, al principio."},{"id":"a1u01d2.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Luis ha Marta: Mba'éichapa reiko?\nAna:","after":"?","tiles":["iporã","ha","peẽ"],"bank":[2,0,1],"hint":"Ana contesta primero. Después les devuelve la pregunta a los dos.","full":"Luis ha Marta: Mba'éichapa reiko?\nAna: Iporã, ha {peẽ}?","es":"Luis y Marta: ¿Cómo andás? Ana: Bien, ¿y ustedes?","explain":"Ana dice primero cómo está: iporã, «bien». Después les devuelve la pregunta a Luis y a Marta, que la escuchan: ha peẽ, «¿y ustedes?». Ha, «y», va antes de peẽ."}],"exam":[{"id":"a1u01d2.e1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis le pregunta a Ana si ella también habla guaraní: «Che añe'ẽ guaraníme, ha (   )?»","options":["nde","ha'e","che","ore"],"answer":1,"explain":"Luis le habla a Ana, así que para él ella es nde, «vos»: ha nde, «¿y vos?». Ha'e sirve para hablar de otra persona, no para hablarle a Ana; che sería Luis otra vez, y ore, «nosotros sin vos», dejaría afuera a Ana."},{"id":"a1u01d2.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Dos alumnas hablan guaraní y se lo cuentan a su docente: «(   ) guaraníme.»","options":["Ñande ñañe'ẽ","Ha'ekuéra oñe'ẽ","Ore roñe'ẽ","Che añe'ẽ"],"answer":3,"explain":"Las alumnas hablan de ellas dos, y la docente que las escucha no está en ese grupo: ore roñe'ẽ. Ñande ñañe'ẽ sumaría a la docente, ha'ekuéra oñe'ẽ hablaría de otras personas y che añe'ẽ, de una sola alumna."},{"id":"a1u01d2.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana habla de su mamá y su papá.) ","after":" oñe'ẽ guaraníme.","tiles":["ha'e","kuéra"],"bank":[1,0],"full":"(Ana habla de su mamá y su papá.) {Ha'ekuéra} oñe'ẽ guaraníme.","es":"(Ana habla de su mamá y su papá.) Ellos hablan guaraní.","explain":"Ana habla de dos personas, su mamá y su papá, así que va el plural: ha'e, «él, ella», más -kuéra da ha'ekuéra, «ellos». El acento pasa a -kuéra."}]},"words":{"es":"Una foto de familia","intro":"Tocá a cada persona en la foto que te muestra Ana: su familia y sus amigos.","sound":{"focus":"Las vocales nasales","letters":["ã","ẽ","ĩ","õ","ũ","ỹ"],"note":"En ã ẽ ĩ õ ũ ỹ el aire sale también por la nariz, sin agregar una n. La tilde nasal (~) cambia la palabra: pytu es «aliento» y pytũ, «oscuro». Los pares de hoy usan ã, ẽ y ũ; ĩ, õ y ỹ aparecen en peteĩ «uno», mokõi «dos» y tapỹi «choza».","pairs":[["pytu","aliento","pytũ","oscuro"],["oke","duerme","okẽ","puerta"],["tupa","cama","Tupã","Dios"],["pyta","talón; quedarse","pytã","rojo"]]},"words":[{"id":"chesy","gn":"che sy","es":"mi mamá","parts":[["che","mi"],["sy","madre"]],"note":"Che es «yo» y también «mi»."},{"id":"cheru","gn":"che ru","es":"mi papá","parts":[["che","mi"],["ru","padre"]]},{"id":"mita","gn":"mitã","es":"niño, niña","note":"Mitã sirve para niño y para niña."},{"id":"kunatai","gn":"kuñataĩ","es":"chica, muchacha","note":"La tilde nasal (~) va solo en la ĩ del final."},{"id":"kuna","gn":"kuña","es":"mujer","note":"La a suena nasal por la ñ, pero no lleva tilde nasal (~)."},{"id":"kuimbae","gn":"kuimba'e","es":"hombre"},{"id":"angiru","gn":"angirũ","es":"amigo, amiga","note":"La tilde nasal (~) va solo en la ũ del final."}],"spell":["mita","angiru","kunatai"],"check":{"id":"a1u01d2.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana habla de su amigo: «Che (   ) oñe'ẽ guaraníme.»","options":["angiru","angirũ","ãngirũ","angirun"],"answer":2,"explain":"Angirũ, «amigo», termina en ũ nasal y lleva tilde nasal (~). Angiru no tiene la nasal, y angirun agrega una n que la palabra no tiene. En ãngirũ sobra la ~ de la a: junto a ng ya suena nasal. Acá che es «mi»: che angirũ, «mi amigo», es otra persona, por eso va oñe'ẽ."}},"skill":{"kind":"reading","es":"Un mensaje de Ana","ask":"¿Quiénes hablan guaraní, según el mensaje?","seconds":60,"passage":"Mba'éichapa, Marta?\n^Ore roñe'ẽ guaraníme: che, che sy ha che ru.^\nHa nde?\nAna","strategy":"Leé primero la pregunta. Después de los dos puntos, Ana dice quiénes son ore.","item":{"id":"a1u01d2.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quiénes hablan guaraní, según el mensaje?","options":["Ana y Marta","Solo la mamá y el papá de Ana","Ana, su mamá y su papá"],"short":["Ana y Marta","Los papás","Ana y sus papás"],"answer":3,"why":["Marta es la que lee el mensaje, y ore deja afuera al que escucha o lee.","Después de los dos puntos, Ana se nombra primero: che, «yo». Ella también habla.","Ore roñe'ẽ guaraníme: che, che sy ha che ru. Son Ana, su mamá y su papá."],"explain":"Ana escribe ore roñe'ẽ guaraníme y después nombra a los de ore: che, che sy ha che ru. Ore deja afuera a Marta, la que lee."}}},{"title":"Presentarse: che réra","grammar":{"points":[{"id":"a1u01d3.p1","form":"Che réra … / Mba'éichapa nde réra?","gloss":"me llamo… / ¿cómo te llamás?","connect":[{"pos":"Decir tu nombre","rule":"Che {réra} …"},{"pos":"Preguntar el nombre","rule":"Mba'éichapa nde {réra}?"},{"pos":"Él o ella (para entender)","rule":"{Héra} …"}],"examples":[{"gn":"Mba'éichapa. Che {réra} Ana.","es":"Hola. Me llamo Ana.","parts":[["mba'éichapa","hola"],["che","mi"],["réra","nombre"]]},{"gn":"Mba'éichapa nde {réra}?","es":"¿Cómo te llamás?","parts":[["mba'éichapa","¿cómo?"],["nde","tu"],["réra","nombre"]]},{"gn":"Mbo'ehára {héra} Rosa.","es":"La profesora se llama Rosa.","parts":[["mbo'ehára","profesora"],["héra","su nombre"]]}],"watch":{"note":"Téra es «nombre» solo. Con che o nde adelante se dice réra. Y no hay verbo: che réra Ana es «mi nombre, Ana».","bad":"Che téra Ana.","good":"Che réra Ana."}},{"id":"a1u01d3.p2","form":"Che …-gua","gloss":"soy de… (sin verbo «ser»)","connect":[{"pos":"Lugar en guaraní","rule":"Che Paraguai{gua}."},{"pos":"Lugar en castellano (suele llevar guion)","rule":"Che Argentina-{gua}."},{"pos":"Él o ella","rule":"Ha'e Paraguai{gua}."}],"examples":[{"gn":"Che Paraguai{gua}.","es":"Soy de Paraguay.","parts":[["che","yo"],["Paraguái","Paraguay"],["-gua","de (un lugar)"]]},{"gn":"Che réra Lucas. Che Argentina-{gua}.","es":"Me llamo Lucas. Soy de Argentina.","parts":[["Argentina","Argentina"],["-gua","de (un lugar)"]]},{"gn":"Mbo'ehára héra Rosa. Ha'e Paraguai{gua}.","es":"La profesora se llama Rosa. Es de Paraguay.","parts":[["ha'e","ella"],["Paraguái","Paraguay"],["-gua","de (un lugar)"]]}],"watch":{"note":"En castellano el «de» va antes del lugar. En guaraní -gua va después, pegado, y no se agrega ningún verbo «ser».","bad":"Che gua Paraguái.","good":"Che Paraguaigua."}}],"compare":{"intro":"Las tres van sin verbo: réra y héra dicen cómo se llama alguien, y -gua dice de dónde es.","forms":[{"form":"che réra · nde réra","tag":"mi nombre · tu nombre","mark":"dot","gn":"A: Mba'éichapa {nde réra}?\nB: {Che réra} Ana.","es":"A: ¿Cómo te llamás?\nB: Me llamo Ana."},{"form":"héra","tag":"su nombre, de él o ella","mark":"dot","gn":"Mbo'ehára {héra} Rosa.","es":"La profesora se llama Rosa."},{"form":"-gua","tag":"de dónde es","mark":"dot","gn":"Che Paraguai{gua}.","es":"Soy de Paraguay."}],"check":{"id":"a1u01d3.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Mba'éichapa nde réra?\nB: Che réra Ana.\nA: ^[Ha mbo'ehára|¿y la profesora?]?^\nB: (   ) Rosa.","options":["Che réra","Nde réra","Héra"],"answer":3,"why":["Che réra es «mi nombre», y B ya dijo el suyo: Ana. Ahora la pregunta es por la profesora.","Nde réra es «tu nombre», el de quien escucha. Pero A pregunta por la profesora.","A pregunta por la profesora, ella: héra, «su nombre». Héra Rosa: se llama Rosa."]}},"drill":[{"id":"a1u01d3.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(^Carlos se presenta^.) Mba'éichapa. (   ) Carlos. [Ha nde|¿y vos?]?","options":["Nde réra","Héra","Che téra","Che réra"],"answer":4,"why":["Nde réra es «tu nombre». Carlos habla de él mismo, y recién después te pregunta a vos: ha nde?","Héra es el nombre de otra persona, de él o de ella. Carlos habla de sí mismo.","Téra es la palabra sola. Después de che se dice réra: che réra.","Carlos se presenta: che réra, «mi nombre». Después te pregunta a vos: ha nde?"]},{"id":"a1u01d3.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Mirta: Che réra Mirta. ^[Ha nde|¿y vos?]^, mba'éichapa (   ) réra?\nDiego: Che réra Diego.","options":["che","nde","ha'e","ñande"],"answer":2,"why":["Con che, Mirta preguntaría «¿cómo me llamo?». Ya dijo su nombre: ahora pregunta el de Diego.","Ha nde, «¿y vos?»: Mirta pregunta el nombre de Diego, el que escucha. Es nde réra, «tu nombre», y Diego responde con che réra.","Ha'e es «él, ella», y el nombre de él o de ella es héra. Además, Mirta le habla a Diego.","Ñande es «nosotros» con el que escucha incluido. Mirta pregunta el nombre de una sola persona."]},{"id":"a1u01d3.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(^Lucas es de Argentina^.) Mba'éichapa. Che réra Lucas. Che (   ).","options":["Argentina-gua","gua Argentina","Argentina","ha'e Argentina"],"answer":1,"why":["Lugar + -gua dice de dónde sos: Che Argentina-gua, «soy de Argentina». Con un nombre castellano se suele poner guion.","-gua no va adelante como el «de» castellano: va después del lugar, pegado.","Sin -gua, Che Argentina no dice de dónde es Lucas: falta -gua.","Ha'e es «él, ella». Usarlo como «soy» copia el castellano, y en guaraní no hace falta: alcanza con che y el lugar con -gua, Che Argentina-gua."]},{"id":"a1u01d3.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Che Paraguaigua. ^[Ha nde|¿y vos?]?^\nB: (   ) Argentina-gua.","options":["Nde","Ha'e","Che","Ñande"],"answer":3,"why":["Nde Argentina-gua sería «vos sos de Argentina». A pregunta por B, y B responde por sí: che.","Ha'e es «él, ella». B habla de sí.","A pregunta ha nde?, «¿y vos?», y B responde por sí: Che Argentina-gua, «soy de Argentina».","Ñande incluye a A, y A es de Paraguay. B habla solo de sí: che."]},{"id":"a1u01d3.d5","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Che réra Ana. Ha nde,","after":"?","tiles":["mba'éichapa","nde","réra"],"bank":[2,0,1],"hint":"La palabra que pregunta va primero. Después nde, justo antes de réra.","full":"Che réra Ana. Ha nde, mba'éichapa {nde réra}?","es":"Me llamo Ana. Y vos, ¿cómo te llamás?","explain":"Mba'éichapa, «¿cómo?», va primero porque es la palabra que pregunta. Después nde réra, «tu nombre»: nde va antes de réra."},{"id":"a1u01d3.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Mba'éichapa. Che réra Ana. Che ","after":".","tiles":["Paraguái","gua"],"bank":[1,0],"hint":"-gua dice de dónde es alguien. ¿Va antes o después del lugar?","full":"Mba'éichapa. Che réra Ana. Che Paraguai{gua}.","es":"Hola. Me llamo Ana. Soy de Paraguay.","explain":"-gua va después del lugar y pegado, en una sola palabra: Paraguaigua, «de Paraguay». -gua se lleva el acento de la palabra y, como queda al final, no se escribe tilde: Paraguái pierde la suya."}],"exam":[{"id":"a1u01d3.e1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Che réra Pedro. Ha nde, mba'éichapa (   )?\nB: Che réra Lucía.","options":["che réra","nde réra","héra","nde téra"],"answer":2,"explain":"A ya dijo su nombre y ahora pregunta el de B: nde réra, «tu nombre». Che réra sería el nombre de A; héra, el de otra persona; y después de nde no va téra sino réra."},{"id":"a1u01d3.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Mba'éichapa nde réra?\nB: Che réra Marta. Che (   ).","options":["gua Paraguái","Paraguái","Paraguái réra","Paraguaigua"],"answer":4,"explain":"Para decir de dónde es, Marta pega -gua al lugar, sin verbo «ser»: Che Paraguaigua, «soy de Paraguay». Sin -gua, Che Paraguái no lo dice; -gua no va adelante como el «de» castellano; y réra es «nombre», no habla de un lugar."},{"id":"a1u01d3.e3","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"A:","after":"?\nB: Che réra Lucas. Che Argentina-gua.","tiles":["mba'éichapa","nde","réra"],"bank":[1,0,2],"full":"A: Mba'éichapa nde réra?\nB: Che réra Lucas. Che Argentina-gua.","es":"A: ¿Cómo te llamás?\nB: Me llamo Lucas. Soy de Argentina.","explain":"Mba'éichapa va primero: es la palabra que pregunta. Después nde réra, «tu nombre», con nde antes de réra. B responde con che réra."}]},"words":{"gn":"Mbo'ehaópe","es":"En la escuela","intro":"Es tu primer día de clase de guaraní. Tocá cada palabra.","sound":{"focus":"La y, sexta vocal","letters":["y","ỹ"],"note":"La y es la sexta vocal del guaraní (su nasal es ỹ, como en tapỹi, «choza») y no suena como la y castellana. Decí «i» y llevá la lengua hacia atrás, como para «u», sin redondear los labios. Si la cambiás por i o u, cambia la palabra: yvytu es viento; yvyty, cerro.","pairs":[["ita","piedra","yta","nadar"],["sa'i","poco","sa'y","color"],["yvytu","viento","yvyty","cerro"],["hendu","oír","hendy","arder"]]},"words":[{"id":"tera","gn":"téra","es":"nombre","note":"Con che y nde se dice réra: che réra, nde réra. De él o de ella: héra."},{"id":"mboehara","gn":"mbo'ehára","es":"profesor, profesora","parts":[["mbo'e","enseñar"],["-hára","el que hace"]]},{"id":"temimboe","gn":"temimbo'e","es":"alumno, alumna","parts":[["temi-","a quien se…"],["mbo'e","enseñar"]]},{"id":"pyahu","gn":"pyahu","es":"nuevo, nueva","note":"Va después de lo que describe: temimbo'e pyahu, «alumno nuevo» o «alumna nueva»."},{"id":"mboehao","gn":"mbo'ehao","es":"escuela"},{"id":"mboepy","gn":"mbo'epy","es":"clase, lección"},{"id":"aranduka","gn":"aranduka","es":"libro"},{"id":"neeryru","gn":"ñe'ẽryru","es":"diccionario","parts":[["ñe'ẽ","palabra"],["ryru","recipiente"]]}],"spell":["mboepy","pyahu","neeryru"],"check":{"id":"a1u01d3.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Hoy empieza la _clase_ de guaraní.","options":["mbo'epy","mbo'epi","mboepy","mbo'epu"],"answer":1,"explain":"Clase es mbo'epy: con puso entre o y e, y con y al final, la sexta vocal. Mbo'epi y mbo'epu cambian la y por i o u, y mboepy pierde el puso."}},"skill":{"kind":"listening","es":"Comprensión de puntos clave","situation":"Primer día de clase de guaraní. La profesora habla de ella y de una alumna nueva.","ask":"¿Qué dato de la alumna nueva es correcto?","item":{"id":"a1u01d3.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué dato de la alumna nueva es correcto?","options":["Es de Paraguay.","Es de Argentina.","Se llama Nilda."],"short":["De Paraguay","De Argentina","Se llama Nilda"],"printed":true,"answer":2,"why":["De Paraguay es la profesora: Che réra Nilda. Che Paraguaigua. De la alumna dice: Ha'e Argentina-gua.","La profesora dice de la alumna nueva: Ha'e Argentina-gua, «es de Argentina».","Nilda es la profesora: che réra Nilda. La alumna nueva se llama Sofía: héra Sofía."],"script":["Narrador: Primer día de clase de guaraní. La profesora habla de ella y de una alumna nueva.","Narrador: ¿Qué dato de la alumna nueva es correcto?","Mujer: Mba'éichapa. Che réra Nilda.","Mujer: Che Paraguaigua.","Mujer: Temimbo'e pyahu héra Sofía.","Mujer: Ha'e Argentina-gua.","Narrador: ¿Qué dato de la alumna nueva es correcto?"]},"audio":[["N","Primer día de clase de guaraní. La profesora habla de ella y de una alumna nueva.","Primer día de clase de guaraní. La profesora habla de ella y de una alumna nueva."],["N","¿Qué dato de la alumna nueva es correcto?","¿Qué dato de la alumna nueva es correcto?"],["F","Mba'éichapa. Che réra Nilda.","Hola. Me llamo Nilda."],["F","Che Paraguaigua.","Soy de Paraguay."],["F","Temimbo'e pyahu héra Sofía.","La alumna nueva se llama Sofía."],["F","Ha'e Argentina-gua.","Es de Argentina."],["N","¿Qué dato de la alumna nueva es correcto?","¿Qué dato de la alumna nueva es correcto?"]]}},{"title":"Preguntar con -pa","grammar":{"points":[{"id":"a1u01d4.p1","form":"-pa","gloss":"pregunta de sí o no","connect":[{"pos":"Pegado al verbo: preguntás por la acción","rule":"[reikuaa|sabés] + {pa} → reikuaá{pa}?"},{"pos":"Pegado a otra palabra: preguntás por ella","rule":"nde + {pa} → ndé{pa}?"},{"pos":"Para contestar: sí / no","rule":"{Héẽ} / {Nahániri}"}],"examples":[{"gn":"Reñe'ẽ{pa} guaraníme? {Héẽ}, michĩmi.","es":"¿Hablás guaraní? Sí, un poquito.","parts":[["re-","vos"],["ñe'ẽ","hablar"],["-pa","pregunta"]]},{"gn":"Ikatú{pa} aike? {Héẽ}, ikatu.","es":"¿Puedo pasar? Sí, se puede.","parts":[["ikatu","se puede"],["-pa","pregunta"],["aike","entro"]]},{"gn":"Ndé{pa} Juan? {Nahániri}, che Pedro.","es":"¿Vos sos Juan? No, soy Pedro.","parts":[["nde","vos"],["-pa","pregunta"]]}],"watch":{"note":"La -pa de pregunta no se lleva el acento: este queda en la última a de reikuaa. Como esa a ya no es la última vocal de la palabra, se escribe: reikuaápa. Sin la marca, el acento caería en pa.","bad":"Reikuaapa?","good":"Reikuaápa?"}},{"id":"a1u01d4.p2","form":"Mba'épa","gloss":"¿qué? y otras palabras de pregunta","connect":[{"pos":"¿Qué?","rule":"mba'e + {pa} → mba'é{pa}"},{"pos":"¿Quién?","rule":"máva + {pa} → máva{pa}"},{"pos":"¿Dónde?","rule":"moõ + {pa} → moõ{pa}"},{"pos":"¿Cuánto?","rule":"mboy + {pa} → mboý{pa}"}],"examples":[{"gn":"{Mba'épa} reipota?","es":"¿Qué querés?","parts":[["mba'e","qué"],["-pa","pregunta"],["reipota","querés"]]},{"gn":"{Mávapa} ha'e?","es":"¿Quién es?","parts":[["máva","quién"],["-pa","pregunta"],["ha'e","él, ella"]]},{"gn":"{Moõpa} reiko?","es":"¿Dónde vivís?","parts":[["moõ","dónde"],["-pa","pregunta"],["reiko","vivís"]]},{"gn":"{Mboýpa} ovale ko kesu?","es":"¿Cuánto cuesta este queso?","parts":[["mboy","cuánto"],["-pa","pregunta"],["ovale","cuesta"],["ko","este"],["kesu","queso"]]}],"watch":{"note":"Mba'épa, mávapa, moõpa y mboýpa piden un dato. No se contestan con héẽ ni con nahániri: a moõpa reiko se responde con un lugar, como aiko távape (vivo en la ciudad).","bad":"Moõpa reiko? Héẽ.","good":"Moõpa reiko? Aiko távape."}}],"compare":{"intro":"Mirá dónde va -pa: en estas tres, sin -pa afirmás, con -pa en el verbo preguntás sí o no, y con -pa en una palabra de pregunta pedís un dato.","forms":[{"form":"Reñe'ẽ","tag":"Afirma · sin -pa","mark":"dot","gn":"Reñe'ẽ guaraníme.","es":"Hablás guaraní."},{"form":"Reñe'ẽpa","tag":"Sí o no · -pa en el verbo","mark":"dot","gn":"Reñe'ẽ{pa} guaraníme?","es":"¿Hablás guaraní?"},{"form":"Moõpa","tag":"Pide un dato · -pa en moõ","mark":"dot","gn":"Moõ{pa} reñe'ẽ guaraníme?","es":"¿Dónde hablás guaraní?"}],"check":{"id":"a1u01d4.c1","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: ^Moõpa^ reñe'ẽ guaraníme?\nB: (   )","options":["Héẽ, añe'ẽ.","Nahániri.","Che rógape."],"answer":3,"why":["Héẽ contesta preguntas de sí o no. Moõpa pide un lugar.","Nahániri también es para sí o no, y acá te preguntan dónde.","Moõpa pregunta «¿dónde?», y che rógape (en mi casa) es un lugar."]}},"drill":[{"id":"a1u01d4.d1","kind":"choice","area":"grammar","label":"Elegí la pregunta","q":"A: (   ) guaraníme?\nB: ^Héẽ^, [michĩmi|un poquito].","options":["Mba'épa reñe'ẽ","Reñe'ẽpa","Moõpa reñe'ẽ","Mávapa oñe'ẽ"],"answer":2,"why":["Mba'épa pregunta qué hablás. A un «¿qué?» no se contesta héẽ.","B contesta héẽ, sí: es una pregunta de sí o no, con -pa en el verbo. Reñe'ẽpa guaraníme? ¿Hablás guaraní?","Moõpa pregunta dónde. La respuesta sería un lugar, no héẽ.","Mávapa pregunta quién habla guaraní. Héẽ no dice quién."]},{"id":"a1u01d4.d2","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: Reikuaápa che réra?\nB: (   ). ^Nde réra Juan^.","options":["Héẽ","Nahániri","Iporã","Jajotopáta"],"answer":1,"why":["Héẽ es «sí». B sabe el nombre y lo dice: nde réra Juan.","Nahániri es «no», pero B dice el nombre: sí lo sabe.","Iporã, «bien», contesta mba'éichapa. Acá te preguntan sí o no.","Jajotopáta, «nos vemos», es para despedirse. No contesta la pregunta."]},{"id":"a1u01d4.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: (   ) [ovale|cuesta] [ko|este] [kesu|queso]?\nB: ^Diez mil^.","options":["Mba'éichapa","Mávapa","Moõpa","Mboýpa"],"answer":4,"why":["Mba'éichapa pregunta cómo. B no dice cómo: dice un precio.","Mávapa pregunta quién. Diez mil no es una persona.","Moõpa pregunta dónde. Diez mil no es un lugar.","B dice un precio, diez mil: la pregunta es Mboýpa, ¿cuánto? Los precios se suelen decir en castellano, también cuando se habla guaraní."]},{"id":"a1u01d4.d4","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: ^Mávapa^ ha'e?\nB: (   )","options":["Héẽ.","Iporã.","Che sy.","Nahániri."],"answer":3,"why":["Héẽ contesta preguntas de sí o no. Mávapa pregunta quién.","Iporã, «bien», contesta mba'éichapa. No dice quién es.","Mávapa pregunta «¿quién?»: che sy, mi mamá, es una persona.","Nahániri contesta sí o no. Mávapa pide una persona."]},{"id":"a1u01d4.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Ana, ","after":" che réra?","tiles":["rei","kuaa","pa"],"bank":[2,0,1],"hint":"-pa, la marca de pregunta, va al final, y rei- es «vos». Después fijate dónde queda el acento.","full":"Ana, reikuaá{pa} che réra?","es":"Ana, ¿sabés mi nombre?","explain":"rei- (vos) va adelante, kuaa (saber) en el medio y -pa al final: reikuaápa. Con verbos como kuaa, «vos» es rei- y no re-. Como la -pa de pregunta no se lleva el acento, este queda en la última a de kuaa, y se escribe porque ya no es la última vocal."},{"id":"a1u01d4.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" ovale ko kesu?","tiles":["mboy","pa"],"bank":[1,0],"hint":"¿Dónde va -pa en mba'épa? Acá va igual. Después fijate dónde queda el acento.","full":"{Mboýpa} ovale ko kesu?","es":"¿Cuánto cuesta este queso?","explain":"mboy (cuánto) va primero y -pa al final: mboýpa. La -pa de pregunta no se lleva el acento: este queda en la y de mboy. Como esa y ya no es la última vocal, se escribe con tilde: ý."}],"exam":[{"id":"a1u01d4.e1","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: Ndépa Rosa?\nB: (   ), che Rosa.","options":["Nahániri","Héẽ","Iporã","Mávapa"],"answer":2,"explain":"B dice che Rosa, «soy Rosa»: es quien A pensaba, así que contesta héẽ, «sí». Nahániri diría que no es Rosa. Iporã, «bien», contesta mba'éichapa, y mávapa es una pregunta, no una respuesta."},{"id":"a1u01d4.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: (   ) reipota?\nB: Chipa.","options":["Mboýpa","Moõpa","Mávapa","Mba'épa"],"answer":4,"explain":"B contesta con una cosa, chipa: la pregunta es Mba'épa reipota?, ¿qué querés? Mboýpa pregunta cuánto, moõpa dónde y mávapa quién."},{"id":"a1u01d4.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Rosa, ","after":" guaraníme?","tiles":["re","ñe'ẽ","pa"],"bank":[1,2,0],"full":"Rosa, reñe'ẽ{pa} guaraníme?","es":"Rosa, ¿hablás guaraní?","explain":"re (vos) + ñe'ẽ (hablar) + pa (pregunta) = reñe'ẽpa. El acento sigue en la ẽ, y la tilde nasal (~) ya lo marca: no se escribe otro acento."}]},"words":{"es":"Un puesto en el mercado","intro":"Estás en un puesto del mercado. Tocá cada palabra para escucharla.","sound":{"focus":"El puso (')","letters":["'"],"note":"El puso (') es una letra del alfabeto: un corte breve de la voz entre dos vocales, como en «oh-oh» (ka'a, mba'e, ñe'ẽ). Si falta, cambia la palabra: mbo'y es «collar» y mboy, «¿cuántos?». En ka'i / kái y en sevo'i / sevói cambia también el acento: ka'i y sevo'i lo llevan al final; kái y sevói, en la vocal con tilde.","pairs":[["mbo'y","collar","mboy","¿cuántos?"],["ka'i","mono","kái","quemarse"],["sevo'i","lombriz","sevói","cebolla"]]},"words":[{"id":"chipa","gn":"chipa","es":"chipá","note":"Sin acento escrito: en guaraní, sin marca, el acento cae al final."},{"id":"kesu","gn":"kesu","es":"queso","note":"Viene del castellano «queso», escrito a la guaraní."},{"id":"soo","gn":"so'o","es":"carne","note":"So-'o: el puso corta la voz entre las dos o."},{"id":"mandio","gn":"mandi'o","es":"mandioca","note":"Ma-ndi-'o: el puso va entre la i y la o."},{"id":"kaa","gn":"ka'a","es":"yerba mate","note":"La yerba del mate y del tereré. Ka-'a, con un corte entre las dos a."},{"id":"hee","gn":"he'ẽ","es":"dulce","note":"No es héẽ («sí»): he'ẽ lleva puso. Ka'ay he'ẽ es «mate dulce»."},{"id":"oipa","gn":"Oĩpa chipa?","es":"¿Hay chipá?","parts":[["oĩ","hay"],["-pa","pregunta"],["chipa","chipá"]]},{"id":"mboypa","gn":"Mboýpa ovale?","es":"¿Cuánto cuesta?","parts":[["mboy","cuánto"],["-pa","pregunta"],["ovale","cuesta"]],"note":"Ovale viene del castellano «valer»."}],"spell":["kaa","soo","mandio","hee"],"check":{"id":"a1u01d4.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"¿Cómo se escribe _mandioca_ en guaraní?","options":["mandio","mandi'o","mand'io","mandi'õ"],"answer":2,"explain":"Mandi'o lleva puso entre la i y la o: ma-ndi-'o. En mandio falta el corte de la voz. En mand'io el puso queda después de una consonante, y el puso va siempre entre dos vocales. Mandi'õ agrega una tilde nasal (~) que la palabra no lleva."}},"skill":{"kind":"listening","es":"Comprensión de puntos clave","situation":"Una mujer llega a un puesto del mercado y habla con el vendedor. Él dice el precio en castellano, como se suele hacer.","ask":"¿Qué hay en el puesto?","item":{"id":"a1u01d4.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué hay en el puesto?","options":["Chipá y queso","Queso y mandioca","Chipá y mandioca"],"answer":2,"why":["Chipá no hay: ella pregunta oĩpa chipa? y él contesta nahániri.","Él dice oĩ kesu ha mandi'o: hay queso y mandioca.","Mandioca hay, pero chipá no: el vendedor contesta nahániri."],"script":["Narrador: En un puesto del mercado. ¿Qué hay en el puesto?","Hombre: Mba'éichapa. Mba'épa reipota?","Mujer: Iporã. Oĩpa chipa?","Hombre: Nahániri. Oĩ kesu ha mandi'o.","Mujer: Mboýpa ovale ko kesu?","Hombre: Diez mil.","Narrador: ¿Qué hay en el puesto?"]},"audio":[["N","En un puesto del mercado. ¿Qué hay en el puesto?","En un puesto del mercado. ¿Qué hay en el puesto?"],["M","Mba'éichapa. Mba'épa reipota?","Hola, ¿qué tal? ¿Qué querés?"],["F","Iporã. Oĩpa chipa?","Bien. ¿Hay chipá?"],["M","Nahániri. Oĩ kesu ha mandi'o.","No. Hay queso y mandioca."],["F","Mboýpa ovale ko kesu?","¿Cuánto cuesta este queso?"],["M","Diez mil.","Diez mil."],["N","¿Qué hay en el puesto?","¿Qué hay en el puesto?"]]}},{"title":"Aguyje: la cortesía","grammar":{"points":[{"id":"a1u01d5.p1","form":"Aguyje","gloss":"gracias","connect":[{"pos":"Para dar las gracias","rule":"{Aguyje}."},{"pos":"Para dar muchas gracias","rule":"{Aguyjevete}."},{"pos":"A vos (una persona) o a ustedes (varias)","rule":"Aguyje {ndéve}. · Aguyjevete {peẽme}."}],"examples":[{"gn":"{Aguyje} ndéve, Lucía.","es":"Gracias a vos, Lucía.","parts":[["aguyje","gracias"],["nde","vos"],["-ve","a"]]},{"gn":"Nahániri, {aguyje}.","es":"No, gracias.","parts":[["nahániri","no"],["aguyje","gracias"]]},{"gn":"{Aguyjevete} peẽme.","es":"Muchas gracias a ustedes.","parts":[["aguyjevete","muchas gracias"],["peẽ","ustedes"],["-me","a"]]}],"watch":{"note":"La y de aguyje es la sexta vocal del guaraní, no una i. No escribas aguije.","bad":"Aguije.","good":"Aguyje."}},{"id":"a1u01d5.p2","form":"Ikatúpa…? · Cheñyrõmi · Tereg̃uahẽ porãite","gloss":"¿puedo…? · perdón · bienvenido/a","connect":[{"pos":"Pedir permiso: Ikatúpa y lo que querés hacer","rule":"{Ikatúpa} aike?"},{"pos":"Pedir perdón","rule":"{Cheñyrõmi}."},{"pos":"Recibir en tu casa: a una persona · a varias","rule":"{Tere}g̃uahẽ porãite. · {Tape}g̃uahẽ porãite."}],"examples":[{"gn":"{Ikatúpa} aporandumi ndéve peteĩ mba'e?","es":"¿Te puedo preguntar una cosa?","parts":[["ikatu","se puede"],["-pa","(pregunta)"],["a-","yo"],["porandu","preguntar"],["-mi","más suave"],["ndéve","a vos"],["peteĩ","una"],["mba'e","cosa"]]},{"gn":"{Cheñyrõmi}, ña Ramona.","es":"Perdón, doña Ramona.","parts":[["che-","me"],["ñyrõ","perdonar"],["-mi","más suave"],["ña","doña"]]},{"gn":"Eike, Lucía. {Tereg̃uahẽ porãite}.","es":"Pasá, Lucía. Bienvenida.","parts":[["eike","pasá, entrá"],["tere-","que (vos)"],["g̃uahẽ","llegar"],["porã","bien"],["-ite","muy"]]}],"watch":{"note":"Sin tilde, ikatupa sonaría ikatupá. -pa no se lleva el acento: queda en la u de ikatu. Como esa u ya no es la última vocal, se escribe: Ikatúpa.","bad":"Ikatupa aike?","good":"Ikatúpa aike?"}}],"compare":{"intro":"Tres fórmulas para tres momentos de una visita: antes de entrar, cuando te dan algo y cuando algo sale mal.","forms":[{"form":"Ikatúpa…?","tag":"pedir permiso","mark":"dot","gn":"{Ikatúpa} aike?","es":"¿Puedo pasar?"},{"form":"Aguyje","tag":"dar las gracias","mark":"dot","gn":"{Aguyje}, ña Ramona.","es":"Gracias, doña Ramona."},{"form":"Cheñyrõmi","tag":"pedir perdón","mark":"dot","gn":"{Cheñyrõmi}, ña Ramona.","es":"Perdón, doña Ramona."}],"check":{"id":"a1u01d5.c1","kind":"choice","area":"grammar","label":"Elegí la fórmula","q":"(Doña Ramona ^le regala un chipá^ a Lucía.)\nLucía: (   )","options":["Aguyje.","Cheñyrõmi.","Ikatúpa aike?"],"answer":1,"why":["Doña Ramona le hace un regalo a Lucía: Lucía da las gracias con Aguyje.","Cheñyrõmi pide perdón, y no pasó nada malo: doña Ramona le hace un regalo.","Ikatúpa aike? pide permiso para entrar. Acá doña Ramona le da algo, y Lucía le contesta."]}},"drill":[{"id":"a1u01d5.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Lucía: Aguyjevete (   ), ^Ana ha Luis^.","options":["ndéve","peẽme","chéve","nde"],"answer":2,"why":["Ndéve es «a vos», para una sola persona. Lucía les habla a dos: Ana y Luis.","Lucía les da las gracias a dos personas, Ana y Luis. «A ustedes» es peẽme.","Chéve es «a mí». Lucía no se da las gracias a sí misma.","Nde es «vos». Para decir «a vos» hace falta ndéve, y además acá son dos personas."]},{"id":"a1u01d5.d2","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"Ramona: [Reipotápa|¿querés?] terere?\nLucía: ^[Nahániri|no]^, (   ).","options":["tereg̃uahẽ porãite","mba'éichapa","aguyje","ikatúpa aike"],"answer":3,"why":["Tereg̃uahẽ porãite da la bienvenida a quien llega. No contesta a «¿querés tereré?».","Mba'éichapa? pregunta cómo está alguien. Acá Lucía contesta, no pregunta.","Lucía no quiere tereré y lo dice con cortesía: Nahániri, aguyje («No, gracias»).","Ikatúpa aike? pide permiso para entrar. Ramona le ofrece tereré, y Lucía tiene que contestar."]},{"id":"a1u01d5.d3","kind":"choice","area":"grammar","label":"Elegí la frase","q":"Lucía: (   )\nRamona: ^[Eike|pasá]^, Lucía. Tereg̃uahẽ porãite.","options":["Ikatúpa aike?","Jajotopáta.","Tereg̃uahẽ porãite.","Iporã, ha nde?"],"answer":1,"why":["Ramona le contesta Eike, «pasá». Entonces Lucía pidió permiso para entrar: Ikatúpa aike?","Jajotopáta es para despedirse, y Lucía recién llega: Ramona le dice «pasá».","Tereg̃uahẽ porãite lo dice quien recibe, y la que recibe es Ramona. Lucía es la que llega.","Iporã, ha nde? contesta a Mba'éichapa?, y nadie le preguntó a Lucía cómo está."]},{"id":"a1u01d5.d4","kind":"choice","area":"grammar","label":"Elegí la fórmula","q":"(Ana y Luis llegan a la casa de doña Ramona.)\nRamona: (   ), ^Ana ha Luis^.","options":["Ikatúpa aike","Jajotopáta","Tereg̃uahẽ porãite","Tapeg̃uahẽ porãite"],"answer":4,"why":["Ikatúpa aike pide permiso para entrar. Ramona está en su casa: ella es la que recibe.","Jajotopáta es para despedirse, y Ana y Luis recién llegan.","Tereg̃uahẽ porãite es para una sola persona, y Ramona recibe a dos: Ana y Luis.","Ramona recibe a dos personas, Ana y Luis. A varias se les dice Tapeg̃uahẽ porãite."]},{"id":"a1u01d5.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis le abre la puerta a Ana.)\nAna: Aguyje ","after":", Luis.","tiles":["nde","ve"],"bank":[1,0],"hint":"Ana le da las gracias a una sola persona, Luis: «a vos». Fijate después dónde queda el acento.","full":"(Luis le abre la puerta a Ana.)\nAna: Aguyje {ndéve}, Luis.","es":"Ana: Gracias a vos, Luis.","explain":"nde, ve. Nde es «vos» y -ve, «a»: ndéve es «a vos». -ve no se lleva el acento: queda en la e de nde. Como esa e ya no es la última vocal, se escribe: ndéve."},{"id":"a1u01d5.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Lucía: ","after":", ña Ramona.","tiles":["che","ñyrõ","mi"],"bank":[1,2,0],"hint":"Como en Jajotopáta, la persona va adelante. Lo que suaviza el pedido va al final.","full":"Lucía: {Cheñyrõmi}, ña Ramona.","es":"Lucía: Perdón, doña Ramona.","explain":"che, ñyrõ, mi. Acá che- es «me», ñyrõ es «perdonar» y -mi lo hace más suave. Van juntos, en una sola palabra: Cheñyrõmi, «perdoname»."}],"exam":[{"id":"a1u01d5.e1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le da un chipá a Luis.)\nLuis: Aguyje (   ), Ana.","options":["peẽme","chéve","ndéve","nde"],"answer":3,"explain":"Luis le da las gracias a una sola persona, Ana: «a vos» es ndéve. Peẽme es «a ustedes», para varias personas; chéve es «a mí»; y nde solo, sin -ve, no quiere decir «a vos»."},{"id":"a1u01d5.e2","kind":"choice","area":"grammar","label":"Elegí la fórmula","q":"(Lucía vuelca sin querer el tereré de doña Ramona.)\nLucía: (   ), ña Ramona.","options":["Aguyje","Tereg̃uahẽ porãite","Jajotopáta","Cheñyrõmi"],"answer":4,"explain":"Lucía volcó el tereré sin querer: pide perdón con Cheñyrõmi. Aguyje da las gracias, Tereg̃uahẽ porãite da la bienvenida y Jajotopáta es para despedirse. Ninguna de esas tres pide perdón."},{"id":"a1u01d5.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Lucía llega a la casa de doña Ramona.)\nLucía: ","after":" aike, ña Ramona?","tiles":["ikatu","pa"],"bank":[1,0],"full":"(Lucía llega a la casa de doña Ramona.)\nLucía: {Ikatúpa} aike, ña Ramona?","es":"Lucía: ¿Puedo pasar, doña Ramona?","explain":"ikatu, pa. -pa va al final y no se lleva el acento: queda en la u de ikatu. Como esa u ya no es la última vocal, se escribe: Ikatúpa."}]},"words":{"es":"De visita en una casa paraguaya","intro":"Estás de visita en la casa de doña Ramona, la abuela de Ana. Tocá cada palabra de la escena.","sound":{"focus":"Teclear ã ẽ ĩ õ ũ ỹ, g̃ y el puso (')","letters":["ã","ẽ","ĩ","õ","ũ","ỹ","g̃","'"],"note":"Para estas letras, la app tiene su propia fila de teclas: ã ẽ ĩ õ ũ ỹ, la g̃ (una g con ~) y el puso ('). Cada marca cuenta: okẽ es «puerta» y oke, «duerme»; porã es «bien» y póra, «fantasma». La ĩ y la ỹ están en peteĩ «uno» y tapỹi «choza».","pairs":[["okẽ","puerta","oke","duerme"],["porã","lindo, bien","póra","fantasma"],["téra","nombre","térã","o"]]},"words":[{"id":"oga","gn":"óga","es":"casa","note":"Lleva tilde porque el acento no cae al final: ó-ga."},{"id":"oke","gn":"okẽ","es":"puerta","note":"Sin la ~ es otra palabra: oke es «duerme»."},{"id":"tereguahe","gn":"Tereg̃uahẽ porãite","es":"bienvenido, bienvenida","parts":[["tere-","que (vos)"],["g̃uahẽ","llegar"],["porã","bien"],["-ite","muy"]],"note":"A varias personas: Tapeg̃uahẽ porãite. En diarios también se ve Tereguahẽ, sin la ~ de la g. En la app escribimos g̃."},{"id":"terere","gn":"terere","es":"tereré","note":"Va sin tilde: en guaraní el acento al final no se marca. En la ronda, decir aguyje («gracias») al devolver la guampa quiere decir «no quiero más»."},{"id":"kaay","gn":"ka'ay","es":"mate","parts":[["ka'a","yerba"],["y","agua"]],"note":"Es el mate, que se toma caliente. El frío es el terere."},{"id":"angiru","gn":"angirũ","es":"amigo, amiga","note":"Sirve para amigo y para amiga. La ~ va solo en la ũ del final."},{"id":"avanee","gn":"avañe'ẽ","es":"guaraní (la lengua)","parts":[["ava","gente"],["ñe'ẽ","lengua"]],"note":"Es el nombre del guaraní en guaraní."},{"id":"cheniromi","gn":"Cheñyrõmi","es":"perdón, disculpá","parts":[["che-","me"],["ñyrõ","perdonar"],["-mi","más suave"]]}],"spell":["tereguahe","avanee","cheniromi","angiru"],"check":{"id":"a1u01d5.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Doña Ramona recibe a Lucía en la puerta: «_Bienvenida_».","options":["Tereg̃uahe poraite","Tereg̃uahẽ porãite","Tereg̃uahẽ poraite","Tereg̃uahe porãite"],"answer":2,"explain":"Se escribe con tres tildes nasales (~): la de g̃, la de ẽ y la de ã. Las otras opciones pierden la ~ de ẽ, la de ã o las dos. La ~ de la g a veces no se escribe (Tereguahẽ), pero la de ẽ y la de ã no pueden faltar."}},"skill":{"kind":"reading","es":"Un mensaje de gracias","ask":"Un WhatsApp después de la visita: ¿para qué escribe Lucía?","seconds":60,"passage":"Maitei, ña Ramona ha Ana!\n^Aguyjevete peẽme^.\n^Jajotopáta^!\nLucía","strategy":"Buscá las fórmulas que ya conocés: cada una dice qué hace quien escribe.","item":{"id":"a1u01d5.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué hace Lucía en su mensaje?","options":["Pide perdón y se despide.","Da la bienvenida y pregunta cómo están.","Da las gracias y se despide."],"short":["Pide perdón","Da la bienvenida","Da las gracias"],"answer":3,"why":["Se despide, sí (Jajotopáta), pero no pide perdón: no escribe Cheñyrõmi.","No escribe Tereg̃uahẽ porãite (bienvenida) ni Mba'éichapa? (¿cómo están?).","Aguyjevete peẽme es «muchas gracias a ustedes», y Jajotopáta, «nos vemos»."],"explain":"Lucía les escribe Aguyjevete peẽme («muchas gracias a ustedes») a doña Ramona y a Ana, y se despide con Jajotopáta («nos vemos»). No pide perdón (Cheñyrõmi), no da la bienvenida (Tereg̃uahẽ porãite) ni pregunta cómo están (Mba'éichapa?)."}}},{"title":"Repaso de la semana","grammar":{"points":[],"compare":{"intro":"Cuatro pares de la semana que se parecen: fijate a cuántos les hablás, si incluís al que escucha, de quién es el nombre y si la frase lleva -pa.","forms":[{"form":"ndéve · peẽme","tag":"a vos · a ustedes","mark":"dot","gn":"Aguyje {ndéve}, Ana. Aguyjevete {peẽme}, Ana ha Luis.","es":"Gracias a vos, Ana. Muchas gracias a ustedes, Ana y Luis."},{"form":"ñande · ore","tag":"con vos · sin vos","mark":"dot","gn":"{Ñande}: che ha nde. {Ore}: che ha Luis.","es":"Ñande: yo y vos. Ore: yo y Luis, sin vos."},{"form":"che réra · nde réra","tag":"mi nombre · tu nombre","mark":"dot","gn":"Rosa: Mba'éichapa {nde réra}?\nLuis: {Che réra} Luis.","es":"Rosa: ¿Cómo te llamás?\nLuis: Me llamo Luis."},{"form":"-pa","tag":"pregunta · respuesta","mark":"dot","gn":"Ana: Ndé{pa} Luis?\nLuis: Héẽ, che Luis.","es":"Ana: ¿Vos sos Luis?\nLuis: Sí, soy Luis."}],"check":{"id":"a1u01d6.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana: ^Reñe'ẽpa^ guaraníme?\nLuis: ^Héẽ^, (   ) guaraníme.","options":["reñe'ẽpa","añe'ẽ","oñe'ẽ"],"answer":2,"why":["Reñe'ẽpa es la pregunta de Ana, con -pa. Luis ya responde y afirma: sin -pa.","Luis responde que sí y habla de él: añe'ẽ, «hablo». No lleva -pa porque afirma.","Oñe'ẽ es la forma de ha'e, otra persona. Ana le pregunta a Luis con re- («vos»): él responde por él mismo, añe'ẽ."]}},"drill":[{"id":"a1u01d6.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis cuenta de dónde son ^sus abuelos^: «(   ) Paraguaigua.»","options":["Ha'e","Ore","Peẽ","Ha'ekuéra"],"answer":4,"why":["Ha'e es una sola persona, «él» o «ella». Los abuelos son más de uno.","Ore es «nosotros» y sumaría a Luis, pero él cuenta de dónde son sus abuelos.","Peẽ es «ustedes», para hablarles a ellos. Luis cuenta de dónde son sus abuelos, no les habla a ellos.","Luis habla de varias personas, sus abuelos: ha'ekuéra, «ellos». Ha'ekuéra Paraguaigua: son de Paraguay."]},{"id":"a1u01d6.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana le habla a la profesora. Para decir «nosotros: ^Luis y yo^», Ana dice (   ).","options":["ore","ñande","peẽ","ha'ekuéra"],"answer":1,"why":["La profesora escucha y no está en el grupo: son Luis y Ana. Ese «nosotros» es ore.","Ñande incluye al que escucha: sumaría a la profesora.","Peẽ es «ustedes». Ana habla de ella misma y de Luis.","Ha'ekuéra es «ellos» o «ellas». Ana se incluye: dice «nosotros»."]},{"id":"a1u01d6.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Mba'éichapa? Che réra Rosa. ^[Ha nde|¿y vos?]^?\nLuis: Iporã. (   ) Luis.","options":["Nde réra","Héra","Che réra","Ha nde"],"answer":3,"why":["Nde réra es «tu nombre», el de Rosa. Luis dice el suyo.","Héra es el nombre de otra persona, de él o de ella. Luis habla de él mismo.","Rosa pregunta ha nde?, «¿y vos?». Luis dice su nombre: che réra, «mi nombre».","Ha nde es «¿y vos?»: devuelve una pregunta, no dice un nombre."]},{"id":"a1u01d6.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Ikatúpa aike, ña Ramona?\nRamona: (   ), Rosa. ^[Eike|pasá]^.","options":["Nahániri","Héẽ","Jajotopáta","Ha nde"],"answer":2,"why":["Nahániri es «no», pero Ramona le dice Eike, «pasá»: la deja pasar.","Rosa pide permiso para entrar, y Ramona le dice Eike, «pasá»: la respuesta es sí, Héẽ.","Jajotopáta es para despedirse, y Rosa recién llega.","Ha nde es «¿y vos?». Ikatúpa aike? pide un sí o un no."]},{"id":"a1u01d6.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Nde sy ","after":" guaraníme?","tiles":["o","ñe'ẽ","pa"],"bank":[2,0,1],"hint":"Nde sy, «tu mamá», es otra persona, como ha'e: el verbo empieza con o-. -pa va al final.","full":"Nde sy {o}ñe'ẽ{pa} guaraníme?","es":"¿Tu mamá habla guaraní?","explain":"Nde sy, «tu mamá», es otra persona: o- + ñe'ẽ = oñe'ẽ, «habla». -pa va al final y hace la pregunta: oñe'ẽpa. El acento sigue en la ẽ, y la tilde nasal ya lo marca."},{"id":"a1u01d6.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"(Son las nueve de la mañana.)\nRosa:","after":", Juan?","tiles":["mba'éichapa","nde","pyhareve"],"bank":[1,2,0],"hint":"Empezá por la palabra que pregunta. Nde va antes de pyhareve, como en nde réra.","full":"(Son las nueve de la mañana.)\nRosa: {Mba'éichapa} nde pyhareve, Juan?","es":"(Son las nueve de la mañana.)\nRosa: Buen día, Juan.","explain":"Mba'éichapa va primero: es la palabra que pregunta. Después viene nde pyhareve, «tu mañana», con nde antes de pyhareve, como en nde réra. Es el saludo de la mañana: «buen día»."}],"exam":[{"id":"a1u01d6.e1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana le habla a Luis. Para decir «nosotros: vos y yo», Ana dice (   ).","options":["ore","peẽ","ñande","ha'ekuéra"],"answer":3,"explain":"Luis es el que escucha, y Ana lo incluye: «vos y yo» es ñande. Ore dejaría afuera a Luis, peẽ es «ustedes» y ha'ekuéra, «ellos»."},{"id":"a1u01d6.e2","kind":"choice","area":"grammar","label":"Elegí la frase","q":"(Lucía se va de la casa de doña Ramona.)\nLucía: Aguyjevete, ña Ramona. (   )","options":["Tereg̃uahẽ porãite.","Ikatúpa aike?","Mba'éichapa?","Jajotopáta."],"answer":4,"explain":"Lucía se va: después de dar las gracias, se despide con Jajotopáta, «nos vemos». Tereg̃uahẽ porãite es para recibir a quien llega, Ikatúpa aike? pide permiso para entrar y Mba'éichapa? saluda al llegar."},{"id":"a1u01d6.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" nde réra?","tiles":["mba'e","icha","pa"],"bank":[2,0,1],"full":"Mba'éicha{pa} nde réra?","es":"¿Cómo te llamás?","explain":"mba'e («qué») + -icha («como») + -pa (pregunta). Ni -icha ni -pa se llevan el acento: queda en la e de mba'e, que ya no es la última vocal, y se escribe: Mba'éichapa."}]},"words":{"es":"Rosa visita a Ana","intro":"Rosa llega tarde a la casa de Ana. Tocá cada palabra, de la puerta a la despedida.","sound":{"focus":"Repaso: nasales, la y y el puso","letters":["ã","y","'"],"note":"Tres cosas de la semana cambian la palabra: la tilde nasal, la sexta vocal (y) y el puso. Escuchá cada par y fijate qué cambia.","pairs":[["pyta","talón","pytã","rojo"],["ita","piedra","yta","nadar"],["ka'i","mono","kái","quemarse"]]},"words":[{"id":"ikatupa","gn":"Ikatúpa aike?","es":"¿Puedo pasar?","parts":[["ikatu","se puede"],["-pa","pregunta"],["aike","entro, paso"]],"note":"En la puerta, antes de entrar."},{"id":"hee","gn":"Héẽ","es":"Sí","note":"Va sin puso. Con puso, he'ẽ es «dulce». «No» es Nahániri."},{"id":"teregua","gn":"Tereg̃uahẽ porãite","es":"Bienvenida, bienvenido","parts":[["tere-","que (vos)"],["g̃uahẽ","llegar"],["porã","bien"],["-ite","muy"]],"note":"A varias personas: Tapeg̃uahẽ porãite."},{"id":"mbaeichapa","gn":"Mba'éichapa?","es":"Hola, ¿cómo estás?","parts":[["mba'e","qué"],["-icha","como"],["-pa","pregunta"]]},{"id":"ipora","gn":"Iporã, ha nde?","es":"Bien, ¿y vos?","parts":[["iporã","bien"],["ha","y"],["nde","vos"]]},{"id":"chenyromi","gn":"Cheñyrõmi","es":"Perdón, disculpá","parts":[["che-","me"],["ñyrõ","perdonar"],["-mi","más suave"]],"note":"Rosa llega tarde y se disculpa."},{"id":"aguyje","gn":"Aguyje","es":"Gracias","note":"Muchas gracias: Aguyjevete."},{"id":"jajotopata","gn":"Jajotopáta","es":"Nos vemos","parts":[["ja-","nosotros (con vos)"],["jo-","uno al otro"],["topa","encontrar"],["-ta","futuro"]],"note":"Para despedirse."}],"spell":["mbaeichapa","teregua","chenyromi","aguyje"],"check":{"id":"a1u01d6.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa pregunta: Ikatúpa aike? Ana le contesta que _sí_. ¿Cómo se escribe en guaraní?","options":["He'ẽ","Hee","Héẽ","Jeẽ"],"answer":3,"explain":"Sí es Héẽ: con h, con la ẽ nasal y sin puso. He'ẽ, con puso, es «dulce». Hee no tiene ninguna marca: le falta la tilde nasal (~) de la ẽ. Jeẽ cambia la h por j."}},"skill":{"kind":"reading","es":"Un chat en la puerta","ask":"¿Qué le pide Ana a Luis?","seconds":60,"passage":"Ana: Mba'éichapa, Luis?\nLuis: Iporã, ha nde?\nAna: Iporã. ^Ikatúpa aike?^\nLuis: ^Héẽ^, Ana. ^Tereg̃uahẽ porãite.^\nAna: Aguyjevete.","strategy":"Ana hace dos preguntas: una saluda y la otra pide algo. La respuesta de Luis viene justo después de cada una.","item":{"id":"a1u01d6.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué le pide Ana a Luis?","options":["Que le diga su nombre.","Que la deje pasar.","Que se vean otro día.","Que la perdone."],"short":["Su nombre","Pasar","Verse otro día","Perdón"],"answer":2,"why":["Ana no pregunta el nombre: ya lo sabe y le escribe «Luis». Para eso diría Mba'éichapa nde réra?","Ana pregunta Ikatúpa aike?, «¿puedo pasar?», y Luis le contesta Héẽ, «sí».","Ana no habla de otro día: recién llega y pide pasar. Jajotopáta, «nos vemos», es para irse.","Para pedir perdón, Ana escribiría Cheñyrõmi, y no lo escribe."],"explain":"Ana pregunta Ikatúpa aike?, «¿puedo pasar?». Luis responde Héẽ, «sí», y le da la bienvenida con Tereg̃uahẽ porãite. Ana le pide que la deje pasar."}}}],"test":["a1u01t.1","a1u01t.2","a1u01t.3","a1u01t.4","a1u01t.5","a1u01t.6","a1u01t.7","a1u01t.8","a1u01t.9","a1u01t.10","a1u01t.11","a1u01t.12","a1u01t.13","a1u01t.14","a1u01t.15","a1u01t.16","a1u01t.17","a1u01t.18","a1u01t.19","a1u01t.20"]},{"n":2,"gn":"","es":"¿Quién sos? Verbos de acción","days":[{"title":"Prefijos areales a-/re-/o-: quién hace la acción","grammar":{"points":[{"id":"a1u02d1.p1","form":"a- · re- · o-","gloss":"yo · vos · él, ella","connect":[{"pos":"Al principio del verbo, pegado a la raíz: guata, «caminar»","rule":"{a}guata · {re}guata · {o}guata"},{"pos":"Con o sin pronombre: el prefijo ya dice quién","rule":"Che {a}purahéi = {A}purahéi"},{"pos":"Para preguntar quién lo hace: Mávapa + o-","rule":"Mávapa {o}purahéi?"}],"examples":[{"gn":"Che {a}purahéi.","es":"Yo canto.","parts":[["che","yo"],["a-","yo"],["purahéi","cantar"]]},{"gn":"Nde {re}mba'apo heta.","es":"Vos trabajás mucho.","parts":[["nde","vos"],["re-","vos"],["mba'apo","trabajar"],["heta","mucho"]]},{"gn":"Ha'e {o}jeroky.","es":"Ella baila.","parts":[["ha'e","él, ella"],["o-","él, ella"],["jeroky","bailar"]]},{"gn":"Rosa: Mávapa {o}karu?\nAna: Che {a}karu.","es":"Rosa: ¿Quién come?\nAna: Yo como.","parts":[["mávapa","¿quién?"],["o-","él, ella"],["karu","comer"],["che","yo"],["a-","yo"]]}],"watch":{"note":"El castellano pone la persona al final del verbo: camin-o, camin-ás. El guaraní la pone al principio: a-guata, re-guata. Sin prefijo, guata no es «camino»: le falta la persona.","bad":"Che guata.","good":"Che aguata."}},{"id":"a1u02d1.p2","form":"aha · reho · oho / aju · reju · ou","gloss":"voy · vas · va / vengo · venís · viene","connect":[{"pos":"Ir cambia la raíz: ha con a-, ho con re- y o-","rule":"{aha} · {reho} · {oho}"},{"pos":"Venir: ju con a- y re-; «viene» es ou, sin j","rule":"{aju} · {reju} · {ou}"},{"pos":"Con un momento del día, como en la unidad 1","rule":"Rosa {ou} ko ka'aru."}],"examples":[{"gn":"Rosa {ou} ko pyhareve.","es":"Rosa viene esta mañana.","parts":[["ou","viene"],["ko","esta"],["pyhareve","mañana"]]},{"gn":"{Rejú}pa ko pyhare?","es":"¿Venís esta noche?","parts":[["re-","vos"],["ju","venir"],["-pa","pregunta"],["ko pyhare","esta noche"]]},{"gn":"Luis {oho} ko ka'aru, ha che {aha} ko pyhare.","es":"Luis va esta tarde, y yo voy esta noche.","parts":[["oho","va"],["ko ka'aru","esta tarde"],["ha","y"],["aha","voy"],["ko pyhare","esta noche"]]},{"gn":"Luis: Mávapa {ou}?\nAna: {Ou} che sy.","es":"Luis: ¿Quién viene?\nAna: Viene mi mamá.","parts":[["mávapa","¿quién?"],["ou","viene"],["che sy","mi mamá"]]}],"watch":{"note":"Ir y venir son irregulares. Con a-, la raíz de «ir» es ha: aha. Con re- y o- es ho: reho, oho. Y «viene» es ou: oju no existe.","bad":"Ha'e oju.","good":"Ha'e ou."}}],"compare":{"intro":"Tres personas en un verbo: el prefijo cambia y la raíz queda, salvo en «ir», donde hasta la raíz cambia.","forms":[{"form":"a-","tag":"yo","mark":"dot","gn":"Che {a}ha ko ka'aru.","es":"Yo voy esta tarde."},{"form":"re-","tag":"vos","mark":"dot","gn":"Nde {re}ho ko ka'aru.","es":"Vos vas esta tarde."},{"form":"o-","tag":"él, ella","mark":"dot","gn":"Ha'e {o}ho ko ka'aru.","es":"Él va esta tarde."}],"check":{"id":"a1u02d1.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Mávapa ^ou^ ko pyhare?\nAna: (   ) che ru.","options":["Aju","Reju","Ou"],"answer":3,"why":["Aju es «vengo», con a-: Ana hablaría de ella misma, y habla de su papá.","Reju es «venís», con re-: la que viene sería Rosa, y Ana habla de su papá.","Ana habla de su papá, otra persona: ou, «viene». Ou che ru es «viene mi papá»."]}},"drill":[{"id":"a1u02d1.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la fiesta, Rosa cuenta qué hace esta noche.)\nRosa: ^Che^ (   ) ko pyhare.","options":["apurahéi","repurahéi","opurahéi","purahéi"],"answer":1,"why":["Che es «yo», y el verbo lo repite al principio: a- + purahéi = apurahéi, «canto».","repurahéi es «cantás», con re-, «vos». Rosa habla de ella misma, no de vos.","opurahéi es «canta», con o-: sería otra persona, él o ella.","purahéi sin prefijo es «canción», la cosa: che purahéi sería «mi canción». Le falta la persona: a-."]},{"id":"a1u02d1.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana: (   ) ^remba'apo^ [heta|mucho], Luis.","options":["Che","Nde","Ha'e","Mávapa"],"answer":2,"why":["Che es «yo» y va con a-: che amba'apo. Acá el verbo lleva re-.","re- es «vos»: nde remba'apo, «vos trabajás». Ana le habla a Luis.","Ha'e es «él» o «ella» y va con o-: ha'e omba'apo.","Mávapa, «¿quién?», pregunta por otra persona y va con o-: Mávapa omba'apo? Con re- no cuadra."]},{"id":"a1u02d1.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: Ana, ^rehópa^ ko ka'aru?\nAna: Héẽ, (   ) ko ka'aru.","options":["aha","aho","reho","oho"],"answer":1,"why":["Luis pregunta con re-, «vos», y Ana responde por ella misma, con a-. Con a-, la raíz de «ir» es ha: aha, «voy».","aho no existe: ho es la raíz de «ir» con re- y con o-, nunca con a-.","reho es «vas», con re-: es lo que pregunta Luis. Ana responde por ella misma.","oho es «va», con o-: sería otra persona, no Ana."]},{"id":"a1u02d1.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: ^Che ru^ (   ) ko ka'aru, ha che sy ou ko pyhare.","options":["aha","oha","reho","oho"],"answer":4,"why":["aha es «voy», con a-: Rosa hablaría de ella misma, y habla de su papá.","oha no existe: con o-, la raíz de «ir» es ho. Con a- es ha: aha.","reho es «vas», con re-: Rosa le hablaría a vos. Ella habla de su papá, otra persona.","Che ru, «mi papá», es otra persona: o- + ho = oho, «va». Mi papá va esta tarde, y mi mamá viene esta noche."]},{"id":"a1u02d1.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Luis, ","after":" ko pyhare?","tiles":["re","ju","pa"],"bank":[2,0,1],"hint":"re- es «vos» y va primero; -pa cierra la pregunta. Después fijate dónde queda el acento.","full":"Luis, {re}jú{pa} ko pyhare?","es":"Luis, ¿venís esta noche?","explain":"re- (vos) + ju (venir) + -pa (pregunta) = rejúpa, «¿venís?». La -pa no se lleva el acento: queda en la u de ju, que ya no es la última vocal, y se escribe ú."},{"id":"a1u02d1.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Nde sy ","after":" ko ka'aru?","tiles":["o","ho","pa"],"bank":[1,2,0],"hint":"Nde sy, «tu mamá», es otra persona: el verbo empieza con o-, y con o- la raíz de «ir» es ho. -pa va al final.","full":"Nde sy {o}hó{pa} ko ka'aru?","es":"¿Tu mamá va esta tarde?","explain":"Nde sy es otra persona: o- + ho = oho, «va». -pa cierra la pregunta: ohópa. El acento queda en la o de ho, que ya no es la última vocal, y se escribe ó."}],"exam":[{"id":"a1u02d1.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Ana: _Che apurahéi ko pyhare_.","options":["Vos cantás esta noche.","Yo canto esta noche.","Ella canta esta noche.","Yo bailo esta noche."],"answer":2,"explain":"Che es «yo», y a- lo repite al principio del verbo: apurahéi es «canto». «Cantás» sería repurahéi, con re-; «canta», opurahéi, con o-; y «bailo», ajeroky."},{"id":"a1u02d1.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa habla de su mamá.)\nRosa: Che sy (   ) ko pyhareve.","options":["aju","reju","oju","ou"],"answer":4,"explain":"Che sy, «mi mamá», es otra persona: el verbo lleva o-. Y con o-, «venir» es ou: oju no existe. Aju es «vengo», con a-, y reju, «venís», con re-."},{"id":"a1u02d1.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana invita a Luis.)\nAna: ","after":" ko ka'aru, Luis?","tiles":["re","ju","pa"],"bank":[1,2,0],"full":"(Ana invita a Luis.)\nAna: Rejúpa ko ka'aru, Luis?","es":"Ana: ¿Venís esta tarde, Luis?","explain":"re- (vos) va primero: Ana le habla a Luis. Después la raíz ju, «venir», y al final -pa, que hace la pregunta: rejúpa, «¿venís?». La -pa no se lleva el acento: queda en la u, que ya no es la última vocal, y se escribe ú."}]},"words":{"es":"Un sábado en casa de Ana","intro":"Es sábado en la casa de Ana, en Itauguá. Tocá cada acción: todas empiezan con a-, «yo».","sound":{"focus":"La j y la h","letters":["j","h"],"note":"La j guaraní suena como la y de «yo» en boca de un paraguayo, o la j inglesa de «John»: nunca la jota castellana. La jota suave paraguaya, un soplo, se escribe h y siempre suena: aha, ahendu, heta. Acá no usamos pares mínimos: comparamos palabras.","pairs":[["ajapo","hago","aha","voy"],["ajeroky","bailo","ahendu","escucho"],["jagua","perro","heta","mucho"]]},"words":[{"id":"ajapo","gn":"ajapo","es":"hago","parts":[["a-","yo"],["japo","hacer"]],"note":"La j suena como la y de «yo» en boca de un paraguayo, o la j inglesa de «John»: nunca la jota."},{"id":"ajeroky","gn":"ajeroky","es":"bailo","parts":[["a-","yo"],["jeroky","bailar"]],"note":"jeroky también es «danza»: el baile y la acción."},{"id":"aju","gn":"aju","es":"vengo","parts":[["a-","yo"],["ju","venir"]],"note":"Con vos: reju. Con él o ella: ou, sin j."},{"id":"aha","gn":"aha","es":"voy","parts":[["a-","yo"],["ha","ir"]],"note":"La h suena: un soplo, como la jota suave paraguaya. Con vos: reho; con él o ella: oho."},{"id":"ahendu","gn":"ahendu","es":"escucho, oigo","parts":[["a-","yo"],["hendu","oír"]],"note":"nd es una sola letra: a-he-ndu."},{"id":"apurahei","gn":"apurahéi","es":"canto","parts":[["a-","yo"],["purahéi","cantar"]],"note":"purahéi también es «canción». Lleva tilde: el acento no cae en la última vocal."},{"id":"ambaapo","gn":"amba'apo","es":"trabajo","parts":[["a-","yo"],["mba'apo","trabajar"]],"note":"mba'apo también es «trabajo», la cosa. El puso corta la voz: mba-'a-po."},{"id":"akaru","gn":"akaru","es":"como (de comer)","parts":[["a-","yo"],["karu","comer"]],"note":"karu también es «almuerzo»."}],"spell":["ajeroky","ahendu","apurahei","ajapo"],"check":{"id":"a1u02d1.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Es sábado y Ana _canta_ en el patio. ¿Cómo se escribe en guaraní?","options":["opurajéi","opurahéi","opurahéy","opuraéi"],"answer":2,"explain":"Canta es opurahéi: con o-, porque es Ana, otra persona, y con h, que suena como la jota suave paraguaya. Opurajéi la escribe con j, que es otra letra: suena como la j inglesa de «John». Opurahéy cambia la i por la y, que en guaraní es otra vocal, la sexta. Opuraéi se come la h, que nunca es muda."}},"skill":{"kind":"listening","es":"Respuesta rápida","situation":"En el patio, Ana le pregunta a Luis qué hace.","ask":"¿Qué responde Luis?","item":{"id":"a1u02d1.r1","kind":"choice","area":"listening","label":"Respuesta rápida","q":"¿Qué responde Luis?","options":["Amba'apo.","Remba'apo.","Omba'apo."],"answer":1,"why":["Ana pregunta con re-, «vos»: rejapo, «hacés». Luis responde por él, con a-: amba'apo, «trabajo».","Remba'apo es «trabajás», con re-: Luis hablaría de Ana, no de él.","Omba'apo es «trabaja», con o-: sería otra persona, no Luis."],"script":["Narrador: En el patio. ¿Qué responde Luis?","Mujer: Mba'épa rejapo, Luis?","Narrador: 1","Hombre: Amba'apo.","Narrador: 2","Hombre: Remba'apo.","Narrador: 3","Hombre: Omba'apo."]},"audio":[["N","En el patio. ¿Qué responde Luis?","En el patio. ¿Qué responde Luis?"],["F","Mba'épa rejapo, Luis?","¿Qué hacés, Luis?"],["N","1","1"],["M","Amba'apo.","Trabajo."],["N","2","2"],["M","Remba'apo.","Trabajás."],["N","3","3"],["M","Omba'apo.","Trabaja."]]}},{"title":"ja-/ña-, ro-, pe-: plural de persona","grammar":{"points":[{"id":"a1u02d2.p1","form":"ja- / ña- · ro-","gloss":"nosotros con vos · nosotros sin vos","connect":[{"pos":"ja- es el «nosotros» de ñande: incluye al que escucha","rule":"Ñande {ja}karu."},{"pos":"Si la raíz es nasal (lleva ñ, m, n, mb, nd, ng, nt o una vocal con ~), ja- se vuelve ña-","rule":"{ña}ñe'ẽ · {ña}mba'apo · {ña}hendu"},{"pos":"ro- es el «nosotros» de ore, sin el que escucha; no cambia","rule":"Ore {ro}karu · {ro}mba'apo"}],"examples":[{"gn":"Ñande {ja}karu ko ka'aru.","es":"Nosotros (con vos) comemos esta tarde.","parts":[["ñande","nosotros, con vos"],["ja-","nosotros (con vos)"],["karu","comer"],["ko ka'aru","esta tarde"]]},{"gn":"{Ña}ñe'ẽ guaraníme.","es":"Hablamos (vos y yo) en guaraní.","parts":[["ña-","nosotros (con vos)"],["ñe'ẽ","hablar"],["guaraníme","en guaraní"]]},{"gn":"Ore {ro}mba'apo ko pyhareve.","es":"Nosotros (sin vos) trabajamos esta mañana.","parts":[["ore","nosotros, sin vos"],["ro-","nosotros (sin vos)"],["mba'apo","trabajar"],["ko pyhareve","esta mañana"]]},{"gn":"Ore {ro}ju ko ka'aru ha {ro}ho ko pyhare.","es":"Venimos esta tarde y nos vamos esta noche (sin vos).","parts":[["ore","nosotros, sin vos"],["ro-","nosotros (sin vos)"],["ju","venir"],["ko ka'aru","esta tarde"],["ha","y"],["ho","ir"],["ko pyhare","esta noche"]]}],"watch":{"note":"Delante de una raíz nasal, ja- se vuelve ña-: jañe'ẽ y jamba'apo no existen. Ro- no cambia: roñe'ẽ, romba'apo.","bad":"Jañe'ẽ guaraníme.","good":"Ñañe'ẽ guaraníme."}},{"id":"a1u02d2.p2","form":"pe- · o-","gloss":"ustedes · ellos, ellas","connect":[{"pos":"pe- es el prefijo de peẽ, «ustedes»; no cambia ante una raíz nasal","rule":"Peẽ {pe}karu · {pe}hendu"},{"pos":"Ellos y ellas llevan o-, igual que él o ella: el pronombre o la situación dice que son varios","rule":"Ha'ekuéra {o}mba'apo."},{"pos":"Para preguntarles a varios adónde van","rule":"Moõpa {pe}ho?"}],"examples":[{"gn":"Peẽ {pe}purahéi.","es":"Ustedes cantan.","parts":[["peẽ","ustedes"],["pe-","ustedes"],["purahéi","cantar"]]},{"gn":"Peẽ {pe}jeroky ko pyhare.","es":"Ustedes bailan esta noche.","parts":[["peẽ","ustedes"],["pe-","ustedes"],["jeroky","bailar"],["ko pyhare","esta noche"]]},{"gn":"Ha'ekuéra {o}mba'apo heta.","es":"Ellos (o ellas) trabajan mucho.","parts":[["ha'ekuéra","ellos, ellas"],["o-","ellos, ellas"],["mba'apo","trabajar"],["heta","mucho"]]},{"gn":"Moõpa {pe}ho?","es":"¿Adónde van ustedes?","parts":[["moõ","dónde"],["-pa","pregunta"],["pe-","ustedes"],["ho","ir"]]}],"watch":{"note":"Si les hablás a varios, no uses re-: re- es para una sola persona. Para ustedes va pe-.","bad":"Peẽ rekaru.","good":"Peẽ pekaru."}}],"compare":{"intro":"Dos «nosotros» que el castellano no separa, y el «ustedes»: fijate si el que escucha come o no.","forms":[{"form":"ja-","tag":"nosotros con vos","mark":"dot","gn":"Ñande {ja}karu.","es":"Comemos, vos y yo."},{"form":"ro-","tag":"nosotros sin vos","mark":"dot","gn":"Ore {ro}karu.","es":"Comemos, sin vos."},{"form":"pe-","tag":"ustedes","mark":"dot","gn":"Peẽ {pe}karu.","es":"Ustedes comen."}],"check":{"id":"a1u02d2.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana les pregunta a Luis y a Rosa ^adónde van^.)\nAna: Moõpa (   )?","options":["jaha","roho","peho"],"answer":3,"why":["Jaha es «vamos», con ja-: incluiría a Ana, y ella pregunta por Luis y Rosa.","Roho es «vamos, sin vos»: Ana hablaría de ella y de otros. Pero pregunta por los dos que la escuchan.","Ana les pregunta a Luis y a Rosa, los que escuchan: «ustedes», peẽ, lleva pe-. Moõpa peho?: ¿adónde van?"]}},"drill":[{"id":"a1u02d2.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le habla ^a Luis^.)\nAna: Ñande (   ) ko ka'aru.","options":["jakaru","rokaru","pekaru","okaru"],"answer":1,"why":["Ana le habla a Luis y lo incluye: ñande, «nosotros con vos», lleva ja-. Ñande jakaru: comemos, Ana y Luis.","Ro- es el prefijo de ore, «nosotros sin vos». Con ñande no va: Luis está incluido.","Pe- es el prefijo de peẽ, «ustedes». Ana se incluye, por eso dice ñande.","O- es «él, ella» o «ellos, ellas». Ñande pide ja-."]},{"id":"a1u02d2.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis y Ana trabajan esta mañana. Luis se lo dice ^a Ana^.)\nLuis: Ñande (   ) ko pyhareve.","options":["jamba'apo","ñamba'apo","romba'apo","omba'apo"],"answer":2,"why":["Mba'apo empieza con mb, una letra nasal: ja- se vuelve ña-. Jamba'apo no existe.","Ñande pide ja-, y como mba'apo es nasal (mb), ja- se vuelve ña-: ñamba'apo, «trabajamos, vos y yo».","Ro- es el prefijo de ore, «nosotros sin vos». Luis incluye a Ana, que lo escucha: ñande.","O- es «él, ella» o «ellos». Luis habla de él y de Ana: ñande."]},{"id":"a1u02d2.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana les habla a Luis y a Rosa.)\nAna: ^Peẽ^ (   ) ko pyhare.","options":["rejeroky","pejeroky","jajeroky","ojeroky"],"answer":2,"why":["Re- es «vos», una sola persona. Ana les habla a dos: peẽ, con pe-.","Peẽ, «ustedes», lleva pe-: pejeroky, «ustedes bailan».","Ja- es el «nosotros» de ñande e incluiría a Ana. Ella habla de Luis y de Rosa, los que escuchan: peẽ.","O- es «él, ella» o «ellos»: así Ana hablaría de otras personas, no de los dos que la escuchan."]},{"id":"a1u02d2.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis habla de ^sus abuelos^: «Ha'ekuéra (   ) heta.»","options":["amba'apo","remba'apo","romba'apo","omba'apo"],"answer":4,"why":["A- es «yo». Luis habla de sus abuelos, no de él.","Re- es «vos», el que escucha. Luis habla de otras personas.","Ro- es «nosotros sin vos» y sumaría a Luis. Él habla solo de sus abuelos.","Ha'ekuéra, «ellos», lleva o-, igual que ha'e: omba'apo heta, «trabajan mucho»."]},{"id":"a1u02d2.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana les habla a Luis y a Rosa.)\nAna: Peẽ ","after":" ko ka'aru.","tiles":["pe","karu"],"bank":[1,0],"hint":"Pe- es el prefijo de peẽ, «ustedes»: va primero, pegado a la raíz.","full":"(Ana les habla a Luis y a Rosa.)\nAna: Peẽ {pe}karu ko ka'aru.","es":"(Ana les habla a Luis y a Rosa.)\nAna: Ustedes comen esta tarde.","explain":"pe- («ustedes») + karu («comer») = pekaru: el prefijo va primero, pegado a la raíz. Peẽ pekaru ko ka'aru: ustedes comen esta tarde. El acento queda en la u final, así que no se escribe tilde."},{"id":"a1u02d2.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana invita a Luis.)\nAna: ","after":" guaraníme!","tiles":["ña","ñe'ẽ"],"bank":[1,0],"hint":"ñe'ẽ es nasal: ¿qué prefijo lleva el «nosotros con vos»? Va primero, pegado a la raíz.","full":"(Ana invita a Luis.)\nAna: {Ña}ñe'ẽ guaraníme!","es":"(Ana invita a Luis.)\nAna: ¡Hablemos en guaraní!","explain":"ña- («nosotros, con vos») + ñe'ẽ («hablar») = ñañe'ẽ: como ñe'ẽ es nasal, no va ja-. Ñañe'ẽ es «hablamos» y también, como invitación, «¡hablemos!», igual que Jaha! o Jakaru!. El acento está en la ẽ, y la tilde nasal ya lo marca: no se escribe otro acento."}],"exam":[{"id":"a1u02d2.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa le escribe a Juan: «_Ore roju_ ko pyhare.»","options":["Ustedes vienen esta noche.","Venimos esta noche, vos también.","Venimos esta noche, sin vos.","Ellos vienen esta noche."],"answer":3,"explain":"Ore es «nosotros sin vos», y ro- es su prefijo: ore roju, «venimos», sin Juan, el que lee. Con Juan incluido sería ñande, con ja-; «ustedes vienen» sería peẽ peju, y «ellos vienen», ha'ekuéra ou."},{"id":"a1u02d2.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana y Luis van esta tarde a la casa de la abuela Ramona. Ana la llama y le avisa.)\nAna: (   ) ko ka'aru, ña Ramona.","options":["Aju","Roju","Peju","Ou"],"answer":2,"explain":"Ana habla de ella y de Luis, los que van, y la abuela, que la escucha, no está en el grupo: ore, con ro-. Roju ko ka'aru: venimos esta tarde. Aju sería «vengo», Ana sola, y Luis también va; peju, «ustedes vienen», como si la abuela viniera; ou, «viene», otra persona sola, sin Ana."},{"id":"a1u02d2.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Ñande ","after":" ko pyhareve.","tiles":["ña","mba'apo"],"bank":[1,0],"full":"Ñande {ñamba'apo} ko pyhareve.","es":"Nosotros (con vos) trabajamos esta mañana.","explain":"Ña- va primero: es el prefijo, la parte que dice quién. Mba'apo es nasal por el mb, y por eso el «nosotros con vos» es ña-, no ja-: ñamba'apo, «trabajamos»."}]},"words":{"gn":"Jaha!","es":"Domingo en familia","intro":"Domingo en lo de la abuela Ramona, en Caacupé: sopa paraguaya del tatakua, el horno de barro, y después, baile. Tocá cada palabra: cada una empieza con el prefijo que dice quiénes.","sound":{"focus":"La r, siempre suave","letters":["r","rr"],"note":"La r guaraní es siempre la r suave de «caro», también al principio de la palabra: ru, réra, roju, nunca «rroju». La rr fuerte solo aparece en préstamos del castellano, como karréta y vúrro. No hay pares mínimos r/rr en palabras guaraníes: comparamos palabras.","pairs":[["ru","padre","vúrro","burro"],["nde réra","tu nombre","karréta","carreta"],["roju","venimos (sin vos)","arro","arroz"]]},"words":[{"id":"jaha","gn":"Jaha!","es":"¡Vamos!","parts":[["ja-","nosotros (con vos)"],["ha","ir"]],"note":"Se dice hasta en castellano paraguayo. Es «vamos» y también «vayamos»."},{"id":"jakaru","gn":"jakaru","es":"comemos (vos y yo)","parts":[["ja-","nosotros (con vos)"],["karu","comer"]],"note":"También sirve para invitar: Jakaru!, «¡comamos!»."},{"id":"nanee","gn":"ñañe'ẽ","es":"hablamos (vos y yo)","parts":[["ña-","nosotros (con vos)"],["ñe'ẽ","hablar"]],"note":"ñe'ẽ es nasal: ja- se vuelve ña-."},{"id":"nambaapo","gn":"ñamba'apo","es":"trabajamos (vos y yo)","parts":[["ña-","nosotros (con vos)"],["mba'apo","trabajar"]],"note":"mb es nasal: ña-. El puso corta: ña-mba-'a-po."},{"id":"roju","gn":"roju","es":"venimos (sin vos)","parts":[["ro-","nosotros (sin vos)"],["ju","venir"]],"note":"La r es suave, como en «caro», también al principio: no es «rroju»."},{"id":"roho","gn":"roho","es":"vamos (sin vos)","parts":[["ro-","nosotros (sin vos)"],["ho","ir"]],"note":"Con ro- la raíz de «ir» es ho, como con re- y o-: roho, reho, oho. Con ja- es ha: jaha."},{"id":"peju","gn":"peju","es":"ustedes vienen; ¡vengan!","parts":[["pe-","ustedes"],["ju","venir"]],"note":"Con pe- la misma forma sirve para invitar: Peju!, «¡vengan!»."},{"id":"pekaru","gn":"pekaru","es":"ustedes comen","parts":[["pe-","ustedes"],["karu","comer"]],"note":"Y para invitar a varios: Pekaru!, «¡coman!»."}],"spell":["nanee","nambaapo","roju","pekaru"],"check":{"id":"a1u02d2.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Le decís a Ana: «Vos y yo _trabajamos_.» ¿Cómo se escribe en guaraní?","options":["ñamba'apo","jamba'apo","ñambaapo","ñama'apo"],"answer":1,"explain":"Trabajamos, vos y yo, es ñamba'apo: mba'apo es nasal por el mb, así que el prefijo es ña-, no ja-. Ñambaapo pierde el puso, que corta la voz entre las dos a: mba-'a-po. Y en ñama'apo cambió la raíz: la que cambia es la parte de adelante, ja- a ña-; mba'apo queda igual."}},"skill":{"kind":"reading","es":"Un mensaje al grupo","ask":"¿Quiénes comen esta tarde?","seconds":60,"passage":"Mba'éichapa? Ko ka'aru ^jakaru^ ha ^jajeroky^. Oĩ chipa ha so'o. ^Peju^!\nAna","strategy":"Mirá el prefijo del verbo: ja- incluye a los que leen el mensaje; ro- los dejaría afuera.","item":{"id":"a1u02d2.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Quiénes comen esta tarde?","options":["Ana y los del grupo, con vos.","Ana y su familia, sin el grupo.","Solo los del grupo, sin Ana.","Ana sola."],"short":["Ana y el grupo","Ana y su familia","Solo el grupo","Ana sola"],"answer":1,"why":["Jakaru lleva ja-, el «nosotros» de ñande: incluye a los que leen el mensaje, el grupo, con vos.","Sin el grupo sería ore, con ro-: rokaru. Ana escribe jakaru.","Solo ustedes, sin Ana, sería peẽ pekaru, con pe-. Peju! sí lleva pe-, pero es la invitación: «vengan».","Ana sola sería akaru, con a-. Jakaru habla de varios, con vos."],"explain":"Ana escribe jakaru ha jajeroky: ja- es el «nosotros» de ñande, que incluye a los que leen. Comen Ana y los del grupo, con vos. Peju!, con pe-, es la invitación: «vengan»."}}},{"title":"-pe/-me «en, a»","grammar":{"points":[{"id":"a1u02d3.p1","form":"-pe","gloss":"en, a (lugar)","connect":[{"pos":"Después del lugar y pegado; no delante, como el «en» castellano","rule":"óga → óga{pe} · mbo'ehao → mbo'ehaó{pe}"},{"pos":"Con ir es «a»; con estar es «en»","rule":"Aha mbo'ehaó{pe} · Che sy oĩ óga{pe}"},{"pos":"-pe no se lleva el acento: la raíz lo guarda y, si esa vocal ya no es la última, lleva tilde","rule":"koty → kotý{pe} · ka'aguy → ka'aguý{pe}"}],"examples":[{"gn":"Che amba'apo mbo'ehaó{pe}.","es":"Yo trabajo en la escuela.","parts":[["che","yo"],["a-","yo"],["mba'apo","trabajar"],["mbo'ehao","escuela"],["-pe","en"]]},{"gn":"Aha che jarýi róga{pe}.","es":"Voy a la casa de mi abuela.","parts":[["aha","voy"],["che jarýi","mi abuela"],["róga","casa (óga después de su dueño: che róga)"],["-pe","a"]]},{"gn":"Che ru oĩ kotý{pe}.","es":"Mi papá está en la pieza.","parts":[["che ru","mi papá"],["oĩ","está (y también «hay»)"],["koty","pieza, cuarto"],["-pe","en"]]},{"gn":"Rosa: Moõpa remba'apo, Juan?\nJuan: Kokué{pe}.","es":"Rosa: ¿Dónde trabajás, Juan?\nJuan: En la chacra.","parts":[["moõpa","¿dónde?"],["remba'apo","trabajás"],["kokue","chacra"],["-pe","en"]]}],"watch":{"note":"El castellano dice «en la escuela», con «en» delante. El guaraní lo pega atrás: mbo'ehaópe. Y la tilde: mbo'ehao lleva el acento en la o final; con -pe esa o ya no es la última vocal, y se escribe mbo'ehaópe.","bad":"mbo'ehaope","good":"mbo'ehaópe"}},{"id":"a1u02d3.p2","form":"-me","gloss":"en, a (tras sílaba nasal)","connect":[{"pos":"Si la última sílaba es nasal (vocal con ~, o junto a m, n, ñ), -pe se vuelve -me","rule":"tetã → tetã{me} · ñu → ñú{me} · guarani → guaraní{me}"},{"pos":"Sobre una vocal con ~ no se agrega tilde: la ~ ya marca el acento","rule":"tetã → tetã{me} · [ñe'ẽ|lengua] → ñe'ẽ{me}"},{"pos":"Si la última sílaba es oral, va -pe aunque antes haya ñ o mb: -pe/-me solo miran la última sílaba, no toda la raíz como ña-","rule":"mbo'ehao → mbo'ehaó{pe} · Ñemby → Ñembý{pe}"}],"examples":[{"gn":"Añe'ẽ guaraní{me}.","es":"Hablo en guaraní.","parts":[["a-","yo"],["ñe'ẽ","hablar"],["guarani","guaraní"],["-me","en (tras sílaba nasal)"]]},{"gn":"Ha'ekuéra omba'apo ñú{me}.","es":"Ellos trabajan en el campo.","parts":[["ha'ekuéra","ellos, ellas"],["o-","ellos, ellas"],["mba'apo","trabajar"],["ñu","campo"],["-me","en (tras sílaba nasal)"]]},{"gn":"Luis oho Ñembý{pe}, ha Rosa oho ñú{me}.","es":"Luis va a Ñemby, y Rosa va al campo.","parts":[["oho","va"],["Ñemby","Ñemby (una ciudad cerca de Asunción)"],["-pe","a (tras sílaba oral)"],["ha","y"],["ñu","campo"],["-me","a (tras sílaba nasal)"]]},{"gn":"Che sy omba'apo ko tetã{me}, Paraguái{pe}.","es":"Mi mamá trabaja en este país, en Paraguay.","parts":[["che sy","mi mamá"],["omba'apo","trabaja"],["ko","este"],["tetã","país"],["-me","en (tras sílaba nasal)"],["Paraguái","Paraguay, el país"],["-pe","en (tras sílaba oral)"]]}],"watch":{"note":"Después de una sílaba nasal no va -pe: no se dice tetãpe, se dice tetãme. Y sobre la ã no se agrega tilde: la ~ ya marca el acento.","bad":"tetãpe","good":"tetãme"}}],"compare":{"intro":"Dos formas de «en, a» y el «de» de la unidad 1: mirá la última sílaba del lugar y lo que querés decir.","forms":[{"form":"-pe","tag":"en, a · tras sílaba oral","mark":"dot","gn":"Che sy oĩ óga{pe}.","es":"Mi mamá está en casa."},{"form":"-me","tag":"en, a · tras sílaba nasal","mark":"dot","gn":"Añe'ẽ guaraní{me}.","es":"Hablo en guaraní."},{"form":"-gua","tag":"de (origen) · unidad 1 · -gua sí se lleva el acento","mark":"dot","gn":"Che Paraguai{gua}.","es":"Soy de Paraguay."}],"check":{"id":"a1u02d3.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis trabaja ^en el campo^.)\nLuis: Amba'apo (   ).","options":["ñúpe","ñúme","ñugua"],"answer":2,"why":["Ñu termina en sílaba nasal, por la ñ: ahí no va -pe.","La ñ hace nasal la u de ñu: -pe se vuelve -me. Amba'apo ñúme, «trabajo en el campo».","-gua es el «de» de origen, como en Paraguaigua: diría de dónde es Luis. Él dice dónde trabaja: ñúme."]}},"drill":[{"id":"a1u02d3.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis contesta que su mamá está ^en casa^.)\nAna: Moõpa oĩ nde sy, Luis?\nLuis: Oĩ (   ).","options":["ógape","ógame","óga","kotýpe"],"answer":1,"why":["Moõpa pregunta dónde, y Luis responde con un lugar: óga, «casa», con -pe pegado atrás. Óga termina en sílaba oral y guarda su tilde: ógape, «en casa».","-me va solo tras sílaba nasal, y ga es oral: ógape.","Óga solo es «casa», el nombre de la cosa. Para decir «en casa» hay que pegarle -pe.","Kotýpe es «en la pieza», y Luis dice que su mamá está en casa: óga."]},{"id":"a1u02d3.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan trabaja ^en la chacra^.)\nJuan: Amba'apo (   ).","options":["kokuéme","kokuépe","kokue","ka'aguýpe"],"answer":2,"why":["-me va tras sílaba nasal, y kue es oral: kokuépe.","Kokue termina en sílaba oral: va -pe. El acento queda en la e, que ya no es la última vocal, y se escribe: kokuépe, «en la chacra».","Kokue solo es «chacra». Para «en la chacra» se le pega -pe: kokuépe.","Ka'aguýpe es «en el monte», y Juan trabaja en la chacra: kokue."]},{"id":"a1u02d3.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta adónde va Luis: ^a Ñemby^.)\nAna: Luis oho (   ).","options":["Ñembýme","Ñembýpe","Ñemby","Ka'akupépe"],"answer":2,"why":["Ñemby tiene ñ y mb, pero la última sílaba es mby: mb es una letra distinta de m, y la y que la sigue es oral. Tras sílaba oral va -pe. El día 2, con ja-/ña-, una mb en la raíz ya pedía ña- (ñamba'apo): los prefijos miran toda la raíz; -pe/-me, solo la última sílaba.","Mirá la última sílaba: mby. Su vocal es oral, así que va -pe, y la y, que ya no es la última vocal, lleva tilde: Ñembýpe, «a Ñemby».","Ñemby solo es el nombre de la ciudad. Para «a Ñemby» se le pega -pe.","Ka'akupépe es «a Caacupé», y Luis va a Ñemby."]},{"id":"a1u02d3.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa cuenta dónde trabaja su papá: ^en este país^.)\nRosa: Che ru omba'apo ko (   ).","options":["tetãpe","tetáme","tetã","tetãme"],"answer":4,"why":["La ã es nasal: tras sílaba nasal, -pe se vuelve -me.","Tetáme perdió la ~, y la ~ es la que dice que la a es nasal y que ahí va el acento. Sin ella la palabra cambia: es tetãme, sin otra tilde.","Tetã solo es «país». Para decir «en este país» se le pega -me: ko tetãme.","Tetã termina en ã, nasal: va -me. Y sobre la ã no se agrega tilde: la ~ ya marca el acento. Ko tetãme, «en este país»."]},{"id":"a1u02d3.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Che amba'apo ","after":".","tiles":["mbo'ehao","pe"],"bank":[1,0],"hint":"-pe es un sufijo: va después del lugar, pegado. Después fijate dónde queda el acento.","full":"Che amba'apo {mbo'ehaópe}.","es":"Yo trabajo en la escuela.","explain":"mbo'ehao («escuela») + -pe («en») = mbo'ehaópe. La última sílaba de mbo'ehao es oral, así que va -pe. -pe no se lleva el acento: queda en la o de mbo'ehao, que ya no es la última vocal, y se escribe ó."},{"id":"a1u02d3.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Che jarýi oñe'ẽ ","after":".","tiles":["guarani","me"],"bank":[1,0],"hint":"La última sílaba de guarani es ni, con n: ¿va -pe o -me? Después fijate dónde queda el acento.","full":"Che jarýi oñe'ẽ {guaraníme}.","es":"Mi abuela habla en guaraní.","explain":"guarani + -me: la n hace nasal la última sílaba, así que no va -pe. -me no se lleva el acento: queda en la i de guarani, que ya no es la última vocal, y se escribe í: guaraníme."}],"exam":[{"id":"a1u02d3.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: Che ru _omba'apo ñúme_.","options":["Mi papá trabaja en el campo.","Mi papá va al campo.","Mi papá trabaja en la chacra.","Mi papá trabaja en la ciudad."],"answer":1,"explain":"Omba'apo es «trabaja», con o-, y ñúme es ñu, «campo», con -me, «en»: tras la ñ nasal no va -pe. «Va» sería oho; «la chacra», kokue; y «la ciudad», táva."},{"id":"a1u02d3.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta dónde está su abuela: en Caacupé.)\nAna: Che jarýi oĩ (   ).","options":["Ka'akupéme","Ka'akupe","Itauguápe","Ka'akupépe"],"answer":4,"explain":"Ka'akupe termina en pe, una sílaba oral: va -pe, y el acento queda en la e de Ka'akupe, que ya no es la última vocal: Ka'akupépe, «en Caacupé». -me va solo tras sílaba nasal, Ka'akupe solo es el nombre de la ciudad, sin «en», e Itauguápe es «en Itauguá», otra ciudad."},{"id":"a1u02d3.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Rosa: Amba'apo ko ","after":".","tiles":["tetã","me"],"bank":[1,0],"full":"Rosa: Amba'apo ko {tetãme}.","es":"Rosa: Trabajo en este país.","explain":"tetã («país») va primero y -me pegado atrás: tetãme, «en el país». La ã es nasal, así que no va -pe. El acento sigue en la ã, y la ~ ya lo marca: no se escribe otra tilde."}]},"words":{"gn":"Itauguápe","es":"El pueblo de Ana","intro":"Ana te muestra Itauguá y los lugares de su semana. Tocá cada palabra: ya llevan -pe o -me.","sound":{"focus":"La tilde con sufijo: ógape, kotýpe","letters":["á","é","í","ó","ú","ý"],"note":"-pe y -me no se llevan el acento: la raíz lo guarda y, si esa vocal ya no es la última, se escribe la tilde: koty → kotýpe, ka'aguy → ka'aguýpe. Sobre una vocal con ~ no se agrega tilde (tetã → tetãme); si la vocal es nasal solo por la ñ, la m o la n de al lado, no lleva ~ y sí puede llevar tilde: ñu → ñúme. Los pares mínimos de acento son raros en guaraní: acá comparamos cada palabra sola y con su sufijo.","pairs":[["óga","casa","ógape","en casa"],["koty","pieza","kotýpe","en la pieza"],["ñu","campo","ñúme","en el campo"],["tetã","país","tetãme","en el país"]]},"words":[{"id":"tavape","gn":"távape","es":"en el pueblo, en la ciudad","parts":[["táva","pueblo, ciudad"],["-pe","en, a"]],"note":"Táva lleva tilde: el acento no cae al final. Con -pe la guarda."},{"id":"kokuepe","gn":"kokuépe","es":"en la chacra","parts":[["kokue","chacra"],["-pe","en, a"]],"note":"Kokue termina en e: con -pe se escribe é."},{"id":"kaaguype","gn":"ka'aguýpe","es":"en el monte","parts":[["ka'aguy","monte, bosque"],["-pe","en, a"]],"note":"Ka'aguy termina en y: con -pe se escribe ý. El puso corta: ka-'a-guy."},{"id":"nume","gn":"ñúme","es":"en el campo","parts":[["ñu","campo"],["-me","en, a (tras nasal)"]],"note":"Ñu es nasal por la ñ: va -me, y la u se escribe ú."},{"id":"kotype","gn":"kotýpe","es":"en la pieza, en el cuarto","parts":[["koty","pieza, cuarto"],["-pe","en, a"]],"note":"Ana oĩ kotýpe: Ana está en la pieza."},{"id":"ysyrype","gn":"ysyrýpe","es":"en el arroyo","parts":[["ysyry","arroyo"],["-pe","en, a"]],"note":"Tres veces la y, la sexta vocal, y la última con tilde."},{"id":"tetame","gn":"tetãme","es":"en el país","parts":[["tetã","país"],["-me","en, a (tras nasal)"]],"note":"Sobre la ã no se pone tilde: la ~ ya marca el acento."},{"id":"koape","gn":"ko'ápe","es":"aquí, acá","note":"Termina en -pe, como los lugares. Se escribe con puso y con tilde en la á: ko-'á-pe."}],"spell":["kotype","kaaguype","nume","tetame"],"check":{"id":"a1u02d3.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana está en la pieza: «Ana oĩ _en la pieza_.» ¿Cómo se escribe en guaraní?","options":["kotýme","kotípe","kotýpe","cotýpe"],"answer":3,"explain":"En la pieza es kotýpe: koty, «pieza», con -pe. El acento queda en la y, que ya no es la última vocal, y lleva tilde. Kotýme lleva -me, que va solo tras sílaba nasal; kotípe cambia la y por i, otra vocal; y cotýpe usa la c, que no es una letra del guaraní: acá va k."}},"skill":{"kind":"listening","es":"Comprensión de puntos clave","situation":"En la ronda de tereré, Rosa y Juan hablan de dónde trabajan.","ask":"¿Dónde trabaja Juan?","item":{"id":"a1u02d3.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Dónde trabaja Juan?","options":["En la escuela.","En la chacra.","En Itauguá."],"answer":2,"why":["La escuela es de Rosa: ella dice che amba'apo mbo'ehaópe, «yo trabajo en la escuela».","Juan dice amba'apo kokuépe: «trabajo en la chacra». Kokue es «chacra», y -pe, «en».","Itauguápe, «en Itauguá», también lo dice Rosa, de su escuela. Juan solo dice kokuépe."],"script":["Narrador: En la ronda de tereré. ¿Dónde trabaja Juan?","Mujer: Moõpa remba'apo, Juan?","Hombre: Amba'apo kokuépe. Ha nde?","Mujer: Che amba'apo mbo'ehaópe, Itauguápe.","Narrador: ¿Dónde trabaja Juan?"]},"audio":[["N","En la ronda de tereré. ¿Dónde trabaja Juan?","En la ronda de tereré. ¿Dónde trabaja Juan?"],["F","Moõpa remba'apo, Juan?","¿Dónde trabajás, Juan?"],["M","Amba'apo kokuépe. Ha nde?","Trabajo en la chacra. ¿Y vos?"],["F","Che amba'apo mbo'ehaópe, Itauguápe.","Yo trabajo en la escuela, en Itauguá."],["N","¿Dónde trabaja Juan?","¿Dónde trabaja Juan?"]]}},{"title":"-gui «de, desde»","grammar":{"points":[{"id":"a1u02d4.p1","form":"-gui","gloss":"de, desde (el lugar de donde se viene o se sale)","connect":[{"pos":"Después del lugar, pegado, como -pe","rule":"Itaugua → Itauguá{gui} · Paraguay → Paraguaý{gui}"},{"pos":"Con venir (ou) y con salir (osẽ: o- + sẽ, «salir»)","rule":"Ou Paraguaý{gui} · Osẽ tatakuá{gui}"},{"pos":"No cambia tras una sílaba nasal y no se lleva el acento: el acento queda en la raíz, que lleva tilde solo si hace falta","rule":"tetã{gui} · mbo'ehaó{gui}"}],"examples":[{"gn":"Che aju Itakuruví{gui}.","es":"Vengo de Itacurubí.","parts":[["che","yo"],["a-","yo"],["ju","venir"],["Itakuruvi","Itacurubí"],["-gui","de, desde"]]},{"gn":"Chipa osẽ tatakuá{gui}.","es":"El chipá sale del horno de barro.","parts":[["chipa","chipá"],["o-","él, ella: el chipá"],["sẽ","salir"],["tatakua","horno de barro"],["-gui","de"]]},{"gn":"Rosa ou Paraguaý{gui}.","es":"Rosa viene de Asunción.","parts":[["ou","viene"],["Paraguay","Asunción: así se llama en guaraní"],["-gui","de, desde"]]},{"gn":"Luis osẽ mbo'ehaó{gui} ko ka'aru.","es":"Luis sale de la escuela esta tarde.","parts":[["o-","él"],["sẽ","salir"],["mbo'ehao","escuela"],["-gui","de"],["ko ka'aru","esta tarde"]]}],"watch":{"note":"El castellano pone «de» delante: «vengo de Itauguá». El guaraní lo pega atrás, al nombre del lugar: Itauguágui. Ni delante ni separado.","bad":"Aju gui Itaugua.","good":"Aju Itauguágui."}},{"id":"a1u02d4.p2","form":"Moõguipa …?","gloss":"¿de dónde …?","connect":[{"pos":"moõ, «dónde», + -gui, «de», + -pa, la pregunta","rule":"{Moõguipa} reju?"},{"pos":"Se responde con el lugar y -gui","rule":"Aju Itauguá{gui}."},{"pos":"Compará con Moõpa, «dónde» o «adónde»: Moõpa reiko?, Moõpa reho?","rule":"{Moõpa} reho? · {Moõguipa} reju?"}],"examples":[{"gn":"{Moõguipa} ou?","es":"¿De dónde viene?","parts":[["moõ","dónde"],["-gui","de"],["-pa","pregunta"],["ou","viene"]]},{"gn":"Luis: {Moõguipa} reju, Ana?\nAna: Aju Itauguá{gui}.","es":"Luis: ¿De dónde venís, Ana?\nAna: Vengo de Itauguá.","parts":[["moõguipa","¿de dónde?"],["reju","venís"],["aju","vengo"],["Itauguágui","de Itauguá"]]},{"gn":"Rosa: {Moõguipa} osẽ ko chipa?\nAna: Tatakuá{gui}.","es":"Rosa: ¿De dónde sale este chipá?\nAna: Del horno de barro.","parts":[["osẽ","sale"],["ko","este"],["chipa","chipá"],["tatakua","horno de barro"],["-gui","de"]]},{"gn":"Ana: {Moõguipa} peju?\nLuis: Roju mbo'ehaó{gui}.","es":"Ana: ¿De dónde vienen ustedes?\nLuis: Venimos (sin vos) de la escuela.","parts":[["peju","ustedes vienen"],["roju","venimos (sin vos)"],["mbo'ehao","escuela"],["-gui","de"]]}],"watch":{"note":"-pa va al final de la palabra que pregunta, como en Mba'éichapa: moõ + gui + pa = Moõguipa. Moõpagui no existe.","bad":"Moõpagui reju?","good":"Moõguipa reju?"}}],"compare":{"intro":"Tres sufijos de lugar: adónde vas, de dónde venís y de dónde sos.","forms":[{"form":"-pe","tag":"a, en","mark":"dot","gn":"Aha Itauguá{pe}.","es":"Voy a Itauguá."},{"form":"-gui","tag":"de, desde","mark":"dot","gn":"Aju Itauguá{gui}.","es":"Vengo de Itauguá."},{"form":"-gua","tag":"de (origen) · unidad 1","mark":"dot","gn":"Che Itaugua{gua}.","es":"Soy de Itauguá."}],"check":{"id":"a1u02d4.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: ^Moõguipa^ reju, Juan?\nJuan: Aju (   ).","options":["Itauguápe","Itauguágui","Itauguagua"],"answer":2,"why":["-pe dice adónde va o dónde está: Aha Itauguápe, «voy a Itauguá». Rosa pregunta de dónde viene.","Moõguipa pregunta «¿de dónde?», y se responde con -gui: Aju Itauguágui, «vengo de Itauguá».","-gua dice de dónde sos: Che Itauguagua, «soy de Itauguá». Rosa pregunta de dónde viene Juan, no de dónde es."]}},"drill":[{"id":"a1u02d4.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa llega a Itauguá. Viene ^de Asunción^.)\nRosa: Aju (   ).","options":["Paraguaýpe","gui Paraguay","Paraguay","Paraguaýgui"],"answer":4,"why":["-pe es «a» o «en»: Aha Paraguaýpe, «voy a Asunción». Rosa viene de ahí: -gui.","A diferencia del «de» castellano, -gui no va delante ni separado: se pega al final del lugar, Paraguaýgui.","Paraguay solo es el nombre: Asunción. Para decir «de Asunción» hay que pegarle -gui atrás.","Rosa viene de Asunción: el lugar lleva -gui, pegado atrás. Paraguay lleva el acento en la y final; como -gui no se lo lleva, se escribe ý: Paraguaýgui."]},{"id":"a1u02d4.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis ^sale de la escuela^ esta tarde.)\nAna: Luis osẽ (   ) ko ka'aru.","options":["mbo'ehaógui","mbo'ehaópe","mbo'ehaóme","mbo'ehaõgui"],"answer":1,"why":["Luis sale de la escuela: el lugar lleva -gui, pegado atrás. Mbo'ehao lleva el acento en la o final; con -gui esa o ya no es la última vocal, y se escribe ó: mbo'ehaógui.","-pe es «a» o «en»: Oho mbo'ehaópe, «va a la escuela». Luis sale de ahí: -gui.","-me es la forma de -pe tras una sílaba nasal, y la última sílaba de mbo'ehao es oral, la o: el mb del principio no cuenta. Además diría «en»; Luis sale de ahí: -gui, que no cambia nunca.","La ~ es la tilde nasal: haría nasal la o y cambiaría el sonido, y mbo'ehao no tiene vocal nasal. El acento se marca con la tilde aguda: mbo'ehaógui."]},{"id":"a1u02d4.d3","kind":"choice","area":"grammar","label":"Elegí la palabra","q":"Ana: (   ) reju, Luis?\nLuis: ^Aju Paraguaýgui^.","options":["Moõpa","Mávapa","Moõguipa","Moõpagui"],"answer":3,"why":["Moõpa pregunta «dónde» o «adónde»: Moõpa reiko?, Moõpa reho? Luis responde de dónde viene, con -gui, y la pregunta también lo lleva.","Mávapa pregunta «¿quién?». Luis responde con un lugar, no con una persona.","Luis responde Aju Paraguaýgui, «vengo de Asunción»: la pregunta es Moõguipa reju?, «¿de dónde venís?», con moõ + -gui + -pa.","-pa cierra la palabra que pregunta, como en Mba'éichapa: moõ + gui + pa. Moõpagui no existe."]},{"id":"a1u02d4.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: ^Moõguipa^ osẽ ko chipa?\nAna: (   )","options":["Tatakuápe.","Tatakuágui.","Tatakuáme.","Gui tatakua."],"answer":2,"why":["Tatakuápe es «en el horno», con -pe: dice dónde está, no de dónde sale.","Luis pregunta de dónde sale el chipá, con -gui, y Ana responde con -gui: Tatakuágui, «del horno de barro».","-me es la forma de -pe tras una sílaba nasal, y kua, la última sílaba de tatakua, es oral. Además diría «en»; el chipá sale de ahí: -gui, que no cambia nunca.","A diferencia del «de» castellano, -gui no va delante ni separado: se pega al final del lugar, tatakuágui."]},{"id":"a1u02d4.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana llega a Caacupé, a la casa de su abuela.)\nAna: Aju ","after":".","tiles":["Itaugua","gui"],"bank":[1,0],"hint":"Itaugua es el lugar y -gui es el sufijo: va después, pegado. Después fijate dónde queda el acento.","full":"(Ana llega a Caacupé, a la casa de su abuela.)\nAna: Aju Itauguá{gui}.","es":"Ana: Vengo de Itauguá.","explain":"Itaugua («Itauguá») + -gui («de») = Itauguágui, «de Itauguá». -gui no se lleva el acento: queda en la a final de Itaugua, que ya no es la última vocal, y se escribe á."},{"id":"a1u02d4.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis llega a la casa de Ana.)\nAna: ","after":" reju, Luis?","tiles":["moõ","gui","pa"],"bank":[2,0,1],"hint":"moõ, «dónde», va primero. -pa cierra la pregunta, como en Mba'éichapa.","full":"(Luis llega a la casa de Ana.)\nAna: {Moõguipa} reju, Luis?","es":"Ana: ¿De dónde venís, Luis?","explain":"moõ («dónde») + -gui («de») + -pa (pregunta) = Moõguipa, «¿de dónde?». -pa va al final, como en Mba'éichapa: moõpagui no existe. Ni -gui ni -pa se llevan el acento: queda en la õ, y la tilde nasal ya lo marca."}],"exam":[{"id":"a1u02d4.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Luis: Moõguipa reju?\nAna: _Aju Itauguágui_.","options":["Voy a Itauguá.","Soy de Itauguá.","Vengo de Itauguá.","Vengo de Asunción."],"answer":3,"explain":"Aju es «vengo» (a-, «yo», + ju, «venir»), y -gui, pegado a Itaugua, es «de»: «vengo de Itauguá». «Voy a Itauguá» sería Aha Itauguápe, con -pe; «soy de Itauguá», Che Itauguagua, con -gua; y Asunción en guaraní es Paraguay, no Itaugua."},{"id":"a1u02d4.e2","kind":"choice","area":"grammar","label":"Elegí la palabra","q":"(Luis y Rosa llegan. Ana les pregunta de dónde vienen.)\nAna: (   ) peju?","options":["Moõpa","Mávapa","Moõpagui","Moõguipa"],"answer":4,"explain":"Ana pregunta «de dónde»: moõ («dónde») + -gui («de») + -pa (pregunta) = Moõguipa. Peju es «ustedes vienen», así que Moõguipa peju? es «¿de dónde vienen?». Moõpa pregunta «dónde» o «adónde», sin el «de»; Mávapa pregunta «quién»; y moõpagui no existe, porque -pa cierra la palabra."},{"id":"a1u02d4.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Rosa quiere saber de dónde viene la mamá de Ana.)\nRosa: ","after":" ou nde sy?","tiles":["moõ","gui","pa"],"bank":[1,2,0],"full":"(Rosa quiere saber de dónde viene la mamá de Ana.)\nRosa: {Moõguipa} ou nde sy?","es":"Rosa: ¿De dónde viene tu mamá?","explain":"moõ («dónde») va primero: es la palabra que pregunta. Después -gui («de»), y al final -pa, que cierra la pregunta, como en Mba'éichapa: Moõguipa, «¿de dónde?». Con ou nde sy, «viene tu mamá», queda «¿de dónde viene tu mamá?»."}]},"words":{"gn":"Moõguipa reju?","es":"¿De dónde venís? En la terminal","intro":"En la terminal de Asunción llega gente de todas partes. Tocá cada palabra: los lugares ya llevan -gui, «de».","sound":{"focus":"La armonía nasal: ña-, -me, n-","letters":["ã","ẽ","ñ","m","n"],"note":"Una raíz nasal (vocal con ~, o m, n, ñ, mb, nd, ng, nt) contagia el prefijo: ja- se vuelve ña- (ñañe'ẽ) y, mañana, nd- se vuelve n- (nañe'ẽi, «no hablo»). Los sufijos miran solo la última sílaba: tetãme, pero Ñembýpe; -gui no cambia: tetãgui. Los dos primeros pares son mínimos, oral contra nasal; los otros dos muestran el contagio.","pairs":[["tupa","cama","Tupã","Dios"],["pytu","aliento","pytũ","oscuro"],["ógape","en casa","tetãme","en el país"],["jakaru","comemos (vos y yo)","ñañe'ẽ","hablamos (vos y yo)"]]},"words":[{"id":"mooguipa","gn":"Moõguipa reju?","es":"¿De dónde venís?","parts":[["moõ","dónde"],["-gui","de"],["-pa","pregunta"],["reju","venís"]],"note":"Moõpa reiko? es «¿dónde vivís?» (unidad 1). Con -gui adentro, la pregunta es de dónde."},{"id":"paraguaygui","gn":"Paraguaýgui","es":"desde Asunción","parts":[["Paraguay","Asunción"],["-gui","de, desde"]],"note":"En guaraní, Paraguay (con y, acento al final) es Asunción. El país es Paraguái, con ái."},{"id":"ose","gn":"osẽ","es":"sale","parts":[["o-","él, ella"],["sẽ","salir"]],"note":"Palabra nueva: sẽ, «salir», con o-, el prefijo del día 1. Con -gui dice de dónde sale algo: Chipa osẽ tatakuágui."},{"id":"itauguagui","gn":"Itauguágui","es":"desde Itauguá","parts":[["Itaugua","Itauguá"],["-gui","de, desde"]],"note":"La capital del ñandutí. Itaugua termina en a: con -gui se escribe á."},{"id":"itakuruvigui","gn":"Itakuruvígui","es":"desde Itacurubí","parts":[["Itakuruvi","Itacurubí"],["-gui","de, desde"]],"note":"En castellano se escribe Itacurubí; en guaraní, con k y v. Con -gui, la i final se escribe í."},{"id":"tatakuagui","gn":"tatakuágui","es":"del horno de barro","parts":[["tatakua","horno de barro"],["-gui","de"]],"note":"tata, «fuego», y kua, «hueco». De ahí sale el chipá."},{"id":"nanduti","gn":"ñanduti","es":"ñandutí (encaje)","note":"Quiere decir «telaraña». Es el encaje de Itauguá, redondo como un sol. Como terere, no lleva tilde aguda: el acento va en la última vocal."},{"id":"kokuegui","gn":"kokuégui","es":"de la chacra","parts":[["kokue","chacra"],["-gui","de"]],"note":"En la chacra es kokuépe, del día 3. De la chacra, kokuégui: la é queda igual."}],"spell":["paraguaygui","itauguagui","itakuruvigui","tatakuagui"],"check":{"id":"a1u02d4.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa viene de Asunción: Rosa ou _desde Asunción_. ¿Cómo se escribe en guaraní?","options":["Paraguaýgui","Paraguaýgüi","Paraguáigui","Paraguaýpe"],"answer":1,"explain":"Desde Asunción es Paraguaýgui: Paraguay, «Asunción», lleva el acento en la y final, y como -gui no se lo lleva, esa y ya no es la última vocal y se escribe ý. Paraguaýgüi usa la diéresis del castellano: en guaraní la u de gu siempre suena, también delante de i, y la ü no es una letra del alfabeto. Paraguáigui es «desde Paraguay», el país, con ái. Y Paraguaýpe es «a Asunción» o «en Asunción», con -pe."}},"skill":{"kind":"reading","es":"Un chat en la terminal","ask":"¿De dónde viene Ana?","seconds":60,"passage":"Rosa: Mba'éichapa, Ana? ^Moõguipa reju?^\nAna: ^Aju Itauguágui.^ Aha Ka'akupépe, che jarýi rógape. Ha nde?\nRosa: Che aju Paraguaýgui. Aha Ñembýpe.\nAna: Jajotopáta, Rosa.","strategy":"Buscá -gui después del nombre de un lugar: ahí está el «de dónde». -pe dice adónde va. Y fijate quién habla.","item":{"id":"a1u02d4.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿De dónde viene Ana?","options":["De Asunción.","De Caacupé.","De Itauguá.","De Ñemby."],"short":["Asunción","Caacupé","Itauguá","Ñemby"],"answer":3,"why":["Paraguaýgui, «de Asunción», lo dice Rosa de ella misma: Che aju Paraguaýgui.","Ka'akupépe lleva -pe: es adónde va Ana, a la casa de su abuela, no de dónde viene.","Ana responde Aju Itauguágui: viene de Itauguá. El lugar lleva -gui, «de».","Ñembýpe lleva -pe, y lo dice Rosa: es adónde va ella."],"explain":"A Moõguipa reju? Ana responde Aju Itauguágui: -gui marca de dónde viene, Itauguá. Ka'akupépe y Ñembýpe llevan -pe, adónde va cada una, y Paraguaýgui es de donde viene Rosa."}}},{"title":"Negación nd-…-i: el «no» rodea al verbo","grammar":{"points":[{"id":"a1u02d5.p1","form":"nd-…-i","gloss":"no (raíz oral)","connect":[{"pos":"nd- delante del prefijo de persona y -i al final: dos partes, una sola palabra. Con vos, delante de re- va nde-: hoy solo lo mirás, no se practica","rule":"{nd}aguatá{i} · {nd}ereguatá{i} · {nd}oguatá{i}"},{"pos":"Con ir, venir y hacer","rule":"{nd}ahá{i} · {nd}ohó{i} · {nd}oú{i} · {nd}ajapó{i}"},{"pos":"-i no se lleva el acento: la raíz escribe su tilde","rule":"ndoguat{á}i · ndajap{ó}i · ndoh{ó}i"}],"examples":[{"gn":"Ko pyhareve {nd}ahá{i}.","es":"Esta mañana no voy.","parts":[["ko pyhareve","esta mañana"],["nd-","no, al principio"],["a-","yo"],["ha","ir"],["-i","no, al final"]]},{"gn":"Che sy {nd}ohó{i} mbo'ehaópe.","es":"Mi mamá no va a la escuela.","parts":[["che sy","mi mamá"],["nd-","no"],["o-","él, ella"],["ho","ir (con o-)"],["-i","no"],["mbo'ehaópe","a la escuela"]]},{"gn":"{Nd}ajapó{i} mba'eve.","es":"No hago nada.","parts":[["nd-","no"],["a-","yo"],["japo","hacer"],["-i","no"],["mba'eve","nada"]]},{"gn":"Luis {nd}oú{i} ko ka'aru: oky.","es":"Luis no viene esta tarde: llueve.","parts":[["nd-","no"],["ou","viene"],["-i","no"],["ko ka'aru","esta tarde"],["oky","llueve"]]}],"watch":{"note":"El castellano pone un solo «no» delante del verbo: «no voy». El guaraní necesita las dos partes, nd- al principio y -i al final, en una sola palabra. Con una sola, la frase queda a medias.","bad":"Ndaha mbo'ehaópe.","good":"Ndahái mbo'ehaópe."}},{"id":"a1u02d5.p2","form":"n-…-i","gloss":"no (raíz nasal)","connect":[{"pos":"Si la raíz es nasal, nd- se vuelve n-: na-, nere-, no-. Con sẽ, «salir»","rule":"{n}asẽ{i} · {n}eresẽ{i} · {n}osẽ{i}"},{"pos":"También con ñe'ẽ, mba'apo y hendu, que tienen ñ y ẽ, mb o nd","rule":"{n}añe'ẽ{i} · {n}omba'apó{i} · {n}ohendú{i}"},{"pos":"Sobre una vocal nasal no se agrega tilde: la ~ ya marca el acento","rule":"nos{ẽ}i · nañe'{ẽ}i"}],"examples":[{"gn":"Che {n}añe'ẽ{i} guaraníme.","es":"Yo no hablo guaraní.","parts":[["n-","no, al principio (raíz nasal)"],["a-","yo"],["ñe'ẽ","hablar"],["-i","no, al final"],["guaraníme","en guaraní"]]},{"gn":"Ha'e {n}ohendú{i} ha {n}oñe'ẽ{i}.","es":"Ella no oye y no habla.","parts":[["n-","no"],["o-","él, ella"],["hendu","oír"],["-i","no"],["ha","y"],["ñe'ẽ","hablar"]]},{"gn":"{N}amba'apó{i} ko pyhare.","es":"No trabajo esta noche.","parts":[["n-","no"],["a-","yo"],["mba'apo","trabajar"],["-i","no"],["ko pyhare","esta noche"]]},{"gn":"Che ru {n}osẽ{i} ógagui: oky.","es":"Mi papá no sale de la casa: llueve.","parts":[["che ru","mi papá"],["n-","no"],["o-","él"],["sẽ","salir"],["-i","no"],["ógagui","de la casa"],["oky","llueve"]]}],"watch":{"note":"Delante de una raíz nasal no va nd-: ndañe'ẽi y ndamba'apói no existen. Se dice nañe'ẽi, namba'apói: la n sola ya es la primera parte del «no».","bad":"Ndañe'ẽi guaraníme.","good":"Nañe'ẽi guaraníme."}}],"compare":{"intro":"Dos «no» dentro del verbo, según la raíz, y el «no» que responde solo.","forms":[{"form":"nd-…-i","tag":"no · raíz oral","mark":"dot","gn":"{Nd}ahá{i} mbo'ehaópe.","es":"No voy a la escuela."},{"form":"n-…-i","tag":"no · raíz nasal","mark":"dot","gn":"{N}añe'ẽ{i} guaraníme.","es":"No hablo guaraní."},{"form":"Nahániri","tag":"no · respuesta sola (unidad 1)","mark":"dot","gn":"{Nahániri}, ndahái.","es":"No, no voy."}],"check":{"id":"a1u02d5.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Reñe'ẽpa guaraníme, Lucas?\nLucas: ^Nahániri^, (   ).","options":["ndañe'ẽi","nañe'ẽi","añe'ẽ"],"answer":2,"why":["ñe'ẽ es una raíz nasal, por la ñ y la ẽ: delante no va nd-, sino n-. Ndañe'ẽi no existe.","Lucas dice que no y lo niega en el verbo: n- + añe'ẽ + -i = nañe'ẽi, «no hablo». Sobre la ẽ no se agrega tilde: la ~ ya marca el acento.","Añe'ẽ es «hablo», sin negación: Lucas diría que sí habla. Pero empieza con Nahániri, «no»."]}},"drill":[{"id":"a1u02d5.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: ^Rehópa^ kokuépe ko pyhareve, Juan?\nJuan: Nahániri, (   ): [oky|llueve].","options":["ndaha","nahái","ndahái","ndohói"],"answer":3,"why":["A ndaha le falta la -i del final. El «no» guaraní tiene dos partes, nd- y -i, y con una sola la palabra queda a medias.","ha, la raíz de «ir» con a-, es oral: delante va nd-, no n-. Nahái no existe.","Luis pregunta con re-, «vos», y Juan responde por él, con a-: aha, «voy». El «no» lo rodea: nd- + aha + -i = ndahái, «no voy». La -i no se lleva el acento, y la a de ha se escribe á.","Ndohói es «no va», con o-: sería otra persona. Juan habla de él mismo, con a-."]},{"id":"a1u02d5.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Llueve, y en la chacra no se trabaja.)\nJuan: ^Che ru^ (   ) ko pyhareve.","options":["nomba'apói","ndomba'apói","namba'apói","omba'apói"],"answer":1,"why":["Che ru, «mi papá», es otra persona: o-. Y mba'apo es una raíz nasal, por la mb: n- + omba'apo + -i = nomba'apói, «no trabaja».","Delante de una raíz nasal como mba'apo no va nd-, sino n-: nomba'apói.","Namba'apói es «no trabajo», con a-, «yo». Juan habla de su papá, con o-.","A omba'apói le falta la n- del principio: la -i sola no niega nada. El «no» necesita las dos partes."]},{"id":"a1u02d5.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana habla guaraní, pero su mamá no.)\nAna: Che añe'ẽ guaraníme, ha ^che sy^ (   ).","options":["nañe'ẽi","ndoñe'ẽi","oñe'ẽ","noñe'ẽi"],"answer":4,"why":["Nañe'ẽi es «no hablo», con a-: Ana hablaría de ella misma, y ella sí habla: añe'ẽ.","ñe'ẽ es una raíz nasal: delante va n-, no nd-. Ndoñe'ẽi no existe.","Oñe'ẽ es «habla», sin negación: diría que su mamá sí habla guaraní, y no es así.","Che sy es otra persona: o-. ñe'ẽ es nasal: n- + oñe'ẽ + -i = noñe'ẽi, «no habla». La ẽ ya lleva la tilde nasal: no se agrega otra."]},{"id":"a1u02d5.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa pregunta si Luis viene esta tarde.)\nAna: Nahániri, ^Luis^ (   ) ko ka'aru.","options":["ndoú","ndoúi","noúi","ou"],"answer":2,"why":["A ndoú le falta la -i del final: el «no» tiene dos partes, y con una sola la palabra queda a medias.","Luis es otra persona, y «viene» es ou. El «no» lo rodea: nd- + ou + -i = ndoúi, «no viene». La -i no se lleva el acento: queda en la u, que se escribe ú.","ou es una raíz oral: delante va nd-, no n-. Noúi no existe.","Ou es «viene», sin negación: diría que Luis sí viene, y Ana acaba de decir Nahániri, «no»."]},{"id":"a1u02d5.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Luis: Ko pyhareve ","after":" mba'eve.","tiles":["nd","a","japo","i"],"bank":[2,0,3,1],"hint":"El «no» rodea al verbo: nd- va primero y -i al final. En el medio, a- («yo») y la raíz japo, «hacer».","full":"Luis: Ko pyhareve {nd}ajapó{i} mba'eve.","es":"Luis: Esta mañana no hago nada.","explain":"nd- + a- («yo») + japo («hacer») + -i = ndajapói, «no hago». Las dos partes del «no» rodean al verbo. La -i no se lleva el acento: queda en la o de japo, que ya no es la última vocal, y se escribe ó. Con mba'eve, «nada»: «no hago nada»."},{"id":"a1u02d5.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Lucas recién empieza a estudiar guaraní.)\nLucas: Che ","after":" guaraníme.","tiles":["n","a","ñe'ẽ","i"],"bank":[3,2,0,1],"hint":"ñe'ẽ es nasal: la primera parte del «no» es n-, sin d. Después a- («yo»), la raíz y, al final, -i.","full":"(Lucas recién empieza a estudiar guaraní.)\nLucas: Che {n}añe'ẽ{i} guaraníme.","es":"Lucas: Yo no hablo guaraní.","explain":"n- + a- («yo») + ñe'ẽ («hablar») + -i = nañe'ẽi, «no hablo». Como ñe'ẽ es una raíz nasal, la primera parte del «no» es n-, no nd-. El acento queda en la ẽ, y la tilde nasal ya lo marca: no se agrega otra."}],"exam":[{"id":"a1u02d5.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"(Llueve.)\nLuis: Che ru _nosẽi_ ko pyhareve.","options":["Mi papá sale esta mañana.","Yo no salgo esta mañana.","Mi papá no viene esta mañana.","Mi papá no sale esta mañana."],"answer":4,"explain":"Lo subrayado es sẽ, «salir», con o-, otra persona, mi papá, y con el «no» en dos partes: n- al principio, porque sẽ es una raíz nasal, y -i al final: nosẽi, «no sale». «Sale» sería osẽ, sin negación; «yo no salgo» llevaría a-, «yo»; y «no viene» sería ndoúi."},{"id":"a1u02d5.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Llueve, y la mamá de Ana se queda en casa.)\nAna: Che sy (   ) mbo'ehaópe ko pyhareve.","options":["ndahái","ndohói","nohói","ndoho"],"answer":2,"explain":"Che sy, «mi mamá», es otra persona: o-, y con o- la raíz de «ir» es ho. El «no» la rodea: nd- + oho + -i = ndohói, «no va». Ndahái es «no voy», con a-; nohói lleva n-, que va solo delante de una raíz nasal, y ho es oral; y a ndoho le falta la -i: el «no» necesita las dos partes."},{"id":"a1u02d5.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Llueve.)\nRosa: Juan ","after":" kokuépe ko pyhareve.","tiles":["n","o","mba'apo","i"],"bank":[1,3,0,2],"full":"(Llueve.)\nRosa: Juan {n}omba'apó{i} kokuépe ko pyhareve.","es":"Rosa: Juan no trabaja en la chacra esta mañana.","explain":"n- va primero: mba'apo es una raíz nasal, por la mb, así que la primera parte del «no» es n-, no nd-. Después o- (él: Juan), la raíz mba'apo («trabajar») y, al final, -i: nomba'apói, «no trabaja». La -i no se lleva el acento: queda en la última o de mba'apo, que ya no es la última vocal, y se escribe ó."}]},"words":{"es":"Un día de lluvia","intro":"Llueve en Itauguá y nadie sale de la casa de Ana. Tocá cada palabra: mb, nd, ng y nt son una sola letra, con un solo sonido.","sound":{"focus":"Las letras mb, nd, ng, nt","letters":["mb","nd","ng","nt"],"note":"mb, nd, ng y nt son letras del alfabeto: un solo sonido, en una sola sílaba. Empezá con un zumbido, «mmm» o «nnn», y soltalo en la b o la d, sin poner una e delante: mba'e, no «embae». No hay pares mínimos seguros: comparamos palabras, con mb y nd al principio y con ng y nt adentro, donde van casi siempre.","pairs":[["mba'eve","nada","ndaipóri","no hay"],["angirũ","amigo, amiga","mante","nomás"],["mba'e","cosa; qué","ndahái","no voy"]]},"words":[{"id":"ama","gn":"ama","es":"lluvia","note":"La lluvia, la cosa. «Llueve» es oky."},{"id":"oky","gn":"oky","es":"llueve","parts":[["o-","él, ella"],["ky","llover"]],"note":"Un verbo con o-, como «llueve» en castellano: no hay quien lo haga."},{"id":"ndaikuaai","gn":"ndaikuaái","es":"no sé","parts":[["nd-","no"],["ai-","yo"],["kuaa","saber"],["-i","no"]],"note":"ai- es el «yo» de verbos como kuaa, como el rei- de reikuaa (unidad 1). Lo estudiamos en la unidad 5."},{"id":"ndahai","gn":"ndahái","es":"no voy","parts":[["nd-","no"],["a-","yo"],["ha","ir"],["-i","no"]],"note":"nd es una sola letra: nda-hái, sin e delante."},{"id":"mbaeve","gn":"mba'eve","es":"nada","note":"Va con un verbo negado: Ndajapói mba'eve, «no hago nada». Adentro está mba'e, «qué, cosa», como en Mba'épa."},{"id":"ndaipori","gn":"Ndaipóri","es":"No hay","note":"Es el «no» de oĩ, «hay»: Oĩpa mandi'o? Ndaipóri. Es una palabra aparte, que no se arma con oĩ, y termina en -ri. Lo vemos mejor en la unidad 7."},{"id":"mbarakaja","gn":"mbarakaja","es":"gato","note":"mb al principio, en una sola sílaba: mba-ra-ka-ja."},{"id":"aguyjemante","gn":"Aguyje mante","es":"Gracias nomás","parts":[["aguyje","gracias"],["mante","nomás, solamente"]],"note":"Como el «gracias nomás» del castellano paraguayo. nt es una sola letra, como en «canto»."}],"spell":["ndaikuaai","mbaeve","ndaipori","mbarakaja"],"check":{"id":"a1u02d5.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa pregunta algo y Luis no sabe: Luis dice «_No sé_». ¿Cómo se escribe en guaraní?","options":["Ndakuaái","Naikuaái","Ndaikuaái","Ndaikuái"],"answer":3,"explain":"No sé es Ndaikuaái: nd- al principio, porque kuaa es una raíz oral; ai-, el «yo» de kuaa, con su i; la raíz kuaa, con dos aes; y -i al final, que no se lleva el acento: la última a de kuaa ya no es la última vocal, y se escribe á. Ndakuaái pierde la i de ai-, como reikuaa, que no es rekuaa. Naikuaái pone n-, que va solo delante de una raíz nasal. Ndaikuái se come una a de kuaa."}},"skill":{"kind":"listening","es":"Respuesta rápida","situation":"Llueve. Ana le pregunta a Luis si va a la escuela esta tarde.","ask":"¿Qué responde Luis?","item":{"id":"a1u02d5.r1","kind":"choice","area":"listening","label":"Respuesta rápida","q":"¿Qué responde Luis?","options":["Nahániri, ndahái. Oky.","Nahániri, aha.","Héẽ, ndahái."],"answer":1,"why":["Luis dice que no, Nahániri, y lo niega en el verbo: ndahái, «no voy». Después da la razón: oky, «llueve».","Nahániri, aha se contradice: «no, voy». Aha es «voy», sin negación.","Héẽ, ndahái se contradice al revés: «sí, no voy». Ndahái es «no voy», y pide un Nahániri delante."],"script":["Narrador: Llueve. ¿Qué responde Luis?","Mujer: Rehópa mbo'ehaópe ko ka'aru, Luis?","Narrador: 1","Hombre: Nahániri, ndahái. Oky.","Narrador: 2","Hombre: Nahániri, aha.","Narrador: 3","Hombre: Héẽ, ndahái."]},"audio":[["N","Llueve. ¿Qué responde Luis?","Llueve. ¿Qué responde Luis?"],["F","Rehópa mbo'ehaópe ko ka'aru, Luis?","¿Vas a la escuela esta tarde, Luis?"],["N","1","1"],["M","Nahániri, ndahái. Oky.","No, no voy. Llueve."],["N","2","2"],["M","Nahániri, aha.","No, voy."],["N","3","3"],["M","Héẽ, ndahái.","Sí, no voy."]]}},{"title":"Repaso de la semana","grammar":{"points":[],"compare":{"intro":"Cuatro pares de la semana que se parecen: quién hace la acción, si la última sílaba es nasal, si vas o venís, y cómo se arma el «no».","forms":[{"form":"a- · ja- · ro-","tag":"yo · con vos · sin vos","mark":"dot","gn":"{A}karu. Ñande {ja}karu. Ore {ro}karu.","es":"Como. Comemos, vos y yo. Comemos, sin vos."},{"form":"-pe · -me","tag":"en, a: tras oral · tras nasal","mark":"dot","gn":"óga{pe} · tetã{me} · guaraní{me}","es":"en casa · en el país · en guaraní"},{"form":"-pe · -gui","tag":"adónde · de dónde","mark":"dot","gn":"Aha Itauguá{pe}. Aju Itauguá{gui}.","es":"Voy a Itauguá. Vengo de Itauguá."},{"form":"nd-…-i · n-…-i","tag":"no: raíz oral · raíz nasal","mark":"dot","gn":"{Nd}ahá{i}. {N}añe'ẽ{i}.","es":"No voy. No hablo."}],"check":{"id":"a1u02d6.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: ^Moõguipa^ reju, Juan?\nJuan: (   ) kokuégui.","options":["Aha","Aju","Ou"],"answer":2,"why":["Aha es «voy», el verbo de ir. Rosa pregunta con reju, «venís», y Juan responde con el mismo verbo, venir, y con a-: aju, «vengo».","Moõguipa reju? es «¿de dónde venís?», y Juan responde por él, con a-: aju, «vengo». Aju kokuégui: vengo de la chacra.","Ou es «viene», con o-: sería otra persona. Juan habla de él mismo: a-."]}},"drill":[{"id":"a1u02d6.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa habla de sus papás: van a Asunción esta mañana.)\nRosa: ^Ha'ekuéra^ (   ) Paraguaýpe ko pyhareve.","options":["aha","reho","roho","oho"],"answer":4,"why":["Aha es «voy», con a-: Rosa hablaría de ella misma, y habla de sus papás.","Reho es «vas», con re-: Rosa le hablaría al que escucha. Ha'ekuéra son otras personas.","Roho es «vamos, sin vos», con ro-: sumaría a Rosa. Ha'ekuéra, «ellos», son solo sus papás.","Ha'ekuéra, «ellos», lleva o-, igual que ha'e, y con o- la raíz de «ir» es ho: oho, «van». Paraguaýpe, con -pe, es adónde: a Asunción."]},{"id":"a1u02d6.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le habla a Luis.)\nAna: ^Ñande^ (   ) guaraníme, Luis.","options":["jañe'ẽ","ñañe'ẽ","roñe'ẽ","oñe'ẽ"],"answer":2,"why":["Ñe'ẽ es nasal, por la ñ y la ẽ, y delante de una raíz nasal ja- se vuelve ña-. Jañe'ẽ no se dice.","Ñande pide ja-, el «nosotros con vos». Como ñe'ẽ es nasal, ja- se vuelve ña-: ñañe'ẽ, «hablamos, vos y yo».","Ro- es el prefijo de ore, «nosotros sin vos». Ñande incluye a Luis, que escucha.","O- es «él, ella» o «ellos»: oñe'ẽ, «habla». Ñande pide el «nosotros con vos»."]},{"id":"a1u02d6.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa cuenta dónde está su papá: ^en el país^.)\nRosa: Che ru oĩ (   ).","options":["tetãpe","tetãgui","tetãme","tetãgua"],"answer":3,"why":["La ã es una vocal nasal: después de una sílaba nasal, -pe se vuelve -me. Tetãpe no se dice.","-gui es «de, desde»: tetãgui diría de dónde viene o sale. Rosa dice dónde está su papá, con oĩ.","Tetã termina en ã, nasal: va -me, no -pe. Y sobre la ã no se agrega tilde: tetãme, «en el país».","-gua es el «de» de origen, como en Paraguaigua: diría de dónde es alguien. Rosa dice dónde está: tetãme."]},{"id":"a1u02d6.d4","kind":"choice","area":"grammar","label":"Elegí la palabra","q":"Ana: (   ) reho, Luis?\nLuis: ^Aha Ka'akupépe^.","options":["Moõpa","Moõguipa","Mávapa","Mba'épa"],"answer":1,"why":["Luis responde adónde va, con -pe: Aha Ka'akupépe. La pregunta es Moõpa reho?, «¿adónde vas?».","Moõguipa pregunta «¿de dónde?» y se responde con -gui, como Aju Itauguágui. Luis responde con -pe: adónde va.","Mávapa pregunta «¿quién?», y Luis responde con un lugar, no con una persona.","Mba'épa pregunta «¿qué?», como en Mba'épa rejapo? Luis responde con un lugar, no con una acción."]},{"id":"a1u02d6.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Llueve.)\nRosa: Che sy ","after":" ko pyhare.","tiles":["nd","ou","i"],"bank":[2,0,1],"hint":"Che sy es otra persona, y «viene» es ou, entera. El «no» la rodea: nd- delante y -i al final.","full":"(Llueve.)\nRosa: Che sy {nd}oú{i} ko pyhare.","es":"Rosa: Mi mamá no viene esta noche.","explain":"nd- (no) + ou (viene) + -i (no) = ndoúi, «no viene». Las dos partes del «no» rodean al verbo, como en ndohói. La -i no se lleva el acento: queda en la u de ou, que ya no es la última vocal, y se escribe ú."},{"id":"a1u02d6.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana cuenta dónde está su mamá: en la pieza.)\nAna: Che sy oĩ ","after":".","tiles":["koty","pe"],"bank":[1,0],"hint":"Koty, «pieza», va primero y el sufijo pegado atrás. La última sílaba de koty es oral: ¿-pe o -me? Después fijate dónde queda el acento.","full":"(Ana cuenta dónde está su mamá: en la pieza.)\nAna: Che sy oĩ {kotýpe}.","es":"Ana: Mi mamá está en la pieza.","explain":"koty («pieza») + -pe («en») = kotýpe, «en la pieza». Ty, la última sílaba de koty, es oral: va -pe, no -me. -pe no se lleva el acento: queda en la y de koty, que ya no es la última vocal, y se escribe ý."}],"exam":[{"id":"a1u02d6.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: Che sy _ndohói_ Itauguápe ko ka'aru.","options":["Mi mamá no va a Itauguá esta tarde.","Mi mamá va a Itauguá esta tarde.","Mi mamá no viene de Itauguá esta tarde.","Yo no voy a Itauguá esta tarde."],"answer":1,"explain":"Ndohói es «no va»: nd- y -i rodean a oho, «va», con o- porque Rosa habla de su mamá. Sin el «no» sería oho; «no viene de» pediría ou y -gui, Itauguágui; y «yo no voy» sería ndahái, con a-."},{"id":"a1u02d6.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le habla a Luis: hacen chipá los dos.)\nAna: Ñande (   ) chipa ko ka'aru.","options":["ñajapo","ajapo","jajapo","ojapo"],"answer":3,"explain":"Ñande, «nosotros con vos», pide ja-, y japo no tiene ninguna letra nasal, así que ja- se queda: jajapo, «hacemos, vos y yo». Ña- va solo delante de una raíz nasal, como en ñañe'ẽ; ajapo es «hago», Ana sola; y ojapo, «hace», otra persona."},{"id":"a1u02d6.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Llueve.)\nJuan: Che ru ","after":" kokuépe ko pyhareve.","tiles":["n","o","mba'apo","i"],"bank":[2,3,1,0],"full":"(Llueve.)\nJuan: Che ru {n}omba'apó{i} kokuépe ko pyhareve.","es":"Juan: Mi papá no trabaja en la chacra esta mañana.","explain":"n- (el «no» delante de una raíz nasal) + o- (él) + mba'apo (trabajar) + -i (la otra parte del «no») = nomba'apói, «no trabaja». Mba'apo es nasal por la mb: por eso no va nd-. La -i no se lleva el acento: queda en la o de mba'apo, que ya no es la última vocal, y se escribe ó. Kokuépe, con -pe, es dónde: en la chacra."}]},"words":{"es":"La semana de Ana","intro":"Repasamos la semana de Ana: de su casa, en Itauguá, a la casa de la abuela, en Caacupé. Tocá cada palabra.","sound":{"focus":"Repaso: j, h, r, la tilde, ña- y mb, nd","letters":["j","h","r","ý","ñ","mb","nd"],"note":"Lo de la semana, en cinco pares de palabras para contrastar: no son pares mínimos. La j suena como la y fuerte de «yo», la h siempre suena, como la jota suave paraguaya, y la r es siempre suave, también al principio. -pe no se lleva el acento, y por eso koty se vuelve kotýpe; con una raíz nasal, ja- se vuelve ña-, como en ñañe'ẽ; y mb y nd son una sola letra, en una sola sílaba.","pairs":[["aha","voy","aju","vengo"],["ru","padre","vúrro","burro"],["koty","pieza","kotýpe","en la pieza"],["jakaru","comemos (vos y yo)","ñañe'ẽ","hablamos (vos y yo)"],["mba'eve","nada","ndaipóri","no hay"]]},"words":[{"id":"jaha","gn":"Jaha!","es":"¡Vamos!","parts":[["ja-","nosotros (con vos)"],["ha","ir"]],"note":"Se dice hasta en castellano paraguayo. Con ja- la raíz de «ir» es ha, como con a-: aha, jaha."},{"id":"ambaapo","gn":"amba'apo","es":"trabajo","parts":[["a-","yo"],["mba'apo","trabajar"]],"note":"mb es una sola letra, en una sola sílaba, y el puso corta la voz: a-mba-'a-po."},{"id":"ahendu","gn":"ahendu","es":"escucho, oigo","parts":[["a-","yo"],["hendu","oír"]],"note":"La h suena, como la jota suave paraguaya, y nd es una sola letra: a-he-ndu."},{"id":"nanee","gn":"ñañe'ẽ","es":"hablamos (vos y yo)","parts":[["ña-","nosotros (con vos)"],["ñe'ẽ","hablar"]],"note":"Ñe'ẽ es nasal, por la ñ y la ẽ: ja- se vuelve ña-."},{"id":"kotype","gn":"kotýpe","es":"en la pieza, en el cuarto","parts":[["koty","pieza, cuarto"],["-pe","en, a"]],"note":"-pe no se lleva el acento: queda en la y, que ya no es la última vocal, y lleva tilde."},{"id":"itauguagui","gn":"Itauguágui","es":"desde Itauguá","parts":[["Itaugua","Itauguá"],["-gui","de, desde"]],"note":"El pueblo de Ana y del ñandutí. Con -gui, la a final de Itaugua se escribe á."},{"id":"ndaikuaai","gn":"ndaikuaái","es":"no sé","parts":[["nd-","no"],["ai-","yo (con kuaa, como rei- en reikuaa)"],["kuaa","saber"],["-i","no"]],"note":"nd es una sola letra, sin e delante. La -i no se lleva el acento: la a se escribe á."},{"id":"ndaipori","gn":"Ndaipóri","es":"No hay","note":"Es el «no» de oĩ, «hay». Es una forma irregular, con -ri al final en lugar de -i: se aprende entera. Ndaipóri chipa: no hay chipá."}],"spell":["nanee","kotype","itauguagui","ndaikuaai"],"check":{"id":"a1u02d6.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana le pregunta a Luis si oye la música. Luis: «_Escucho_.» ¿Cómo se escribe en guaraní?","options":["ajendu","ahendu","aendu","ahendy"],"answer":2,"explain":"Escucho es ahendu: a-, «yo», y hendu, «oír». La h suena como la jota suave paraguaya, pero se escribe h: con j sería otra letra, la y fuerte de «yo». Aendu se come la h, que nunca es muda. Y ahendy cambia la u por la y, la sexta vocal: hendy es otra palabra, «arder»."}},"skill":{"kind":"reading","es":"Un chat del domingo","ask":"¿Qué hace Ana en Caacupé?","seconds":75,"passage":"Luis: Moõpa reho, Ana?\nAna: Aha Ka'akupépe, che jarýi rógape.\nLuis: Mba'épa rejapo Ka'akupépe?\nAna: ^Akaru ha añe'ẽ guaraníme.^ ^Namba'apói.^\nLuis: Ha nde ru?\nAna: Ha'e ndohói: omba'apo Paraguaýpe.","strategy":"Las respuestas de Ana vienen justo después de cada pregunta de Luis. Buscá la segunda, y fijate qué verbo lleva n-…-i: eso es lo que no hace.","item":{"id":"a1u02d6.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué hace Ana en Caacupé?","options":["Trabaja.","Va a la escuela.","Come y habla guaraní.","Trabaja en Asunción."],"short":["Trabaja","Va a la escuela","Come y habla","Trabaja en Asunción"],"answer":3,"why":["Ana dice Namba'apói: n-…-i rodea a mba'apo. Justamente no trabaja.","Nadie habla de la escuela: mbo'ehao no aparece en el chat.","A Mba'épa rejapo Ka'akupépe? Ana responde Akaru ha añe'ẽ guaraníme: come y habla en guaraní.","El que trabaja en Asunción es su papá: omba'apo Paraguaýpe, con o-."],"explain":"Luis pregunta Mba'épa rejapo Ka'akupépe?, «¿qué hacés en Caacupé?», y Ana responde Akaru ha añe'ẽ guaraníme: come y habla en guaraní. Namba'apói niega el trabajo, y Paraguaýpe, Asunción, es donde trabaja su papá."}}}],"test":["a1u02t.1","a1u02t.2","a1u02t.3","a1u02t.4","a1u02t.5","a1u02t.6","a1u02t.7","a1u02t.8","a1u02t.9","a1u02t.10","a1u02t.11","a1u02t.12","a1u02t.13","a1u02t.14","a1u02t.15","a1u02t.16","a1u02t.17","a1u02t.18","a1u02t.19","a1u02t.20"]},{"n":3,"gn":"","es":"¿Cómo estás? Predicados chendales","days":[{"title":"che-/nde- para estados y cualidades (sin «estar»)","grammar":{"points":[{"id":"a1u03d1.p1","form":"che- · nde-/ne- + estado","gloss":"estoy…, tengo… (sin «estar»)","connect":[{"pos":"Para hablar de vos mismo: che- pegado al estado. En otros textos lo vas a ver separado, che kane'õ: se dice igual","rule":"{Che}kane'õ."},{"pos":"Para el que escucha: nde-","rule":"{Nde}pochy."},{"pos":"Si la palabra es nasal (lleva ~ o m, n, ñ, mb, nd, ng, nt), nde- se dice y se escribe ne-","rule":"{Ne}kane'õ."}],"examples":[{"gn":"Luis: {Che}kane'õ.","es":"Luis: Estoy cansado.","parts":[["che-","yo (me pasa)"],["kane'õ","cansancio, cansado"]]},{"gn":"{Che}vare'a ha {che}y'uhéi.","es":"Tengo hambre y sed.","parts":[["che-","yo"],["vare'a","hambre"],["ha","y"],["y'uhéi","sed"]]},{"gn":"{Nde}pochy, Juan.","es":"Estás enojado, Juan.","parts":[["nde-","vos (te pasa)"],["pochy","enojo, enojado"]]},{"gn":"Rosa: {Ne}kane'õ, Luis.\nLuis: Héẽ, {che}kane'õ ha {che}ro'y.","es":"Rosa: Estás cansado, Luis.\nLuis: Sí, estoy cansado y tengo frío.","parts":[["ne-","vos, ante una palabra nasal"],["kane'õ","cansancio"],["héẽ","sí"],["ro'y","frío"]]}],"watch":{"note":"En castellano decís «estoy cansado» con el verbo estar. En guaraní no hay verbo: che- va pegado al estado, y con eso alcanza. Tampoco va a-, que es para las acciones, como aguata: akane'õ no es «estoy cansado».","bad":"Akane'õ.","good":"Chekane'õ."}},{"id":"a1u03d1.p2","form":"i- / h- + estado","gloss":"él, ella está… (tercera persona)","connect":[{"pos":"Para otra persona: i- pegado al estado. Antes de una vocal la i- cambia un poco, como en ijy'uhéi, «tiene sed»: hoy solo lo mirás","rule":"Che sy {i}kane'õ."},{"pos":"Con el nombre delante, o con ha'e, igual lleva i-","rule":"Ana {i}pochy. Ha'e {i}vare'a."},{"pos":"Algunas palabras tienen tres formas, como téra · che réra · héra. Rasy es así: tasy suelta, cherasy con che-, hasy para él o ella","rule":"{t}asy · che{r}asy · {h}asy"},{"pos":"Ojo: no toda palabra que empieza con r cambia. Ro'y lleva i-, como kane'õ","rule":"che{r}o'y · {i}ro'y"}],"examples":[{"gn":"Che sy {i}kane'õ.","es":"Mi mamá está cansada.","parts":[["che sy","mi mamá"],["i-","ella (le pasa)"],["kane'õ","cansancio"]]},{"gn":"Ana {i}pochy.","es":"Ana está enojada.","parts":[["i-","ella"],["pochy","enojo"]]},{"gn":"Mitã {i}vare'a.","es":"El niño tiene hambre.","parts":[["mitã","niño"],["i-","él"],["vare'a","hambre"]]},{"gn":"Che ru {h}asy.","es":"Mi papá está enfermo.","parts":[["che ru","mi papá"],["hasy","está enfermo; con che- es cherasy"]]}],"watch":{"note":"Sin i- la palabra no dice de quién es el estado: kane'õ solo es «cansancio». El castellano no tiene esta marca: «mi mamá cansada» no es una oración, pero Che sy ikane'õ sí.","bad":"Che sy kane'õ.","good":"Che sy ikane'õ."}}],"compare":{"intro":"Tres cosas con che: un estado tuyo, el estado de otra persona y el «mi» de posesión.","forms":[{"form":"chekane'õ","tag":"yo · estado, pegado","mark":"dot","gn":"{Chekane'õ}.","es":"Estoy cansado."},{"form":"ikane'õ","tag":"él, ella · estado","mark":"dot","gn":"Che sy {ikane'õ}.","es":"Mi mamá está cansada."},{"form":"che sy","tag":"mi · posesión, separado","mark":"dot","gn":"{Che sy} ikane'õ.","es":"Mi mamá está cansada."}],"check":{"id":"a1u03d1.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa habla de ^su papá^, que está cansado: «Che ru (   ).»","options":["chekane'õ","ikane'õ","kane'õ"],"answer":2,"why":["Chekane'õ es «estoy cansada»: Rosa hablaría de ella misma. Acá habla de su papá, otra persona.","Che ru, «mi papá», es otra persona: el estado lleva i-. Che ru ikane'õ, «mi papá está cansado».","Kane'õ sin marca es solo «cansancio», la cosa: Che ru kane'õ no es una oración. Falta la i-."]}},"drill":[{"id":"a1u03d1.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Termina el partido. ^Juan dice cómo está él mismo^.)\nJuan: (   ).","options":["Akane'õ","Chekane'õ","Ikane'õ","Kane'õ"],"answer":2,"why":["a- es para las acciones, como aguata. Un estado no lleva a-: akane'õ no es «estoy cansado».","Juan habla de él mismo y de un estado: che- pegado a kane'õ. Chekane'õ, «estoy cansado».","Ikane'õ es «está cansado», de otra persona. Juan habla de él mismo.","Kane'õ sin marca es «cansancio», la cosa: no dice de quién es."]},{"id":"a1u03d1.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa ve que Juan está enojado y ^se lo dice a él^: «(   ), Juan.»","options":["Chepochy","Ipochy","Ndepochy","Nepochy"],"answer":3,"why":["Chepochy es «estoy enojada»: Rosa hablaría de ella misma, y le habla a Juan de él.","Ipochy es «está enojado», de otra persona. Rosa le habla a Juan directamente, de vos a vos.","Rosa le habla a Juan: nde- pegado a pochy. Ndepochy, «estás enojado».","ne- reemplaza a nde- solo antes de una palabra nasal, como nekane'õ. Pochy no es nasal: no tiene ~ ni m, n, ñ. Queda nde-: ndepochy."]},{"id":"a1u03d1.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Un nene pide chipa: tiene hambre.)\n^Mitã^ (   ).","options":["ivare'a","chevare'a","ndevare'a","vare'a"],"answer":1,"why":["Mitã, «el niño», es otra persona: el estado lleva i-. Mitã ivare'a, «el niño tiene hambre».","Chevare'a es «tengo hambre»: hablaría de mí. Acá se habla del niño.","Ndevare'a es «tenés hambre», hablándole a vos. Acá se habla del niño, no se le habla a él.","Vare'a sin marca es «hambre», la cosa: mitã vare'a no es una oración. Falta la i-."]},{"id":"a1u03d1.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis habla de ^su mamá^, que está enferma: «Che sy (   ).»","options":["cherasy","irasy","hasy","tasy"],"answer":3,"why":["Cherasy es «estoy enfermo»: Luis hablaría de él mismo. Acá habla de su mamá.","Rasy es de las palabras con tres formas, como téra, che réra, héra: tasy, cherasy, hasy. Para él o ella es hasy: irasy no existe.","Che sy es otra persona, y para él o ella rasy tiene su propia forma, hasy, como réra tiene héra. Che sy hasy, «mi mamá está enferma».","Tasy es la palabra suelta, «dolor, enfermedad», sin marcar a nadie: no dice que la mamá esté enferma."]},{"id":"a1u03d1.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(A Juan le duele la cabeza.)\nJuan: ","after":".","tiles":["che","akã","rasy"],"bank":[2,0,1],"hint":"che- va primero. Después la parte del cuerpo, akã, y al final rasy, «dolor».","full":"(A Juan le duele la cabeza.)\nJuan: {Che}akãrasy.","es":"Juan: Me duele la cabeza.","explain":"che- (yo, me pasa) + akã («cabeza») + rasy («dolor, enfermo») = cheakãrasy, «me duele la cabeza»: en guaraní es un estado, todo en una palabra. No lleva tilde: el acento va en la última vocal, la y. La ~ de akã marca la nasal."},{"id":"a1u03d1.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Rosa: ","after":", Luis.","tiles":["ne","kane'õ"],"bank":[1,0],"hint":"Kane'õ es nasal, lleva ~: el «vos» no es nde- sino ne-, y va primero.","full":"Rosa: {Ne}kane'õ, Luis.","es":"Rosa: Estás cansado, Luis.","explain":"ne- (vos) + kane'õ («cansancio») = nekane'õ, «estás cansado». Antes de una palabra nasal, nde- se vuelve ne-: nekane'õ. Con una palabra oral queda nde-: ndepochy."}],"exam":[{"id":"a1u03d1.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Luis: _Chero'y ha chevare'a_.","options":["Tengo frío y hambre.","Tengo calor y sed.","Tiene frío y hambre.","Estoy cansado y enojado."],"answer":1,"explain":"Che- marca un estado mío: chero'y es «tengo frío» (ro'y, «frío») y chevare'a, «tengo hambre» (vare'a, «hambre»). «Tiene» sería otra persona, con i-: iro'y ha ivare'a. Calor y sed son otras palabras: «tengo sed» es chey'uhéi. Cansado es chekane'õ y enojado, chepochy."},{"id":"a1u03d1.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana habla de su abuela, que está enojada.)\nAna: Che jarýi (   ).","options":["chepochy","ndepochy","ipochy","pochy"],"answer":3,"explain":"Che jarýi, «mi abuela», es otra persona: el estado lleva i-. Che jarýi ipochy, «mi abuela está enojada». Chepochy sería «estoy enojada», ndepochy, «estás enojada», y pochy solo es «enojo», la cosa, sin decir de quién."},{"id":"a1u03d1.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Ana: Mba'éichapa reiko, Rosa?\nRosa: ","after":".","tiles":["che","akã","rasy"],"bank":[2,1,0],"full":"Ana: Mba'éichapa reiko, Rosa?\nRosa: Cheakãrasy.","es":"Ana: ¿Cómo andás, Rosa?\nRosa: Me duele la cabeza.","explain":"che- (yo, me pasa) va primero. Después va akã («cabeza») y al final rasy («dolor»): cheakãrasy, «me duele la cabeza». Es un estado de Rosa: todo junto, en una sola palabra, y sin tilde."}]},"words":{"es":"Después del partido","intro":"Termina el partido en la cancha del barrio y todos dicen cómo están. Tocá cada palabra.","sound":{"focus":"La ch: che, chepochy","letters":["ch"],"note":"La ch suena más bien como «sh», aunque también vas a oír la ch castellana. Es una sola letra, y hoy abre casi todas las palabras: che-, «yo», como en chepochy y chero'y. No hay pares mínimos seguros: cada par trae una palabra sola y la misma con che-.","pairs":[["pochy","enojo","chepochy","estoy enojado, enojada"],["ro'y","frío","chero'y","tengo frío"],["y'uhéi","sed","chey'uhéi","tengo sed"]]},"words":[{"id":"kaneo","gn":"chekane'õ","es":"estoy cansado, cansada","parts":[["che-","yo"],["kane'õ","cansancio"]],"note":"Muy cansado: chekane'õiterei. A vos: nekane'õ, porque kane'õ es nasal."},{"id":"varea","gn":"chevare'a","es":"tengo hambre","parts":[["che-","yo"],["vare'a","hambre"]],"note":"La palabra de todos los días. En cursos y diccionarios, el hambre es también ñembyahýi; para algunos hablantes, vare'a es más bien «angurria»."},{"id":"yuhei","gn":"chey'uhéi","es":"tengo sed","parts":[["che-","yo"],["y'uhéi","sed"]],"note":"Se escribe con puso entre la y y la u, y con tilde en la e: y'uhéi."},{"id":"roy","gn":"chero'y","es":"tengo frío","parts":[["che-","yo"],["ro'y","frío"]],"note":"Sin che-, ro'y es «hace frío»: Ajépa ro'y, «qué frío»."},{"id":"haku","gn":"haku","es":"hace calor; está caliente","note":"Habla del día o de una cosa, por eso va sin che-. «Tengo calor» es otra palabra: chembyry'ái."},{"id":"pochy","gn":"chepochy","es":"estoy enojado, enojada","parts":[["che-","yo"],["pochy","enojo"]],"note":"A vos: ndepochy. Él o ella: ipochy. Lleva dos veces la ch: che-po-chy."},{"id":"kaigue","gn":"chekaigue","es":"estoy desganado, desganada","parts":[["che-","yo"],["kaigue","desgano"]],"note":"Muy paraguayo: en castellano también se dice «ando kaigue»."},{"id":"akarasy","gn":"cheakãrasy","es":"me duele la cabeza","parts":[["che-","yo"],["akã","cabeza"],["rasy","dolor, enfermo"]],"note":"Rasy es la forma con che-: hasy es «le duele, está enfermo»."}],"spell":["kaneo","yuhei","akarasy","pochy"],"check":{"id":"a1u03d1.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Después del partido, Juan dice: «_Tengo sed_.» ¿Cómo se escribe en guaraní?","options":["chey'uhẽi","chey'uhéi","chei'uhéi","shey'uhéi"],"answer":2,"explain":"Se escribe chey'uhéi: con ch al principio, con el puso que corta la voz entre la y y la u, y con la tilde en la é, porque el acento no cae en la última vocal. Shey'uhéi escribe el primer sonido con sh, y en guaraní se escribe con la ch. Chey'uhẽi cambia la tilde por una ~, y la e de y'uhéi no es nasal. Chei'uhéi cambia la y por i, otra vocal."}},"skill":{"kind":"listening","es":"Comprensión de puntos clave","situation":"Termina el partido. Una mujer le pregunta a un hombre cómo está.","ask":"¿Qué le pasa al hombre?","item":{"id":"a1u03d1.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué le pasa al hombre?","options":["Está cansado y tiene sed.","Tiene hambre y frío.","Está enojado."],"answer":1,"why":["El hombre dice Chekane'õ ha chey'uhéi: che- marca sus estados, kane'õ es «cansancio» y y'uhéi, «sed». Por eso ella le propone tereré.","Hambre sería chevare'a, y frío, chero'y. El hombre no dice ninguna de las dos.","Enojado sería chepochy. El hombre habla de cansancio y de sed, y ella lo invita a tomar tereré."],"script":["Narrador: Termina el partido. ¿Qué le pasa al hombre?","Mujer: Mba'éichapa reiko, Luis?","Hombre: Chekane'õ ha chey'uhéi.","Mujer: Jaha, oĩ terere."]},"audio":[["N","Termina el partido. ¿Qué le pasa al hombre?","Termina el partido. ¿Qué le pasa al hombre?"],["F","Mba'éichapa reiko, Luis?","¿Cómo andás, Luis?"],["M","Chekane'õ ha chey'uhéi.","Estoy cansado y tengo sed."],["F","Jaha, oĩ terere.","Vamos, hay tereré."]]}},{"title":"Areal «yo hago» vs. chendal «a mí me pasa»","grammar":{"points":[{"id":"a1u03d2.p1","form":"a- · re- · o- + acción","gloss":"yo hago, vos hacés, él o ella hace","connect":[{"pos":"Las acciones llevan el prefijo areal de la unidad 2: a- yo, re- vos, o- él o ella","rule":"{A}karu · {Re}karu · {O}karu"},{"pos":"También las acciones del cuerpo: levantarse, bañarse, dormir","rule":"{A}pu'ã · {a}jahu · {a}ke"},{"pos":"El castellano pone la persona al final (com-o); el guaraní, al principio","rule":"{A}karu"}],"examples":[{"gn":"{A}pu'ã ha {a}jahu.","es":"Me levanto y me baño.","parts":[["a-","yo"],["pu'ã","levantarse"],["ha","y"],["jahu","bañarse"]]},{"gn":"{A}karu ha {a}ke.","es":"Como y duermo.","parts":[["a-","yo"],["karu","comer"],["ha","y"],["ke","dormir"]]},{"gn":"Che sy {o}purahéi ha che ru {o}jeroky.","es":"Mi mamá canta y mi papá baila.","parts":[["che sy","mi mamá"],["o-","él, ella"],["purahéi","cantar"],["ha","y"],["che ru","mi papá"],["jeroky","bailar"]]},{"gn":"Ko'ág̃a {a}mba'apo.","es":"Ahora trabajo.","parts":[["ko'ág̃a","ahora"],["a-","yo"],["mba'apo","trabajar"]]}],"watch":{"note":"Comer es una acción: lleva a-. Che- es para los estados, como chekane'õ. No los mezcles: chekaru no es «como».","bad":"Chekaru.","good":"Akaru."}},{"id":"a1u03d2.p2","form":"che- + estado · a- + sentimiento","gloss":"a mí me pasa · algunos sentimientos van como acciones","connect":[{"pos":"Un estado o una sensación lleva che-, como ayer","rule":"{Che}kane'õ · {che}vare'a · {che}mandu'a"},{"pos":"Pero algunos sentimientos se conjugan como acciones, con a-","rule":"{A}vy'a · {a}kyhyje"},{"pos":"El diccionario dice de qué tipo es cada palabra: aprendé cada una con su prefijo","rule":"{a}vy'a · {che}mandu'a"}],"examples":[{"gn":"{Che}vare'a. {A}karu.","es":"Tengo hambre. Como.","parts":[["che-","yo: me pasa"],["vare'a","hambre"],["a-","yo: hago"],["karu","comer"]]},{"gn":"{A}vy'a, Ana.","es":"Estoy contento, Ana.","parts":[["a-","yo"],["vy'a","alegrarse"]]},{"gn":"{A}kyhyje.","es":"Tengo miedo.","parts":[["a-","yo"],["kyhyje","tener miedo"]]},{"gn":"{Che}mandu'a, Luis.","es":"Me acuerdo, Luis.","parts":[["che-","yo: me pasa"],["mandu'a","acordarse"]]}],"watch":{"note":"«Estoy contento» parece un estado, pero vy'a se conjuga como acción: avy'a. Chevy'a no es «estoy contento»: vy'a solo es «la alegría», la cosa.","bad":"Chevy'a.","good":"Avy'a."}}],"compare":{"intro":"Tres frases de un domingo: una acción con a-, un estado con che- y estar en un lugar, con aime.","forms":[{"form":"akaru","tag":"areal · yo hago","mark":"dot","gn":"{Akaru}.","es":"Como."},{"form":"chevare'a","tag":"chendal · a mí me pasa","mark":"dot","gn":"{Chevare'a}.","es":"Tengo hambre."},{"form":"aime","tag":"lugar · estoy en","mark":"dot","gn":"{Aime} ógape.","es":"Estoy en casa."}],"check":{"id":"a1u03d2.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le cuenta a Luis que ^está en su casa^.)\nAna: (   ) ógape.","options":["Akaru","Chevare'a","Aime"],"answer":3,"why":["Akaru es «como», una acción con a-. Akaru ógape sería «como en casa»: dice qué hace, no que está ahí.","Chevare'a es «tengo hambre», un estado con che-. Tampoco dice dónde está.","Para estar en un lugar hay un verbo, aime, que lleva a- como las acciones: Aime ógape, «estoy en casa»."]}},"drill":[{"id":"a1u03d2.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis cuenta ^qué hace él^ a la mañana.)\nLuis: (   ) ha ^ajahu^.","options":["Chepu'ã","Apu'ã","Ipu'ã","Pu'ã"],"answer":2,"why":["Che- es para los estados, como chekane'õ. Levantarse es una acción: lleva a-. Chepu'ã no es «me levanto».","Levantarse es una acción y Luis habla de él mismo: a- + pu'ã = apu'ã, «me levanto». Después se baña: ajahu, también con a-.","I- marca el estado de otra persona, como en ikane'õ. Pu'ã es una acción, y además Luis habla de él.","Pu'ã sin prefijo no dice quién se levanta: le falta la persona, como guata sin a- en la unidad 2."]},{"id":"a1u03d2.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis comió bien y ^está contento^.)\nLuis: (   ), Ana.","options":["Chevy'a","Ivy'a","Avy'a","Vy'a"],"answer":3,"why":["Parece un estado, pero vy'a se conjuga como acción, con a-. Chevy'a no es «estoy contento».","Ivy'a no es «está contento»: vy'a va como acción, y para otra persona es ovy'a, con o-. Además, Luis habla de él.","Vy'a va como una acción, y Luis habla de él: a- + vy'a = avy'a, «estoy contento».","Vy'a solo es «la alegría», la cosa. Le falta la persona: a-."]},{"id":"a1u03d2.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta que su papá ^trabaja^.)\nAna: Che ru (   ).","options":["amba'apo","chemba'apo","mba'apo","omba'apo"],"answer":4,"why":["A- es «yo»: Ana hablaría de ella misma, y habla de su papá.","Che- es para los estados, como chekane'õ, y además dice «yo». Trabajar es una acción, y la hace otra persona: o-.","Mba'apo solo es «trabajo», la cosa, o la raíz sin persona: che ru mba'apo no dice que trabaje. Falta la persona: o-.","Che ru, «mi papá», es otra persona: o- + mba'apo = omba'apo, «trabaja»."]},{"id":"a1u03d2.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le habla a Luis de la fiesta, y Luis ^se acuerda^.)\nLuis: (   ), Ana.","options":["Chemandu'a","Amandu'a","Imandu'a","Mandu'a"],"answer":1,"why":["Acordarse es un estado, de los que van con che-: chemandu'a, «me acuerdo». Luis habla de él.","Acordarse no se conjuga como acción: amandu'a no es «me acuerdo». Va con che-, como chekane'õ.","Imandu'a es «se acuerda», otra persona, con la i- de ikane'õ. Luis habla de él mismo.","Mandu'a solo es «el recuerdo», la cosa: no dice quién se acuerda. Le falta la persona, che-."]},{"id":"a1u03d2.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis vuelve de la cancha al mediodía.)\nLuis: ","after":" ha akaru.","tiles":["che","vare'a"],"bank":[1,0],"hint":"El hambre es un estado, no una acción: el «yo» de los estados va primero, pegado. La acción de al lado, akaru, lleva a-.","full":"(Luis vuelve de la cancha al mediodía.)\nLuis: {Che}vare'a ha akaru.","es":"Luis: Tengo hambre y como.","explain":"che- (yo, me pasa) + vare'a («hambre») = chevare'a, «tengo hambre». El hambre es un estado: lleva che-, no a-. Comer es una acción: por eso akaru lleva a-. En una sola oración están los dos «yo» del guaraní: che- para lo que te pasa y a- para lo que hacés."},{"id":"a1u03d2.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis ve una víbora.)\nLuis: ","after":".","tiles":["a","kyhyje"],"bank":[1,0],"hint":"Tener miedo se conjuga como una acción, igual que avy'a: el prefijo de «yo» va primero, pegado a la raíz.","full":"(Luis ve una víbora.)\nLuis: {A}kyhyje.","es":"Luis: Tengo miedo.","explain":"a- («yo») + kyhyje («tener miedo») = akyhyje, «tengo miedo». Parece un estado, pero kyhyje va con los prefijos de acción, como vy'a: akyhyje, no chekyhyje. Sin tilde: el acento cae en la última vocal."}],"exam":[{"id":"a1u03d2.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Ana: _Avy'a_, Luis.","options":["Me baño, Luis.","Estoy contenta, Luis.","Tengo miedo, Luis.","Estoy cansada, Luis."],"answer":2,"explain":"Vy'a es «alegrarse» y se conjuga como acción: avy'a, «estoy contenta». «Me baño» es ajahu; «tengo miedo», akyhyje; y «estoy cansada», chekane'õ, con che-."},{"id":"a1u03d2.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis está enojado y se va. Lo cuenta él mismo.)\nLuis: (   ) ha aha.","options":["Apochy","Ipochy","Chepochy","Pochy"],"answer":3,"explain":"Estar enojado es un estado, y Luis habla de él mismo: che- + pochy = chepochy. Chepochy ha aha, «estoy enojado y me voy». Apochy no es «estoy enojado»: a- es para las acciones, como aha. Ipochy es «está enojado», otra persona. Y pochy sin marca es solo «el enojo», la cosa: no dice de quién."},{"id":"a1u03d2.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis cuenta qué hace el lunes a la mañana.)\nLuis: Apu'ã ha ","after":".","tiles":["a","mba'apo"],"bank":[1,0],"full":"(Luis cuenta qué hace el lunes a la mañana.)\nLuis: Apu'ã ha {a}mba'apo.","es":"Luis: Me levanto y trabajo.","explain":"a- («yo») va primero y después la raíz mba'apo, «trabajar»: amba'apo, «trabajo». Trabajar es una acción, como levantarse: las dos llevan a-, no che-."}]},"words":{"es":"Un domingo en casa de Ana","intro":"Es domingo. Ana cuenta qué hace y qué le pasa en su casa, de la mañana a la noche. Tocá cada palabra.","sound":{"focus":"Sin marca, el acento va al final: ajahu, akyhyje","letters":["u","e","ó","á"],"note":"Una palabra sin ninguna marca, ni tilde ni ~, lleva el acento en la última vocal: la u de ajahu, la e de akyhyje. Es al revés del castellano, que pondría el acento antes: a-JA-hu. Cuando una palabra lleva tilde, el acento va ahí, como en óga y ko'ág̃a: no son pares mínimos, cada par trae una palabra sin tilde y otra con tilde.","pairs":[["ake","duermo","óga","casa"],["ajahu","me baño","ko'ág̃a","ahora"],["akyhyje","tengo miedo","nahániri","no"]]},"words":[{"id":"apua","gn":"apu'ã","es":"me levanto","parts":[["a-","yo"],["pu'ã","levantarse"]],"note":"Epu'ã, «levantate», es el nombre de la app."},{"id":"ajahu","gn":"ajahu","es":"me baño","parts":[["a-","yo"],["jahu","bañarse"]],"note":"La j suena como la y de «yo» en boca de un paraguayo, y la h es un soplo que siempre suena. Va sin tilde: el acento cae en la u, a-ja-HU."},{"id":"avya","gn":"avy'a","es":"estoy contento, contenta","parts":[["a-","yo"],["vy'a","alegrarse; alegría"]],"note":"Un sentimiento que se conjuga como acción. Vy'a solo es «la alegría»."},{"id":"akyhyje","gn":"akyhyje","es":"tengo miedo","parts":[["a-","yo"],["kyhyje","tener miedo; miedo"]],"note":"Otro sentimiento que va como acción, igual que avy'a: akyhyje, no chekyhyje. Tiene h y j, y va sin tilde: a-ky-hy-JE."},{"id":"chemandua","gn":"chemandu'a","es":"me acuerdo","parts":[["che-","yo: me pasa"],["mandu'a","acordarse; recuerdo"]],"note":"Un estado: va con che-, pegado, y no con a-. Él o ella: imandu'a."},{"id":"aime","gn":"aime","es":"estoy (en un lugar)","note":"Aime ógape, «estoy en casa». Con los estados de ayer no va: «estoy cansada» es chekane'õ, no aime kane'õ. Con porã sí se dice: Aime porãiterei, «estoy muy bien»."},{"id":"koaga","gn":"ko'ág̃a","es":"ahora","note":"Ko'ág̃a amba'apo: ahora trabajo. Se escribe con puso, con tilde en la á y con g̃, la g con nariz. También se ve ko'ágã, con la ~ en la a."},{"id":"ake","gn":"ake","es":"duermo","parts":[["a-","yo"],["ke","dormir"]],"note":"Con él o ella: oke. Che ru oke, «mi papá duerme»."}],"spell":["ajahu","akyhyje","apua","avya"],"check":{"id":"a1u03d2.k1","kind":"choice","area":"vocab","label":"Cuál está bien escrita","q":"Ana anota cuatro palabras de su domingo. Solo una está _bien escrita_. ¿Cuál?","options":["akyhyjé","ko'ag̃a","ajahu","aké"],"answer":3,"explain":"Ajahu está bien: va sin tilde porque el acento cae en la última vocal, la u, y en guaraní eso no se marca. Por lo mismo sobra la tilde de akyhyjé y de aké, que es la costumbre del castellano: se escriben akyhyje y ake. A ko'ag̃a, en cambio, le falta la suya: el acento va antes del final, en la primera a, y ahí sí se escribe, ko'ág̃a."}},"skill":{"kind":"reading","es":"Un mensaje de Ana","ask":"¿Qué hace Ana ahora?","seconds":60,"passage":"Mba'éichapa, Luis?\nKo'ág̃a ^ajahu^ ha ^akaru^. Chekane'õiterei.\nJajotopáta ko pyhare.\nAna","strategy":"Buscá los verbos con a-: son lo que hace Ana. Lo que le pasa va con che-.","item":{"id":"a1u03d2.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué hace Ana ahora?","options":["Se baña y come.","Duerme.","Baila y canta.","Va a la escuela."],"short":["Se baña y come","Duerme","Baila y canta","A la escuela"],"answer":1,"why":["Ana escribe ajahu ha akaru: a- es «yo», jahu «bañarse» y karu «comer». Se baña y come.","Dormir es ke: ake, «duermo». Ana no lo escribe; escribe que está muy cansada, chekane'õiterei.","Bailar y cantar son ajeroky ha apurahéi, y no están en el mensaje.","Ir es aha, y la escuela, mbo'ehao: ninguna de las dos está en el mensaje. Ana solo dice que se ven esta noche: Jajotopáta ko pyhare."],"explain":"Ana escribe Ko'ág̃a ajahu ha akaru: «ahora me baño y como». Los verbos con a- dicen lo que hace; chekane'õiterei, con che-, dice cómo está: muy cansada."}}},{"title":"Oración nominal sin «ser»","grammar":{"points":[{"id":"a1u03d3.p1","form":"che · nde · ha'e + sustantivo","gloss":"soy…, sos…, es… (sin verbo)","connect":[{"pos":"Para decir qué sos: che y el sustantivo, nada más, como en Che Paraguaigua","rule":"{Che} mbo'ehára."},{"pos":"Para el que escucha: nde","rule":"{Nde} temimbo'e pyahu."},{"pos":"Para otra persona: ha'e, o directamente su nombre","rule":"{Ha'e} pohanohára. · Ana pohanohára."}],"examples":[{"gn":"{Che} mbo'ehára.","es":"Soy profesora.","parts":[["che","yo"],["mbo'ehára","profesora"]]},{"gn":"{Nde} temimbo'e pyahu.","es":"Sos alumno nuevo.","parts":[["nde","vos"],["temimbo'e","alumno"],["pyahu","nuevo"]]},{"gn":"{Ha'e} pohanohára.","es":"Él es médico.","parts":[["ha'e","él, ella"],["pohanohára","médico"]]},{"gn":"Che ru {chokokue} ha che sy {ñemuhára}.","es":"Mi papá es agricultor y mi mamá, vendedora.","parts":[["che ru","mi papá"],["chokokue","agricultor"],["ha","y"],["che sy","mi mamá"],["ñemuhára","vendedora"]]}],"watch":{"note":"No hay «soy»: che y la palabra. Vas a oír y leer también Che ha'e mbo'ehára, con ha'e en el lugar de «soy»: es el molde del castellano con palabras guaraníes, y la forma propia del guaraní va sin ha'e. Ojo: che + sustantivo también es «mi», como en che sy. El contexto dice si Che mbo'ehára es «soy profesora» o «mi profesora».","bad":"Che ha'e mbo'ehára.","good":"Che mbo'ehára."}},{"id":"a1u03d3.p2","form":"X ha'e Y · ndaha'éi","gloss":"X es Y · no es","connect":[{"pos":"Con otra persona adelante (Ana, che ru), podés poner ha'e en el medio: hace de «es»","rule":"Ana {ha'e} che sy."},{"pos":"Las dos formas se dicen y se escriben: sin nada o con ha'e","rule":"Che ru chokokue. · Che ru {ha'e} chokokue."},{"pos":"A Mávapa ha'e? (unidad 1) respondés con ha'e y quién es","rule":"Mávapa ha'e? {Ha'e} che angirũ."},{"pos":"Para negar: ndaha'éi, una sola palabra, con el nd-…-i de la unidad 2 alrededor de ha'e. No cambia con la persona: también es «no soy»","rule":"{Ndaha'éi} che sy. · Che {ndaha'éi} mbo'ehára."}],"examples":[{"gn":"Ana {ha'e} che sy.","es":"Ana es mi mamá.","parts":[["ha'e","él, ella; acá hace de «es»"],["che sy","mi mamá"]]},{"gn":"Luis: Mávapa ha'e?\nRosa: {Ha'e} che angirũ.","es":"Luis: ¿Quién es?\nRosa: Es mi amigo.","parts":[["mávapa","¿quién?"],["ha'e","es; él, ella"],["che angirũ","mi amigo"]]},{"gn":"{Ndaha'éi} che sy, ha'e che jarýi.","es":"No es mi mamá, es mi abuela.","parts":[["nda-","no (primera parte)"],["ha'e","es"],["-i","no (segunda parte)"],["che jarýi","mi abuela"]]},{"gn":"Luis {ndaha'éi} mbo'ehára, ha'e pohanohára.","es":"Luis no es profesor, es médico.","parts":[["ndaha'éi","no es"],["mbo'ehára","profesor"],["pohanohára","médico"]]}],"watch":{"note":"Ha'e puede unir dos nombres, pero no hace de «está» ni de «es» delante de un estado o una cualidad: ahí va la i- del día 1. «Ana está cansada» es Ana ikane'õ, y «Ana es hábil», Ana ikatupyry.","bad":"Ana ha'e kane'õ.","good":"Ana ikane'õ."}}],"compare":{"intro":"Tres oraciones sin «ser» ni «estar»: con un sustantivo solo, con ha'e entre dos nombres y con una cualidad.","forms":[{"form":"che mbo'ehára","tag":"pronombre + sustantivo · sin verbo","mark":"dot","gn":"{Che mbo'ehára}.","es":"Soy profesora."},{"form":"ha'e","tag":"entre dos nombres · puede hacer de «es»","mark":"dot","gn":"Ana {ha'e} che sy.","es":"Ana es mi mamá."},{"form":"ikatupyry","tag":"cualidad · i-, como el día 1","mark":"dot","gn":"Ana {ikatupyry}.","es":"Ana es hábil."}],"check":{"id":"a1u03d3.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis presenta a Rosa, ^su amiga^: «Rosa (   ) che angirũ.»","options":["ha'e","ndaha'éi","ikatupyry"],"answer":1,"why":["Luis dice quién es Rosa: entre Rosa y che angirũ, ha'e hace de «es». Rosa ha'e che angirũ, «Rosa es mi amiga».","Ndaha'éi es «no es», y Rosa sí es su amiga: Luis la presenta como tal.","Ikatupyry es una cualidad, «es hábil», con la i- del día 1. No dice quién es Rosa, y Luis la presenta como su amiga."]}},"drill":[{"id":"a1u03d3.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la fiesta, Juan dice qué es: ^agricultor^.)\nJuan: Che (   ).","options":["aime chokokue","achokokue","ichokokue","chokokue"],"answer":4,"why":["Aime es «estoy», como en Aime ógape, del día 2. Para decir qué sos no va ningún verbo: ni «soy» ni «estoy».","A- es el prefijo de las acciones, como en amba'apo. Chokokue es un sustantivo y no lleva a-.","I- trae a otra persona, «él, ella», como en ikane'õ. Juan habla de él mismo: después de che, el sustantivo va solo.","Para decir qué sos: che y el sustantivo, nada más. Che chokokue, «soy agricultor»."]},{"id":"a1u03d3.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana habla ^de un señor^ que conoce: él es médico.)\nAna: (   ) pohanohára.","options":["Ndaha'éi","Nde","Ha'e","Peẽ"],"answer":3,"why":["Ndaha'éi pohanohára es «no es médico», y el señor sí es médico.","Nde pohanohára es «vos sos médico», hablándole a él. Ana habla de él, no con él.","Ana habla de otra persona: ha'e, «él». Ha'e pohanohára, «él es médico», sin ningún «es».","Peẽ es «ustedes», varias personas a las que les hablás. Es un solo señor, y Ana habla de él."]},{"id":"a1u03d3.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa señala a un muchacho, ^el compañero de Luis^.)\nRosa: Mávapa ha'e?\nLuis: (   ) che irũ.","options":["Che","Ha'e","Nde","Ndaha'éi"],"answer":2,"why":["Che che irũ sería «yo soy mi compañero»: che es «yo» y che irũ, «mi compañero». Así no se dice quién es el muchacho.","Rosa pregunta quién es él, y Luis responde con ha'e y quién es: Ha'e che irũ, «es mi compañero».","Nde che irũ es «vos sos mi compañero», hablándole a Rosa. Luis habla del muchacho.","Ndaha'éi che irũ es «no es mi compañero», y sí lo es: Rosa señala al compañero de Luis."]},{"id":"a1u03d3.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis muestra una foto. Rosa cree que es su mamá, pero ^es su abuela^.)\nLuis: (   ) che sy, ha'e che jarýi.","options":["Ndaha'éi","Nahániri","Ha'e","Che"],"answer":1,"why":["Para negar un «es», ndaha'éi: el nd-…-i de la unidad 2 alrededor de ha'e. Ndaha'éi che sy, «no es mi mamá».","Nahániri es «no», la respuesta suelta a una pregunta de sí o no. Para decir «no es» hace falta ndaha'éi, una sola palabra.","Ha'e che sy es «es mi mamá», y la de la foto no es su mamá: Luis lo niega.","Che che sy sería «yo soy mi mamá». Luis no habla de él mismo: dice quién es la de la foto."]},{"id":"a1u03d3.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis no es profesor.)\nAna: Luis ","after":" mbo'ehára, ha'e pohanohára.","tiles":["nda","ha'e","i"],"bank":[2,0,1],"hint":"El «no» de la unidad 2 tiene dos partes que rodean la palabra: nda- adelante y -i al final.","full":"(Luis no es profesor.)\nAna: Luis {nda}ha'é{i} mbo'ehára, ha'e pohanohára.","es":"Ana: Luis no es profesor, es médico.","explain":"nda- + ha'e + -i = ndaha'éi, «no es»: el «no» de dos partes rodea a ha'e. La -i no se lleva el acento: queda en la e de ha'e, que ya no es la última vocal, y por eso se escribe é: ndaha'éi. Después, sin negación: ha'e pohanohára, «es médico»."},{"id":"a1u03d3.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(En la fiesta, Luis dice qué es.)\nLuis: Che ","after":".","tiles":["pohano","hára"],"bank":[1,0],"hint":"-hára, «el que hace», es un sufijo: va después de la raíz, como en mbo'ehára.","full":"(En la fiesta, Luis dice qué es.)\nLuis: Che pohano{hára}.","es":"Luis: Soy médico.","explain":"pohano («curar») + -hára («el que») = pohanohára, «el que cura», el médico, como mbo'ehára, «el que enseña». Con che adelante y sin verbo: Che pohanohára, «soy médico». -hára se lleva el acento: por eso la tilde va en hára, y pohano no lleva ninguna."}],"exam":[{"id":"a1u03d3.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"(Rosa pregunta por un hombre de la foto.)\nLuis: _Ndaha'éi che irũ_.","options":["Es mi compañero.","No es mi compañero.","No es mi mamá.","Mi compañero no está."],"answer":2,"explain":"Ndaha'éi es «no es»: el nd-…-i de la negación alrededor de ha'e. Che irũ es «mi compañero». «Es mi compañero» sería Ha'e che irũ, sin negar; «mi mamá» es che sy; y «no está» hablaría de un lugar, no de quién es alguien."},{"id":"a1u03d3.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la fiesta, una vecina dice qué es: vendedora.)\nVecina: Che (   ).","options":["añemuhára","oñemuhára","iñemuhára","ñemuhára"],"answer":4,"explain":"Para decir qué sos, che y el sustantivo, nada más: Che ñemuhára, «soy vendedora». Añemuhára y oñemuhára llevan a- y o-, los prefijos de las acciones, y ñemuhára es un sustantivo: va sin prefijo. Iñemuhára lleva i-, que es de otra persona, como en ikane'õ."},{"id":"a1u03d3.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Rosa muestra una foto de un señor.)\nRosa: ","after":" che ru, ha'e che angirũ.","tiles":["nda","ha'e","i"],"bank":[1,2,0],"full":"(Rosa muestra una foto de un señor.)\nRosa: {Nda}ha'é{i} che ru, ha'e che angirũ.","es":"Rosa: No es mi papá, es mi amigo.","explain":"nda- va primero, después ha'e y al final -i: ndaha'éi, «no es». El «no» del guaraní tiene dos partes que rodean la palabra. La tilde va en la é porque -i no se lleva el acento. Después, sin negar: ha'e che angirũ, «es mi amigo»."}]},"words":{"es":"La fiesta de San Juan del barrio","intro":"Es la noche de San Juan en el barrio: hay fuego, chipa y música. Ana te presenta a su gente: quién es cada uno y qué hace. Tocá cada palabra.","sound":{"focus":"La ñ, sin ~ al lado: kuña, ñemuhára","letters":["ñ"],"note":"La ñ suena como en castellano, y en guaraní también empieza muchas palabras: ñemuhára, ñande, ñu. La vocal que la toca ya suena nasal por ella, y por eso se escribe sin ~: kuña, no «kuñã». No hay pares mínimos seguros: son palabras para contrastar, unas con ~ y otras sin ~.","pairs":[["kuña","mujer","mitã","niño, niña"],["ñu","campo","irũ","compañero, compañera"],["ñande","nosotros, con vos","ñe'ẽ","hablar"]]},"words":[{"id":"pohanohara","gn":"pohanohára","es":"médico, médica","parts":[["pohano","curar, sanar"],["-hára","el que, la que"]],"note":"Como mbo'ehára: -hára es «el que hace» y se lleva el acento: po-ha-no-HÁ-ra. También se ve escrito pohãnohára, con la ~ de pohã, «remedio»: es la misma palabra."},{"id":"mbaapohara","gn":"mba'apohára","es":"trabajador, trabajadora","parts":[["mba'apo","trabajar"],["-hára","el que"]],"note":"El que trabaja en un lugar: un obrero, una empleada. En los diarios se lee mucho, por «los trabajadores»."},{"id":"chokokue","gn":"chokokue","es":"agricultor, agricultora","note":"La ch suena como en che. Es la palabra para «campesino, agricultor»; los diarios la usan mucho."},{"id":"nemuhara","gn":"ñemuhára","es":"vendedor, vendedora","parts":[["ñemu","vender, comerciar"],["-hára","el que"]],"note":"También «comerciante»."},{"id":"mitarusu","gn":"mitãrusu","es":"muchacho, joven","parts":[["mitã","niño"],["-rusu","grande"]],"note":"Un niño ya grande: un adolescente, un joven."},{"id":"mitakuna","gn":"mitãkuña","es":"chica, muchacha joven","parts":[["mitã","niño, niña"],["kuña","mujer"]],"note":"Va de la niña a la muchacha joven. Kuñataĩ (unidad 1) es la muchacha ya más grande, la señorita."},{"id":"kunakarai","gn":"kuñakarai","es":"señora","parts":[["kuña","mujer"],["karai","señor"]],"note":"Ña Ramona (unidad 1) es una kuñakarai. Sin tilde: el acento cae al final, ka-ra-i."},{"id":"cheiru","gn":"che irũ","es":"mi compañero, mi compañera","parts":[["che","mi"],["irũ","compañero, compañera"]],"note":"Un amigo cercano es che angirũ (unidad 1). Che + sustantivo también puede ser una oración: Che mbo'ehára, «soy profesora». El contexto decide."}],"spell":["pohanohara","mbaapohara","nemuhara","mitakuna"],"check":{"id":"a1u03d3.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"En la fiesta, Ana te presenta a una _señora_, la mamá de Luis. ¿Cómo se escribe en guaraní?","options":["kuñacarai","kunakarai","kuñakarai","kuñakarãi"],"answer":3,"explain":"Se escribe kuñakarai: kuña, «mujer», con ñ, y karai, «señor», con k, porque la c no es una letra del guaraní. Kunakarai pierde la ñ. Kuñakarãi le pone una tilde nasal a la a: karãi es otra palabra, «arañar». Karai, «señor», es todo oral: ka-ra-i, con el acento al final y sin ninguna marca."}},"skill":{"kind":"listening","es":"Comprensión de puntos clave","situation":"En la fiesta de San Juan, Ana le presenta dos personas a Luis.","ask":"¿Qué es Lucas?","item":{"id":"a1u03d3.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué es Lucas?","options":["Médico.","Profesor.","Agricultor."],"answer":1,"why":["Ana dice Lucas ha'e che irũ, «Lucas es mi compañero», y enseguida Ha'e pohanohára: ese ha'e es Lucas, y pohanohára es «médico».","Mbo'ehára, «profesora», es la mamá de Ana: de ella dice Ha'e mbo'ehára, antes de presentar a Lucas.","Agricultor es chokokue, y nadie lo dice en la fiesta."],"script":["Narrador: En la fiesta de San Juan. Ana presenta a dos personas. ¿Qué es Lucas?","Mujer: Ha'e che sy, Luis. Ha'e mbo'ehára.","Hombre: Mba'éichapa, kuñakarai.","Mujer: Ha Lucas ha'e che irũ. Ha'e pohanohára.","Hombre: Maitei, Lucas."]},"audio":[["N","En la fiesta de San Juan. Ana presenta a dos personas. ¿Qué es Lucas?","En la fiesta de San Juan. Ana presenta a dos personas. ¿Qué es Lucas?"],["F","Ha'e che sy, Luis. Ha'e mbo'ehára.","Ella es mi mamá, Luis. Es profesora."],["M","Mba'éichapa, kuñakarai.","Hola, señora."],["F","Ha Lucas ha'e che irũ. Ha'e pohanohára.","Y Lucas es mi compañero. Es médico."],["M","Maitei, Lucas.","Hola, Lucas."]]}},{"title":"Sí/no con -pa y piko; respuestas","grammar":{"points":[{"id":"a1u03d4.p1","form":"-pa en la palabra que preguntás","gloss":"pregunta de sí o no, con estados y nombres","connect":[{"pos":"-pa va pegado a la palabra que preguntás, que suele ir primera. Con nde queda Ndépa, como en la unidad 1","rule":"Ndé{pa} pohanohára?"},{"pos":"Con un estado, va en el estado; la persona viene después","rule":"Ikane'õ{pa} nde ru?"},{"pos":"Con una acción, en el verbo, como en la unidad 1","rule":"Og̃uahẽ{pa} Ana? · Rejú{pa} ko pyhare?"},{"pos":"-pa no se lleva el acento. Si la vocal tónica deja de ser la última, se escribe la tilde; sobre una vocal con ~ no se agrega nada","rule":"nde → ndé{pa} · reju → rejú{pa} · og̃uahẽ → og̃uahẽ{pa}"}],"examples":[{"gn":"Ana: Ndé{pa} pohanohára?\nLuis: Héẽ, che pohanohára.","es":"Ana: ¿Vos sos médico?\nLuis: Sí, soy médico.","parts":[["nde","vos"],["-pa","pregunta"],["pohanohára","médico, médica; también se ve pohãnohára"],["héẽ","sí"]]},{"gn":"Ikane'õ{pa} nde ru?","es":"¿Está cansado tu papá?","parts":[["i-","él, ella (le pasa)"],["kane'õ","cansancio"],["-pa","pregunta"],["nde ru","tu papá"]]},{"gn":"Og̃uahẽ{pa} Ana?","es":"¿Llegó Ana?","parts":[["o-","él, ella"],["g̃uahẽ","llegar"],["-pa","pregunta"]]},{"gn":"Rejú{pa} ko pyhare?","es":"¿Venís esta noche?","parts":[["re-","vos"],["ju","venir"],["-pa","pregunta"],["ko pyhare","esta noche"]]}],"watch":{"note":"-pa es un sufijo: va pegado, sin espacio, a la palabra que preguntás. No es una palabra suelta, como el «¿no?» que el castellano agrega al final.","bad":"Ikane'õ pa nde ru?","good":"Ikane'õpa nde ru?"}},{"id":"a1u03d4.p2","form":"piko · Héẽ / Nahániri / na-…-i","gloss":"pregunta con sorpresa · las respuestas","connect":[{"pos":"piko va donde iría -pa, después de la palabra que preguntás. En la charla suele sumar sorpresa o duda: «¿en serio?»","rule":"Nde {piko} mbo'ehára? · Og̃uahẽ {piko} Ana?"},{"pos":"Acá piko va suelto. También lo vas a ver pegado, y entonces nde lleva tilde. En el castellano del Paraguay se oye «pio»","rule":"Nde {piko} mbo'ehára? · Ndé{piko} mbo'ehára?"},{"pos":"Para responder que sí: Héẽ y el estado, ya sin -pa. Si te preguntan por vos (Nekane'õpa?), respondés con che-. Para responder que no: Nahániri","rule":"{Héẽ}, chekane'õ. · {Nahániri}."},{"pos":"Para negar un estado, el «no» de dos partes de la unidad 2 rodea a che- y al estado: na-…-i si la palabra es nasal, nda-…-i si es oral","rule":"{Na}chemandu'á{i}. · {Nda}chevare'á{i}."}],"examples":[{"gn":"Luis: Nde {piko} mbo'ehára?\nAna: {Héẽ}, che mbo'ehára.","es":"Luis: ¿En serio sos profesora?\nAna: Sí, soy profesora.","parts":[["nde","vos"],["piko","¿en serio? (sorpresa, duda)"],["mbo'ehára","profesora"],["héẽ","sí"]]},{"gn":"Rosa: Og̃uahẽ pohanohára.\nJuan: Añeté{pa}?\nRosa: {Héẽ}, {upéicha}.","es":"Rosa: Llegó el médico.\nJuan: ¿De verdad?\nRosa: Sí, así es.","parts":[["og̃uahẽ","llega, llegó"],["añete","verdad, cierto"],["-pa","pregunta"],["héẽ","sí"],["upéicha","así"]]},{"gn":"Ana: Nekane'õ{pa}?\nLuis: {Nahániri}, {na}chekane'õ{i}. Chevare'a.","es":"Ana: ¿Estás cansado?\nLuis: No, no estoy cansado. Tengo hambre.","parts":[["ne-","vos, ante una palabra nasal"],["kane'õ","cansancio"],["-pa","pregunta"],["nahániri","no"],["na-…-i","no, en dos partes"],["chevare'a","tengo hambre"]]},{"gn":"Juan: Og̃uahẽ {piko} Ana?\nRosa: {Héẽ}, og̃uahẽ ko'ág̃a.","es":"Juan: ¿En serio llegó Ana?\nRosa: Sí, llegó ahora.","parts":[["og̃uahẽ","llega, llegó"],["piko","¿en serio?"],["héẽ","sí"],["ko'ág̃a","ahora"]]}],"watch":{"note":"El «no» del castellano puesto delante no niega el estado. Nahániri responde que no; para negar el estado va el «no» de dos partes de la unidad 2, alrededor de che- y del estado. Es na-…-i si la palabra es nasal (nachemandu'ái, nachekane'õi) y nda-…-i si es oral (ndachevare'ái).","bad":"No chemandu'a.","good":"Nachemandu'ái."}}],"compare":{"intro":"Tres preguntas: una neutra con -pa, una con sorpresa con piko y una abierta, que no se responde con sí o no.","forms":[{"form":"-pa","tag":"sí o no · neutra","mark":"dot","gn":"Ndé{pa} mbo'ehára?","es":"¿Vos sos profesora?"},{"form":"piko","tag":"sí o no · sorpresa, duda","mark":"up","gn":"Nde {piko} mbo'ehára?","es":"¿Vos sos profesora? ¿En serio?"},{"form":"Mba'éichapa…?","tag":"pregunta abierta · unidad 1","mark":"dot","gn":"{Mba'éichapa} reiko?","es":"¿Cómo andás?"}],"check":{"id":"a1u03d4.c1","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(Rosa es ^profesora^.)\nAna: Ndépa pohanohára?\nRosa: (   )","options":["Mba'éichapa?","Nahániri, che mbo'ehára.","Héẽ, chekane'õ."],"answer":2,"why":["Mba'éichapa? es un saludo y una pregunta abierta: no responde a una pregunta de sí o no.","Ndépa pohanohára? pregunta sí o no por lo que es Rosa. Ella responde que no y dice qué es: Nahániri, che mbo'ehára, «no, soy profesora».","Héẽ diría que sí es médica, y Rosa es profesora. Además, chekane'õ habla de cansancio, y Ana preguntó qué es Rosa, no cómo está."]}},"drill":[{"id":"a1u03d4.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis quiere saber si ^el papá de Ana está enfermo^.)\nLuis: (   ) nde ru?","options":["Rasýpa","Pa hasy","Hasýpa","Ikane'õpa"],"answer":3,"why":["Rasy es la forma que va con che- y nde-, como réra en che réra y nde réra: cherasy. Para otra persona, nde ru, va h-: hasy, como héra.","-pa no va delante ni suelto: es un sufijo y se pega al final de la palabra que preguntás, Hasýpa.","Luis pregunta por hasy, «está enfermo», y -pa va pegado a esa palabra: Hasýpa nde ru?, «¿está enfermo tu papá?». Hasy termina en y tónica; con -pa esa y ya no es la última vocal y se escribe la tilde: hasýpa.","Ikane'õpa pregunta si está cansado, y Luis quiere saber si está enfermo: hasy."]},{"id":"a1u03d4.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana quiere saber si Luis es médico. ^Se lo pregunta a él^.)\nAna: (   ) pohanohára?","options":["Ndépa","Ha'épa","Ndéve","Mávapa"],"answer":1,"why":["Ana le pregunta a Luis por él mismo: nde + -pa = Ndépa, con tilde porque la e ya no es la última vocal. Ndépa pohanohára?, «¿vos sos médico?».","Ha'épa pohanohára? pregunta por otra persona: ha'e, «él, ella». Ana le habla a Luis y pregunta por él mismo: nde.","Ndéve es «a vos», como en Aguyje ndéve (unidad 1): lleva -ve, no -pa, y no pregunta nada.","Mávapa pohanohára? es «¿quién es médico?»: una pregunta abierta, que no se responde con sí o no. Ana quiere saber si Luis lo es: Ndépa."]},{"id":"a1u03d4.d3","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"Juan: Nde piko pohanohára?\nAna: (   ), ^che mbo'ehára^.","options":["Héẽ","Nahániri","Upéicha","Aguyje"],"answer":2,"why":["Héẽ es «sí», pero Ana dice che mbo'ehára, «soy profesora»: no es médica. Responde que no.","Juan pregunta, con sorpresa, si Ana es médica. Ella es profesora, así que responde Nahániri, «no», y dice lo que sí es.","Upéicha confirma, como en Héẽ, upéicha, «sí, así es»: diría que Ana es médica, y ella dice que es profesora.","Aguyje es «gracias»: no responde que sí ni que no. Ana corrige a Juan: Nahániri."]},{"id":"a1u03d4.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa le ofrece chipá, pero Juan ^no tiene hambre^.)\nRosa: [Reipotápa|¿querés?] chipa?\nJuan: Nahániri, (   ).","options":["chevare'a","nachevare'ái","ndavare'ái","ndachevare'ái"],"answer":4,"why":["Chevare'a es «tengo hambre»: afirma, y Juan no tiene hambre.","na- va solo delante de una palabra nasal, como en nachemandu'ái. Vare'a es oral: nda-.","Ndavare'ái conjuga vare'a como una acción: nd- + a- + vare'a + -i, con la a- de ndahái, «no voy» (unidad 2). Vare'a es un estado y lleva che-: ndachevare'ái.","Vare'a es oral, sin ~ ni m, n, ñ: el «no» de dos partes es nda-…-i alrededor de chevare'a. Ndachevare'ái, «no tengo hambre». La tilde aparece en la á porque -i no se lleva el acento."]},{"id":"a1u03d4.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana pregunta si llegó el médico.)\nAna: ","after":" pohanohára?","tiles":["o","g̃uahẽ","pa"],"bank":[2,0,1],"hint":"El prefijo de «él, ella» va primero, pegado a g̃uahẽ. -pa cierra la palabra que pregunta.","full":"(Ana pregunta si llegó el médico.)\nAna: {O}g̃uahẽ{pa} pohanohára?","es":"Ana: ¿Llegó el médico?","explain":"o- («él, ella») + g̃uahẽ («llegar») + -pa (pregunta) = Og̃uahẽpa, «¿llegó?». -pa va pegado a la palabra que pregunta, acá la primera, y la persona, pohanohára, viene después. El acento sigue en la ẽ: la ~ ya lo marca y no se agrega tilde."},{"id":"a1u03d4.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Rosa pregunta por la fiesta, y Juan no se acuerda.)\nRosa: Nemandu'ápa?\nJuan: ","after":".","tiles":["na","che","mandu'a","i"],"bank":[3,1,0,2],"hint":"El «no» tiene dos partes: una al principio y otra al final. En el medio van che- y el estado.","full":"(Rosa pregunta por la fiesta, y Juan no se acuerda.)\nRosa: Nemandu'ápa?\nJuan: {Na}chemandu'á{i}.","es":"Rosa: ¿Te acordás?\nJuan: No me acuerdo.","explain":"na- + che- + mandu'a («acordarse») + -i = Nachemandu'ái, «no me acuerdo». Mandu'a es nasal, con m y nd: por eso va na- y no nda-. -i no se lleva el acento: queda en la a final de mandu'a, que ya no es la última vocal, y se escribe á."}],"exam":[{"id":"a1u03d4.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Luis: Og̃uahẽ pohanohára.\nAna: _Añetépa?_","options":["¿Ahora?","¿Quién?","¿De verdad?","¿Dónde está?"],"answer":3,"explain":"Añete es «verdad, cierto», y -pa lo vuelve pregunta: Añetépa?, «¿de verdad?». Ahora es ko'ág̃a, ¿quién? es Mávapa y ¿dónde? es Moõpa: ninguna de esas palabras está en lo subrayado."},{"id":"a1u03d4.e2","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(La mamá de Luis está cansada.)\nAna: Ikane'õpa nde sy?\nLuis: (   )","options":["Héẽ, kane'õ.","Héẽ, nekane'õ.","Nahániri, ikane'õ.","Héẽ, ikane'õ."],"answer":4,"explain":"Ana pregunta por la mamá de Luis, otra persona, y ella sí está cansada: Héẽ, ikane'õ, «sí, está cansada», con la i- de la tercera persona. Héẽ, kane'õ no dice de quién es el cansancio, le falta la i-; Héẽ, nekane'õ le diría a Ana que ella está cansada; y Nahániri, ikane'õ se contradice: dice «no» y después «está cansada»."},{"id":"a1u03d4.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis comió hace un rato.)\nLuis: ","after":".","tiles":["nda","che","vare'a","i"],"bank":[2,0,3,1],"full":"(Luis comió hace un rato.)\nLuis: {Nda}chevare'á{i}.","es":"Luis: No tengo hambre.","explain":"nda- + che- + vare'a («hambre») + -i = Ndachevare'ái, «no tengo hambre». El «no» tiene dos partes que rodean a che- y al estado. Vare'a es oral, sin ~ ni m, n, ñ: por eso va nda- y no na-. -i no se lleva el acento: queda en la a final de vare'a y se escribe á."}]},"words":{"es":"¿Ya llegó? Un chat de sí o no","intro":"Ana y su mamá se escriben: la abuela está enferma y esperan al médico. Tocá cada palabra del chat.","sound":{"focus":"La g̃: una g con nariz","letters":["g̃"],"note":"La g̃ es la g suave de «agua» con el aire saliendo también por la nariz: og̃uahẽ, ko'ág̃a, ag̃aite. Los diarios escriben la g sin la ~ (oguahẽ) o pasan la ~ a la vocal (ko'ágã): son las mismas palabras, y acá las escribimos con g̃. No hay pares mínimos: compará la g sin nariz con la g̃ con nariz.","pairs":[["aguyje","gracias","ag̃aite","enseguida"],["jagua","perro","og̃uahẽ","llega"],["óga","casa","ko'ág̃a","ahora"]]},"words":[{"id":"oguahe","gn":"og̃uahẽ","es":"llega, llegó","parts":[["o-","él, ella"],["g̃uahẽ","llegar"]],"note":"Como en Tereg̃uahẽ porãite (unidad 1). Los diarios escriben oguahẽ, sin la ~ en la g; acá va con g̃."},{"id":"koaga","gn":"ko'ág̃a","es":"ahora","note":"Og̃uahẽ ko'ág̃a: llegó ahora. También se ve ko'ágã, con la ~ en la última a."},{"id":"agaite","gn":"ag̃aite","es":"enseguida, ahora mismo","parts":[["ag̃a","luego, pronto"],["-ite","muy, mismo"]],"note":"Ag̃aite ag̃uahẽta: enseguida llego. La -ta es la del futuro, como en Jajotopáta."},{"id":"anete","gn":"añete","es":"cierto, verdad","note":"Añetépa?: ¿de verdad?"},{"id":"upeicha","gn":"upéicha","es":"así","note":"Para confirmar lo que te dicen: Héẽ, upéicha, «sí, así es». Lleva tilde en la é: el acento no cae en la última vocal."},{"id":"ndahaei","gn":"ndaha'éi","es":"no es","parts":[["nda-","no (primera parte)"],["ha'e","es"],["-i","no (segunda parte)"]],"note":"Una sola palabra, con la tilde en la é. Ndaha'éi che sy: no es mi mamá. Con che y nde no cambia: Che ndaha'éi pohanohára, «no soy médico»."},{"id":"ndaikatui","gn":"ndaikatúi","es":"no se puede, no puedo","parts":[["nda-","no"],["ikatu","se puede"],["-i","no"]],"note":"Ikatu es «se puede» (unidad 1): ndaikatúi, «no se puede». Lleva tilde en la ú."},{"id":"nachemandua","gn":"nachemandu'ái","es":"no me acuerdo","parts":[["na-","no"],["che-","yo"],["mandu'a","acordarse"],["-i","no"]],"note":"Chemandu'a: me acuerdo. Mandu'a es nasal, por eso va na- y no nda-."}],"spell":["oguahe","koaga","agaite","ndahaei"],"check":{"id":"a1u03d4.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana escribe que el médico llegó _ahora_. ¿Cómo se escribe en guaraní?","options":["ko'ág̃a","koág̃a","ko'aga","ko'ãga"],"answer":1,"explain":"Ahora es ko'ág̃a: con puso entre la o y la a, con la tilde en la á, porque el acento no cae en la última vocal, y con la g̃, la g con nariz. Koág̃a perdió el puso y ko'aga no tiene ninguna marca. Ko'ãga pone la ~ en la primera a: ahí va la tilde del acento, y la nariz va después, en la g̃. Los diarios la escriben en la última a: ko'ágã."}},"skill":{"kind":"reading","es":"Un chat con mamá","ask":"¿Quién llega ahora?","seconds":60,"passage":"Mamá: Mba'éichapa, Ana? Nde jarýi hasy.\nAna: Añetépa? ^Og̃uahẽpa pohanohára?^\nMamá: ^Héẽ, og̃uahẽ ko'ág̃a.^\nAna: Ha nde? Nekane'õpa?\nMamá: Nahániri. Chevare'a.","strategy":"Hay tres preguntas con -pa. Buscá la que habla de llegar, og̃uahẽ, y leé la respuesta que viene justo después: ahí está el dato.","item":{"id":"a1u03d4.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quién llega ahora?","options":["Ana.","El médico.","La mamá de Ana.","La abuela."],"short":["Ana","El médico","La mamá","La abuela"],"answer":2,"why":["Ana es la que pregunta Og̃uahẽpa pohanohára?: quiere saber si llegó el médico. No dice que ella llegue a ningún lado.","Ana pregunta Og̃uahẽpa pohanohára?, «¿llegó el médico?», y mamá responde Héẽ, og̃uahẽ ko'ág̃a: sí, llegó ahora. El que llega es el médico.","De la mamá habla la última pregunta, Nekane'õpa?, «¿estás cansada?». Ella responde Nahániri, «no», y agrega Chevare'a, «tengo hambre». No dice que llegue.","La abuela, nde jarýi, está enferma, hasy: por eso viene el médico. La que llega no es ella."],"explain":"Ana pregunta Og̃uahẽpa pohanohára? y mamá responde Héẽ, og̃uahẽ ko'ág̃a: el médico llegó ahora. La abuela, nde jarýi, está enferma (hasy), y la mamá no está cansada: tiene hambre (chevare'a)."}}},{"title":"Acento: palabra aguda por defecto y tilde","grammar":{"points":[{"id":"a1u03d5.p1","form":"jagua · óga · mitã","gloss":"sin marca: aguda · con tilde: el acento va antes · vocal con ~: nunca tilde","connect":[{"pos":"Sin ninguna marca, el acento cae en la última vocal: al revés del castellano","rule":"jagu{a} · kara{i} · terer{e} · Ypakara{i}"},{"pos":"Si cae antes, se escribe la tilde en esa vocal, también en los diptongos","rule":"{ó}ga · jar{ý}i · purah{é}i · Paragu{á}i · mba'{é}ichapa"},{"pos":"Una vocal con ~ nunca lleva tilde, ni cuando es la tónica: si el acento cae en ella, la ~ basta","rule":"mit{ã} · kane'{õ} · pete{ĩ}"}],"examples":[{"gn":"{Jagua} okaru.","es":"El perro come.","parts":[["jagua","perro: ja-GUA, aguda, sin tilde"],["okaru","come: o-ka-RU, aguda, sin tilde"]]},{"gn":"{Karai} Juan ipochy.","es":"Don Juan está enojado.","parts":[["karai","señor: ka-ra-I, aguda, sin tilde"],["karai Juan","don Juan"],["ipochy","está enojado: i-po-CHY, sin tilde"]]},{"gn":"Che {róga} ituicha.","es":"Mi casa es grande.","parts":[["róga","casa, después de che: RÓ-ga, el acento va antes y se escribe la tilde"],["ituicha","es grande: i-tui-CHA, aguda, sin tilde"]]},{"gn":"{Purahéi} iporã.","es":"La canción es linda.","parts":[["purahéi","canción: pu-ra-HÉI, la tilde va en la e del diptongo"],["iporã","es linda: i-po-RÃ, la ~ marca la nasal y el acento"]]}],"watch":{"note":"El castellano marca con tilde la aguda que termina en vocal: tereré, ñandutí, guaraní. El guaraní no la marca: terere, ñanduti y, en los textos en guaraní, guarani. La tilde guaraní marca lo que NO es aguda. Si le ponés tilde a jagua, escribís una marca que el guaraní no usa: sin ninguna marca, el acento ya cae en la última vocal.","bad":"Jaguá okaru.","good":"Jagua okaru."}},{"id":"a1u03d5.p2","form":"ikatúpa · Itauguápe · ógape","gloss":"con -pa, -pe o -gui, la tilde aparece o se queda donde estaba","connect":[{"pos":"-pa, -pe (o -me) y -gui no se llevan el acento: queda en la raíz, y como esa vocal ya no es la última de la palabra, se escribe la tilde","rule":"ikatu → ikat{ú}pa · Itaugua → Itaugu{á}pe · Ypakarai → Ypakara{í}pe"},{"pos":"Con estos sufijos, si la palabra ya tenía tilde, la tilde se queda donde estaba","rule":"óga → {ó}gape · Paraguái → Paragu{á}ipe"},{"pos":"Si la vocal tónica lleva ~, no cambia nada: la ~ ya marca el acento","rule":"tetã → tet{ã}me · tet{ã}gui · oĩ → o{ĩ}pa"},{"pos":"Ojo con -gua, el «de» de origen de la unidad 1: ese sí se lleva el acento, y la raíz pierde su tilde","rule":"Paraguái → Paraguai{gua}"}],"examples":[{"gn":"Aha {Itauguápe}.","es":"Voy a Itauguá.","parts":[["aha","voy"],["Itaugua","Itauguá: I-tau-GUA, sola va sin tilde"],["-pe","a: no se lleva el acento, y la a de Itaugua se escribe á"]]},{"gn":"Aju {Paraguáigui}.","es":"Vengo de Paraguay.","parts":[["aju","vengo"],["Paraguái","Paraguay: Pa-ra-GUÁI, ya lleva tilde"],["-gui","de: no se lleva el acento, la tilde se queda"]]},{"gn":"{Reikuaápa} Ypakarai?","es":"¿Conocés Ypacaraí?","parts":[["reikuaa","conocés, sabés: rei-kua-A"],["-pa","pregunta: no se lleva el acento, y la a final se escribe á"],["Ypakarai","Ypacaraí: sola, aguda y sin tilde"]]},{"gn":"Aike {mbo'ehaópe}.","es":"Entro a la escuela.","parts":[["aike","entro, paso"],["mbo'ehao","escuela: mbo-'e-ha-O"],["-pe","a, en: la o de mbo'ehao se escribe ó"]]}],"watch":{"note":"Itaugua, sola, no lleva tilde: es aguda. Con -pe, la a tónica ya no es la última vocal y la tilde se escribe: Itauguápe. Son las dos caras de la misma regla, y la segunda es la que se olvida.","bad":"Itauguape","good":"Itauguápe"}}],"compare":{"intro":"Tres palabras y tres acentos: una aguda sin tilde, una con tilde y una que recibe la tilde cuando lleva sufijo.","forms":[{"form":"jagua","tag":"sin tilde · aguda","mark":"dot","gn":"{Jagua} okaru.","es":"El perro come."},{"form":"óga · che róga","tag":"con tilde · el acento va antes","mark":"dot","gn":"Che {róga} ituicha.","es":"Mi casa es grande."},{"form":"ikatúpa","tag":"con sufijo · aparece la tilde","mark":"dot","gn":"{Ikatúpa} aike?","es":"¿Puedo pasar?"}],"check":{"id":"a1u03d5.c1","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Luis escribe en la pizarra: jaguá, óga, ikatupa. Se dicen ^ja-GUA, Ó-ga, i-ka-TÚ-pa^. ¿Cuál de las tres está _bien escrita_?","options":["jaguá","óga","ikatupa"],"answer":2,"why":["Jagua es aguda, ja-GUA, y en guaraní la aguda no lleva tilde. Esa tilde es la costumbre del castellano.","Óga se dice Ó-ga: el acento va antes de la última vocal, y por eso se escribe la tilde. Está bien.","Ikatu es aguda y va sin tilde, pero con -pa la u tónica ya no es la última vocal y hay que escribir la tilde: ikatúpa."]}},"drill":[{"id":"a1u03d5.d1","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Rosa escribe cuatro palabras que se dicen ^con el acento en la última vocal^: ja-GUA, ka-ra-I, mi-TÃ, te-re-RE. Solo una está _bien escrita_. ¿Cuál?","options":["terere","jaguá","karái","mitá"],"answer":1,"why":["Terere es aguda, te-re-RE, y en guaraní la aguda no lleva tilde. El castellano escribe tereré; el guaraní, terere.","Jagua es aguda, ja-GUA: sin tilde. Jaguá lleva la tilde del castellano, que acá sobra.","Karai se dice ka-ra-I, con el acento al final: sin tilde. Karái movería el acento a la a del medio.","Mitã es aguda, pero su a es nasal: lleva la ~, y una vocal con ~ nunca lleva tilde. Mitá cambia la ~ por la tilde y pierde la nasal."]},{"id":"a1u03d5.d2","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Luis escribe cuatro palabras que se dicen ^con el acento antes de la última vocal^: na-HÁ-ni-ri, mbo-'e-HÁ-ra, TÉ-ra, pu-ra-HÉI. Solo una está _bien escrita_. ¿Cuál?","options":["nahaniri","mbo'éhara","terá","purahéi"],"answer":4,"why":["Sin tilde, nahaniri se leería na-ha-ni-RI, como una aguda. El acento va en la segunda a, y por eso lleva tilde: nahániri.","La tilde está, pero en otra vocal: mbo'éhara se leería mbo-'É-ha-ra. El acento va en la a de hára: mbo'ehára.","Terá lleva la tilde en la última vocal, donde el guaraní no la escribe nunca, y así se leería te-RA. El acento va en la e: téra.","Purahéi se dice pu-ra-HÉI: el acento cae antes de la última vocal y se escribe la tilde, en la e del diptongo. Está bien."]},{"id":"a1u03d5.d3","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Luis escribe cuatro lugares con -pe, «en». ^-pe no se lleva el acento^. Solo uno está _bien escrito_. ¿Cuál?","options":["kotype","ogápe","Itauguápe","mbo'ehaope"],"answer":3,"why":["Koty lleva el acento en la y final (unidad 2). Con -pe esa y ya no es la última vocal y hay que escribir la tilde: kotýpe.","Óga ya tenía su tilde en la o, y con -pe se queda ahí: ógape. Ogápe la mueve a la a, y así se leería o-GÁ-pe.","Itaugua es aguda y va sin tilde. Con -pe, la a tónica ya no es la última vocal y se escribe la tilde: Itauguápe. Está bien.","Mbo'ehao lleva el acento en la o final (unidad 2). Con -pe esa o queda adentro de la palabra y se escribe mbo'ehaópe: acá falta la tilde."]},{"id":"a1u03d5.d4","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"Ana escribe «Aju Paraguáigui», «vengo de Paraguay». ^Paraguái ya tenía tilde^. ¿Qué pasa con la _tilde_ al agregar -gui?","options":["Se queda en la á: -gui no se lleva el acento.","Se mueve a -gui, que ahora es el final de la palabra.","Se borra: con sufijo no hay tilde.","Se escriben dos: Paraguáiguí."],"answer":1,"why":["Paraguái ya lleva su tilde en la á. -gui no se lleva el acento, así que todo queda igual: Paraguáigui. Lo mismo pasa con -pe: Paraguáipe.","-gui nunca se lleva el acento: sigue en la á de Paraguái. El que sí se lo lleva es -gua, y por eso Paraguaigua va sin tilde.","La tilde no se borra: el acento sigue en la á, que no es la última vocal, y por eso se escribe. Solo se pierde con un sufijo que se lleva el acento, como -gua.","Una palabra lleva una sola tilde, en la vocal tónica. Paraguáiguí tendría dos, y -gui no se lleva el acento."]},{"id":"a1u03d5.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis va a Ypacaraí.)\nLuis: Aha ","after":".","tiles":["Ypakarai","pe"],"bank":[1,0],"hint":"-pe va después del lugar, pegado. Después fijate dónde queda el acento: ¿sigue en la última vocal?","full":"(Luis va a Ypacaraí.)\nLuis: Aha {Ypakaraípe}.","es":"Luis: Voy a Ypacaraí.","explain":"Ypakarai («Ypacaraí») + -pe («a») = Ypakaraípe. Ypakarai es aguda, y-pa-ka-ra-I, y sola va sin tilde. -pe no se lleva el acento: queda en esa i, que ya no es la última vocal, y por eso ahora se escribe í."},{"id":"a1u03d5.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana le pregunta a Luis si conoce Caacupé.)\nAna: ","after":" Ka'akupe?","tiles":["reikuaa","pa"],"bank":[1,0],"hint":"-pa cierra la palabra que pregunta y no se lleva el acento. ¿En qué vocal queda?","full":"(Ana le pregunta a Luis si conoce Caacupé.)\nAna: {Reikuaápa} Ka'akupe?","es":"Ana: ¿Conocés Caacupé?","explain":"reikuaa («conocés, sabés») + -pa (pregunta) = Reikuaápa. Reikuaa termina en a tónica, rei-kua-A. -pa no se lleva el acento: queda en esa a, que ya no es la última vocal, y se escribe á. Ka'akupe, sola, sigue sin tilde: es aguda."}],"exam":[{"id":"a1u03d5.e1","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Rosa anota en su cuaderno cuatro palabras que ya conocés. Solo una está _bien escrita_. ¿Cuál?","options":["ndeve","okarú","jarýi","mba'eichapa"],"answer":3,"explain":"Jarýi lleva el acento en la y, antes de la última vocal, y por eso se escribe la tilde. Ndeve y mba'eichapa también lo llevan antes del final y necesitan la suya: ndéve y mba'éichapa. Okaru, en cambio, es aguda, o-ka-RU, y va sin tilde: la de okarú es la costumbre del castellano."},{"id":"a1u03d5.e2","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Cuatro palabras con sufijo. Solo una está _bien escrita_. ¿Cuál?","options":["reikuaapa","tetáme","Paraguaigui","oĩpa"],"answer":4,"explain":"En oĩpa la vocal tónica es la ĩ, con ~: una vocal con ~ nunca lleva tilde, así que con -pa no cambia nada. En reikuaapa y Paraguaigui la vocal tónica es oral y no es la última, así que la tilde tiene que estar: reikuaápa y Paraguáigui, que conserva la de Paraguái. Y tetáme cambia la ~ por una tilde: es tetãme, con la ã nasal."},{"id":"a1u03d5.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis va a Caacupé.)\nAna: Luis oho ","after":".","tiles":["Ka'akupe","pe"],"bank":[1,0],"full":"(Luis va a Caacupé.)\nAna: Luis oho {Ka'akupépe}.","es":"Ana: Luis va a Caacupé.","explain":"Ka'akupe («Caacupé») + -pe («a») = Ka'akupépe. Ka'akupe es aguda, ka-'a-ku-PE, y sola va sin tilde. -pe no se lleva el acento: queda en la e final de Ka'akupe, que ya no es la última vocal, y por eso se escribe é."}]},"words":{"es":"Nombres que cambian de tilde en castellano","intro":"Un mapa del Paraguay y tres cosas muy paraguayas. Casi todas son agudas y van sin tilde en guaraní; el castellano les pone la suya. Solo Paraguái lleva tilde en guaraní y no en castellano. Tocá cada una.","sound":{"focus":"La tilde nasal (~) también es tilde","letters":["ã","õ","ĩ"],"note":"Una vocal con ~ nunca lleva tilde, ni cuando es la tónica: ahí la ~ marca también el acento, como en mitã, kane'õ y peteĩ. Con un sufijo que no se lleva el acento, la vocal oral recibe la tilde (ikatúpa) y la nasal queda como estaba (oĩpa, Tovatĩme). No son pares mínimos: cada par trae una palabra sola y la misma con sufijo.","pairs":[["ikatu","se puede","ikatúpa","¿se puede?"],["oĩ","hay","oĩpa","¿hay?"],["Tovatĩ","Tobatí","Tovatĩme","en Tobatí"]]},"words":[{"id":"paraguai","gn":"Paraguái","es":"Paraguay","note":"Lleva tilde: el acento no cae en la última vocal, Pa-ra-GUÁI. Con -pe la tilde se queda, Paraguáipe; con -gua se pierde, Paraguaigua (unidad 1), aunque algunos diarios escriben Paraguáigua."},{"id":"kaakupe","gn":"Ka'akupe","es":"Caacupé","note":"Ka-'a-ku-PE, aguda y sin tilde; el castellano escribe Caacupé. Es la ciudad de la Virgen de Caacupé, patrona del Paraguay, adonde se peregrina en diciembre. Con -pe: Ka'akupépe."},{"id":"ypakarai","gn":"Ypakarai","es":"Ypacaraí","note":"El lago y el pueblo. Y-pa-ka-ra-I, sin tilde. El castellano escribe Ypacaraí, y en algunos textos en guaraní se copia esa tilde. Con -pe: Ypakaraípe."},{"id":"itaugua","gn":"Itaugua","es":"Itauguá","note":"La capital del ñandutí. I-tau-GUA, sin tilde. En castellano es Itauguá, y así aparece también en muchos textos en guaraní. Con -pe: Itauguápe."},{"id":"tovati","gn":"Tovatĩ","es":"Tobatí","note":"To-va-TĨ: aguda, con la última vocal nasal. Lleva la ~ y ninguna tilde; el castellano escribe Tobatí, con b y con tilde. Es un pueblo de oleros y ceramistas, cerca de Caacupé. Con -me: Tovatĩme."},{"id":"terere","gn":"terere","es":"tereré","note":"Sin tilde en guaraní (unidad 1): te-re-RE. El castellano la necesita: tereré."},{"id":"nanduti","gn":"ñanduti","es":"ñandutí (el encaje)","note":"El encaje de Itauguá, redondo como un sol. Quiere decir «telaraña». Ñan-du-TI, sin tilde en guaraní; también se ve ñandutí, a la castellana."},{"id":"jaguarete","gn":"jaguarete","es":"yaguareté (el jaguar)","parts":[["jagua","perro"],["-ete","verdadero"]],"note":"Ja-gua-re-TE, sin tilde. El castellano lo escribe con y y con tilde: yaguareté. La j suena como la y de «yo»."}],"spell":["paraguai","kaakupe","ypakarai","tovati"],"check":{"id":"a1u03d5.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"En el mapa, Ana señala el lago: «_Ypacaraí_». ¿Cómo se escribe en guaraní?","options":["Ipakaraí","Ypacarai","Ypakarai","Ypakarãi"],"answer":3,"explain":"Ypakarai: con y, la sexta vocal, con k y sin tilde, porque es aguda y en guaraní la aguda no lleva tilde; la de Ypacaraí es del castellano, aunque a veces se copia. Ipakaraí cambia la y por i y le pone la tilde castellana. Ypacarai usa la c, que no es una letra del guaraní. Ypakarãi le pone una ~ a una vocal que no es nasal, y la ~ cambia el sonido."}},"skill":{"kind":"listening","es":"Buscar el dato","situation":"En la terminal, una mujer le cuenta a un hombre de dónde viene y adónde va.","ask":"¿Adónde va la mujer?","item":{"id":"a1u03d5.r1","kind":"choice","area":"listening","label":"Buscar el dato","q":"¿Adónde va la mujer?","options":["A Itauguá.","A Caacupé.","A Ypacaraí."],"answer":2,"why":["Itauguágui lleva -gui, «de»: Itauguá es de donde viene la mujer, no adónde va.","La mujer dice Ko'ág̃a aha Ka'akupépe: aha es «voy» y -pe, «a». Va a Caacupé.","Ypakaraípe lo dice el hombre, y habla de él: Ha che aha Ypakaraípe, «y yo voy a Ypacaraí»."],"explain":"La mujer dice Aju Itauguágui, «vengo de Itauguá», y Ko'ág̃a aha Ka'akupépe, «ahora voy a Caacupé»: -gui es de donde viene y -pe, adónde va. Ypacaraí es adonde va el hombre.","script":["Narrador: En la terminal. ¿Adónde va la mujer?","Mujer: Aju Itauguágui. Ko'ág̃a aha Ka'akupépe.","Hombre: Ha che aha Ypakaraípe.","Narrador: ¿Adónde va la mujer?"]},"audio":[["N","En la terminal. ¿Adónde va la mujer?","En la terminal. ¿Adónde va la mujer?"],["F","Aju Itauguágui. Ko'ág̃a aha Ka'akupépe.","Vengo de Itauguá. Ahora voy a Caacupé."],["M","Ha che aha Ypakaraípe.","Y yo voy a Ypacaraí."],["N","¿Adónde va la mujer?","¿Adónde va la mujer?"]]}},{"title":"Repaso de la semana","grammar":{"points":[],"compare":{"intro":"Cuatro pares de la semana que se parecen: fijate si es acción o estado, si va pegado o separado, si la pregunta lleva -pa o piko, y si hay un «es» o un «no es».","forms":[{"form":"chevare'a · akaru","tag":"estado, che- · acción, a-","mark":"dot","gn":"{Chevare'a}. Ko'ág̃a {akaru}.","es":"Tengo hambre. Ahora como."},{"form":"che sy · chekane'õ","tag":"mi, separado · estoy, pegado","mark":"dot","gn":"{Che sy} hasy ha {chekane'õ}.","es":"Mi mamá está enferma y yo estoy cansada."},{"form":"-pa · piko","tag":"pregunta neutra · con sorpresa","mark":"dot","gn":"Ndé{pa} mbo'ehára? · Nde {piko} mbo'ehára?","es":"¿Vos sos profesora? · ¿Vos sos profesora? ¿En serio?"},{"form":"ha'e · ndaha'éi","tag":"es · no es","mark":"dot","gn":"Ana {ha'e} che sy. Rosa {ndaha'éi} che sy.","es":"Ana es mi mamá. Rosa no es mi mamá."}],"check":{"id":"a1u03d6.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis muestra una foto. Rosa cree que es la mamá de Luis, pero ^es su profesora^.)\nLuis: (   ) che sy, ha'e che mbo'ehára.","options":["Ha'e","Ndaha'éi","Ndaikatúi"],"answer":2,"why":["Ha'e che sy diría «es mi mamá», y la de la foto es su profesora: Luis lo niega.","Rosa se equivoca, y Luis niega el «es» con ndaha'éi, una sola palabra: Ndaha'éi che sy, «no es mi mamá». Después, sin negar: ha'e che mbo'ehára, «es mi profesora».","Ndaikatúi es «no se puede»: el nd-…-i rodea a ikatu, no a ha'e. Ndaikatúi che sy no dice nada. Para negar un «es» va ndaha'éi."]}},"drill":[{"id":"a1u03d6.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana habla de ^su abuela^, que está enferma.)\nAna: Che jarýi (   ).","options":["cherasy","irasy","hasy","nderasy"],"answer":3,"why":["Cherasy es «estoy enferma»: Ana hablaría de ella misma. Acá habla de su abuela.","Rasy es de las palabras con tres formas, como téra, che réra, héra: tasy, cherasy, hasy. Para él o ella es hasy: irasy no existe.","Che jarýi, «mi abuela», es otra persona, y para él o ella rasy tiene su propia forma, hasy, como réra tiene héra. Che jarýi hasy, «mi abuela está enferma».","Nderasy es «estás enferma», hablándole a ella. Ana habla de su abuela, no con ella."]},{"id":"a1u03d6.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis le cuenta a Ana ^qué hace él mismo^: trabaja.)\nLuis: Ko'ág̃a (   ), Ana.","options":["amba'apo","chemba'apo","omba'apo","mba'apo"],"answer":1,"why":["Trabajar es una acción y Luis habla de él mismo: a- + mba'apo = amba'apo, «trabajo». Ko'ág̃a amba'apo, «ahora trabajo».","Che- es para los estados, como chekane'õ. Trabajar es una acción y lleva a-: chemba'apo no es «yo trabajo».","O- es «él, ella»: omba'apo es «trabaja», de otra persona. Luis habla de él mismo.","Mba'apo sin prefijo es «trabajo», la cosa, o la raíz sin persona: no dice quién trabaja."]},{"id":"a1u03d6.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa quiere saber si Juan está enojado. ^Se lo pregunta a él^.)\nRosa: (   ), Juan?","options":["Repochýpa","Ipochýpa","Nepochýpa","Ndepochýpa"],"answer":4,"why":["Re- es el «vos» de las acciones, como en rekaru, «comés». Pochy es un estado, y con los estados el «vos» es nde-, no re-: Repochýpa no va.","I- es «él, ella»: Ipochýpa pregunta si otra persona está enojada. Rosa le pregunta a Juan por él mismo: nde-.","Ne- reemplaza a nde- solo antes de una palabra nasal, como nekane'õ. Pochy es oral, sin ~ ni m, n, ñ: queda nde-.","Rosa le habla a Juan, de vos a vos, y de un estado: nde- + pochy, y -pa pegado al estado, que es lo que Rosa pregunta. La y tónica ya no es la última vocal, así que aparece la tilde: Ndepochýpa?, «¿estás enojado?»."]},{"id":"a1u03d6.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la fiesta, ^Luis dice qué es él mismo^: médico.)\nLuis: (   ) pohanohára.","options":["Aime","Ha'e","Che","Ndaha'éi"],"answer":3,"why":["Aime es «estoy» en un lugar, como en Aime ógape. Para decir qué sos no va ningún verbo: ni «soy» ni «estoy».","Ha'e pohanohára es «él es médico», de otra persona. Luis habla de él mismo: che.","Para decir qué sos: che y el sustantivo, nada más. Che pohanohára, «soy médico».","Ndaha'éi pohanohára niega: «no es médico» o «no soy médico». Luis sí es médico, y eso es lo que dice."]},{"id":"a1u03d6.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis ve que Ana sonríe.)\nLuis: ","after":", Ana?","tiles":["re","vy'a","pa"],"bank":[1,2,0],"hint":"Vy'a va como una acción: el «vos» es re-, y va primero. -pa va al final.","full":"(Luis ve que Ana sonríe.)\nLuis: {Re}vy'á{pa}, Ana?","es":"Luis: ¿Estás contenta, Ana?","explain":"re- («vos») + vy'a («alegrarse») + -pa (pregunta) = Revy'ápa, «¿estás contenta?». Vy'a va como una acción: por eso lleva re-, el «vos» de las acciones, y no nde-. -pa no se lleva el acento: queda en la a de vy'a, que ya no es la última vocal, y se escribe á."},{"id":"a1u03d6.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis pregunta si llegó la mamá de Ana.)\nLuis: ","after":" nde sy?","tiles":["o","g̃uahẽ","pa"],"bank":[2,1,0],"hint":"Nde sy es otra persona: el verbo empieza con el prefijo de «él, ella». -pa va al final.","full":"(Luis pregunta si llegó la mamá de Ana.)\nLuis: {O}g̃uahẽ{pa} nde sy?","es":"Luis: ¿Llegó tu mamá?","explain":"o- («él, ella») + g̃uahẽ («llegar») + -pa (pregunta) = Og̃uahẽpa, «¿llegó?». Nde sy, «tu mamá», es otra persona: por eso el verbo lleva o-. -pa va pegado al verbo, y nde sy viene después. Acá no aparece ninguna tilde: el acento cae en la ẽ, y la ~ ya lo marca. Compará con Revy'ápa, donde la a es oral y recibe la tilde."}],"exam":[{"id":"a1u03d6.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: Nemandu'ápa, Juan?\nJuan: _Nachemandu'ái_.","options":["No me acuerdo.","Me acuerdo.","No sé.","No tengo hambre."],"answer":1,"explain":"Na-…-i es el «no» de dos partes alrededor de che- y mandu'a, «acordarse»: nachemandu'ái, «no me acuerdo». Mandu'a es nasal, por eso va na- y no nda-. «Me acuerdo» sería chemandu'a, sin negar; «no sé» es ndaikuaái; y «no tengo hambre», ndachevare'ái, con nda- porque vare'a es oral."},{"id":"a1u03d6.e2","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Luis repasa cuatro palabras de la semana. Solo una está _bien escrita_. ¿Cuál?","options":["ndaha'ei","Ka'akupé","añetepa","hasýpa"],"answer":4,"explain":"Hasýpa está bien: hasy es aguda, ha-SY, y sola va sin tilde, pero -pa no se lleva el acento, así que la y tónica ya no es la última vocal y se escribe ý. Por lo mismo les falta la tilde a añetepa y a ndaha'ei: son añetépa, con -pa, y ndaha'éi, con -i. Ka'akupé lleva la tilde del castellano: en guaraní es aguda y va sin tilde, Ka'akupe."},{"id":"a1u03d6.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(En la fiesta, Rosa cree que la señora es la abuela de Luis.)\nLuis: ","after":" che jarýi, ha'e che sy.","tiles":["nda","ha'e","i"],"bank":[1,0,2],"full":"(En la fiesta, Rosa cree que la señora es la abuela de Luis.)\nLuis: {Nda}ha'é{i} che jarýi, ha'e che sy.","es":"Luis: No es mi abuela, es mi mamá.","explain":"nda- va primero, después ha'e y al final -i: ndaha'éi, «no es». El «no» del guaraní tiene dos partes que rodean la palabra. La tilde va en la é porque -i no se lleva el acento. Después, sin negar: ha'e che sy, «es mi mamá»."}]},"words":{"es":"Volver de Caacupé","intro":"Ana y su familia vuelven de la peregrinación a Caacupé. Tocá cada palabra: cómo están, quién llega y quién es quién.","sound":{"focus":"Repaso: la ch, el acento, la ñ, la g̃ y la ~","letters":["ch","a","á","ñ","g̃","ẽ"],"note":"Lo de la semana, en cuatro pares de palabras para contrastar: no son pares mínimos. La ch de chey'uhéi suena más bien como «sh»; avy'a, sin ninguna marca, lleva el acento al final, y ko'ág̃a lo lleva donde está la tilde. Junto a la ñ la vocal va sin ~ (kuña), y og̃uahẽ lleva la g̃, la g con nariz, y una ẽ cuya ~ marca también el acento.","pairs":[["y'uhéi","sed","chey'uhéi","tengo sed"],["avy'a","estoy contento, contenta","ko'ág̃a","ahora"],["kuña","mujer","mitã","niño, niña"],["jagua","perro","og̃uahẽ","llega"]]},"words":[{"id":"kaneo","gn":"chekane'õ","es":"estoy cansado, cansada","parts":[["che-","yo"],["kane'õ","cansancio"]],"note":"Muy cansado: chekane'õiterei. A vos: nekane'õ, porque kane'õ es nasal."},{"id":"yuhei","gn":"chey'uhéi","es":"tengo sed","parts":[["che-","yo"],["y'uhéi","sed"]],"note":"El puso corta la voz entre la y y la u, y la tilde va en la é."},{"id":"avya","gn":"avy'a","es":"estoy contento, contenta","parts":[["a-","yo"],["vy'a","alegrarse; alegría"]],"note":"Un sentimiento que va como acción, con a-: avy'a, no chevy'a. A vos: revy'a."},{"id":"oguahe","gn":"og̃uahẽ","es":"llega, llegó","parts":[["o-","él, ella"],["g̃uahẽ","llegar"]],"note":"Og̃uahẽpa nde sy?: ¿llegó tu mamá? Los diarios escriben oguahẽ, sin la ~ en la g: también vale."},{"id":"koaga","gn":"ko'ág̃a","es":"ahora","note":"Og̃uahẽ ko'ág̃a: llegó ahora. También se ve ko'ágã, con la ~ en la a."},{"id":"kaakupe","gn":"Ka'akupe","es":"Caacupé","note":"Sin tilde: el acento cae al final, Ka-'a-ku-PE. Con -pe aparece la tilde: Ka'akupépe, «a Caacupé». La Virgen de Caacupé se festeja el 8 de diciembre."},{"id":"pohanohara","gn":"pohanohára","es":"médico, médica","parts":[["pohano","curar, sanar"],["-hára","el que, la que"]],"note":"Como mbo'ehára: -hára, «el que», se lleva el acento."},{"id":"ndahaei","gn":"ndaha'éi","es":"no es","parts":[["nda-","no (primera parte)"],["ha'e","es"],["-i","no (segunda parte)"]],"note":"Una sola palabra, con la tilde en la é. Ndaha'éi che sy: no es mi mamá."}],"spell":["kaneo","yuhei","oguahe","koaga"],"check":{"id":"a1u03d6.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana escribe que su mamá _llega_ ahora. ¿Cómo se escribe en guaraní?","options":["oguahe","og̃uahẽ","og̃uahe","ogüahẽ"],"answer":2,"explain":"Llega es og̃uahẽ: con la g̃, la g con nariz, y con la ẽ nasal, que marca el acento. Oguahe no tiene ninguna marca. Og̃uahe perdió la ~ de la ẽ, que es la vocal tónica. Ogüahẽ usa la diéresis del castellano, que no es una letra del guaraní. Los diarios escriben oguahẽ, sin la ~ en la g, y también lo aceptamos."}},"skill":{"kind":"reading","es":"Un chat al volver","ask":"¿Quién está enfermo?","seconds":75,"passage":"Luis: Mba'éichapa, Ana? Og̃uahẽpa nde sy?\nAna: Héẽ, og̃uahẽ ko'ág̃a. ^Che sy ikane'õ ha che jarýi hasy.^\nLuis: Añetépa? Ha nde?\nAna: Chey'uhéi. Oĩpa terere?\nLuis: Héẽ. Jaha.","strategy":"Dos personas tienen un estado: una con i- y otra con h-. Buscá hasy, «está enfermo», y fijate de quién se dice.","item":{"id":"a1u03d6.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quién está enfermo?","options":["La mamá de Ana.","La abuela de Ana.","Ana.","Luis."],"short":["La mamá","La abuela","Ana","Luis"],"answer":2,"why":["Che sy ikane'õ: la mamá está cansada, con i- y kane'õ, «cansancio». Cansada, no enferma.","Ana escribe che jarýi hasy: hasy es «está enferma», la forma de rasy para él o ella, como héra. La enferma es su abuela.","De ella misma, Ana dice Chey'uhéi, «tengo sed»: ni cansancio ni enfermedad.","Luis pregunta, y al final responde Héẽ, «sí», y Jaha, «vamos». Por el tereré pregunta Ana: Oĩpa terere? De cómo está él, Luis no dice nada."],"explain":"Ana escribe Che sy ikane'õ ha che jarýi hasy: su mamá está cansada (ikane'õ) y su abuela está enferma (hasy). Ella misma solo tiene sed, chey'uhéi."}}}],"test":["a1u03t.1","a1u03t.2","a1u03t.3","a1u03t.4","a1u03t.5","a1u03t.6","a1u03t.7","a1u03t.8","a1u03t.9","a1u03t.10","a1u03t.11","a1u03t.12","a1u03t.13","a1u03t.14","a1u03t.15","a1u03t.16","a1u03t.17","a1u03t.18","a1u03t.19","a1u03t.20"]},{"n":4,"gn":"","es":"Mi familia","days":[{"title":"Posesión con che/nde + sustantivo","grammar":{"points":[{"id":"a1u04d1.p1","form":"che + sustantivo","gloss":"mi, mis","connect":[{"pos":"Delante del sustantivo. Che no cambia: es «mi» y también «mis»","rule":"{che} sy · {che} memby"},{"pos":"Con las palabras en r- que ya usás","rule":"{che} réra · {che} róga · {che} ru"},{"pos":"El dueño va primero, también cuando es otra persona: «la casa de mi abuela»","rule":"{che jarýi} róga"},{"pos":"Para «nuestro»: ñande (con vos) · ore (sin vos)","rule":"{ñande} ru · {ore} róga"}],"examples":[{"gn":"{Che} róga iporã.","es":"Mi casa es linda.","parts":[["che","mi"],["róga","casa (con che)"],["iporã","es linda"]]},{"gn":"Ha'e {che} ra'y.","es":"Él es mi hijo.","parts":[["ha'e","él"],["che","mi"],["ra'y","hijo (dice el papá)"]]},{"gn":"Aha {che jarýi} rógape.","es":"Voy a la casa de mi abuela.","parts":[["a-ha","voy"],["che jarýi","mi abuela"],["róga-pe","a la casa"]]},{"gn":"{Che} sy ha {che} ru oñe'ẽ guaraníme.","es":"Mi mamá y mi papá hablan guaraní.","parts":[["che sy","mi mamá"],["ha","y"],["che ru","mi papá"],["oñe'ẽ","hablan"],["guaraníme","en guaraní"]]}],"watch":{"note":"En castellano decís primero la cosa y después de quién es: «la casa de mi abuela». En guaraní es al revés y sin «de»: primero el dueño, después la cosa.","bad":"róga che jarýi","good":"che jarýi róga"}},{"id":"a1u04d1.p2","form":"nde / ne + sustantivo","gloss":"tu, tus","connect":[{"pos":"Delante del sustantivo, como che","rule":"{nde} sy · {nde} ru · {nde} róga"},{"pos":"Delante de una palabra nasal (con ~, o con m, n, ñ, mb, nd, ng), nde pierde la d","rule":"{ne} memby · {ne} ramói · {ne} angirũ"},{"pos":"Para preguntar el nombre de alguien de la familia","rule":"Mba'éichapa héra {nde} ru?"},{"pos":"Para preguntar dónde queda la casa","rule":"Moõpa {nde} róga?"}],"examples":[{"gn":"Mba'éichapa héra {nde} ru?","es":"¿Cómo se llama tu papá?","parts":[["mba'éichapa","¿cómo?"],["héra","su nombre"],["nde ru","tu papá"]]},{"gn":"Moõpa {nde} róga?","es":"¿Dónde queda tu casa?","parts":[["moõpa","¿dónde?"],["nde","tu"],["róga","casa (con nde)"]]},{"gn":"Mba'éichapa héra {ne} memby?","es":"¿Cómo se llama tu hijo? (o tu hija)","parts":[["ne","tu (ante palabra nasal)"],["memby","hijo o hija (dice la mamá)"]]},{"gn":"Mba'éichapa héra {ne} ramói?","es":"¿Cómo se llama tu abuelo?","parts":[["ne","tu (ante palabra nasal)"],["ramói","abuelo (con che, ne)"]]}],"watch":{"note":"Delante de una palabra nasal, nde pierde la d: ne memby, ne ramói, ne angirũ. Nde memby se entiende, pero no se escribe así.","bad":"nde memby","good":"ne memby"}}],"compare":{"intro":"Che y nde son los pronombres de la semana 1 y también los posesivos: lo que cambia es si van solos o delante de un sustantivo.","forms":[{"form":"che + sustantivo","tag":"mi, mis","mark":"dot","gn":"{Che} sy oñe'ẽ guaraníme.","es":"Mi mamá habla guaraní."},{"form":"nde / ne + sustantivo","tag":"tu, tus","mark":"dot","gn":"Mba'éichapa héra {nde} sy?","es":"¿Cómo se llama tu mamá?"},{"form":"che · nde solos","tag":"yo · vos (semana 1)","mark":"dot","gn":"{Che} Paraguaigua, ha {nde}?","es":"Yo soy de Paraguay, ¿y vos?"}],"check":{"id":"a1u04d1.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan le pregunta a Rosa cómo se llama ^la mamá de ella^.\nJuan: Mba'éichapa héra (   ) sy?","options":["che","nde","ne"],"answer":2,"why":["Che es «mi»: Juan preguntaría por su propia mamá, y pregunta por la de Rosa.","Juan le habla a Rosa de la mamá de ella: nde sy, «tu mamá». Sy es una palabra oral, así que nde no cambia.","Ne es nde delante de una palabra nasal, como en ne memby. Sy no tiene ~ ni m, n, ñ: queda nde sy."]}},"drill":[{"id":"a1u04d1.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le muestra a Juan una foto de ^la abuela de ella^.)\nJuan: Mávapa ha'e?\nAna: Ha'e (   ) jarýi.","options":["nde","ne","che","héra"],"answer":3,"why":["Nde es «tu»: sería la abuela de Juan, y la foto es de la abuela de Ana.","Ne solo va delante de una palabra nasal, y jarýi es oral. Además sería «tu», no «mi».","Ana habla de su propia abuela: che jarýi, «mi abuela».","Héra es «su nombre», como en Héra Rosa. No dice de quién es la abuela."]},{"id":"a1u04d1.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan: Mba'éichapa héra (   ) ^memby^, Rosa?","options":["nde","ne","che","ñande"],"answer":2,"why":["Nde es «tu», pero memby es una palabra nasal, con m: delante de ella nde pierde la d.","Juan le pregunta a Rosa por el hijo de ella: «tu hijo». Memby empieza con m, es nasal, así que nde se vuelve ne: ne memby.","Che es «mi»: Juan preguntaría por su propio hijo, y le pregunta a Rosa por el de ella.","Ñande es «nuestro» con vos: metería a Juan. Y delante de una palabra nasal sería ñane."]},{"id":"a1u04d1.d3","kind":"choice","area":"grammar","label":"Elegí el orden","q":"Luis habla de ^la casa de su abuela^.\nLuis: (   ) iporã.","options":["Róga che jarýi","Che róga jarýi","Jarýi che róga","Che jarýi róga"],"answer":4,"why":["Róga che jarýi calca el orden del castellano, con la casa primero. En guaraní el dueño va primero, y róga sola, sin dueño delante, no se dice.","Che róga jarýi es «mi casa» y después «abuela». Jarýi tiene que ir antes de róga, porque es la dueña.","Jarýi che róga es «abuela» y después «mi casa»: así la casa es de Luis, no de la abuela.","Primero el dueño, che jarýi, y después la cosa, róga: «la casa de mi abuela», sin «de»."]},{"id":"a1u04d1.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana vive con su hermano Luis. Le muestra la casa a Juan.)\nAna: (   ) róga iporã. ^(nuestra casa)^","options":["Ore","Ñande","Nde","Che"],"answer":1,"why":["La casa es de Ana y de Luis, y Juan, el que escucha, no vive ahí: ore róga, «nuestra casa», sin vos.","Ñande incluye al que escucha: ñande róga sería también la casa de Juan.","Nde es «tu»: nde róga sería la casa de Juan.","Che róga es «mi casa»: deja afuera a Luis, y la casa es de los dos, «nuestra»."]},{"id":"a1u04d1.d5","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Aha","after":".","tiles":["che","ru","rógape"],"bank":[2,0,1],"hint":"Primero el dueño, después la casa. Rógape es róga con -pe, «a».","full":"Aha {che ru} rógape.","es":"Voy a la casa de mi papá.","explain":"Che ru, «mi papá», va primero: es el dueño. Después viene la casa, róga, con -pe, «a»: rógape. Para decir de quién es algo no hace falta «de»: el orden ya lo dice. Ru sola no se dice: siempre lleva un dueño delante."},{"id":"a1u04d1.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Moõpa","after":"?","tiles":["ne","ramói","róga"],"bank":[1,2,0],"hint":"Como Moõpa nde róga?, pero la casa es del abuelo: el dueño va primero. Y delante de ramói, nde cambia.","full":"Moõpa {ne} ramói róga?","es":"¿Dónde queda la casa de tu abuelo?","explain":"Primero el dueño, ne ramói, «tu abuelo», y después róga: «la casa de tu abuelo». Ramói es una palabra nasal, con m, así que nde se vuelve ne. Ramói y róga no van solas: las dos llevan un dueño delante."}],"exam":[{"id":"a1u04d1.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Luis: _Che sy ha che ru_ oñe'ẽ guaraníme.","options":["Tu mamá y tu papá hablan guaraní.","Mi mamá y tu papá hablan guaraní.","Mi mamá y mi papá hablan guaraní.","Mi abuela y mi abuelo hablan guaraní."],"answer":3,"explain":"Che es «mi» y va delante de cada sustantivo: che sy, «mi mamá», ha, «y», che ru, «mi papá». «Tu» sería nde: nde sy, nde ru. Y abuela y abuelo son che jarýi y che ramói."},{"id":"a1u04d1.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa le pregunta a Juan por el amigo de él.)\nRosa: Mba'éichapa héra (   ) angirũ, Juan?","options":["nde","ne","che","héra"],"answer":2,"explain":"Rosa le pregunta a Juan por el amigo de él: «tu amigo». Angirũ es una palabra nasal, con ũ, así que nde pierde la d: ne angirũ. Che sería «mi», y héra ya está en la frase: es «su nombre», no un posesivo."},{"id":"a1u04d1.e3","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"(Juan le pregunta a Rosa por la casa del papá de ella.)\nJuan: Moõpa","after":"?","tiles":["nde","ru","róga"],"bank":[2,0,1],"full":"(Juan le pregunta a Rosa por la casa del papá de ella.)\nJuan: Moõpa nde ru róga?","es":"Juan: ¿Dónde queda la casa de tu papá?","explain":"Nde ru, «tu papá», va primero: es el dueño. Después la casa, róga. Ru es una palabra oral, así que nde no cambia. Sin «de»: el orden dice de quién es la casa, y ni ru ni róga van solas."}]},"words":{"es":"La foto de la familia","intro":"La foto del domingo, en el patio y con tereré. Tocá cada persona: todas van con che, «mi». Fijate quién lo dice: «hijo» e «hija» cambian según quién habla. La mamá dice memby; el papá, ra'y y rajy.","sound":{"focus":"La tilde en dos vocales juntas: jarýi, ramói","letters":["ýi","ói","éi","ái"],"note":"Jarýi, ramói y Paraguái terminan en dos vocales, y el acento va en la primera: como no es la última vocal de la palabra, lleva tilde. Sin tilde, el acento cae en la i del final, como en karai y en Ypakarai. No hay pares mínimos seguros: los dos primeros pares contrastan una palabra sin tilde con una que la lleva, y el tercero trae las dos de hoy.","pairs":[["Ypakarai","Ypacaraí","Paraguái","Paraguay"],["ahai","escribo","apurahéi","canto"],["ramói","abuelo (con che)","jarýi","abuela"]]},"words":[{"id":"sy","gn":"che sy","es":"mi mamá","parts":[["che","mi"],["sy","madre"]],"note":"Sy es «madre». Es oral: con nde no cambia, nde sy."},{"id":"ru","gn":"che ru","es":"mi papá","parts":[["che","mi"],["ru","padre (con che, nde, ñande)"]],"note":"Sola, la palabra es túva. Con che, nde, ñande y ore se vuelve ru: che ru, ñande ru."},{"id":"memby","gn":"che memby","es":"mi hijo, mi hija","parts":[["che","mi"],["memby","hijo o hija (dice la mamá)"]],"note":"Lo dice la mamá, de un hijo o de una hija. Es nasal, con m: con nde se dice ne memby."},{"id":"ray","gn":"che ra'y","es":"mi hijo","parts":[["che","mi"],["ra'y","hijo (dice el papá)"]],"note":"Lo dice el papá. Lleva puso: ra'y. Sola, la palabra es ta'ýra."},{"id":"rajy","gn":"che rajy","es":"mi hija","parts":[["che","mi"],["rajy","hija (dice el papá)"]],"note":"Lo dice el papá. La j suena como la y fuerte de «yo»: rajy, nunca con jota. Sola, la palabra es tajýra."},{"id":"jaryi","gn":"che jarýi","es":"mi abuela","parts":[["che","mi"],["jarýi","abuela"]],"note":"Tilde en la ý: el acento no cae al final. Es oral: con nde no cambia, nde jarýi."},{"id":"ramoi","gn":"che ramói","es":"mi abuelo","parts":[["che","mi"],["ramói","abuelo (con che, ne)"]],"note":"Sola es tamói. Es nasal, con m: con nde se dice ne ramói. Tilde en la ó: el acento no cae en la última vocal."},{"id":"rembireko","gn":"che rembireko","es":"mi esposa","parts":[["che","mi"],["rembireko","esposa (con che)"]],"note":"Sola es tembireko. Con che es rembireko y con «su» es hembireko: la h suena. Es nasal, con mb: con nde se dice ne rembireko. «Mi esposo» es che ména."}],"spell":["rajy","ramoi","rembireko","jaryi"],"check":{"id":"a1u04d1.k1","kind":"choice","area":"vocab","label":"Cuál está bien escrita","q":"Luis anota quién es quién en la foto. Solo una palabra está _bien escrita_. ¿Cuál?","options":["jaryi","rajý","ramói","membý"],"answer":3,"explain":"Ramói está bien: termina en dos vocales y el acento va en la primera, la o, que no es la última de la palabra, y por eso lleva tilde. A jaryi le falta la suya, por lo mismo: se escribe jarýi. Rajy y memby llevan el acento en la última vocal, y en guaraní eso no se marca: en rajý y en membý la tilde sobra."}},"skill":{"kind":"listening","es":"Comprensión de puntos clave","situation":"Ana le muestra a Juan la foto de su familia y le dice quién es cada uno.","ask":"¿Cómo se llama el abuelo de Ana?","item":{"id":"a1u04d1.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Cómo se llama el abuelo de Ana?","options":["Luis.","Pedro.","Marta."],"short":["Luis","Pedro","Marta"],"printed":true,"answer":2,"why":["Luis es el papá de Ana: Ha'e che ru, héra Luis, «él es mi papá, se llama Luis».","Cuando Juan pregunta Mávapa ha'e?, Ana responde Che ramói, héra Pedro: «mi abuelo, se llama Pedro».","Marta es la mamá de Ana: Ha'e che sy, héra Marta, «ella es mi mamá, se llama Marta»."],"script":["Narrador: Ana le muestra a Juan la foto de su familia. ¿Cómo se llama el abuelo de Ana?","Mujer: Ha'e che sy, héra Marta.","Mujer: Ha'e che ru, héra Luis.","Narrador: Juan señala a un señor de la foto.","Hombre: Mávapa ha'e?","Mujer: Che ramói, héra Pedro.","Hombre: Mba'éichapa héra ne memby?","Mujer: Héra Sofía.","Narrador: ¿Cómo se llama el abuelo de Ana?"]},"audio":[["N","Ana le muestra a Juan la foto de su familia. ¿Cómo se llama el abuelo de Ana?","Ana le muestra a Juan la foto de su familia. ¿Cómo se llama el abuelo de Ana?"],["F","Ha'e che sy, héra Marta.","Ella es mi mamá, se llama Marta."],["F","Ha'e che ru, héra Luis.","Él es mi papá, se llama Luis."],["N","Juan señala a un señor de la foto.","Juan señala a un señor de la foto."],["M","Mávapa ha'e?","¿Quién es?"],["F","Che ramói, héra Pedro.","Mi abuelo, se llama Pedro."],["M","Mba'éichapa héra ne memby?","¿Cómo se llama tu hija?"],["F","Héra Sofía.","Se llama Sofía."],["N","¿Cómo se llama el abuelo de Ana?","¿Cómo se llama el abuelo de Ana?"]]}},{"title":"Plural -kuéra, -nguéra tras nasal (mitãnguéra)","grammar":{"points":[{"id":"a1u04d2.p1","form":"-kuéra","gloss":"plural: los, las (tras sílaba oral)","connect":[{"pos":"Pegado al sustantivo. Se lleva el acento, y la raíz pierde su tilde","rule":"óga → oga{kuéra} · túva → tuva{kuéra}"},{"pos":"Con el posesivo, el dueño sigue primero","rule":"che memby{kuéra} · ne memby{kuéra}"},{"pos":"Ya lo conocés: ha'e, «él», y ha'ekuéra, «ellos»","rule":"ha'e → ha'e{kuéra}"},{"pos":"No es obligatorio: con un número, el sustantivo va solo","rule":"[mokõi|dos] {mitã}"}],"examples":[{"gn":"Jagua{kuéra} oyta.","es":"Los perros nadan.","parts":[["jagua","perro"],["-kuéra","plural"],["o-","ellos"],["yta","nadar"]]},{"gn":"Guyra{kuéra} opurahéi.","es":"Los pájaros cantan.","parts":[["guyra","pájaro"],["-kuéra","plural"],["opurahéi","cantan"]]},{"gn":"Ne memby{kuéra} moõpa oĩ?","es":"¿Dónde están tus hijos?","parts":[["ne","tu, tus"],["memby","hijo, hija"],["-kuéra","plural"],["moõpa","¿dónde?"],["oĩ","están"]]},{"gn":"Mbo'ehara{kuéra} oñe'ẽ guaraníme.","es":"Los profesores hablan guaraní.","parts":[["mbo'ehára","profesor, profesora"],["-kuéra","plural: el acento pasa a la é"],["oñe'ẽ","hablan"],["guaraníme","en guaraní"]]}],"watch":{"note":"-kuéra se lleva el acento, y una palabra guaraní lleva una sola tilde: la de la raíz desaparece. Óga es «casa»; «las casas» es ogakuéra.","bad":"ógakuéra","good":"ogakuéra"}},{"id":"a1u04d2.p2","form":"-nguéra","gloss":"plural tras sílaba nasal","connect":[{"pos":"Última sílaba con tilde nasal (~): la ~ se queda, y el acento pasa a la é","rule":"mitã → mitã{nguéra} · angirũ → angirũ{nguéra}"},{"pos":"Última sílaba con m, n o ñ, aunque no lleve ~ (mb, nd y ng son otras letras, y no cuentan)","rule":"kuña → kuña{nguéra} · mitãkuña → mitãkuña{nguéra}"},{"pos":"Solo la última sílaba: memby termina en mby, y mb es otra letra, no una m: esa sílaba es oral. Para nde → ne cuenta toda la palabra","rule":"ne memby → ne memby{kuéra}"},{"pos":"Para «a los niños», -pe va después del plural: ra es sílaba oral","rule":"mitã{nguéra}pe"}],"examples":[{"gn":"Mitã{nguéra} oho mbo'ehaópe.","es":"Los niños van a la escuela.","parts":[["mitã","niño, niña"],["-nguéra","plural tras nasal"],["oho","van"],["mbo'ehao","escuela"],["-pe","a"]]},{"gn":"Kuña{nguéra} opurahéi.","es":"Las mujeres cantan.","parts":[["kuña","mujer"],["-nguéra","plural tras nasal"],["opurahéi","cantan"]]},{"gn":"Che angirũ{nguéra} Paraguaigua.","es":"Mis amigos son de Paraguay.","parts":[["che","mi, mis"],["angirũ","amigo, amiga"],["-nguéra","plural tras nasal"],["Paraguaigua","de Paraguay"]]},{"gn":"Mitã{nguéra} okaru korapýpe.","es":"Los niños comen en el patio.","parts":[["mitã","niño, niña"],["-nguéra","plural tras nasal"],["o-","ellos"],["karu","comer"],["korapy","patio"],["-pe","en"]]}],"watch":{"note":"Tras una sílaba nasal no va -kuéra. Y no agregues otra ~: mitã ya la tiene, y la a de kuña no la lleva, porque la ñ ya la hace nasal.","bad":"mitãkuéra","good":"mitãnguéra"}}],"compare":{"intro":"El plural que ya conocés de ha'ekuéra tiene dos formas: fijate si la última sílaba de la palabra es oral o nasal.","forms":[{"form":"-kuéra","tag":"tras sílaba oral","mark":"dot","gn":"Jagua{kuéra} oyta.","es":"Los perros nadan."},{"form":"-nguéra","tag":"tras sílaba nasal","mark":"dot","gn":"Mitã{nguéra} oho mbo'ehaópe.","es":"Los niños van a la escuela."},{"form":"ha'ekuéra","tag":"ellos, ellas (semana 1)","mark":"dot","gn":"{Ha'ekuéra} oñe'ẽ guaraníme.","es":"Ellos hablan guaraní."}],"check":{"id":"a1u04d2.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana habla de ^las mujeres^ del barrio: «(   ) opurahéi.»","options":["Kuñakuéra","Kuñanguéra","Kuñãnguéra"],"answer":2,"why":["Kuña termina en ña, una sílaba nasal por la ñ: ahí no va -kuéra.","La última sílaba de kuña es nasal, por la ñ: va -nguéra. Kuñanguéra opurahéi: las mujeres cantan.","Kuñãnguéra agrega una ~ que la palabra no lleva: junto a la ñ, la a ya suena nasal y no se marca."]}},"drill":[{"id":"a1u04d2.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana habla de ^los pájaros^ del patio: «(   ) opurahéi ko pyhareve.»","options":["Guyrakuéra","Guyranguéra","Guirakuéra","Guyracuéra"],"answer":1,"why":["Guyra termina en ra, sílaba oral: va -kuéra, que se lleva el acento. Guyrakuéra opurahéi ko pyhareve: los pájaros cantan esta mañana.","-nguéra va solo tras una sílaba nasal, y ra es oral.","Guirakuéra cambia la y por i. Guy-ra lleva la y, la sexta vocal.","Guyracuéra escribe el plural con c, y la c no es una letra del guaraní: ese sonido se escribe con k, kuéra."]},{"id":"a1u04d2.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana le pregunta a Rosa dónde están ^los hijos de Rosa^: «Ne (   ) moõpa oĩ?»","options":["membynguéra","mẽmbykuéra","membykuéra","membikuéra"],"answer":3,"why":["-nguéra va tras una sílaba nasal, y la última sílaba de memby, mby, es oral: mb es otra letra, no una m. Para el plural se mira solo la última sílaba.","Mẽmbykuéra agrega una ~ a la e: junto a la m ya suena nasal, y no se marca.","La última sílaba de memby es mby, y es oral: mb es otra letra, no una m. Va -kuéra. Para nde → ne cuenta toda la palabra (ne memby); para el plural, solo la última sílaba (membykuéra). Ne membykuéra moõpa oĩ?: ¿dónde están tus hijos?","Membikuéra cambia la y por i. Memby termina en y, la sexta vocal."]},{"id":"a1u04d2.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis habla de ^sus amigos^: «Che (   ) oĩ [ko'ápe|aquí].»","options":["angirũkuéra","angirũnguéra","angirunguéra","ãngirũnguéra"],"answer":2,"why":["-kuéra va tras una sílaba oral, y angirũ termina en ũ, nasal.","Angirũ termina en ũ, nasal: va -nguéra. Che angirũnguéra oĩ ko'ápe: mis amigos están aquí.","Angirunguéra pierde la ~ de la ũ. La raíz es angirũ, y la ~ se queda.","En ãngirũnguéra sobra la ~ de la a: junto a ng ya suena nasal, y no se marca."]},{"id":"a1u04d2.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa habla de ^las casas^ del barrio: «(   ) iporã.»","options":["Oganguéra","Ogãkuéra","Ogacuéra","Ogakuéra"],"answer":4,"why":["-nguéra es la forma de después de una sílaba nasal, y ga es oral.","Ogãkuéra agrega una ~ que la palabra no lleva: óga no tiene ningún sonido nasal.","Ogacuéra escribe el plural con c, y la c no es una letra del guaraní: ese sonido se escribe con k, kuéra.","Óga pierde su tilde porque -kuéra se lleva el acento: ogakuéra, con una sola tilde. Ogakuéra iporã: las casas son lindas."]},{"id":"a1u04d2.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Mbo'ehára oñe'ẽ ","after":".","tiles":["mitã","nguéra","pe"],"bank":[2,0,1],"hint":"Primero el plural, después -pe, «a». Fijate dónde queda el acento.","full":"Mbo'ehára oñe'ẽ mitã{nguéra}pe.","es":"El profesor les habla a los niños.","explain":"mitã («niño») + -nguéra (plural tras nasal, porque mitã termina en ã) + -pe («a») = mitãnguérape. -nguéra se lleva el acento, y -pe no lo mueve: queda la ~ en la ã y la tilde en la é. Después de -nguéra va -pe, porque ra es sílaba oral."},{"id":"a1u04d2.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" oñe'ẽ guaraníme.","tiles":["mbo'ehára","kuéra"],"bank":[1,0],"hint":"-kuéra va después del sustantivo y se lleva el acento: mirá qué pasa con la tilde de hára.","full":"{Mbo'eharakuéra} oñe'ẽ guaraníme.","es":"Los profesores hablan guaraní.","explain":"mbo'ehára («profesor») + -kuéra = mbo'eharakuéra, «los profesores». -kuéra se lleva el acento, y la tilde de hára desaparece: una palabra, una sola tilde."}],"exam":[{"id":"a1u04d2.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Ana: _Che membykuéra_ oho mbo'ehaópe.","options":["Mi hijo va a la escuela.","Mis hijos van a la escuela.","Tus hijos van a la escuela.","Nuestros hijos van a la escuela."],"answer":2,"explain":"Che es «mi», y -kuéra hace el plural: che membykuéra, «mis hijos». Un solo hijo sería che memby, «tus hijos» sería ne membykuéra, y «nuestros» llevaría ñane u ore, no che: delante de una palabra nasal como memby, ñande se vuelve ñane, igual que nde se vuelve ne."},{"id":"a1u04d2.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa habla de las niñas de la escuela.)\nRosa: (   ) opurahéi mbo'ehaópe.","options":["Mitãkuñakuéra","Mitakuñanguéra","Mitãkuñanguéra","Mitãkuñãnguéra"],"answer":3,"explain":"Mitãkuña («niña») termina en ña, sílaba nasal por la ñ: va -nguéra, que se lleva el acento. Mitãkuñakuéra usa la forma de después de una sílaba oral, mitakuñanguéra pierde la ~ de mitã, que la palabra sí lleva, y mitãkuñãnguéra agrega una ~ junto a la ñ, donde no se escribe."},{"id":"a1u04d2.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Che sy oñe'ẽ ","after":".","tiles":["kuña","nguéra","pe"],"bank":[1,2,0],"full":"Che sy oñe'ẽ kuña{nguéra}pe.","es":"Mi mamá les habla a las mujeres.","explain":"kuña («mujer») + -nguéra (plural tras la ñ, sílaba nasal) + -pe («a») = kuñanguérape. -nguéra se lleva el acento, y -pe va al final sin moverlo: la tilde queda en la é."}]},"words":{"es":"El patio de la escuela","intro":"En el patio de la escuela del barrio hay chicos, profesores y animales. Tocá cada palabra y fijate cuáles llevan -kuéra y cuáles -nguéra.","sound":{"focus":"El acento se mueve: ogakuéra","letters":["é"],"note":"Una palabra lleva una sola tilde de acento, y -kuéra se queda con él: la de la raíz desaparece (óga → ogakuéra, túva → tuvakuéra). La ~ es otra marca: dice que la vocal es nasal, y por eso se queda aunque el acento pase a la é: mitã → mitãnguéra. No hay pares mínimos seguros de acento: son palabras para contrastar, en singular y en plural.","pairs":[["óga","casa","ogakuéra","casas"],["túva","padre","tuvakuéra","padres"],["ha'e","él, ella","ha'ekuéra","ellos, ellas"],["mitã","niño, niña","mitãnguéra","niños, niñas"]]},"words":[{"id":"mitanguera","gn":"mitãnguéra","es":"los niños, las niñas","parts":[["mitã","niño, niña"],["-nguéra","plural tras nasal"]],"note":"La ~ se queda y el acento va a la é."},{"id":"mitakuna","gn":"mitãkuña","es":"niña","parts":[["mitã","niño"],["kuña","mujer"]],"note":"Plural: mitãkuñanguéra, porque termina en ña."},{"id":"mitarusu","gn":"mitãrusu","es":"joven, adolescente","note":"Plural: mitãrusukuéra, porque su es una sílaba oral."},{"id":"mboeharakuera","gn":"mbo'eharakuéra","es":"los profesores, las profesoras","parts":[["mbo'ehára","profesor, profesora"],["-kuéra","plural"]],"note":"Pierde la tilde de hára: -kuéra se lleva el acento."},{"id":"jaguakuera","gn":"jaguakuéra","es":"los perros","parts":[["jagua","perro"],["-kuéra","plural"]],"note":"La j suena como la y fuerte de «yo», nunca como la jota."},{"id":"guyrakuera","gn":"guyrakuéra","es":"los pájaros","parts":[["guyra","pájaro"],["-kuéra","plural"]],"note":"Guy-ra: la y es la sexta vocal."},{"id":"mymbakuera","gn":"mymbakuéra","es":"los animales","parts":[["mymba","animal"],["-kuéra","plural"]],"note":"Mymba termina en mba: mb es una sola letra, no una m, y esa sílaba es oral: por eso -kuéra."},{"id":"korapy","gn":"korapy","es":"patio","note":"«En el patio» es korapýpe: -pe no se lleva el acento, y aparece la tilde en la ý."}],"spell":["mitanguera","mboeharakuera","jaguakuera","mymbakuera"],"check":{"id":"a1u04d2.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Los chicos del patio: _los niños_. ¿Cómo se escribe en guaraní?","options":["mitãkuéra","mitankuéra","mitãnguéra","mitanguéra"],"answer":3,"explain":"Mitã termina en ã, nasal, así que el plural es -nguéra, con el acento en la é: mitãnguéra. Mitãkuéra usa la forma de después de una sílaba oral. Mitankuéra escribe una n en lugar de la ~, y la nasal de mitã es la ~ de la ã. Mitanguéra pierde esa ~, que la palabra sí lleva."}},"skill":{"kind":"reading","es":"Un aviso de la escuela","ask":"¿Quiénes cantan esta tarde?","seconds":60,"passage":"Maitei, sy ha tuvakuéra.\n^Mitãnguéra opurahéi^ ko ka'aru mbo'ehaópe.\nMbo'eharakuéra oñe'ẽ guaraníme.\nTapeg̃uahẽ porãite.","strategy":"La primera línea saluda y la última da la bienvenida. En las dos del medio, la palabra con -kuéra o -nguéra va primero y después viene lo que hace: buscá opurahéi, «cantan», y mirá qué palabra va delante.","item":{"id":"a1u04d2.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quiénes cantan esta tarde?","options":["Los niños.","Los profesores.","Los padres.","Los pájaros."],"short":["Niños","Profesores","Padres","Pájaros"],"answer":1,"why":["Mitãnguéra opurahéi ko ka'aru: los niños cantan esta tarde. Mitãnguéra es el plural de mitã.","De los profesores, mbo'eharakuéra, el aviso dice que hablan guaraní (oñe'ẽ guaraníme), no que cantan.","Sy ha tuvakuéra, las madres y los padres, son a quienes saluda el aviso: Maitei, sy ha tuvakuéra. No cantan.","Guyrakuéra, los pájaros, no aparece en el aviso."],"explain":"El aviso saluda a las madres y a los padres (sy ha tuvakuéra) y dice: Mitãnguéra opurahéi ko ka'aru mbo'ehaópe, «los niños cantan esta tarde en la escuela». Los profesores hablan guaraní, no cantan."}}},{"title":"Demostrativos ko, pe, amo","grammar":{"points":[{"id":"a1u04d3.p1","form":"ko · pe · amo + sustantivo","gloss":"este, esta · ese, esa · aquel, aquella","connect":[{"pos":"Cerca de quien habla: «este, esta»","rule":"{ko} vaka · {ko} óga"},{"pos":"Cerca de quien escucha: «ese, esa»","rule":"{pe} jagua · {pe} mitã"},{"pos":"Lejos de los dos, a la vista: «aquel, aquella»","rule":"{amo} óga · {amo} kavaju"},{"pos":"Siempre delante del sustantivo, y sin género: la misma palabra para «este» y «esta». Ya la usás con los momentos del día","rule":"{ko} ka'aru · {ko} pyhare"}],"examples":[{"gn":"{Ko} vaka iky'a.","es":"Esta vaca está sucia.","parts":[["ko","esta"],["vaka","vaca"],["i-","está (él, ella)"],["ky'a","sucio, sucia"]]},{"gn":"{Pe} mitã iporã.","es":"Ese chico es lindo.","parts":[["pe","ese"],["mitã","niño, niña"],["iporã","es lindo, está bien"]]},{"gn":"{Amo} óga ituicha.","es":"Aquella casa es grande.","parts":[["amo","aquella"],["óga","casa"],["i-","es (él, ella)"],["tuicha","grande"]]},{"gn":"{Pe} karai ha'e che ru.","es":"Ese señor es mi papá.","parts":[["pe","ese"],["karai","señor"],["ha'e","es (entre dos nombres)"],["che ru","mi papá"]]}],"watch":{"note":"Va siempre delante del sustantivo, como el posesivo, y no cambia: ko sirve para «este» y para «esta».","bad":"óga ko","good":"ko óga"}},{"id":"a1u04d3.p2","form":"ko'ã · umi + sustantivo","gloss":"estos, estas · esos, esas, aquellos, aquellas","connect":[{"pos":"Ko, para varios: ko'ã, con puso y ã","rule":"{ko'ã} mba'e · {ko'ã} óga"},{"pos":"Pe y amo, para varios: umi, que sirve para «esos» y para «aquellos»","rule":"{umi} mitã · {umi} jagua"},{"pos":"El sustantivo puede ir sin -kuéra: ko'ã y umi ya dicen que son varios. Con -kuéra también se dice","rule":"{umi} kavaju · {umi} mitãnguéra"},{"pos":"Pe, umi y ko'ã se usan también donde el castellano pone «el, los, las»: pe karai, «el señor»; umi mitã, «los chicos». Acá los practicamos como «ese, esos»","rule":"{pe} karai · {umi} mitã"}],"examples":[{"gn":"{Umi} kavaju oĩ korapýpe.","es":"Esos caballos están en el patio.","parts":[["umi","esos"],["kavaju","caballo"],["oĩ","están"],["korapý-pe","en el patio"]]},{"gn":"{Umi} jagua oyta.","es":"Esos perros nadan.","parts":[["umi","esos"],["jagua","perro"],["o-","ellos"],["yta","nadar"]]},{"gn":"{Ko'ã} óga ituicha.","es":"Estas casas son grandes.","parts":[["ko'ã","estas"],["óga","casa"],["ituicha","es grande, son grandes"]]},{"gn":"{Umi} mitã oho mbo'ehaópe.","es":"Esos chicos van a la escuela.","parts":[["umi","esos"],["mitã","niño, niña"],["oho","van"],["mbo'ehaó-pe","a la escuela"]]}],"watch":{"note":"El plural del demostrativo no se hace con -kuéra: es otra palabra. Y el sustantivo puede quedar como está: ko'ã mitã, «estos chicos».","bad":"kokuéra mitã","good":"ko'ã mitã"}}],"compare":{"intro":"Tres distancias y un plural: fijate dónde está la cosa y si es una o varias.","forms":[{"form":"ko · pe · amo","tag":"uno: cerca de mí · cerca de vos · lejos","mark":"dot","gn":"{Ko} vaka iky'a.","es":"Esta vaca está sucia."},{"form":"ko'ã · umi","tag":"varios: estos · esos, aquellos","mark":"dot","gn":"{Umi} kavaju oĩ korapýpe.","es":"Esos caballos están en el patio."},{"form":"ko + momento del día","tag":"esta tarde, esta noche (semana 1)","mark":"dot","gn":"Jajotopáta {ko} ka'aru.","es":"Nos vemos esta tarde."}],"check":{"id":"a1u04d3.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan señala un perro que está ^al lado de Rosa^.)\nJuan: (   ) jagua iporã.","options":["Ko","Pe","Amo"],"answer":2,"why":["Ko es «este»: el perro estaría al lado de Juan, el que habla. Y está al lado de Rosa.","El perro está al lado de Rosa, la que escucha: pe jagua, «ese perro».","Amo es «aquel», para algo lejos de los dos. El perro está al lado de Rosa."]}},"drill":[{"id":"a1u04d3.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana tiene ^un gato en brazos^.)\nAna: (   ) mbarakaja iporã.","options":["Amo","Pe","Umi","Ko"],"answer":4,"why":["Amo es «aquel», para algo lejos de los dos. Ana tiene el gato en brazos.","Pe es «ese»: el gato estaría cerca del que escucha. Lo tiene Ana, la que habla.","Umi es para varios, «esos». Es un solo gato, y además lo tiene Ana.","Ana tiene el gato en brazos, cerca de ella, la que habla: ko mbarakaja, «este gato»."]},{"id":"a1u04d3.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis señala ^una casa lejos, al final de la calle^.)\nLuis: (   ) óga ituicha.","options":["Ko","Pe","Amo","Ko'ã"],"answer":3,"why":["Ko es «esta», para algo cerca de Luis. La casa está al final de la calle.","Pe es «esa», para algo cerca del que escucha. La casa está lejos de los dos.","La casa está lejos de los dos, pero a la vista: amo óga, «aquella casa».","Ko'ã es «estas», para varias cosas cerca de quien habla. Es una sola casa y está lejos."]},{"id":"a1u04d3.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana tiene ^dos libros en la mano^.)\nAna: (   ) aranduka iporã.","options":["Ko'ã","Umi","Ko","Pe"],"answer":1,"why":["Son dos libros y los tiene Ana, la que habla: ko'ã aranduka, «estos libros». Ko'ã es el ko de varios.","Umi es para varios, pero lejos de quien habla: «esos» o «aquellos». Ana los tiene en la mano.","Ko es «este», para uno solo. Ana tiene dos libros.","Pe es «ese»: uno solo, y cerca del que escucha. Son dos y los tiene Ana."]},{"id":"a1u04d3.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan habla de ^los chicos que están con Rosa^.)\nJuan: (   ) mitã oñe'ẽ guaraníme.","options":["Ko'ã","Umi","Ko","Pekuéra"],"answer":2,"why":["Ko'ã es «estos», para varios cerca de quien habla. Los chicos están con Rosa, no con Juan.","Son varios chicos y están con Rosa, no con Juan: umi mitã, «esos chicos». El sustantivo queda como está.","Ko es «este»: uno solo, y cerca de Juan. Son varios y están con Rosa.","El plural de pe no se hace con -kuéra: para varios hay otra palabra, umi."]},{"id":"a1u04d3.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Umi kavaju oĩ ","after":".","tiles":["korapy","pe"],"bank":[1,0],"hint":"Primero el lugar, korapy, y después -pe, «en». -pe no se lleva el acento: fijate dónde queda la tilde.","full":"Umi kavaju oĩ korapý{pe}.","es":"Esos caballos están en el patio.","explain":"korapy («patio») + -pe («en») = korapýpe, «en el patio». -pe no se lleva el acento: queda en la y de korapy. Como esa y ya no es la última vocal, se escribe la tilde: korapýpe. Umi, «esos», va delante de kavaju."},{"id":"a1u04d3.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"","after":"umi mbarakaja iporã.","tiles":["ko'ã","jagua","ha"],"bank":[2,0,1],"hint":"Ko'ã va delante del sustantivo, como ko. Ha, «y», une las dos partes.","full":"{Ko'ã} jagua ha umi mbarakaja iporã.","es":"Estos perros y esos gatos son lindos.","explain":"Ko'ã, «estos», va delante de jagua: ko'ã jagua, «estos perros». Después ha, «y», une con umi mbarakaja, «esos gatos». El demostrativo va siempre primero, y el sustantivo queda sin -kuéra: ko'ã y umi ya dicen que son varios."}],"exam":[{"id":"a1u04d3.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: _Amo óga_ ituicha.","options":["Esta casa","Esa casa","Aquella casa","Aquellas casas"],"answer":3,"explain":"Amo es «aquel, aquella»: algo lejos de los dos, a la vista. Amo óga ituicha: aquella casa es grande. «Esta casa» sería ko óga; «esa casa», pe óga; y para varias casas lejos se usa umi: umi óga."},{"id":"a1u04d3.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan señala dos gallinas que tiene al lado.)\nJuan: (   ) ryguasu ituicha.","options":["Ko","Umi","Pe","Ko'ã"],"answer":4,"explain":"Son dos gallinas y están al lado de Juan, el que habla: ko'ã ryguasu, «estas gallinas». Ko y pe son para una sola, y umi es para varias pero lejos de quien habla, «esas» o «aquellas»."},{"id":"a1u04d3.e3","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"","after":"ko'ã vaka oĩ korapýpe.","tiles":["umi","kavaju","ha"],"bank":[1,2,0],"full":"Umi kavaju ha ko'ã vaka oĩ korapýpe.","es":"Esos caballos y estas vacas están en el patio.","explain":"Umi, «esos», va delante de kavaju: umi kavaju, «esos caballos». Después ha, «y», une con ko'ã vaka, «estas vacas». El demostrativo va siempre primero, y el sustantivo queda sin -kuéra: umi y ko'ã ya dicen que son varios. Oĩ korapýpe: están en el patio."}]},"words":{"gn":"Korapýpe","es":"En el patio","intro":"El patio de la casa de Juan: animales y cosas para señalar con ko, pe y amo. Tocá cada palabra. Dos nombres vienen del castellano, escritos a la guaraní: vaka y kavaju.","sound":{"focus":"La v: vaka, kavaju","letters":["v"],"note":"La v del guaraní no es la b ni la v del castellano: el labio de abajo roza los dientes, sin fuerza, como en yvyra y túva. Vaka y kavaju vienen del castellano y se escriben a la guaraní, con v donde «caballo» lleva b; como no llevan tilde, el acento va al final: va-ká, ka-va-jú. No hay pares mínimos seguros con v: son palabras para contrastar.","pairs":[["vaka","vaca","kavaju","caballo"],["yvyra","árbol","túva","padre"]]},"words":[{"id":"jagua","gn":"jagua","es":"perro","note":"La j suena como la y fuerte de «yo», nunca como la jota. Plural: jaguakuéra."},{"id":"mbarakaja","gn":"mbarakaja","es":"gato","note":"Empieza con mb, como mba'e: una sola letra. Plural: mbarakajakuéra."},{"id":"ryguasu","gn":"ryguasu","es":"gallina","note":"La r es suave, como en «caro», también al principio. Ryguasu rupi'a es «huevo»."},{"id":"kavaju","gn":"kavaju","es":"caballo","note":"Del castellano «caballo», escrito a la guaraní: la c se escribe k y la ll se escribe j. Sin tilde, el acento va al final: ka-va-jú."},{"id":"vaka","gn":"vaka","es":"vaca","note":"Del castellano «vaca»: con v y con k, y con el acento al final: va-ká. Ko vaka iky'a, «esta vaca está sucia»."},{"id":"yvyra","gn":"yvyra","es":"árbol, madera","note":"Dos y, la sexta vocal: y-vy-ra. Es el árbol y también la madera; el árbol como planta se dice también yvyramáta."},{"id":"apyka","gn":"apyka","es":"silla","note":"La y del medio es la sexta vocal: a-py-ka."},{"id":"korapy","gn":"korapy","es":"patio","note":"«En el patio» es korapýpe: -pe no se lleva el acento, y aparece la tilde en la ý."}],"spell":["kavaju","vaka","yvyra","apyka"],"check":{"id":"a1u04d3.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Juan señala un animal: Amo _caballo_ ituicha. ¿Cómo se escribe «caballo» en guaraní?","options":["cavaju","kavaju","kabaju","kavallu"],"answer":2,"explain":"Se escribe kavaju: la c de «caballo» se escribe k, porque la c no es una letra del guaraní, y la ll se escribe j. Cavaju deja la c; kabaju escribe b, que sola no es una letra del guaraní, acá va v; y kavallu deja la ll del castellano."}},"skill":{"kind":"listening","es":"Comprensión de puntos clave","situation":"En el patio de la casa de Juan. Rosa mira los animales y habla de ellos con Juan.","ask":"¿Qué animal está lejos de los dos?","item":{"id":"a1u04d3.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué animal está lejos de los dos?","options":["El perro.","El gato.","El caballo."],"short":["Perro","Gato","Caballo"],"printed":true,"answer":3,"why":["Rosa dice pe jagua, «ese perro»: pe es para algo cerca del que escucha, Juan. El perro está al lado de Juan, no lejos.","Rosa dice ko mbarakaja, «este gato»: ko es para algo cerca de quien habla. Rosa tiene el gato al lado.","Juan dice amo kavaju ituicha, «aquel caballo es grande»: amo es para algo lejos de los dos, a la vista."],"script":["Narrador: En el patio de la casa de Juan. Rosa habla de los animales. ¿Qué animal está lejos de los dos?","Mujer: Pe jagua iporã, Juan.","Hombre: Héẽ. Ha amo kavaju ituicha.","Mujer: Ha ko mbarakaja?","Hombre: Che rajy mbarakaja.","Narrador: ¿Qué animal está lejos de los dos?"]},"audio":[["N","En el patio de la casa de Juan. Rosa habla de los animales. ¿Qué animal está lejos de los dos?","En el patio de la casa de Juan. Rosa habla de los animales. ¿Qué animal está lejos de los dos?"],["F","Pe jagua iporã, Juan.","Ese perro es lindo, Juan."],["M","Héẽ. Ha amo kavaju ituicha.","Sí. Y aquel caballo es grande."],["F","Ha ko mbarakaja?","¿Y este gato?"],["M","Che rajy mbarakaja.","Es el gato de mi hija."],["N","¿Qué animal está lejos de los dos?","¿Qué animal está lejos de los dos?"]]}},{"title":"máva «quién», mba'e «qué»","grammar":{"points":[{"id":"a1u04d4.p1","form":"Mávapa …?","gloss":"¿quién?","connect":[{"pos":"Para preguntar por una persona: máva, «quién», con -pa pegado","rule":"{Mávapa} ha'e?"},{"pos":"Con los demostrativos de ayer: ko, pe, amo","rule":"{Mávapa} pe karai? · {Mávapa} ko mitã?"},{"pos":"En la charla también se oye con piko. Pegado a la palabra que pregunta se escribe junto: Mávapiko. Con nde lo viste suelto: Nde piko (semana 3)","rule":"{Mávapiko} pe karai?"},{"pos":"Se responde con la persona, con o sin ha'e","rule":"{Che ru}. · Ha'e {che ru}."}],"examples":[{"gn":"{Mávapa} ha'e?","es":"¿Quién es?","parts":[["máva","quién"],["-pa","pregunta"],["ha'e","él, ella"]]},{"gn":"{Mávapa} pe karai?","es":"¿Quién es ese señor?","parts":[["mávapa","¿quién?"],["pe","ese"],["karai","señor"]]},{"gn":"Juan: {Mávapa} ko mitã?\nRosa: Che memby.","es":"Juan: ¿Quién es este chico?\nRosa: Mi hijo.","parts":[["ko","este"],["mitã","chico, niño"],["che memby","mi hijo (dice la mamá)"]]},{"gn":"Juan: {Mávapa} amo kuñataĩ?\nLuis: Ha'e che rajy.","es":"Juan: ¿Quién es aquella chica?\nLuis: Es mi hija.","parts":[["amo","aquella"],["kuñataĩ","chica, señorita"],["ha'e","ella"],["che rajy","mi hija (dice el papá)"]]}],"watch":{"note":"Máva no es aguda: el acento cae en la primera a, y ahí va la tilde. La -pa de pregunta no se lleva el acento ni lo mueve.","bad":"Mavápa","good":"Mávapa"}},{"id":"a1u04d4.p2","form":"Mba'épa …?","gloss":"¿qué?","connect":[{"pos":"Para preguntar por una cosa o por una acción","rule":"{Mba'épa} reipota? · {Mba'épa} rejapo?"},{"pos":"La pregunta del alumno: «¿qué significa?»","rule":"{Mba'épa} he'ise?"},{"pos":"Para preguntar qué hay","rule":"{Mba'épa} oĩ?"},{"pos":"De mba'e salen una palabra que ya usás, mba'éichapa, «¿cómo?», y otra para reconocer, mba'érepa, «¿por qué?»","rule":"mba'e + icha + pa → {Mba'éichapa} · mba'e + re + pa → {Mba'érepa}"}],"examples":[{"gn":"{Mba'épa} he'ise «jarýi»?","es":"¿Qué significa «jarýi»?","parts":[["mba'e","qué"],["-pa","pregunta"],["he'ise","significa"],["jarýi","abuela"]]},{"gn":"{Mba'épa} reipota?","es":"¿Qué querés?","parts":[["mba'épa","¿qué?"],["reipota","querés"]]},{"gn":"{Mba'épa} rejapo, Luis?","es":"¿Qué hacés, Luis?","parts":[["mba'épa","¿qué?"],["re-","vos"],["japo","hacer"]]},{"gn":"{Mba'épa} oĩ korapýpe?","es":"¿Qué hay en el patio?","parts":[["mba'épa","¿qué?"],["oĩ","hay"],["korapy","patio"],["-pe","en"]]}],"watch":{"note":"Mba'e es aguda: el acento cae en la e. Con -pa, esa e ya no es la última vocal, y hay que escribir la tilde: Mba'épa. Sin tilde, Mba'epa se leería con el acento en la a del final.","bad":"Mba'epa","good":"Mba'épa"}}],"compare":{"intro":"Tres palabras para pedir un dato: por una persona, por una cosa y por un lugar. Las tres llevan -pa pegado, y ninguna se contesta con héẽ ni con nahániri.","forms":[{"form":"Mávapa","tag":"¿quién? · una persona","mark":"dot","gn":"{Mávapa} pe karai?","es":"¿Quién es ese señor?"},{"form":"Mba'épa","tag":"¿qué? · una cosa o una acción","mark":"dot","gn":"{Mba'épa} reipota?","es":"¿Qué querés?"},{"form":"Moõpa","tag":"¿dónde? · un lugar (semana 1)","mark":"dot","gn":"{Moõpa} nde róga?","es":"¿Dónde queda tu casa?"}],"check":{"id":"a1u04d4.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa quiere saber quién es ^la mujer de la foto^.\nRosa: (   ) pe kuña?","options":["Mba'épa","Moõpa","Mávapa"],"answer":3,"why":["Mba'épa pregunta por una cosa: Mba'épa pe kuña? sería «¿qué es esa mujer?». Por una persona se pregunta con mávapa.","Moõpa pregunta «¿dónde?», por un lugar. Rosa no quiere saber dónde está la mujer: quiere saber quién es.","Rosa pregunta por una persona, la mujer de la foto: Mávapa pe kuña?, «¿quién es esa mujer?»."]}},"drill":[{"id":"a1u04d4.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan: (   ) ha'e?\nRosa: ^Che sy.^","options":["Moõpa","Mávapa","Mba'épa","Mboýpa"],"answer":2,"why":["Moõpa pregunta «¿dónde?». Che sy no es un lugar: para decir dónde, Rosa respondería con un lugar, como che rógape.","Rosa responde con una persona, che sy, «mi mamá»: Juan preguntó quién es. Mávapa ha'e?, «¿quién es?».","Mba'épa pregunta «¿qué?», por una cosa. Che sy es una persona.","Mboýpa pregunta «¿cuánto?», como en Mboýpa ovale? Che sy no es una cantidad."]},{"id":"a1u04d4.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana: (   ) reipota?\nLuis: ^Mandi'o.^","options":["Mávapa","Moõpa","Mba'éichapa","Mba'épa"],"answer":4,"why":["Mávapa pregunta «¿quién?», por una persona, y mandi'o es una cosa.","Moõpa pregunta «¿dónde?». Mandi'o no es un lugar.","Mba'éichapa pregunta «¿cómo?», como en Mba'éichapa reiko? Luis no dice cómo: dice qué quiere.","Luis responde con una cosa, mandi'o: Ana preguntó qué quiere. Mba'épa reipota?, «¿qué querés?»."]},{"id":"a1u04d4.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: (   ) [he'ise|significa] «korapy»?\nAna: ^«Patio».^","options":["Mboýpa","Mba'éichapa","Mba'épa","Mávapa"],"answer":3,"why":["Mboýpa pregunta «¿cuánto?». «Patio» no es una cantidad.","Mba'éichapa pregunta «¿cómo?». He'ise es «significa», y lo que Luis pide es un significado: un «qué».","Luis pregunta el significado de una palabra: Mba'épa he'ise «korapy»?, «¿qué significa korapy?». Ana se lo dice: «patio».","Mávapa pregunta «¿quién?», y una palabra no es una persona."]},{"id":"a1u04d4.d4","kind":"choice","area":"grammar","label":"Cómo se escribe","q":"Rosa pregunta ^quién^ es el muchacho de allá.\nRosa: (   ) amo [karia'y|muchacho]?","options":["Mãvapa","Mávapa","Mábapa","Mávapã"],"answer":2,"why":["Mãvapa pone una ~ en la primera a, como si fuera nasal. Máva es oral: su marca es la tilde de acento, á.","Máva lleva la tilde de acento en la primera a, y -pa va pegado sin moverla: Mávapa amo karia'y?, «¿quién es aquel muchacho?».","Mábapa escribe con b: la b sola no es una letra del guaraní, solo está en mb. El sonido de máva se escribe con v.","Mávapã agrega una ~ a la a de -pa. Esa a es oral: -pa se escribe siempre igual, sin ~."]},{"id":"a1u04d4.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" he'ise «ramói»?","tiles":["mba'e","pa"],"bank":[1,0],"hint":"-pa va al final y no se lleva el acento: fijate qué pasa con la tilde.","full":"{Mba'épa} he'ise «ramói»?","es":"¿Qué significa «ramói»?","explain":"mba'e («qué») + -pa (pregunta) = Mba'épa. -pa no se lleva el acento: queda en la e de mba'e, que ya no es la última vocal, y por eso se escribe la tilde. Mba'épa he'ise «ramói»?: ¿qué significa «ramói»?"},{"id":"a1u04d4.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" ko mitã?","tiles":["máva","pa"],"bank":[1,0],"hint":"Máva ya tiene su tilde, y -pa no la mueve.","full":"{Mávapa} ko mitã?","es":"¿Quién es este chico?","explain":"máva («quién») + -pa (pregunta) = Mávapa. La tilde ya estaba en la primera a de máva y se queda ahí: -pa no se lleva el acento. Mávapa ko mitã?: ¿quién es este chico?"}],"exam":[{"id":"a1u04d4.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: _Mba'épa he'ise «kuñataĩ»?_","options":["¿Quién es esa chica?","¿Qué significa «kuñataĩ»?","¿Dónde está la chica?","¿Cómo se escribe «kuñataĩ»?"],"answer":2,"explain":"Mba'épa es «¿qué?» y he'ise, «significa»: Rosa pregunta qué significa la palabra kuñataĩ. «Quién» sería mávapa, «dónde» sería moõpa y «cómo» sería mba'éichapa."},{"id":"a1u04d4.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan: (   ) amo kuña?\nRosa: Che jarýi.","options":["Mba'épa","Moõpa","Mboýpa","Mávapa"],"answer":4,"explain":"Rosa responde con una persona, che jarýi, «mi abuela»: Juan preguntó quién es aquella mujer, Mávapa amo kuña? Mba'épa pregunta por una cosa, moõpa por un lugar y mboýpa por una cantidad."},{"id":"a1u04d4.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Vendedor: ","after":" reipota?","tiles":["mba'e","pa"],"bank":[1,0],"full":"Vendedor: Mba'épa reipota?","es":"Vendedor: ¿Qué querés?","explain":"mba'e («qué») + -pa (pregunta) = Mba'épa. -pa no se lleva el acento: queda en la e, que ya no es la última vocal, y se escribe la tilde. Mba'épa reipota? es la pregunta del vendedor: «¿qué querés?»."}]},"words":{"es":"¿Quién es? En el cumpleaños","intro":"En el cumpleaños de la abuela hay chipa, sopa paraguaya y gente que no conocés. Tocá cada palabra: con ellas preguntás quién es quién y qué significa lo que oís.","sound":{"focus":"La u siempre suena: kuimba'e, -gui","letters":["ku","gu"],"note":"En castellano la u de «que», «qui», «gue» y «gui» no suena; en guaraní la u suena siempre. Kuimba'e empieza como «cuidar», y -gui y -nguéra se dicen como con diéresis: «güi», «ngüéra». No hay pares mínimos seguros: son palabras para contrastar, y la segunda de cada par lleva ku o gu antes de otra vocal.","pairs":[["kuña","mujer","kuimba'e","hombre"],["ake","duermo","kokue","chacra"],["óga","casa","jagua","perro"],["ógape","en casa","ógagui","de la casa"]]},"words":[{"id":"mavapa","gn":"Mávapa?","es":"¿Quién?","parts":[["máva","quién"],["-pa","pregunta"]],"note":"Tilde en la primera a. En la charla también se oye Mávapiko?, con piko pegado a la palabra que pregunta; con nde va suelto: Nde piko (semana 3)."},{"id":"mbaepa","gn":"Mba'épa?","es":"¿Qué?","parts":[["mba'e","qué; cosa"],["-pa","pregunta"]],"note":"Mba'e es aguda; con -pa aparece la tilde en la é. Mb es una sola letra: mba-'e."},{"id":"mbaepaheise","gn":"Mba'épa he'ise?","es":"¿Qué significa?","parts":[["mba'épa","¿qué?"],["he'ise","significa"]],"note":"La pregunta del alumno. La palabra va después: Mba'épa he'ise «ramói»?"},{"id":"mbaerepa","gn":"Mba'érepa?","es":"¿Por qué?","parts":[["mba'e","qué"],["-re","por"],["-pa","pregunta"]],"note":"Por ahora, solo para reconocerla cuando la oigas."},{"id":"kariay","gn":"karia'y","es":"muchacho, joven","note":"Lleva puso antes de la y final, que es la sexta vocal: karia'y."},{"id":"mitakuna","gn":"mitãkuña","es":"niña","parts":[["mitã","niño, niña"],["kuña","mujer"]],"note":"La del día 2. Plural: mitãkuñanguéra."},{"id":"kuimbae","gn":"kuimba'e","es":"hombre","note":"La u suena: empieza como «cuidar». Mb es una sola letra, y lleva puso antes de la e: kui-mba-'e."},{"id":"angiru","gn":"angirũ","es":"amigo, amiga","note":"Ng en una sola sílaba: a-ngi-rũ. Con nde se dice ne angirũ."}],"spell":["mbaepa","mavapa","kuimbae","angiru"],"check":{"id":"a1u04d4.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"En el cumpleaños hay un _hombre_ que no conocés. ¿Cómo se escribe «hombre» en guaraní?","options":["kuimbae","cuimba'e","kuimba'e","küimba'e"],"answer":3,"explain":"Hombre es kuimba'e: con k, con la u, que en guaraní siempre suena, y con puso antes de la e. Kuimbae pierde el puso. Cuimba'e usa la c, que sola no es una letra del guaraní: ese sonido se escribe k. Küimba'e le pone la diéresis del castellano: en guaraní la u suena sin ninguna marca, y la ü no es una letra del alfabeto."}},"skill":{"kind":"reading","es":"Un chat con foto","ask":"¿Quién es el señor de la foto?","seconds":75,"passage":"Rosa: Mba'éichapa, Juan?\nJuan: Iporã. ^Mávapa pe kuñataĩ?^\nRosa: Che memby, héra Sofía.\nJuan: Ha ^pe karai?^\nRosa: ^Che ramói.^\nJuan: Mba'épa he'ise «ramói»?\nRosa: «Abuelo».","strategy":"Juan pregunta dos veces por una persona, y la respuesta de Rosa viene justo después de cada pregunta. Al final Juan pregunta qué significa una palabra: esa respuesta también te sirve.","item":{"id":"a1u04d4.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Quién es el señor de la foto?","options":["El papá de Rosa.","El abuelo de Rosa.","El hijo de Rosa.","Un amigo de Rosa."],"short":["Su papá","Su abuelo","Su hijo","Un amigo"],"answer":2,"why":["Para el papá, Rosa diría che ru, y no lo dice en el chat.","Juan pregunta Ha pe karai?, «¿y ese señor?», y Rosa responde Che ramói, «mi abuelo». Después se lo traduce: ramói es «abuelo».","Che memby es Sofía, la kuñataĩ de la foto: la hija de Rosa, no el señor.","Un amigo sería che angirũ, y esa palabra no aparece en el chat."],"explain":"Juan pregunta por el señor con Ha pe karai?, y Rosa contesta Che ramói, «mi abuelo». Cuando Juan pregunta Mba'épa he'ise «ramói»?, Rosa lo traduce: «abuelo»."}}},{"title":"Números 1–5 en guaraní y números castellanos en el habla","grammar":{"points":[{"id":"a1u04d5.p1","form":"peteĩ · mokõi · mbohapy · irundy · po + sustantivo","gloss":"uno, dos, tres, cuatro, cinco","connect":[{"pos":"Delante del sustantivo, que queda en singular: el número ya dice cuántos","rule":"{mokõi} kuña · {mbohapy} memby"},{"pos":"Para contar lo que hay, con oĩ, y para preguntar cuántos, con mboýpa (semana 1)","rule":"Oĩ {mbohapy} apyka. · Mboýpa ne memby?"},{"pos":"La edad: ary, «año», con tener: areko, rereko, oguereko. -pa se pega a la última palabra de lo que preguntás: mboy ary → Mboy arýpa","rule":"Oguereko {mokõi} ary. · Mboy arýpa rereko?"},{"pos":"Po es «cinco» y también «mano»","rule":"{po} mitã · {po} ary"}],"examples":[{"gn":"{Mokõi} kuña omba'apo.","es":"Dos mujeres trabajan.","parts":[["mokõi","dos"],["kuña","mujer (en singular)"],["omba'apo","trabajan"]]},{"gn":"Ha'e oguereko {mokõi} ary.","es":"Él tiene dos años.","parts":[["ha'e","él, ella"],["oguereko","tiene (la forma de ha'e)"],["mokõi","dos"],["ary","año"]]},{"gn":"Jareko {peteĩ} jagua.","es":"Tenemos un perro.","parts":[["ja-","nosotros (con vos)"],["reko","tener"],["peteĩ","uno, un"],["jagua","perro"]]},{"gn":"Rosa: Areko {mbohapy} memby.","es":"Rosa: Tengo tres hijos.","parts":[["a-","yo"],["reko","tener"],["mbohapy","tres"],["memby","hijo o hija (dice la mamá)"]]}],"watch":{"note":"Después del número, el sustantivo va sin -kuéra ni -nguéra: el número ya dice cuántos. En castellano agregás la s; en guaraní, no.","bad":"mokõi mitãnguéra","good":"mokõi mitã"}},{"id":"a1u04d5.p2","form":"número castellano + sustantivo","gloss":"de seis en adelante, precios y edad, en el habla","connect":[{"pos":"Los precios se dicen en castellano, como en la semana 1","rule":"Mboýpa ovale? {Diez mil}."},{"pos":"De seis en adelante, en la charla, el número suele ir en castellano, y el sustantivo puede seguir en guaraní","rule":"{doce} mitã · {mil} tapicha"},{"pos":"La edad: el número en castellano, con ary o solo; por escrito suele ir en cifras: 80 ary","rule":"Mboy arýpa rereko? {Veinte}. · Oguereko {ochenta} ary."},{"pos":"Del 6 al 10 en guaraní, para leerlos: son de la escuela y de los textos","rule":"{poteĩ} 6 · {pokõi} 7 · {poapy} 8 · {porundy} 9 · {pa} 10"}],"examples":[{"gn":"Rosa: Mboýpa ovale ko kesu?\nVendedor: {Diez mil}.","es":"Rosa: ¿Cuánto cuesta este queso?\nVendedor: Diez mil.","parts":[["mboýpa","¿cuánto?"],["ovale","cuesta, vale"],["ko kesu","este queso"],["diez mil","el precio, en castellano"]]},{"gn":"Ana: Mboy arýpa rereko?\nLuis: {Veinte}.","es":"Ana: ¿Cuántos años tenés?\nLuis: Veinte.","parts":[["mboy","cuántos"],["ary","año"],["-pa","pregunta"],["rereko","tenés"],["veinte","la edad, en castellano"]]},{"gn":"Che ramói oguereko {ochenta} ary.","es":"Mi abuelo tiene ochenta años.","parts":[["che ramói","mi abuelo"],["oguereko","tiene"],["ochenta","80, en castellano; en un texto se escribe la cifra: 80 ary"],["ary","año"]]},{"gn":"Oguereko {pa} ary.","es":"Tiene diez años.","parts":[["oguereko","tiene"],["pa","diez, el numeral de la escuela"],["ary","año"]]}],"watch":{"note":"El precio se dice entero en castellano. No mezcles los dos sistemas en una misma cifra: pa es «diez» en guaraní, pero diez mil se dice diez mil.","bad":"Mboýpa ovale? Pa mil.","good":"Mboýpa ovale? Diez mil."}}],"compare":{"intro":"Hasta cinco en guaraní y, en la charla, de seis en adelante en castellano; detrás de un número, el sustantivo va sin -kuéra.","forms":[{"form":"peteĩ … po + sustantivo","tag":"1 a 5, en guaraní","mark":"dot","gn":"{Mokõi} kuña opurahéi.","es":"Dos mujeres cantan."},{"form":"número castellano","tag":"más de 5, precios y edad","mark":"dot","gn":"Mboýpa ovale? {Diez mil}.","es":"¿Cuánto cuesta? Diez mil."},{"form":"sustantivo + -kuéra / -nguéra","tag":"plural sin número (día 2)","mark":"dot","gn":"Kuña{nguéra} opurahéi.","es":"Las mujeres cantan."}],"check":{"id":"a1u04d5.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis cuenta las sillas del patio: ^tres^.\nLuis: Oĩ (   ).","options":["mbohapy apyka","mbohapy apykakuéra","mbohapykuéra apyka"],"answer":1,"why":["Tres sillas: mbohapy apyka. El número va delante, y apyka queda en singular, porque el número ya dice cuántas son.","Apykakuéra es «las sillas», sin número. Con mbohapy delante, el plural -kuéra sobra.","-kuéra es el plural del sustantivo, no del número: mbohapy no lo lleva."]}},"drill":[{"id":"a1u04d5.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa tiene ^dos^ hijos.)\nAna: Mboýpa ne memby, Rosa?\nRosa: Areko (   ) memby.","options":["mbohapy","mokõi","peteĩ","po"],"answer":2,"why":["Mbohapy es «tres», y Rosa tiene dos hijos.","Rosa tiene dos hijos: mokõi memby. El número va delante de memby, que queda en singular.","Peteĩ es «uno», y son dos.","Po es «cinco». Y acordate: también es «mano»."]},{"id":"a1u04d5.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta las gallinas del patio: ^cinco^.)\nAna: Oĩ (   ) ryguasu korapýpe.","options":["irundy","mbohapy","po","pa"],"answer":3,"why":["Irundy es «cuatro»: una menos.","Mbohapy es «tres».","Cinco gallinas: po ryguasu. Po va delante, y ryguasu queda en singular.","Pa es «diez», el numeral de la escuela. Ana cuenta cinco."]},{"id":"a1u04d5.d3","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(El chipá cuesta ^dos mil^ guaraníes.)\nRosa: Mboýpa ovale ko chipa?\nVendedor: (   )","options":["Mokõi chipa.","Pa mil.","Héẽ.","Dos mil."],"answer":4,"why":["Mokõi chipa es «dos chipás»: dice cuántos hay, no cuánto cuestan.","Pa mil mezcla los dos sistemas, y además pa es «diez», no «dos». El precio se dice entero en castellano.","Héẽ, «sí», contesta preguntas de sí o no. Mboýpa pide una cantidad.","El precio se dice en castellano: dos mil. Mboýpa ovale? pregunta cuánto cuesta."]},{"id":"a1u04d5.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa habla de ^sus dos hijos^.\nRosa: Areko mokõi (   ).","options":["membykuéra","memby","ra'y","membynguéra"],"answer":2,"why":["Membykuéra es «hijos», en plural, pero detrás de mokõi el sustantivo va sin -kuéra: el número ya dice que son dos.","Detrás del número, memby queda en singular: mokõi memby, «dos hijos». Lo dice la mamá.","Ra'y es «hijo» cuando lo dice el papá. Rosa es la mamá: memby.","Membynguéra falla dos veces: lleva el plural, que no va tras el número, y usa la forma de después de una sílaba nasal, cuando by es oral."]},{"id":"a1u04d5.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Ana: Mboy ","after":" rereko, Luis?","tiles":["ary","pa"],"bank":[1,0],"hint":"-pa va pegado a ary y no se lleva el acento: fijate qué pasa con la tilde.","full":"Ana: Mboy arý{pa} rereko, Luis?","es":"Ana: ¿Cuántos años tenés, Luis?","explain":"ary («año») + -pa (pregunta) = arýpa. -pa no se lleva el acento: queda en la y de ary, que ya no es la última vocal, y por eso se escribe la tilde: ý. Mboy arýpa rereko?: ¿cuántos años tenés?"},{"id":"a1u04d5.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Rosa:","after":" kesu?\nVendedor: Diez mil.","tiles":["mboýpa","ovale","ko"],"bank":[1,2,0],"hint":"Empezá por la palabra que pregunta. Ko va pegado a kesu, como en ko ka'aru.","full":"Rosa: {Mboýpa} ovale ko kesu?\nVendedor: Diez mil.","es":"Rosa: ¿Cuánto cuesta este queso?\nVendedor: Diez mil.","explain":"Mboýpa, «¿cuánto?», va primero: es la palabra que pregunta, como Mba'éichapa en Mba'éichapa nde réra?. Después el verbo, ovale, «cuesta», y al final ko kesu, «este queso», con ko delante del sustantivo, como el día 3. El vendedor contesta el precio entero en castellano: diez mil. La moneda de Paraguay se llama guaraní, como la lengua: el precio va en guaraníes."}],"exam":[{"id":"a1u04d5.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: _Areko mbohapy memby._","options":["Tengo dos hijos.","Tengo tres años.","Tengo muchos hijos.","Tengo tres hijos."],"answer":4,"explain":"Areko es «tengo», mbohapy, «tres», y memby, «hijo» o «hija» cuando lo dice la mamá: «tengo tres hijos». Dos sería mokõi, y «tres años» llevaría ary: mbohapy ary. Mbohapy es un número exacto, no «muchos»."},{"id":"a1u04d5.e2","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(En la despensa.)\nAna: Mboýpa ovale ko so'o?\nVendedor: (   )","options":["Pa.","Mokõi so'o.","Veinte mil.","Oĩ so'o."],"answer":3,"explain":"Mboýpa ovale? pregunta el precio, y el precio se dice en castellano y entero: veinte mil. Pa es «diez» en guaraní, el numeral de la escuela, y no es un precio; mokõi so'o, «dos» de carne, dice una cantidad, no un precio; y Oĩ so'o, «hay carne», contesta Oĩpa so'o?, no cuánto cuesta."},{"id":"a1u04d5.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Juan le pregunta a Rosa por el hijo de ella.)\nJuan: Mboy ","after":" oguereko ne memby?","tiles":["ary","pa"],"bank":[1,0],"full":"(Juan le pregunta a Rosa por el hijo de ella.)\nJuan: Mboy arýpa oguereko ne memby?","es":"Juan: ¿Cuántos años tiene tu hijo?","explain":"ary («año») + -pa (pregunta) = arýpa. -pa no se lleva el acento: queda en la y de ary, que ya no es la última vocal, y se escribe la tilde. Oguereko es «tiene», y ne memby, «tu hijo»: ¿cuántos años tiene tu hijo?"}]},"words":{"es":"En la despensa del barrio","intro":"En la despensa de la esquina contás lo que llevás. Tocá cada palabra: hasta cinco en guaraní, y el precio en castellano.","sound":{"focus":"La k: kesu, kamby","letters":["k"],"note":"La k escribe siempre el mismo sonido, el de la c de «casa» y la qu de «queso»: kesu, kamby, mokõi. La c sola y la q no son letras del guaraní, y por eso queso se escribe kesu. No hay pares mínimos seguros: son palabras para contrastar, con la k delante de vocales distintas.","pairs":[["kesu","queso","kamby","leche"],["mokõi","dos","kuña","mujer"],["apyka","silla","korapy","patio"]]},"words":[{"id":"petei","gn":"peteĩ","es":"uno, una","note":"Tilde nasal en la ĩ: pe-te-ĩ. Peteĩ jagua es «un perro»."},{"id":"mokoi","gn":"mokõi","es":"dos","note":"Con k y con la õ nasal. Mokõive es «los dos»."},{"id":"mbohapy","gn":"mbohapy","es":"tres","note":"Mb es una sola letra: mbo-ha-py. La h suena."},{"id":"irundy","gn":"irundy","es":"cuatro","note":"Nd es una sola letra, y la y del final es la sexta vocal: i-ru-ndy."},{"id":"po","gn":"po","es":"cinco","note":"También es «mano»: cinco dedos. De seis en adelante, en la charla el número suele decirse en castellano."},{"id":"chipa","gn":"chipa","es":"chipá","note":"Sin tilde: en guaraní, sin marca, el acento cae al final. De la semana 1."},{"id":"kesu","gn":"kesu","es":"queso","note":"Del castellano «queso», con k: en guaraní no hay qu. De la semana 1."},{"id":"kamby","gn":"kamby","es":"leche","note":"Con k y con y, la sexta vocal. Vaka kamby es «leche de vaca»."}],"spell":["mokoi","kamby","chipa","kesu"],"check":{"id":"a1u04d5.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa lleva _dos_ chipás. ¿Cómo se escribe «dos» en guaraní?","options":["mocõi","mokoi","mokõi","mokõĩ"],"answer":3,"explain":"Dos es mokõi: con k, porque en guaraní no hay c, y con la õ nasal. Mocõi usa la c del castellano. Mokoi pierde la tilde nasal, y la o de mokõi es nasal. Mokõĩ marca también la i: en mokõi la tilde nasal va solo en la õ, la vocal del acento, y la i va sin marca."}},"skill":{"kind":"listening","es":"Comprensión de puntos clave","situation":"En la despensa. Rosa compra queso y pregunta el precio.","ask":"¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?","item":{"id":"a1u04d5.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?","options":["Tres, y el queso cuesta diez mil.","Dos, y el queso cuesta diez mil.","Dos, y el queso cuesta veinte mil."],"short":["Tres, diez mil","Dos, diez mil","Dos, veinte mil"],"printed":true,"answer":2,"why":["Rosa pide mokõi kesu, «dos quesos», no mbohapy, «tres». El precio sí es diez mil.","Rosa pregunta el precio, Mboýpa ovale?, y el vendedor dice diez mil. Después ella pide mokõi kesu, «dos quesos».","Dos quesos sí, pero el vendedor dice diez mil, no veinte mil."],"script":["Narrador: En la despensa. ¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?","Mujer: Mba'éichapa? Oĩpa kesu?","Hombre: Héẽ, oĩ.","Mujer: Mboýpa ovale?","Hombre: Diez mil.","Mujer: Mokõi kesu, aguyje.","Narrador: ¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?"]},"audio":[["N","En la despensa. ¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?","En la despensa. ¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?"],["F","Mba'éichapa? Oĩpa kesu?","Hola. ¿Hay queso?"],["M","Héẽ, oĩ.","Sí, hay."],["F","Mboýpa ovale?","¿Cuánto cuesta?"],["M","Diez mil.","Diez mil."],["F","Mokõi kesu, aguyje.","Dos quesos, gracias."],["N","¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?","¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?"]]}},{"title":"Repaso de la semana","grammar":{"points":[],"compare":{"intro":"Cuatro pares de la semana que se parecen: fijate si la palabra que sigue es nasal, si son uno o varios, y si preguntás por una persona o por una cosa.","forms":[{"form":"nde · ne","tag":"tu: ante palabra oral · ante palabra nasal","mark":"dot","gn":"Mba'éichapa héra {nde} sy?\nMba'éichapa héra {ne} memby?","es":"¿Cómo se llama tu mamá?\n¿Cómo se llama tu hijo?"},{"form":"-kuéra · -nguéra","tag":"plural: tras sílaba oral · tras sílaba nasal","mark":"dot","gn":"Jagua{kuéra} oyta.\nMitã{nguéra} oho mbo'ehaópe.","es":"Los perros nadan.\nLos niños van a la escuela."},{"form":"ko · ko'ã · pe · umi","tag":"uno · varios","mark":"dot","gn":"{Ko} óga · {ko'ã} óga\n{Pe} mitã · {umi} mitã","es":"esta casa · estas casas\nese chico · esos chicos"},{"form":"Mávapa · Mba'épa","tag":"¿quién? · ¿qué?","mark":"dot","gn":"{Mávapa} ha'e?\n{Mba'épa} he'ise?","es":"¿Quién es?\n¿Qué significa?"}],"check":{"id":"a1u04d6.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa pregunta por ^el muchacho de la foto^.\nRosa: (   ) amo karia'y?\nJuan: ^Che ra'y.^","options":["Mba'épa","Mávapa","Moõpa"],"answer":2,"why":["Mba'épa pregunta por una cosa: Mba'épa amo karia'y? sería «¿qué es aquel muchacho?». Juan responde con una persona.","Rosa pregunta por una persona, el muchacho: Mávapa amo karia'y?, «¿quién es aquel muchacho?». Juan responde Che ra'y, «mi hijo».","Moõpa pregunta «¿dónde?», por un lugar. Juan no dice un lugar: dice quién es."]}},"drill":[{"id":"a1u04d6.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis le pregunta a Juan cómo se llama ^la esposa de él^.\nLuis: Mba'éichapa héra (   ) rembireko, Juan?","options":["nde","che","ne","ñande"],"answer":3,"why":["Nde es «tu», pero rembireko es una palabra nasal: tiene mb (re-mbi-re-ko). Delante de una palabra nasal, nde pierde la d: ne rembireko.","Che es «mi»: Luis preguntaría por su propia esposa, y pregunta por la de Juan.","Luis le pregunta a Juan por la esposa de él, «tu esposa». Rembireko tiene mb, una letra nasal, así que nde se vuelve ne: ne rembireko.","Ñande es «nuestro» con vos: sumaría a Luis. Y delante de una palabra nasal sería ñane."]},{"id":"a1u04d6.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa habla de ^las gallinas^ del patio.\nRosa: (   ) oĩ korapýpe.","options":["Ryguasunguéra","Riguasukuéra","Ryguasucuéra","Ryguasukuéra"],"answer":4,"why":["-nguéra va solo tras una sílaba nasal, y ryguasu termina en su, una sílaba oral.","Riguasukuéra cambia la y por i. La primera sílaba de ry-gua-su lleva la y, la sexta vocal.","Ryguasucuéra escribe el plural con c, y la c no es una letra del guaraní: ese sonido se escribe con k, kuéra.","Ryguasu termina en su, sílaba oral: va -kuéra, que se lleva el acento. Ryguasukuéra oĩ korapýpe: las gallinas están en el patio."]},{"id":"a1u04d6.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan y Rosa están en la puerta. Juan señala ^un caballo al fondo del patio, lejos de los dos^.)\nJuan: (   ) kavaju ituicha.","options":["Amo","Ko","Pe","Umi"],"answer":1,"why":["El caballo está lejos de los dos, pero a la vista: amo kavaju, «aquel caballo». Amo kavaju ituicha: aquel caballo es grande.","Ko es «este», para algo cerca de Juan, el que habla. El caballo está al fondo del patio.","Pe es «ese», para algo cerca de Rosa, la que escucha. El caballo está lejos de los dos.","Umi es para varios, «esos» o «aquellos». Es un solo caballo."]},{"id":"a1u04d6.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis cuenta ^a los chicos^ del patio: son ^cuatro^.\nLuis: Oĩ irundy (   ).","options":["mitãnguéra","mitã","mitãkuéra","mitakuéra"],"answer":2,"why":["Mitãnguéra es «los niños», el plural de mitã, pero después de un número el sustantivo va solo: irundy ya dice que son cuatro.","Después del número, el sustantivo va en singular: irundy mitã, «cuatro chicos». El número ya dice cuántos son.","Mitãkuéra usa la forma de después de una sílaba oral, y mitã termina en ã, nasal. Y después de un número no va plural.","Mitakuéra pierde la ~ de mitã, que la palabra sí lleva, y además pone un plural después del número."]},{"id":"a1u04d6.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Che sy oñe'ẽ ","after":".","tiles":["mitã","nguéra","pe"],"bank":[2,1,0],"hint":"Primero el plural, que se lleva el acento, y al final -pe, «a».","full":"Che sy oñe'ẽ mitã{nguéra}pe.","es":"Mi mamá les habla a los niños.","explain":"mitã («niño») + -nguéra (plural tras nasal, porque mitã termina en ã) + -pe («a») = mitãnguérape. -nguéra se lleva el acento, y -pe no lo mueve: la ~ queda en la ã y la tilde en la é. Después de -nguéra va -pe, porque ra es una sílaba oral."},{"id":"a1u04d6.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" oĩ korapýpe?","tiles":["mba'e","pa"],"bank":[1,0],"hint":"-pa va al final y no se lleva el acento: mirá dónde aparece la tilde.","full":"{Mba'épa} oĩ korapýpe?","es":"¿Qué hay en el patio?","explain":"mba'e («qué») + -pa (pregunta) = Mba'épa. -pa no se lleva el acento: queda en la e de mba'e, que ya no es la última vocal, y por eso se escribe la tilde. Mba'épa oĩ korapýpe?: ¿qué hay en el patio?"}],"exam":[{"id":"a1u04d6.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: _Ne membykuéra moõpa oĩ?_","options":["¿Dónde están tus hijos?","¿Dónde está tu hijo?","¿Quiénes son tus hijos?","¿Dónde están mis hijos?"],"answer":1,"explain":"Ne es «tu» delante de una palabra nasal, y -kuéra hace el plural: ne membykuéra, «tus hijos». Moõpa es «¿dónde?» y oĩ, «están». Un solo hijo sería ne memby, «mis» sería che, y «quiénes» se pregunta con mávapa."},{"id":"a1u04d6.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana tiene dos chipá en la mano y se los muestra a Luis.)\nAna: (   ) chipa iporã.","options":["Umi","Ko","Pe","Ko'ã"],"answer":4,"explain":"Son dos chipá y los tiene Ana, la que habla: ko'ã chipa, «estos chipá». Ko'ã es el ko de varios. Umi es para varios pero lejos de quien habla; ko y pe son para uno solo, y pe, además, para algo cerca del que escucha."},{"id":"a1u04d6.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Mboy ","after":" rereko?","tiles":["ary","pa"],"bank":[1,0],"full":"Mboy arýpa rereko?","es":"¿Cuántos años tenés?","explain":"ary («año») + -pa (pregunta) = arýpa. -pa se pega a la última palabra de lo que se pregunta, mboy ary, «cuántos años», y no se lleva el acento: queda en la y de ary, que ya no es la última vocal, y por eso se escribe la tilde. Rereko es «tenés»: Mboy arýpa rereko?, ¿cuántos años tenés?"}]},"words":{"es":"La familia en la fiesta","intro":"El cumpleaños de la abuela, en el patio. Ana presenta a su familia y señala quién es quién. Tocá cada palabra: son las de toda la semana.","sound":{"focus":"Repaso: la tilde, el acento, la v, la u y la k","letters":["ói","é","v","gu","k"],"note":"La tilde va en la vocal del acento cuando no es la última (ramói). -kuéra y -nguéra se llevan el acento y la tilde de la raíz desaparece (ogakuéra); con -pa, -pe o -gui el acento se queda en la raíz (Mba'épa, ógape, ógagui). La u siempre suena, también en -gui y -kuéra; vaka va con v y con k, y kesu con k, sin c ni qu: son palabras para contrastar, no pares mínimos.","pairs":[["karai","señor","ramói","abuelo (con che)"],["óga","casa","ogakuéra","casas"],["ógape","en casa","ógagui","de la casa"],["vaka","vaca","kesu","queso"]]},"words":[{"id":"ramoi","gn":"che ramói","es":"mi abuelo","parts":[["che","mi"],["ramói","abuelo (con che, ne)"]],"note":"Sola, la palabra es tamói. Es nasal, con m: con nde se dice ne ramói. Tilde en la ó: el acento no cae al final."},{"id":"rembireko","gn":"che rembireko","es":"mi esposa","parts":[["che","mi"],["rembireko","esposa (con che, ne)"]],"note":"Sola, la palabra es tembireko, y «su esposa» es hembireko: la h suena. Es nasal, con mb: con nde se dice ne rembireko."},{"id":"tuvakuera","gn":"tuvakuéra","es":"los padres, los papás","parts":[["túva","padre"],["-kuéra","plural"]],"note":"Túva pierde su tilde: -kuéra se lleva el acento. Sy ha tuvakuéra, «madres y padres». Con che, «mi papá» es che ru."},{"id":"mitanguera","gn":"mitãnguéra","es":"los niños, las niñas","parts":[["mitã","niño, niña"],["-nguéra","plural tras nasal"]],"note":"La ~ se queda y el acento va a la é. Ng es una sola letra: mi-tã-ngué-ra."},{"id":"koa","gn":"ko'ã","es":"estos, estas","note":"El plural de ko, en una sola palabra, con puso y ã: ko'ã mitã, «estos chicos». El sustantivo queda como está."},{"id":"umi","gn":"umi","es":"esos, esas; aquellos, aquellas","note":"El plural de pe y de amo: umi mitã, «esos chicos». Con un número: umi mokõi karia'y, «esos dos muchachos»."},{"id":"mbaepa","gn":"Mba'épa?","es":"¿Qué?","parts":[["mba'e","qué; cosa"],["-pa","pregunta"]],"note":"Mba'e es aguda; con -pa aparece la tilde en la é. Mb es una sola letra: mba-'e."},{"id":"irundy","gn":"irundy","es":"cuatro","note":"Nd es una sola letra, en una sola sílaba: i-ru-ndy. Después del número, el sustantivo va sin plural: irundy mitã, «cuatro chicos»."}],"spell":["mitanguera","tuvakuera","mbaepa","koa"],"check":{"id":"a1u04d6.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana saluda a _los padres_ de los chicos: Maitei, (   ). ¿Cómo se escribe en guaraní?","options":["tuvanguéra","tuvacuéra","tuvakuéra","tubakuéra"],"answer":3,"explain":"«Los padres» es tuvakuéra: túva, «padre», más -kuéra, que se lleva el acento, así que la tilde de túva desaparece. Va es una sílaba oral: por eso -kuéra y no -nguéra. Tuvacuéra escribe el plural con c, que no es una letra del guaraní: ese sonido se escribe con k. Tubakuéra escribe con b, que sola tampoco es una letra del guaraní: acá va v."}},"skill":{"kind":"reading","es":"Un mensaje con foto","ask":"¿Cuántos hijos de Rosa hay en la foto?","seconds":75,"passage":"Maitei, Juan.\n^Ko'ã mitã che membykuéra: Sofía ha Tomás.^\nPe karai che ramói, héra Pedro. Oguereko 80 ary.\n^Umi mokõi mitãkuña che angirũ memby.^\nJajotopáta ko ka'aru.\nRosa","strategy":"Buscá de quién es cada grupo: después de ko'ã mitã y de umi mokõi mitãkuña viene el dueño, che membykuéra o che angirũ memby. Ha, «y», une dos nombres.","item":{"id":"a1u04d6.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Cuántos hijos de Rosa hay en la foto?","options":["Uno.","Dos.","Cuatro.","No lo dice."],"short":["Uno","Dos","Cuatro","No lo dice"],"answer":2,"why":["Un solo hijo sería che memby. Rosa escribe che membykuéra, con -kuéra: más de uno, y da dos nombres.","Ko'ã mitã che membykuéra: Sofía ha Tomás, «estos chicos son mis hijos: Sofía y Tomás». En la foto hay dos hijos de Rosa.","En la foto hay cuatro chicos, pero las dos nenas, umi mokõi mitãkuña, son che angirũ memby: las hijas de la amiga de Rosa, no de Rosa.","Sí lo dice: después de che membykuéra, «mis hijos», vienen los nombres, Sofía ha Tomás."],"explain":"Rosa escribe Ko'ã mitã che membykuéra: Sofía ha Tomás, «estos chicos son mis hijos: Sofía y Tomás»: en la foto hay dos hijos de Rosa. Las otras dos, umi mokõi mitãkuña, son che angirũ memby: las hijas de su amiga."}}}],"test":["a1u04t.1","a1u04t.2","a1u04t.3","a1u04t.4","a1u04t.5","a1u04t.6","a1u04t.7","a1u04t.8","a1u04t.9","a1u04t.10","a1u04t.11","a1u04t.12","a1u04t.13","a1u04t.14","a1u04t.15","a1u04t.16","a1u04t.17","a1u04t.18","a1u04t.19","a1u04t.20"]},{"n":5,"gn":"","es":"Mi día","days":[{"title":"Prefijos aireales ai-/rei-/oi-"},{"title":"Verbos de rutina"},{"title":"La hora y los días, en castellano dentro del guaraní"},{"title":"Moõpa oĩ…? «¿dónde está…?»; araka'e «cuándo»"},{"title":"Armonía nasal I: -pe → -me"},{"title":"Repaso de la semana"}],"test":[]},{"n":6,"gn":"","es":"Ayer y mañana","days":[{"title":"-ta: futuro e intención (a-karu-ta)"},{"title":"kuri: pasado"},{"title":"Palabras de tiempo"},{"title":"Negar el futuro: nd-…-mo'ãi"},{"title":"Mensaje: planes del fin de semana"},{"title":"Repaso de la semana"}],"test":[]},{"n":7,"gn":"","es":"En el mercado y en la mesa","days":[{"title":"oĩ «hay, está»; ndaipóri «no hay»"},{"title":"Precios: cifras castellanas en el guaraní hablado"},{"title":"-se «quiero + verbo» (a-ha-se; -se lleva el acento)"},{"title":"-na: pedido amable"},{"title":"Tereré y comida paraguaya (escena)"},{"title":"Repaso de la semana"}],"test":[]},{"n":8,"gn":"","es":"Pedir, mandar, prohibir","days":[{"title":"Imperativo de 2.ª persona (prefijo e-?)"},{"title":"-ke: orden enérgica; -py: urgencia"},{"title":"Prohibir: ani re-ho-tei «no vayas»"},{"title":"-ndive «con»"},{"title":"Escribir una nota con las 33 letras"},{"title":"Repaso de la semana"}],"test":[]}],"items":{"a1u01d1.c1":{"id":"a1u01d1.c1","kind":"choice","area":"grammar","label":"Elegí la frase","q":"(^Llegás^ a la ronda de tereré.)\nVos: (   )","options":["Jajotopáta, Rosa.","Mba'éichapa, Rosa?","Iporã, ha nde?"],"answer":2,"why":["Jajotopáta es para irte, y recién llegás.","Llegás, así que saludás: Mba'éichapa, Rosa?","Iporã, ha nde? responde a un saludo, y nadie te preguntó nada todavía."],"step":"compare"},"a1u01d1.d1":{"id":"a1u01d1.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: ^Mba'éichapa^, Juan?\nJuan: (   ), ha nde?","options":["Iporã","Jajotopáta","Reiko","Mba'éichapa"],"answer":1,"why":["Rosa pregunta cómo está Juan, y él responde Iporã, «bien». Después le devuelve la pregunta: ha nde?","Jajotopáta es para despedirse, y Rosa recién saluda.","reiko es «andás», hablando de vos, como en Mba'éichapa reiko? Juan tiene que decir cómo está él: Iporã.","Mba'éichapa es la pregunta de Rosa. Juan tiene que responderla: Iporã."],"step":"drill"},"a1u01d1.d2":{"id":"a1u01d1.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Mba'éichapa reiko?\nJuan: Iporã, ha (   )?\nRosa: ^Iporã^.","options":["che","pa","nde","maitei"],"answer":3,"why":["che es «yo». Juan ya dijo cómo está; ahora pregunta por Rosa, y ella responde.","-pa marca la pregunta, pero va pegada a una palabra, como en Mba'éichapa. Sola no pregunta nada.","ha nde? es «¿y vos?»: Juan le devuelve la pregunta a Rosa, y ella responde Iporã.","maitei es un saludo, «hola». Con maitei, Juan no pregunta por Rosa."],"step":"drill"},"a1u01d1.d3":{"id":"a1u01d1.d3","kind":"choice","area":"grammar","label":"Elegí la frase","q":"(Juan ^se va^ de la ronda.)\nJuan: (   )","options":["Mba'éichapa reiko?","Jajotopáta, Rosa.","Iporã, ha nde?","Mba'éichapa, Rosa?"],"answer":2,"why":["Mba'éichapa reiko? pregunta cómo está alguien. Se dice al llegar, no al irse.","Juan se va, así que se despide: Jajotopáta, «nos vemos».","Iporã, ha nde? responde a un saludo, y nadie le preguntó nada a Juan.","Mba'éichapa es para saludar al llegar, y Juan se va."],"step":"drill"},"a1u01d1.d4":{"id":"a1u01d1.d4","kind":"choice","area":"grammar","label":"Elegí la palabra","q":"(Rosa se va. Ella y Juan se vuelven a ver ^esta tarde^.)\nRosa: Jajotopáta ko (   ), Juan.","options":["pyhare","nde","pyhareve","ka'aru"],"answer":4,"why":["ko pyhare es «esta noche», y se vuelven a ver a la tarde.","nde es «vos», como en ha nde? No dice cuándo se van a ver.","pyhareve es «la mañana»: ko pyhareve sería «esta mañana». Y se vuelven a ver a la tarde.","Se vuelven a ver a la tarde: ko ka'aru. Jajotopáta ko ka'aru es «nos vemos esta tarde»."],"step":"drill"},"a1u01d1.d5":{"id":"a1u01d1.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" reiko?","tiles":["mba'e","icha","pa"],"bank":[2,0,1],"hint":"-icha y -pa son sufijos: van después de mba'e. ¿Cuál cierra la pregunta?","full":"Mba'éicha{pa} reiko?","es":"¿Cómo andás?","explain":"mba'e («qué») + -icha («como») + -pa (pregunta) = Mba'éichapa. Ni -icha ni -pa se llevan el acento: queda en la e de mba'e. Como ya no es la última vocal, se escribe é.","step":"drill"},"a1u01d1.d6":{"id":"a1u01d1.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" ko ka'aru, Rosa.","tiles":["ja","jo","topáta"],"bank":[1,2,0],"hint":"ja- y jo- son prefijos: van antes de topáta. ¿Cuál va primero?","full":"{Jajo}topáta ko ka'aru, Rosa.","es":"Nos vemos esta tarde, Rosa.","explain":"ja- («nosotros», con vos) + jo- («uno al otro») + topáta (topa, «encontrar», con -ta, el futuro) = Jajotopáta. Con ko ka'aru, «esta tarde», queda «nos vemos esta tarde».","step":"drill"},"a1u01d1.e1":{"id":"a1u01d1.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: Mba'éichapa reiko?\nJuan: _Iporã, ha nde?_","options":["Hola, ¿cómo estás?","Nos vemos, ¿y vos?","Bien, ¿y vos?","Bien, ¿y yo?"],"answer":3,"explain":"Lo subrayado es la respuesta de Juan. Iporã es «bien», y ha nde? le devuelve la pregunta a Rosa: «¿y vos?». «Hola, ¿cómo estás?» es lo que dijo Rosa, «nos vemos» sería Jajotopáta, y «¿y yo?» no va, porque nde es «vos».","step":"exam"},"a1u01d1.e2":{"id":"a1u01d1.e2","kind":"choice","area":"grammar","label":"Qué significa","q":"(Rosa se va de la casa de Juan.)\nRosa: _Jajotopáta ko pyhare_, Juan.","options":["Nos vemos esta noche, Juan.","Nos vimos anoche, Juan.","Buenas noches, Juan, ¿cómo estás?","Nos vemos esta tarde, Juan."],"answer":1,"explain":"Jajotopáta es «nos vemos»: la -ta habla de lo que va a pasar, no de anoche. Ko pyhare es «esta noche»; «esta tarde» sería ko ka'aru. Y Rosa se va, así que no saluda: se despide.","step":"exam"},"a1u01d1.e3":{"id":"a1u01d1.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana se va de la ronda.)\nAna: ","after":", Juan.","tiles":["ja","jo","topáta"],"bank":[2,1,0],"full":"(Ana se va de la ronda.)\nAna: Jajotopáta, Juan.","es":"Ana: Nos vemos, Juan.","explain":"ja- («nosotros», con vos) va primero y después jo- («uno al otro»). Al final va topáta: topa («encontrar») con -ta, el futuro. Todo junto: Jajotopáta, «nos vemos».","step":"exam"},"a1u01d1.k1":{"id":"a1u01d1.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"A la mañana, saludás: Mba'éichapa nde (   )?","options":["pihareve","pyharebe","piharebe","pyhareve"],"answer":4,"explain":"Se escribe pyhareve. La primera vocal es la y, la sexta vocal: pihareve y piharebe la cambian por i. Y la b sola no es una letra del guaraní: acá va v.","step":"words"},"a1u01d1.r1":{"id":"a1u01d1.r1","kind":"choice","area":"listening","label":"Respuesta rápida","q":"¿Cuál es la mejor respuesta?","options":["Iporã, ha nde?","Jajotopáta ko ka'aru.","Iporã, ha che?"],"answer":1,"why":["Ella pregunta cómo está. Él responde Iporã, «bien», y le devuelve la pregunta: ha nde?, «¿y vos?».","Jajotopáta ko ka'aru es «nos vemos esta tarde»: sirve para irse, no para responder a un saludo.","ha che? es «¿y yo?»: así no le devuelve la pregunta a la vecina. Para eso va ha nde?, «¿y vos?»."],"script":["Narrador: En la parada del colectivo. ¿Qué responde el hombre?","Mujer: Mba'éichapa reiko?","Narrador: 1","Hombre: Iporã, ha nde?","Narrador: 2","Hombre: Jajotopáta ko ka'aru.","Narrador: 3","Hombre: Iporã, ha che?"],"step":"skill"},"a1u01d2.c1":{"id":"a1u01d2.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana y su hermano hablan guaraní. Ana se lo cuenta ^a una vecina nueva^: «(   ) guaraníme.»","options":["Ñande ñañe'ẽ","Ore roñe'ẽ","Ha'ekuéra oñe'ẽ"],"answer":2,"why":["Ñande sumaría a la vecina, que es la que escucha. Pero ella no está en el grupo.","Ana habla de ella y de su hermano, y la vecina queda afuera: ore.","Ha'ekuéra es «ellos»: dejaría afuera a Ana, que también habla guaraní."],"step":"compare"},"a1u01d2.d1":{"id":"a1u01d2.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana habla de ^ella misma^: «(   ) añe'ẽ guaraníme.»","options":["Nde","Che","Ha'e","Ore"],"answer":2,"why":["Nde es «vos», el que escucha. Ana habla de ella misma.","Ana habla de ella misma: che, «yo». Y añe'ẽ es la forma de che.","Ha'e es otra persona, «él» o «ella». Con ha'e, el verbo sería oñe'ẽ.","Ore es «nosotros, sin vos». Ana habla solo de ella."],"step":"drill"},"a1u01d2.d2":{"id":"a1u01d2.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis habla de ^su mamá^: «(   ) oñe'ẽ guaraníme.»","options":["Che","Nde","Ha'ekuéra","Ha'e"],"answer":4,"why":["Che es «yo», Luis mismo, pero él habla de su mamá. Con che, además, el verbo sería añe'ẽ.","Nde es «vos», la persona a la que Luis le habla. Él habla de su mamá.","Ha'ekuéra es «ellos», varias personas. La mamá es una sola.","Luis habla de otra persona, su mamá: ha'e, «ella». Oñe'ẽ es la forma de ha'e."],"step":"drill"},"a1u01d2.d3":{"id":"a1u01d2.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana y Luis hablan guaraní. Ana se lo dice ^a Luis^: «(   ) guaraníme.»","options":["Ñande ñañe'ẽ","Ore roñe'ẽ","Che añe'ẽ","Ha'ekuéra oñe'ẽ"],"answer":1,"why":["Ana habla de ella y de Luis, que es el que escucha: ñande lo incluye.","Ore deja afuera al que escucha, y Luis está en el grupo.","Che añe'ẽ habla solo de Ana. Ella habla de los dos.","Ha'ekuéra es «ellos», otras personas: dejaría afuera a Ana y a Luis."],"step":"drill"},"a1u01d2.d4":{"id":"a1u01d2.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Un señor les pregunta a Ana y a Luis qué idioma hablan. Ana le contesta ^al señor^: «(   ) guaraníme.»","options":["Ñande ñañe'ẽ","Ore roñe'ẽ","Peẽ peñe'ẽ","Ha'ekuéra oñe'ẽ"],"answer":2,"why":["Ñande sumaría al señor, que es el que escucha, y él no está en el grupo.","Ana habla de ella y de Luis, y el señor que escucha queda afuera: ore.","Peẽ es «ustedes»: nunca incluye al que habla, y Ana habla de ella y de Luis.","Ha'ekuéra es «ellos»: dejaría afuera a Ana, que también habla guaraní."],"step":"drill"},"a1u01d2.d5":{"id":"a1u01d2.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Nde ","after":" guaraníme.","tiles":["re","ñe'ẽ"],"bank":[1,0],"hint":"Fijate en añe'ẽ y oñe'ẽ: ¿dónde va la parte que dice quién?","full":"Nde {reñe'ẽ} guaraníme.","es":"Vos hablás guaraní.","explain":"Con nde, «vos», este verbo lleva re- al principio: re + ñe'ẽ = reñe'ẽ, «hablás». El castellano marca la persona al final (hablás); el guaraní, al principio.","step":"drill"},"a1u01d2.d6":{"id":"a1u01d2.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Luis ha Marta: Mba'éichapa reiko?\nAna:","after":"?","tiles":["iporã","ha","peẽ"],"bank":[2,0,1],"hint":"Ana contesta primero. Después les devuelve la pregunta a los dos.","full":"Luis ha Marta: Mba'éichapa reiko?\nAna: Iporã, ha {peẽ}?","es":"Luis y Marta: ¿Cómo andás? Ana: Bien, ¿y ustedes?","explain":"Ana dice primero cómo está: iporã, «bien». Después les devuelve la pregunta a Luis y a Marta, que la escuchan: ha peẽ, «¿y ustedes?». Ha, «y», va antes de peẽ.","step":"drill"},"a1u01d2.e1":{"id":"a1u01d2.e1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis le pregunta a Ana si ella también habla guaraní: «Che añe'ẽ guaraníme, ha (   )?»","options":["nde","ha'e","che","ore"],"answer":1,"explain":"Luis le habla a Ana, así que para él ella es nde, «vos»: ha nde, «¿y vos?». Ha'e sirve para hablar de otra persona, no para hablarle a Ana; che sería Luis otra vez, y ore, «nosotros sin vos», dejaría afuera a Ana.","step":"exam"},"a1u01d2.e2":{"id":"a1u01d2.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Dos alumnas hablan guaraní y se lo cuentan a su docente: «(   ) guaraníme.»","options":["Ñande ñañe'ẽ","Ha'ekuéra oñe'ẽ","Ore roñe'ẽ","Che añe'ẽ"],"answer":3,"explain":"Las alumnas hablan de ellas dos, y la docente que las escucha no está en ese grupo: ore roñe'ẽ. Ñande ñañe'ẽ sumaría a la docente, ha'ekuéra oñe'ẽ hablaría de otras personas y che añe'ẽ, de una sola alumna.","step":"exam"},"a1u01d2.e3":{"id":"a1u01d2.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana habla de su mamá y su papá.) ","after":" oñe'ẽ guaraníme.","tiles":["ha'e","kuéra"],"bank":[1,0],"full":"(Ana habla de su mamá y su papá.) {Ha'ekuéra} oñe'ẽ guaraníme.","es":"(Ana habla de su mamá y su papá.) Ellos hablan guaraní.","explain":"Ana habla de dos personas, su mamá y su papá, así que va el plural: ha'e, «él, ella», más -kuéra da ha'ekuéra, «ellos». El acento pasa a -kuéra.","step":"exam"},"a1u01d2.k1":{"id":"a1u01d2.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana habla de su amigo: «Che (   ) oñe'ẽ guaraníme.»","options":["angiru","angirũ","ãngirũ","angirun"],"answer":2,"explain":"Angirũ, «amigo», termina en ũ nasal y lleva tilde nasal (~). Angiru no tiene la nasal, y angirun agrega una n que la palabra no tiene. En ãngirũ sobra la ~ de la a: junto a ng ya suena nasal. Acá che es «mi»: che angirũ, «mi amigo», es otra persona, por eso va oñe'ẽ.","step":"words"},"a1u01d2.r1":{"id":"a1u01d2.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quiénes hablan guaraní, según el mensaje?","options":["Ana y Marta","Solo la mamá y el papá de Ana","Ana, su mamá y su papá"],"short":["Ana y Marta","Los papás","Ana y sus papás"],"answer":3,"why":["Marta es la que lee el mensaje, y ore deja afuera al que escucha o lee.","Después de los dos puntos, Ana se nombra primero: che, «yo». Ella también habla.","Ore roñe'ẽ guaraníme: che, che sy ha che ru. Son Ana, su mamá y su papá."],"explain":"Ana escribe ore roñe'ẽ guaraníme y después nombra a los de ore: che, che sy ha che ru. Ore deja afuera a Marta, la que lee.","step":"skill"},"a1u01d3.c1":{"id":"a1u01d3.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Mba'éichapa nde réra?\nB: Che réra Ana.\nA: ^[Ha mbo'ehára|¿y la profesora?]?^\nB: (   ) Rosa.","options":["Che réra","Nde réra","Héra"],"answer":3,"why":["Che réra es «mi nombre», y B ya dijo el suyo: Ana. Ahora la pregunta es por la profesora.","Nde réra es «tu nombre», el de quien escucha. Pero A pregunta por la profesora.","A pregunta por la profesora, ella: héra, «su nombre». Héra Rosa: se llama Rosa."],"step":"compare"},"a1u01d3.d1":{"id":"a1u01d3.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(^Carlos se presenta^.) Mba'éichapa. (   ) Carlos. [Ha nde|¿y vos?]?","options":["Nde réra","Héra","Che téra","Che réra"],"answer":4,"why":["Nde réra es «tu nombre». Carlos habla de él mismo, y recién después te pregunta a vos: ha nde?","Héra es el nombre de otra persona, de él o de ella. Carlos habla de sí mismo.","Téra es la palabra sola. Después de che se dice réra: che réra.","Carlos se presenta: che réra, «mi nombre». Después te pregunta a vos: ha nde?"],"step":"drill"},"a1u01d3.d2":{"id":"a1u01d3.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Mirta: Che réra Mirta. ^[Ha nde|¿y vos?]^, mba'éichapa (   ) réra?\nDiego: Che réra Diego.","options":["che","nde","ha'e","ñande"],"answer":2,"why":["Con che, Mirta preguntaría «¿cómo me llamo?». Ya dijo su nombre: ahora pregunta el de Diego.","Ha nde, «¿y vos?»: Mirta pregunta el nombre de Diego, el que escucha. Es nde réra, «tu nombre», y Diego responde con che réra.","Ha'e es «él, ella», y el nombre de él o de ella es héra. Además, Mirta le habla a Diego.","Ñande es «nosotros» con el que escucha incluido. Mirta pregunta el nombre de una sola persona."],"step":"drill"},"a1u01d3.d3":{"id":"a1u01d3.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(^Lucas es de Argentina^.) Mba'éichapa. Che réra Lucas. Che (   ).","options":["Argentina-gua","gua Argentina","Argentina","ha'e Argentina"],"answer":1,"why":["Lugar + -gua dice de dónde sos: Che Argentina-gua, «soy de Argentina». Con un nombre castellano se suele poner guion.","-gua no va adelante como el «de» castellano: va después del lugar, pegado.","Sin -gua, Che Argentina no dice de dónde es Lucas: falta -gua.","Ha'e es «él, ella». Usarlo como «soy» copia el castellano, y en guaraní no hace falta: alcanza con che y el lugar con -gua, Che Argentina-gua."],"step":"drill"},"a1u01d3.d4":{"id":"a1u01d3.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Che Paraguaigua. ^[Ha nde|¿y vos?]?^\nB: (   ) Argentina-gua.","options":["Nde","Ha'e","Che","Ñande"],"answer":3,"why":["Nde Argentina-gua sería «vos sos de Argentina». A pregunta por B, y B responde por sí: che.","Ha'e es «él, ella». B habla de sí.","A pregunta ha nde?, «¿y vos?», y B responde por sí: Che Argentina-gua, «soy de Argentina».","Ñande incluye a A, y A es de Paraguay. B habla solo de sí: che."],"step":"drill"},"a1u01d3.d5":{"id":"a1u01d3.d5","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Che réra Ana. Ha nde,","after":"?","tiles":["mba'éichapa","nde","réra"],"bank":[2,0,1],"hint":"La palabra que pregunta va primero. Después nde, justo antes de réra.","full":"Che réra Ana. Ha nde, mba'éichapa {nde réra}?","es":"Me llamo Ana. Y vos, ¿cómo te llamás?","explain":"Mba'éichapa, «¿cómo?», va primero porque es la palabra que pregunta. Después nde réra, «tu nombre»: nde va antes de réra.","step":"drill"},"a1u01d3.d6":{"id":"a1u01d3.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Mba'éichapa. Che réra Ana. Che ","after":".","tiles":["Paraguái","gua"],"bank":[1,0],"hint":"-gua dice de dónde es alguien. ¿Va antes o después del lugar?","full":"Mba'éichapa. Che réra Ana. Che Paraguai{gua}.","es":"Hola. Me llamo Ana. Soy de Paraguay.","explain":"-gua va después del lugar y pegado, en una sola palabra: Paraguaigua, «de Paraguay». -gua se lleva el acento de la palabra y, como queda al final, no se escribe tilde: Paraguái pierde la suya.","step":"drill"},"a1u01d3.e1":{"id":"a1u01d3.e1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Che réra Pedro. Ha nde, mba'éichapa (   )?\nB: Che réra Lucía.","options":["che réra","nde réra","héra","nde téra"],"answer":2,"explain":"A ya dijo su nombre y ahora pregunta el de B: nde réra, «tu nombre». Che réra sería el nombre de A; héra, el de otra persona; y después de nde no va téra sino réra.","step":"exam"},"a1u01d3.e2":{"id":"a1u01d3.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Mba'éichapa nde réra?\nB: Che réra Marta. Che (   ).","options":["gua Paraguái","Paraguái","Paraguái réra","Paraguaigua"],"answer":4,"explain":"Para decir de dónde es, Marta pega -gua al lugar, sin verbo «ser»: Che Paraguaigua, «soy de Paraguay». Sin -gua, Che Paraguái no lo dice; -gua no va adelante como el «de» castellano; y réra es «nombre», no habla de un lugar.","step":"exam"},"a1u01d3.e3":{"id":"a1u01d3.e3","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"A:","after":"?\nB: Che réra Lucas. Che Argentina-gua.","tiles":["mba'éichapa","nde","réra"],"bank":[1,0,2],"full":"A: Mba'éichapa nde réra?\nB: Che réra Lucas. Che Argentina-gua.","es":"A: ¿Cómo te llamás?\nB: Me llamo Lucas. Soy de Argentina.","explain":"Mba'éichapa va primero: es la palabra que pregunta. Después nde réra, «tu nombre», con nde antes de réra. B responde con che réra.","step":"exam"},"a1u01d3.k1":{"id":"a1u01d3.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Hoy empieza la _clase_ de guaraní.","options":["mbo'epy","mbo'epi","mboepy","mbo'epu"],"answer":1,"explain":"Clase es mbo'epy: con puso entre o y e, y con y al final, la sexta vocal. Mbo'epi y mbo'epu cambian la y por i o u, y mboepy pierde el puso.","step":"words"},"a1u01d3.r1":{"id":"a1u01d3.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué dato de la alumna nueva es correcto?","options":["Es de Paraguay.","Es de Argentina.","Se llama Nilda."],"short":["De Paraguay","De Argentina","Se llama Nilda"],"printed":true,"answer":2,"why":["De Paraguay es la profesora: Che réra Nilda. Che Paraguaigua. De la alumna dice: Ha'e Argentina-gua.","La profesora dice de la alumna nueva: Ha'e Argentina-gua, «es de Argentina».","Nilda es la profesora: che réra Nilda. La alumna nueva se llama Sofía: héra Sofía."],"script":["Narrador: Primer día de clase de guaraní. La profesora habla de ella y de una alumna nueva.","Narrador: ¿Qué dato de la alumna nueva es correcto?","Mujer: Mba'éichapa. Che réra Nilda.","Mujer: Che Paraguaigua.","Mujer: Temimbo'e pyahu héra Sofía.","Mujer: Ha'e Argentina-gua.","Narrador: ¿Qué dato de la alumna nueva es correcto?"],"step":"skill"},"a1u01d4.c1":{"id":"a1u01d4.c1","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: ^Moõpa^ reñe'ẽ guaraníme?\nB: (   )","options":["Héẽ, añe'ẽ.","Nahániri.","Che rógape."],"answer":3,"why":["Héẽ contesta preguntas de sí o no. Moõpa pide un lugar.","Nahániri también es para sí o no, y acá te preguntan dónde.","Moõpa pregunta «¿dónde?», y che rógape (en mi casa) es un lugar."],"step":"compare"},"a1u01d4.d1":{"id":"a1u01d4.d1","kind":"choice","area":"grammar","label":"Elegí la pregunta","q":"A: (   ) guaraníme?\nB: ^Héẽ^, [michĩmi|un poquito].","options":["Mba'épa reñe'ẽ","Reñe'ẽpa","Moõpa reñe'ẽ","Mávapa oñe'ẽ"],"answer":2,"why":["Mba'épa pregunta qué hablás. A un «¿qué?» no se contesta héẽ.","B contesta héẽ, sí: es una pregunta de sí o no, con -pa en el verbo. Reñe'ẽpa guaraníme? ¿Hablás guaraní?","Moõpa pregunta dónde. La respuesta sería un lugar, no héẽ.","Mávapa pregunta quién habla guaraní. Héẽ no dice quién."],"step":"drill"},"a1u01d4.d2":{"id":"a1u01d4.d2","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: Reikuaápa che réra?\nB: (   ). ^Nde réra Juan^.","options":["Héẽ","Nahániri","Iporã","Jajotopáta"],"answer":1,"why":["Héẽ es «sí». B sabe el nombre y lo dice: nde réra Juan.","Nahániri es «no», pero B dice el nombre: sí lo sabe.","Iporã, «bien», contesta mba'éichapa. Acá te preguntan sí o no.","Jajotopáta, «nos vemos», es para despedirse. No contesta la pregunta."],"step":"drill"},"a1u01d4.d3":{"id":"a1u01d4.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: (   ) [ovale|cuesta] [ko|este] [kesu|queso]?\nB: ^Diez mil^.","options":["Mba'éichapa","Mávapa","Moõpa","Mboýpa"],"answer":4,"why":["Mba'éichapa pregunta cómo. B no dice cómo: dice un precio.","Mávapa pregunta quién. Diez mil no es una persona.","Moõpa pregunta dónde. Diez mil no es un lugar.","B dice un precio, diez mil: la pregunta es Mboýpa, ¿cuánto? Los precios se suelen decir en castellano, también cuando se habla guaraní."],"step":"drill"},"a1u01d4.d4":{"id":"a1u01d4.d4","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: ^Mávapa^ ha'e?\nB: (   )","options":["Héẽ.","Iporã.","Che sy.","Nahániri."],"answer":3,"why":["Héẽ contesta preguntas de sí o no. Mávapa pregunta quién.","Iporã, «bien», contesta mba'éichapa. No dice quién es.","Mávapa pregunta «¿quién?»: che sy, mi mamá, es una persona.","Nahániri contesta sí o no. Mávapa pide una persona."],"step":"drill"},"a1u01d4.d5":{"id":"a1u01d4.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Ana, ","after":" che réra?","tiles":["rei","kuaa","pa"],"bank":[2,0,1],"hint":"-pa, la marca de pregunta, va al final, y rei- es «vos». Después fijate dónde queda el acento.","full":"Ana, reikuaá{pa} che réra?","es":"Ana, ¿sabés mi nombre?","explain":"rei- (vos) va adelante, kuaa (saber) en el medio y -pa al final: reikuaápa. Con verbos como kuaa, «vos» es rei- y no re-. Como la -pa de pregunta no se lleva el acento, este queda en la última a de kuaa, y se escribe porque ya no es la última vocal.","step":"drill"},"a1u01d4.d6":{"id":"a1u01d4.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" ovale ko kesu?","tiles":["mboy","pa"],"bank":[1,0],"hint":"¿Dónde va -pa en mba'épa? Acá va igual. Después fijate dónde queda el acento.","full":"{Mboýpa} ovale ko kesu?","es":"¿Cuánto cuesta este queso?","explain":"mboy (cuánto) va primero y -pa al final: mboýpa. La -pa de pregunta no se lleva el acento: este queda en la y de mboy. Como esa y ya no es la última vocal, se escribe con tilde: ý.","step":"drill"},"a1u01d4.e1":{"id":"a1u01d4.e1","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: Ndépa Rosa?\nB: (   ), che Rosa.","options":["Nahániri","Héẽ","Iporã","Mávapa"],"answer":2,"explain":"B dice che Rosa, «soy Rosa»: es quien A pensaba, así que contesta héẽ, «sí». Nahániri diría que no es Rosa. Iporã, «bien», contesta mba'éichapa, y mávapa es una pregunta, no una respuesta.","step":"exam"},"a1u01d4.e2":{"id":"a1u01d4.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: (   ) reipota?\nB: Chipa.","options":["Mboýpa","Moõpa","Mávapa","Mba'épa"],"answer":4,"explain":"B contesta con una cosa, chipa: la pregunta es Mba'épa reipota?, ¿qué querés? Mboýpa pregunta cuánto, moõpa dónde y mávapa quién.","step":"exam"},"a1u01d4.e3":{"id":"a1u01d4.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Rosa, ","after":" guaraníme?","tiles":["re","ñe'ẽ","pa"],"bank":[1,2,0],"full":"Rosa, reñe'ẽ{pa} guaraníme?","es":"Rosa, ¿hablás guaraní?","explain":"re (vos) + ñe'ẽ (hablar) + pa (pregunta) = reñe'ẽpa. El acento sigue en la ẽ, y la tilde nasal (~) ya lo marca: no se escribe otro acento.","step":"exam"},"a1u01d4.k1":{"id":"a1u01d4.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"¿Cómo se escribe _mandioca_ en guaraní?","options":["mandio","mandi'o","mand'io","mandi'õ"],"answer":2,"explain":"Mandi'o lleva puso entre la i y la o: ma-ndi-'o. En mandio falta el corte de la voz. En mand'io el puso queda después de una consonante, y el puso va siempre entre dos vocales. Mandi'õ agrega una tilde nasal (~) que la palabra no lleva.","step":"words"},"a1u01d4.r1":{"id":"a1u01d4.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué hay en el puesto?","options":["Chipá y queso","Queso y mandioca","Chipá y mandioca"],"answer":2,"why":["Chipá no hay: ella pregunta oĩpa chipa? y él contesta nahániri.","Él dice oĩ kesu ha mandi'o: hay queso y mandioca.","Mandioca hay, pero chipá no: el vendedor contesta nahániri."],"script":["Narrador: En un puesto del mercado. ¿Qué hay en el puesto?","Hombre: Mba'éichapa. Mba'épa reipota?","Mujer: Iporã. Oĩpa chipa?","Hombre: Nahániri. Oĩ kesu ha mandi'o.","Mujer: Mboýpa ovale ko kesu?","Hombre: Diez mil.","Narrador: ¿Qué hay en el puesto?"],"step":"skill"},"a1u01d5.c1":{"id":"a1u01d5.c1","kind":"choice","area":"grammar","label":"Elegí la fórmula","q":"(Doña Ramona ^le regala un chipá^ a Lucía.)\nLucía: (   )","options":["Aguyje.","Cheñyrõmi.","Ikatúpa aike?"],"answer":1,"why":["Doña Ramona le hace un regalo a Lucía: Lucía da las gracias con Aguyje.","Cheñyrõmi pide perdón, y no pasó nada malo: doña Ramona le hace un regalo.","Ikatúpa aike? pide permiso para entrar. Acá doña Ramona le da algo, y Lucía le contesta."],"step":"compare"},"a1u01d5.d1":{"id":"a1u01d5.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Lucía: Aguyjevete (   ), ^Ana ha Luis^.","options":["ndéve","peẽme","chéve","nde"],"answer":2,"why":["Ndéve es «a vos», para una sola persona. Lucía les habla a dos: Ana y Luis.","Lucía les da las gracias a dos personas, Ana y Luis. «A ustedes» es peẽme.","Chéve es «a mí». Lucía no se da las gracias a sí misma.","Nde es «vos». Para decir «a vos» hace falta ndéve, y además acá son dos personas."],"step":"drill"},"a1u01d5.d2":{"id":"a1u01d5.d2","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"Ramona: [Reipotápa|¿querés?] terere?\nLucía: ^[Nahániri|no]^, (   ).","options":["tereg̃uahẽ porãite","mba'éichapa","aguyje","ikatúpa aike"],"answer":3,"why":["Tereg̃uahẽ porãite da la bienvenida a quien llega. No contesta a «¿querés tereré?».","Mba'éichapa? pregunta cómo está alguien. Acá Lucía contesta, no pregunta.","Lucía no quiere tereré y lo dice con cortesía: Nahániri, aguyje («No, gracias»).","Ikatúpa aike? pide permiso para entrar. Ramona le ofrece tereré, y Lucía tiene que contestar."],"step":"drill"},"a1u01d5.d3":{"id":"a1u01d5.d3","kind":"choice","area":"grammar","label":"Elegí la frase","q":"Lucía: (   )\nRamona: ^[Eike|pasá]^, Lucía. Tereg̃uahẽ porãite.","options":["Ikatúpa aike?","Jajotopáta.","Tereg̃uahẽ porãite.","Iporã, ha nde?"],"answer":1,"why":["Ramona le contesta Eike, «pasá». Entonces Lucía pidió permiso para entrar: Ikatúpa aike?","Jajotopáta es para despedirse, y Lucía recién llega: Ramona le dice «pasá».","Tereg̃uahẽ porãite lo dice quien recibe, y la que recibe es Ramona. Lucía es la que llega.","Iporã, ha nde? contesta a Mba'éichapa?, y nadie le preguntó a Lucía cómo está."],"step":"drill"},"a1u01d5.d4":{"id":"a1u01d5.d4","kind":"choice","area":"grammar","label":"Elegí la fórmula","q":"(Ana y Luis llegan a la casa de doña Ramona.)\nRamona: (   ), ^Ana ha Luis^.","options":["Ikatúpa aike","Jajotopáta","Tereg̃uahẽ porãite","Tapeg̃uahẽ porãite"],"answer":4,"why":["Ikatúpa aike pide permiso para entrar. Ramona está en su casa: ella es la que recibe.","Jajotopáta es para despedirse, y Ana y Luis recién llegan.","Tereg̃uahẽ porãite es para una sola persona, y Ramona recibe a dos: Ana y Luis.","Ramona recibe a dos personas, Ana y Luis. A varias se les dice Tapeg̃uahẽ porãite."],"step":"drill"},"a1u01d5.d5":{"id":"a1u01d5.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis le abre la puerta a Ana.)\nAna: Aguyje ","after":", Luis.","tiles":["nde","ve"],"bank":[1,0],"hint":"Ana le da las gracias a una sola persona, Luis: «a vos». Fijate después dónde queda el acento.","full":"(Luis le abre la puerta a Ana.)\nAna: Aguyje {ndéve}, Luis.","es":"Ana: Gracias a vos, Luis.","explain":"nde, ve. Nde es «vos» y -ve, «a»: ndéve es «a vos». -ve no se lleva el acento: queda en la e de nde. Como esa e ya no es la última vocal, se escribe: ndéve.","step":"drill"},"a1u01d5.d6":{"id":"a1u01d5.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Lucía: ","after":", ña Ramona.","tiles":["che","ñyrõ","mi"],"bank":[1,2,0],"hint":"Como en Jajotopáta, la persona va adelante. Lo que suaviza el pedido va al final.","full":"Lucía: {Cheñyrõmi}, ña Ramona.","es":"Lucía: Perdón, doña Ramona.","explain":"che, ñyrõ, mi. Acá che- es «me», ñyrõ es «perdonar» y -mi lo hace más suave. Van juntos, en una sola palabra: Cheñyrõmi, «perdoname».","step":"drill"},"a1u01d5.e1":{"id":"a1u01d5.e1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le da un chipá a Luis.)\nLuis: Aguyje (   ), Ana.","options":["peẽme","chéve","ndéve","nde"],"answer":3,"explain":"Luis le da las gracias a una sola persona, Ana: «a vos» es ndéve. Peẽme es «a ustedes», para varias personas; chéve es «a mí»; y nde solo, sin -ve, no quiere decir «a vos».","step":"exam"},"a1u01d5.e2":{"id":"a1u01d5.e2","kind":"choice","area":"grammar","label":"Elegí la fórmula","q":"(Lucía vuelca sin querer el tereré de doña Ramona.)\nLucía: (   ), ña Ramona.","options":["Aguyje","Tereg̃uahẽ porãite","Jajotopáta","Cheñyrõmi"],"answer":4,"explain":"Lucía volcó el tereré sin querer: pide perdón con Cheñyrõmi. Aguyje da las gracias, Tereg̃uahẽ porãite da la bienvenida y Jajotopáta es para despedirse. Ninguna de esas tres pide perdón.","step":"exam"},"a1u01d5.e3":{"id":"a1u01d5.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Lucía llega a la casa de doña Ramona.)\nLucía: ","after":" aike, ña Ramona?","tiles":["ikatu","pa"],"bank":[1,0],"full":"(Lucía llega a la casa de doña Ramona.)\nLucía: {Ikatúpa} aike, ña Ramona?","es":"Lucía: ¿Puedo pasar, doña Ramona?","explain":"ikatu, pa. -pa va al final y no se lleva el acento: queda en la u de ikatu. Como esa u ya no es la última vocal, se escribe: Ikatúpa.","step":"exam"},"a1u01d5.k1":{"id":"a1u01d5.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Doña Ramona recibe a Lucía en la puerta: «_Bienvenida_».","options":["Tereg̃uahe poraite","Tereg̃uahẽ porãite","Tereg̃uahẽ poraite","Tereg̃uahe porãite"],"answer":2,"explain":"Se escribe con tres tildes nasales (~): la de g̃, la de ẽ y la de ã. Las otras opciones pierden la ~ de ẽ, la de ã o las dos. La ~ de la g a veces no se escribe (Tereguahẽ), pero la de ẽ y la de ã no pueden faltar.","step":"words"},"a1u01d5.r1":{"id":"a1u01d5.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué hace Lucía en su mensaje?","options":["Pide perdón y se despide.","Da la bienvenida y pregunta cómo están.","Da las gracias y se despide."],"short":["Pide perdón","Da la bienvenida","Da las gracias"],"answer":3,"why":["Se despide, sí (Jajotopáta), pero no pide perdón: no escribe Cheñyrõmi.","No escribe Tereg̃uahẽ porãite (bienvenida) ni Mba'éichapa? (¿cómo están?).","Aguyjevete peẽme es «muchas gracias a ustedes», y Jajotopáta, «nos vemos»."],"explain":"Lucía les escribe Aguyjevete peẽme («muchas gracias a ustedes») a doña Ramona y a Ana, y se despide con Jajotopáta («nos vemos»). No pide perdón (Cheñyrõmi), no da la bienvenida (Tereg̃uahẽ porãite) ni pregunta cómo están (Mba'éichapa?).","step":"skill"},"a1u01d6.c1":{"id":"a1u01d6.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana: ^Reñe'ẽpa^ guaraníme?\nLuis: ^Héẽ^, (   ) guaraníme.","options":["reñe'ẽpa","añe'ẽ","oñe'ẽ"],"answer":2,"why":["Reñe'ẽpa es la pregunta de Ana, con -pa. Luis ya responde y afirma: sin -pa.","Luis responde que sí y habla de él: añe'ẽ, «hablo». No lleva -pa porque afirma.","Oñe'ẽ es la forma de ha'e, otra persona. Ana le pregunta a Luis con re- («vos»): él responde por él mismo, añe'ẽ."],"step":"compare"},"a1u01d6.d1":{"id":"a1u01d6.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis cuenta de dónde son ^sus abuelos^: «(   ) Paraguaigua.»","options":["Ha'e","Ore","Peẽ","Ha'ekuéra"],"answer":4,"why":["Ha'e es una sola persona, «él» o «ella». Los abuelos son más de uno.","Ore es «nosotros» y sumaría a Luis, pero él cuenta de dónde son sus abuelos.","Peẽ es «ustedes», para hablarles a ellos. Luis cuenta de dónde son sus abuelos, no les habla a ellos.","Luis habla de varias personas, sus abuelos: ha'ekuéra, «ellos». Ha'ekuéra Paraguaigua: son de Paraguay."],"step":"drill"},"a1u01d6.d2":{"id":"a1u01d6.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana le habla a la profesora. Para decir «nosotros: ^Luis y yo^», Ana dice (   ).","options":["ore","ñande","peẽ","ha'ekuéra"],"answer":1,"why":["La profesora escucha y no está en el grupo: son Luis y Ana. Ese «nosotros» es ore.","Ñande incluye al que escucha: sumaría a la profesora.","Peẽ es «ustedes». Ana habla de ella misma y de Luis.","Ha'ekuéra es «ellos» o «ellas». Ana se incluye: dice «nosotros»."],"step":"drill"},"a1u01d6.d3":{"id":"a1u01d6.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Mba'éichapa? Che réra Rosa. ^[Ha nde|¿y vos?]^?\nLuis: Iporã. (   ) Luis.","options":["Nde réra","Héra","Che réra","Ha nde"],"answer":3,"why":["Nde réra es «tu nombre», el de Rosa. Luis dice el suyo.","Héra es el nombre de otra persona, de él o de ella. Luis habla de él mismo.","Rosa pregunta ha nde?, «¿y vos?». Luis dice su nombre: che réra, «mi nombre».","Ha nde es «¿y vos?»: devuelve una pregunta, no dice un nombre."],"step":"drill"},"a1u01d6.d4":{"id":"a1u01d6.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Ikatúpa aike, ña Ramona?\nRamona: (   ), Rosa. ^[Eike|pasá]^.","options":["Nahániri","Héẽ","Jajotopáta","Ha nde"],"answer":2,"why":["Nahániri es «no», pero Ramona le dice Eike, «pasá»: la deja pasar.","Rosa pide permiso para entrar, y Ramona le dice Eike, «pasá»: la respuesta es sí, Héẽ.","Jajotopáta es para despedirse, y Rosa recién llega.","Ha nde es «¿y vos?». Ikatúpa aike? pide un sí o un no."],"step":"drill"},"a1u01d6.d5":{"id":"a1u01d6.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Nde sy ","after":" guaraníme?","tiles":["o","ñe'ẽ","pa"],"bank":[2,0,1],"hint":"Nde sy, «tu mamá», es otra persona, como ha'e: el verbo empieza con o-. -pa va al final.","full":"Nde sy {o}ñe'ẽ{pa} guaraníme?","es":"¿Tu mamá habla guaraní?","explain":"Nde sy, «tu mamá», es otra persona: o- + ñe'ẽ = oñe'ẽ, «habla». -pa va al final y hace la pregunta: oñe'ẽpa. El acento sigue en la ẽ, y la tilde nasal ya lo marca.","step":"drill"},"a1u01d6.d6":{"id":"a1u01d6.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"(Son las nueve de la mañana.)\nRosa:","after":", Juan?","tiles":["mba'éichapa","nde","pyhareve"],"bank":[1,2,0],"hint":"Empezá por la palabra que pregunta. Nde va antes de pyhareve, como en nde réra.","full":"(Son las nueve de la mañana.)\nRosa: {Mba'éichapa} nde pyhareve, Juan?","es":"(Son las nueve de la mañana.)\nRosa: Buen día, Juan.","explain":"Mba'éichapa va primero: es la palabra que pregunta. Después viene nde pyhareve, «tu mañana», con nde antes de pyhareve, como en nde réra. Es el saludo de la mañana: «buen día».","step":"drill"},"a1u01d6.e1":{"id":"a1u01d6.e1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana le habla a Luis. Para decir «nosotros: vos y yo», Ana dice (   ).","options":["ore","peẽ","ñande","ha'ekuéra"],"answer":3,"explain":"Luis es el que escucha, y Ana lo incluye: «vos y yo» es ñande. Ore dejaría afuera a Luis, peẽ es «ustedes» y ha'ekuéra, «ellos».","step":"exam"},"a1u01d6.e2":{"id":"a1u01d6.e2","kind":"choice","area":"grammar","label":"Elegí la frase","q":"(Lucía se va de la casa de doña Ramona.)\nLucía: Aguyjevete, ña Ramona. (   )","options":["Tereg̃uahẽ porãite.","Ikatúpa aike?","Mba'éichapa?","Jajotopáta."],"answer":4,"explain":"Lucía se va: después de dar las gracias, se despide con Jajotopáta, «nos vemos». Tereg̃uahẽ porãite es para recibir a quien llega, Ikatúpa aike? pide permiso para entrar y Mba'éichapa? saluda al llegar.","step":"exam"},"a1u01d6.e3":{"id":"a1u01d6.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" nde réra?","tiles":["mba'e","icha","pa"],"bank":[2,0,1],"full":"Mba'éicha{pa} nde réra?","es":"¿Cómo te llamás?","explain":"mba'e («qué») + -icha («como») + -pa (pregunta). Ni -icha ni -pa se llevan el acento: queda en la e de mba'e, que ya no es la última vocal, y se escribe: Mba'éichapa.","step":"exam"},"a1u01d6.k1":{"id":"a1u01d6.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa pregunta: Ikatúpa aike? Ana le contesta que _sí_. ¿Cómo se escribe en guaraní?","options":["He'ẽ","Hee","Héẽ","Jeẽ"],"answer":3,"explain":"Sí es Héẽ: con h, con la ẽ nasal y sin puso. He'ẽ, con puso, es «dulce». Hee no tiene ninguna marca: le falta la tilde nasal (~) de la ẽ. Jeẽ cambia la h por j.","step":"words"},"a1u01d6.r1":{"id":"a1u01d6.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué le pide Ana a Luis?","options":["Que le diga su nombre.","Que la deje pasar.","Que se vean otro día.","Que la perdone."],"short":["Su nombre","Pasar","Verse otro día","Perdón"],"answer":2,"why":["Ana no pregunta el nombre: ya lo sabe y le escribe «Luis». Para eso diría Mba'éichapa nde réra?","Ana pregunta Ikatúpa aike?, «¿puedo pasar?», y Luis le contesta Héẽ, «sí».","Ana no habla de otro día: recién llega y pide pasar. Jajotopáta, «nos vemos», es para irse.","Para pedir perdón, Ana escribiría Cheñyrõmi, y no lo escribe."],"explain":"Ana pregunta Ikatúpa aike?, «¿puedo pasar?». Luis responde Héẽ, «sí», y le da la bienvenida con Tereg̃uahẽ porãite. Ana le pide que la deje pasar.","step":"skill"},"a1u01t.1":{"id":"a1u01t.1","kind":"choice","area":"vocab","label":"Qué significa","q":"Rosa le escribe a Juan: «_Maitei_, Juan.» ¿Qué le dice?","options":["Perdón, Juan.","Hola, Juan.","Nos vemos, Juan.","Gracias, Juan."],"answer":2,"explain":"Maitei es un saludo cordial: «hola», «saludos». Perdón es Cheñyrõmi, nos vemos es Jajotopáta y gracias es Aguyje.","step":"test","unit":1},"a1u01t.2":{"id":"a1u01t.2","kind":"choice","area":"vocab","label":"Qué significa","q":"Rosa: _Mba'éichapa nde ka'aru_, karai Juan?","options":["Buen día, don Juan.","Nos vemos esta tarde, don Juan.","Buenas tardes, don Juan.","Bienvenido, don Juan."],"answer":3,"explain":"Mba'éichapa nde ka'aru? es el saludo de la tarde: «buenas tardes». Ka'aru es «la tarde», y karai, «señor»: karai Juan es «don Juan». Buen día sería Mba'éichapa nde pyhareve?, nos vemos esta tarde es Jajotopáta ko ka'aru y bienvenido es Tereg̃uahẽ porãite.","step":"test","unit":1},"a1u01t.3":{"id":"a1u01t.3","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Una amiga te presta un libro. Le decís: «_Gracias_.» ¿Cómo se escribe en guaraní?","options":["Aguije","Ahuyje","Aguyjẽ","Aguyje"],"answer":4,"explain":"Gracias es Aguyje, con y, la sexta vocal. Aguije la cambia por i, Ahuyje cambia la g por h y Aguyjẽ agrega una tilde nasal que la palabra no lleva.","step":"test","unit":1},"a1u01t.4":{"id":"a1u01t.4","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Llegás tarde a la clase. Le decís a la profesora: «_Perdón_.» ¿Cómo se escribe en guaraní?","options":["Cheñyrõmi","Cheñyromi","Chenyrõmi","Cheñirõmi"],"answer":1,"explain":"Perdón es Cheñyrõmi: lleva ñ, la vocal y y la o nasal õ. Cheñyromi no tiene la tilde nasal, Chenyrõmi cambia la ñ por n y Cheñirõmi cambia la y por i.","step":"test","unit":1},"a1u01t.5":{"id":"a1u01t.5","kind":"choice","area":"vocab","label":"Elegí la palabra","q":"(Ana te muestra una foto de su mamá.)\nAna: Che (   ).","options":["ru","angirũ","jarýi","sy"],"answer":4,"explain":"En la foto está la mamá de Ana: che sy, «mi mamá». Che ru es «mi papá», che angirũ, «mi amigo» o «mi amiga», y che jarýi, «mi abuela».","step":"test","unit":1},"a1u01t.6":{"id":"a1u01t.6","kind":"choice","area":"vocab","label":"Qué significa","q":"Rosa le pregunta a Juan: «_Moõpa reiko?_»","options":["¿Cómo andás?","¿Qué querés?","¿Dónde vivís?","¿Cuánto cuesta?"],"answer":3,"explain":"Moõpa es «¿dónde?», y reiko, «vivís»: «¿dónde vivís?». ¿Cómo andás? es Mba'éichapa reiko?, ¿qué querés? es Mba'épa reipota? y ¿cuánto cuesta? es Mboýpa ovale?","step":"test","unit":1},"a1u01t.7":{"id":"a1u01t.7","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana y Luis son de Paraguay. Se lo cuentan a Lucas, un chico de Argentina.)\nAna: (   ) Paraguaigua.","options":["Ñande","Ore","Peẽ","Ha'ekuéra"],"answer":2,"explain":"Ana habla de ella y de Luis, y Lucas, el que escucha, no está en el grupo: Ore Paraguaigua, «somos de Paraguay». Ñande incluiría a Lucas, que es de Argentina; peẽ es «ustedes» y ha'ekuéra, «ellos».","step":"test","unit":1},"a1u01t.8":{"id":"a1u01t.8","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa le dice a Juan: «Jajotopáta.» ¿Quiénes se van a ver?","options":["Rosa y otra persona, sin Juan","Juan y otra persona","Rosa y Juan","Otras personas"],"answer":3,"explain":"Jajotopáta empieza con ja-, el «nosotros» de ñande, que incluye al que escucha. Rosa se lo dice a Juan, así que los que se van a ver son Rosa y Juan. Sin Juan sería un «nosotros» como ore.","step":"test","unit":1},"a1u01t.9":{"id":"a1u01t.9","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: Mávapa ha'e?\nB: Che angirũ. (   ) Rosa.","options":["Che réra","Nde réra","Héẽ","Héra"],"answer":4,"explain":"A pregunta quién es (Mávapa ha'e?), y B habla de otra persona, su amiga: el nombre de ella es héra. Héra Rosa: se llama Rosa. Che réra sería el nombre de B, nde réra el de A, y héẽ es «sí».","step":"test","unit":1},"a1u01t.10":{"id":"a1u01t.10","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis y Marta le sirven tereré a Ana.)\nAna: Aguyjevete (   ).","options":["peẽme","ndéve","chéve","nde"],"answer":1,"explain":"Ana les da las gracias a dos personas, Luis y Marta: «a ustedes» es peẽme. Ndéve es «a vos», para una sola persona; chéve es «a mí», y nde solo, sin -ve, no quiere decir «a vos».","step":"test","unit":1},"a1u01t.11":{"id":"a1u01t.11","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"A: Nde ru oñe'ẽpa guaraníme?\nB: (   ), oñe'ẽ guaraníme.","options":["Nahániri","Mávapa","Héẽ","Jajotopáta"],"answer":3,"explain":"B dice que su papá habla guaraní (oñe'ẽ guaraníme), así que responde que sí: Héẽ. Nahániri es «no», Mávapa pregunta «¿quién?» y Jajotopáta es para despedirse.","step":"test","unit":1},"a1u01t.12":{"id":"a1u01t.12","kind":"choice","area":"grammar","label":"Elegí la forma","q":"A: (   ) ovale ko so'o?\nB: Treinta mil.","options":["Mboýpa","Mba'épa","Moõpa","Mávapa"],"answer":1,"explain":"B responde con un precio, treinta mil: la pregunta es Mboýpa ovale?, «¿cuánto cuesta?». Mba'épa pregunta qué, moõpa dónde y mávapa quién.","step":"test","unit":1},"a1u01t.13":{"id":"a1u01t.13","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Rosa les habla a Juan y a Lucas.)\nRosa: ","after":" guaraníme?","tiles":["pe","ñe'ẽ","pa"],"bank":[2,0,1],"full":"(Rosa les habla a Juan y a Lucas.)\nRosa: {Pe}ñe'ẽ{pa} guaraníme?","es":"(Rosa les habla a Juan y a Lucas.)\nRosa: ¿Ustedes hablan guaraní?","explain":"pe, ñe'ẽ, pa. Rosa les habla a dos personas, Juan y Lucas, así que el verbo lleva pe-, el de peẽ («ustedes»): pe- + ñe'ẽ = peñe'ẽ, «hablan». -pa va al final y hace la pregunta: peñe'ẽpa. El acento sigue en la ẽ, y la tilde nasal ya lo marca.","step":"test","unit":1},"a1u01t.14":{"id":"a1u01t.14","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Luis: Mba'éichapa, Ana?\nAna:","after":"?","tiles":["iporã","ha","nde"],"bank":[2,0,1],"full":"Luis: Mba'éichapa, Ana?\nAna: {Iporã}, ha nde?","es":"Luis: Hola, Ana, ¿cómo estás?\nAna: Bien, ¿y vos?","explain":"Iporã, ha, nde. Ana primero responde cómo está: iporã, «bien». Después le devuelve la pregunta a Luis con ha nde, «¿y vos?»: ha, «y», va antes de nde.","step":"test","unit":1},"a1u01t.15":{"id":"a1u01t.15","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿En qué momento del día llega Lucas?","passage":"Mbo'ehára: Mba'éichapa nde pyhareve?\nLucas: Iporã. Ikatúpa aike?\nMbo'ehára: Tereg̃uahẽ porãite. Mba'éichapa nde réra?\nLucas: Che réra Lucas.\nMbo'ehára: Che réra Nilda.","options":["A la mañana.","A la tarde.","A la noche.","No se sabe."],"short":["Mañana","Tarde","Noche","No se sabe"],"answer":1,"explain":"La profesora saluda con Mba'éichapa nde pyhareve?, el saludo de la mañana: pyhareve es «la mañana». La tarde sería ka'aru y la noche, pyhare.","step":"test","unit":1},"a1u01t.16":{"id":"a1u01t.16","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué le pregunta Lucas a la profesora?","passage":"Mbo'ehára: Mba'éichapa nde pyhareve?\nLucas: Iporã. Ikatúpa aike?\nMbo'ehára: Tereg̃uahẽ porãite. Mba'éichapa nde réra?\nLucas: Che réra Lucas.\nMbo'ehára: Che réra Nilda.","options":["Cómo se llama.","Si puede pasar.","Dónde vive.","Si habla guaraní."],"short":["Su nombre","Pasar","Dónde vive","Si habla guaraní"],"answer":2,"explain":"Lucas pregunta Ikatúpa aike?, «¿puedo pasar?», y la profesora le da la bienvenida. El nombre no lo pregunta Lucas: la profesora se lo pregunta a él y después dice el suyo. Lucas no pregunta dónde vive ella ni si habla guaraní.","step":"test","unit":1},"a1u01t.17":{"id":"a1u01t.17","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Cómo se llama la profesora?","passage":"Mbo'ehára: Mba'éichapa nde pyhareve?\nLucas: Iporã. Ikatúpa aike?\nMbo'ehára: Tereg̃uahẽ porãite. Mba'éichapa nde réra?\nLucas: Che réra Lucas.\nMbo'ehára: Che réra Nilda.","options":["Lucas.","Rosa.","No lo dice.","Nilda."],"short":["Lucas","Rosa","No lo dice","Nilda"],"answer":4,"explain":"Al final la profesora dice Che réra Nilda, «me llamo Nilda». Lucas es el alumno que llega, y en el diálogo no hay ninguna Rosa.","step":"test","unit":1},"a1u01t.18":{"id":"a1u01t.18","kind":"choice","area":"listening","label":"Respuesta rápida","q":"Rosa: Jajotopáta, Juan.\n¿Qué le responde Juan?","options":["Mba'éichapa, Rosa?","Tereg̃uahẽ porãite, Rosa.","Jajotopáta, Rosa."],"answer":3,"explain":"Rosa se despide, y Juan le responde con otra despedida: Jajotopáta, «nos vemos». Mba'éichapa? es para saludar al llegar y Tereg̃uahẽ porãite, para recibir a quien llega.","step":"test","unit":1},"a1u01t.19":{"id":"a1u01t.19","kind":"choice","area":"listening","label":"Respuesta rápida","q":"(En el mercado, una mujer llega a un puesto.)\nVendedor: Mba'épa reipota?\n¿Qué le responde la mujer?","options":["Chipa.","Héẽ.","Che réra Ana."],"answer":1,"explain":"Mba'épa reipota? pregunta «¿qué querés?», y se responde con una cosa: chipa. Héẽ responde preguntas de sí o no, y Che réra Ana dice un nombre.","step":"test","unit":1},"a1u01t.20":{"id":"a1u01t.20","kind":"choice","area":"listening","label":"Respuesta rápida","q":"(En el mercado.)\nMujer: Oĩpa mandi'o?\n¿Qué le responde el vendedor?","options":["Che réra Rosa.","Nahániri. Oĩ kesu.","Tereg̃uahẽ porãite."],"answer":2,"explain":"La mujer pregunta si hay mandioca: es una pregunta de sí o no. El vendedor responde Nahániri, «no», y dice lo que sí hay: Oĩ kesu, «hay queso». Che réra Rosa dice un nombre y Tereg̃uahẽ porãite da la bienvenida.","step":"test","unit":1},"a1u02d1.c1":{"id":"a1u02d1.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Mávapa ^ou^ ko pyhare?\nAna: (   ) che ru.","options":["Aju","Reju","Ou"],"answer":3,"why":["Aju es «vengo», con a-: Ana hablaría de ella misma, y habla de su papá.","Reju es «venís», con re-: la que viene sería Rosa, y Ana habla de su papá.","Ana habla de su papá, otra persona: ou, «viene». Ou che ru es «viene mi papá»."],"step":"compare"},"a1u02d1.d1":{"id":"a1u02d1.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la fiesta, Rosa cuenta qué hace esta noche.)\nRosa: ^Che^ (   ) ko pyhare.","options":["apurahéi","repurahéi","opurahéi","purahéi"],"answer":1,"why":["Che es «yo», y el verbo lo repite al principio: a- + purahéi = apurahéi, «canto».","repurahéi es «cantás», con re-, «vos». Rosa habla de ella misma, no de vos.","opurahéi es «canta», con o-: sería otra persona, él o ella.","purahéi sin prefijo es «canción», la cosa: che purahéi sería «mi canción». Le falta la persona: a-."],"step":"drill"},"a1u02d1.d2":{"id":"a1u02d1.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana: (   ) ^remba'apo^ [heta|mucho], Luis.","options":["Che","Nde","Ha'e","Mávapa"],"answer":2,"why":["Che es «yo» y va con a-: che amba'apo. Acá el verbo lleva re-.","re- es «vos»: nde remba'apo, «vos trabajás». Ana le habla a Luis.","Ha'e es «él» o «ella» y va con o-: ha'e omba'apo.","Mávapa, «¿quién?», pregunta por otra persona y va con o-: Mávapa omba'apo? Con re- no cuadra."],"step":"drill"},"a1u02d1.d3":{"id":"a1u02d1.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: Ana, ^rehópa^ ko ka'aru?\nAna: Héẽ, (   ) ko ka'aru.","options":["aha","aho","reho","oho"],"answer":1,"why":["Luis pregunta con re-, «vos», y Ana responde por ella misma, con a-. Con a-, la raíz de «ir» es ha: aha, «voy».","aho no existe: ho es la raíz de «ir» con re- y con o-, nunca con a-.","reho es «vas», con re-: es lo que pregunta Luis. Ana responde por ella misma.","oho es «va», con o-: sería otra persona, no Ana."],"step":"drill"},"a1u02d1.d4":{"id":"a1u02d1.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: ^Che ru^ (   ) ko ka'aru, ha che sy ou ko pyhare.","options":["aha","oha","reho","oho"],"answer":4,"why":["aha es «voy», con a-: Rosa hablaría de ella misma, y habla de su papá.","oha no existe: con o-, la raíz de «ir» es ho. Con a- es ha: aha.","reho es «vas», con re-: Rosa le hablaría a vos. Ella habla de su papá, otra persona.","Che ru, «mi papá», es otra persona: o- + ho = oho, «va». Mi papá va esta tarde, y mi mamá viene esta noche."],"step":"drill"},"a1u02d1.d5":{"id":"a1u02d1.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Luis, ","after":" ko pyhare?","tiles":["re","ju","pa"],"bank":[2,0,1],"hint":"re- es «vos» y va primero; -pa cierra la pregunta. Después fijate dónde queda el acento.","full":"Luis, {re}jú{pa} ko pyhare?","es":"Luis, ¿venís esta noche?","explain":"re- (vos) + ju (venir) + -pa (pregunta) = rejúpa, «¿venís?». La -pa no se lleva el acento: queda en la u de ju, que ya no es la última vocal, y se escribe ú.","step":"drill"},"a1u02d1.d6":{"id":"a1u02d1.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Nde sy ","after":" ko ka'aru?","tiles":["o","ho","pa"],"bank":[1,2,0],"hint":"Nde sy, «tu mamá», es otra persona: el verbo empieza con o-, y con o- la raíz de «ir» es ho. -pa va al final.","full":"Nde sy {o}hó{pa} ko ka'aru?","es":"¿Tu mamá va esta tarde?","explain":"Nde sy es otra persona: o- + ho = oho, «va». -pa cierra la pregunta: ohópa. El acento queda en la o de ho, que ya no es la última vocal, y se escribe ó.","step":"drill"},"a1u02d1.e1":{"id":"a1u02d1.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Ana: _Che apurahéi ko pyhare_.","options":["Vos cantás esta noche.","Yo canto esta noche.","Ella canta esta noche.","Yo bailo esta noche."],"answer":2,"explain":"Che es «yo», y a- lo repite al principio del verbo: apurahéi es «canto». «Cantás» sería repurahéi, con re-; «canta», opurahéi, con o-; y «bailo», ajeroky.","step":"exam"},"a1u02d1.e2":{"id":"a1u02d1.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa habla de su mamá.)\nRosa: Che sy (   ) ko pyhareve.","options":["aju","reju","oju","ou"],"answer":4,"explain":"Che sy, «mi mamá», es otra persona: el verbo lleva o-. Y con o-, «venir» es ou: oju no existe. Aju es «vengo», con a-, y reju, «venís», con re-.","step":"exam"},"a1u02d1.e3":{"id":"a1u02d1.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana invita a Luis.)\nAna: ","after":" ko ka'aru, Luis?","tiles":["re","ju","pa"],"bank":[1,2,0],"full":"(Ana invita a Luis.)\nAna: Rejúpa ko ka'aru, Luis?","es":"Ana: ¿Venís esta tarde, Luis?","explain":"re- (vos) va primero: Ana le habla a Luis. Después la raíz ju, «venir», y al final -pa, que hace la pregunta: rejúpa, «¿venís?». La -pa no se lleva el acento: queda en la u, que ya no es la última vocal, y se escribe ú.","step":"exam"},"a1u02d1.k1":{"id":"a1u02d1.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Es sábado y Ana _canta_ en el patio. ¿Cómo se escribe en guaraní?","options":["opurajéi","opurahéi","opurahéy","opuraéi"],"answer":2,"explain":"Canta es opurahéi: con o-, porque es Ana, otra persona, y con h, que suena como la jota suave paraguaya. Opurajéi la escribe con j, que es otra letra: suena como la j inglesa de «John». Opurahéy cambia la i por la y, que en guaraní es otra vocal, la sexta. Opuraéi se come la h, que nunca es muda.","step":"words"},"a1u02d1.r1":{"id":"a1u02d1.r1","kind":"choice","area":"listening","label":"Respuesta rápida","q":"¿Qué responde Luis?","options":["Amba'apo.","Remba'apo.","Omba'apo."],"answer":1,"why":["Ana pregunta con re-, «vos»: rejapo, «hacés». Luis responde por él, con a-: amba'apo, «trabajo».","Remba'apo es «trabajás», con re-: Luis hablaría de Ana, no de él.","Omba'apo es «trabaja», con o-: sería otra persona, no Luis."],"script":["Narrador: En el patio. ¿Qué responde Luis?","Mujer: Mba'épa rejapo, Luis?","Narrador: 1","Hombre: Amba'apo.","Narrador: 2","Hombre: Remba'apo.","Narrador: 3","Hombre: Omba'apo."],"step":"skill"},"a1u02d2.c1":{"id":"a1u02d2.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana les pregunta a Luis y a Rosa ^adónde van^.)\nAna: Moõpa (   )?","options":["jaha","roho","peho"],"answer":3,"why":["Jaha es «vamos», con ja-: incluiría a Ana, y ella pregunta por Luis y Rosa.","Roho es «vamos, sin vos»: Ana hablaría de ella y de otros. Pero pregunta por los dos que la escuchan.","Ana les pregunta a Luis y a Rosa, los que escuchan: «ustedes», peẽ, lleva pe-. Moõpa peho?: ¿adónde van?"],"step":"compare"},"a1u02d2.d1":{"id":"a1u02d2.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le habla ^a Luis^.)\nAna: Ñande (   ) ko ka'aru.","options":["jakaru","rokaru","pekaru","okaru"],"answer":1,"why":["Ana le habla a Luis y lo incluye: ñande, «nosotros con vos», lleva ja-. Ñande jakaru: comemos, Ana y Luis.","Ro- es el prefijo de ore, «nosotros sin vos». Con ñande no va: Luis está incluido.","Pe- es el prefijo de peẽ, «ustedes». Ana se incluye, por eso dice ñande.","O- es «él, ella» o «ellos, ellas». Ñande pide ja-."],"step":"drill"},"a1u02d2.d2":{"id":"a1u02d2.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis y Ana trabajan esta mañana. Luis se lo dice ^a Ana^.)\nLuis: Ñande (   ) ko pyhareve.","options":["jamba'apo","ñamba'apo","romba'apo","omba'apo"],"answer":2,"why":["Mba'apo empieza con mb, una letra nasal: ja- se vuelve ña-. Jamba'apo no existe.","Ñande pide ja-, y como mba'apo es nasal (mb), ja- se vuelve ña-: ñamba'apo, «trabajamos, vos y yo».","Ro- es el prefijo de ore, «nosotros sin vos». Luis incluye a Ana, que lo escucha: ñande.","O- es «él, ella» o «ellos». Luis habla de él y de Ana: ñande."],"step":"drill"},"a1u02d2.d3":{"id":"a1u02d2.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana les habla a Luis y a Rosa.)\nAna: ^Peẽ^ (   ) ko pyhare.","options":["rejeroky","pejeroky","jajeroky","ojeroky"],"answer":2,"why":["Re- es «vos», una sola persona. Ana les habla a dos: peẽ, con pe-.","Peẽ, «ustedes», lleva pe-: pejeroky, «ustedes bailan».","Ja- es el «nosotros» de ñande e incluiría a Ana. Ella habla de Luis y de Rosa, los que escuchan: peẽ.","O- es «él, ella» o «ellos»: así Ana hablaría de otras personas, no de los dos que la escuchan."],"step":"drill"},"a1u02d2.d4":{"id":"a1u02d2.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis habla de ^sus abuelos^: «Ha'ekuéra (   ) heta.»","options":["amba'apo","remba'apo","romba'apo","omba'apo"],"answer":4,"why":["A- es «yo». Luis habla de sus abuelos, no de él.","Re- es «vos», el que escucha. Luis habla de otras personas.","Ro- es «nosotros sin vos» y sumaría a Luis. Él habla solo de sus abuelos.","Ha'ekuéra, «ellos», lleva o-, igual que ha'e: omba'apo heta, «trabajan mucho»."],"step":"drill"},"a1u02d2.d5":{"id":"a1u02d2.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana les habla a Luis y a Rosa.)\nAna: Peẽ ","after":" ko ka'aru.","tiles":["pe","karu"],"bank":[1,0],"hint":"Pe- es el prefijo de peẽ, «ustedes»: va primero, pegado a la raíz.","full":"(Ana les habla a Luis y a Rosa.)\nAna: Peẽ {pe}karu ko ka'aru.","es":"(Ana les habla a Luis y a Rosa.)\nAna: Ustedes comen esta tarde.","explain":"pe- («ustedes») + karu («comer») = pekaru: el prefijo va primero, pegado a la raíz. Peẽ pekaru ko ka'aru: ustedes comen esta tarde. El acento queda en la u final, así que no se escribe tilde.","step":"drill"},"a1u02d2.d6":{"id":"a1u02d2.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana invita a Luis.)\nAna: ","after":" guaraníme!","tiles":["ña","ñe'ẽ"],"bank":[1,0],"hint":"ñe'ẽ es nasal: ¿qué prefijo lleva el «nosotros con vos»? Va primero, pegado a la raíz.","full":"(Ana invita a Luis.)\nAna: {Ña}ñe'ẽ guaraníme!","es":"(Ana invita a Luis.)\nAna: ¡Hablemos en guaraní!","explain":"ña- («nosotros, con vos») + ñe'ẽ («hablar») = ñañe'ẽ: como ñe'ẽ es nasal, no va ja-. Ñañe'ẽ es «hablamos» y también, como invitación, «¡hablemos!», igual que Jaha! o Jakaru!. El acento está en la ẽ, y la tilde nasal ya lo marca: no se escribe otro acento.","step":"drill"},"a1u02d2.e1":{"id":"a1u02d2.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa le escribe a Juan: «_Ore roju_ ko pyhare.»","options":["Ustedes vienen esta noche.","Venimos esta noche, vos también.","Venimos esta noche, sin vos.","Ellos vienen esta noche."],"answer":3,"explain":"Ore es «nosotros sin vos», y ro- es su prefijo: ore roju, «venimos», sin Juan, el que lee. Con Juan incluido sería ñande, con ja-; «ustedes vienen» sería peẽ peju, y «ellos vienen», ha'ekuéra ou.","step":"exam"},"a1u02d2.e2":{"id":"a1u02d2.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana y Luis van esta tarde a la casa de la abuela Ramona. Ana la llama y le avisa.)\nAna: (   ) ko ka'aru, ña Ramona.","options":["Aju","Roju","Peju","Ou"],"answer":2,"explain":"Ana habla de ella y de Luis, los que van, y la abuela, que la escucha, no está en el grupo: ore, con ro-. Roju ko ka'aru: venimos esta tarde. Aju sería «vengo», Ana sola, y Luis también va; peju, «ustedes vienen», como si la abuela viniera; ou, «viene», otra persona sola, sin Ana.","step":"exam"},"a1u02d2.e3":{"id":"a1u02d2.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Ñande ","after":" ko pyhareve.","tiles":["ña","mba'apo"],"bank":[1,0],"full":"Ñande {ñamba'apo} ko pyhareve.","es":"Nosotros (con vos) trabajamos esta mañana.","explain":"Ña- va primero: es el prefijo, la parte que dice quién. Mba'apo es nasal por el mb, y por eso el «nosotros con vos» es ña-, no ja-: ñamba'apo, «trabajamos».","step":"exam"},"a1u02d2.k1":{"id":"a1u02d2.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Le decís a Ana: «Vos y yo _trabajamos_.» ¿Cómo se escribe en guaraní?","options":["ñamba'apo","jamba'apo","ñambaapo","ñama'apo"],"answer":1,"explain":"Trabajamos, vos y yo, es ñamba'apo: mba'apo es nasal por el mb, así que el prefijo es ña-, no ja-. Ñambaapo pierde el puso, que corta la voz entre las dos a: mba-'a-po. Y en ñama'apo cambió la raíz: la que cambia es la parte de adelante, ja- a ña-; mba'apo queda igual.","step":"words"},"a1u02d2.r1":{"id":"a1u02d2.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Quiénes comen esta tarde?","options":["Ana y los del grupo, con vos.","Ana y su familia, sin el grupo.","Solo los del grupo, sin Ana.","Ana sola."],"short":["Ana y el grupo","Ana y su familia","Solo el grupo","Ana sola"],"answer":1,"why":["Jakaru lleva ja-, el «nosotros» de ñande: incluye a los que leen el mensaje, el grupo, con vos.","Sin el grupo sería ore, con ro-: rokaru. Ana escribe jakaru.","Solo ustedes, sin Ana, sería peẽ pekaru, con pe-. Peju! sí lleva pe-, pero es la invitación: «vengan».","Ana sola sería akaru, con a-. Jakaru habla de varios, con vos."],"explain":"Ana escribe jakaru ha jajeroky: ja- es el «nosotros» de ñande, que incluye a los que leen. Comen Ana y los del grupo, con vos. Peju!, con pe-, es la invitación: «vengan».","step":"skill"},"a1u02d3.c1":{"id":"a1u02d3.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis trabaja ^en el campo^.)\nLuis: Amba'apo (   ).","options":["ñúpe","ñúme","ñugua"],"answer":2,"why":["Ñu termina en sílaba nasal, por la ñ: ahí no va -pe.","La ñ hace nasal la u de ñu: -pe se vuelve -me. Amba'apo ñúme, «trabajo en el campo».","-gua es el «de» de origen, como en Paraguaigua: diría de dónde es Luis. Él dice dónde trabaja: ñúme."],"step":"compare"},"a1u02d3.d1":{"id":"a1u02d3.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis contesta que su mamá está ^en casa^.)\nAna: Moõpa oĩ nde sy, Luis?\nLuis: Oĩ (   ).","options":["ógape","ógame","óga","kotýpe"],"answer":1,"why":["Moõpa pregunta dónde, y Luis responde con un lugar: óga, «casa», con -pe pegado atrás. Óga termina en sílaba oral y guarda su tilde: ógape, «en casa».","-me va solo tras sílaba nasal, y ga es oral: ógape.","Óga solo es «casa», el nombre de la cosa. Para decir «en casa» hay que pegarle -pe.","Kotýpe es «en la pieza», y Luis dice que su mamá está en casa: óga."],"step":"drill"},"a1u02d3.d2":{"id":"a1u02d3.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan trabaja ^en la chacra^.)\nJuan: Amba'apo (   ).","options":["kokuéme","kokuépe","kokue","ka'aguýpe"],"answer":2,"why":["-me va tras sílaba nasal, y kue es oral: kokuépe.","Kokue termina en sílaba oral: va -pe. El acento queda en la e, que ya no es la última vocal, y se escribe: kokuépe, «en la chacra».","Kokue solo es «chacra». Para «en la chacra» se le pega -pe: kokuépe.","Ka'aguýpe es «en el monte», y Juan trabaja en la chacra: kokue."],"step":"drill"},"a1u02d3.d3":{"id":"a1u02d3.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta adónde va Luis: ^a Ñemby^.)\nAna: Luis oho (   ).","options":["Ñembýme","Ñembýpe","Ñemby","Ka'akupépe"],"answer":2,"why":["Ñemby tiene ñ y mb, pero la última sílaba es mby: mb es una letra distinta de m, y la y que la sigue es oral. Tras sílaba oral va -pe. El día 2, con ja-/ña-, una mb en la raíz ya pedía ña- (ñamba'apo): los prefijos miran toda la raíz; -pe/-me, solo la última sílaba.","Mirá la última sílaba: mby. Su vocal es oral, así que va -pe, y la y, que ya no es la última vocal, lleva tilde: Ñembýpe, «a Ñemby».","Ñemby solo es el nombre de la ciudad. Para «a Ñemby» se le pega -pe.","Ka'akupépe es «a Caacupé», y Luis va a Ñemby."],"step":"drill"},"a1u02d3.d4":{"id":"a1u02d3.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa cuenta dónde trabaja su papá: ^en este país^.)\nRosa: Che ru omba'apo ko (   ).","options":["tetãpe","tetáme","tetã","tetãme"],"answer":4,"why":["La ã es nasal: tras sílaba nasal, -pe se vuelve -me.","Tetáme perdió la ~, y la ~ es la que dice que la a es nasal y que ahí va el acento. Sin ella la palabra cambia: es tetãme, sin otra tilde.","Tetã solo es «país». Para decir «en este país» se le pega -me: ko tetãme.","Tetã termina en ã, nasal: va -me. Y sobre la ã no se agrega tilde: la ~ ya marca el acento. Ko tetãme, «en este país»."],"step":"drill"},"a1u02d3.d5":{"id":"a1u02d3.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Che amba'apo ","after":".","tiles":["mbo'ehao","pe"],"bank":[1,0],"hint":"-pe es un sufijo: va después del lugar, pegado. Después fijate dónde queda el acento.","full":"Che amba'apo {mbo'ehaópe}.","es":"Yo trabajo en la escuela.","explain":"mbo'ehao («escuela») + -pe («en») = mbo'ehaópe. La última sílaba de mbo'ehao es oral, así que va -pe. -pe no se lleva el acento: queda en la o de mbo'ehao, que ya no es la última vocal, y se escribe ó.","step":"drill"},"a1u02d3.d6":{"id":"a1u02d3.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Che jarýi oñe'ẽ ","after":".","tiles":["guarani","me"],"bank":[1,0],"hint":"La última sílaba de guarani es ni, con n: ¿va -pe o -me? Después fijate dónde queda el acento.","full":"Che jarýi oñe'ẽ {guaraníme}.","es":"Mi abuela habla en guaraní.","explain":"guarani + -me: la n hace nasal la última sílaba, así que no va -pe. -me no se lleva el acento: queda en la i de guarani, que ya no es la última vocal, y se escribe í: guaraníme.","step":"drill"},"a1u02d3.e1":{"id":"a1u02d3.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: Che ru _omba'apo ñúme_.","options":["Mi papá trabaja en el campo.","Mi papá va al campo.","Mi papá trabaja en la chacra.","Mi papá trabaja en la ciudad."],"answer":1,"explain":"Omba'apo es «trabaja», con o-, y ñúme es ñu, «campo», con -me, «en»: tras la ñ nasal no va -pe. «Va» sería oho; «la chacra», kokue; y «la ciudad», táva.","step":"exam"},"a1u02d3.e2":{"id":"a1u02d3.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta dónde está su abuela: en Caacupé.)\nAna: Che jarýi oĩ (   ).","options":["Ka'akupéme","Ka'akupe","Itauguápe","Ka'akupépe"],"answer":4,"explain":"Ka'akupe termina en pe, una sílaba oral: va -pe, y el acento queda en la e de Ka'akupe, que ya no es la última vocal: Ka'akupépe, «en Caacupé». -me va solo tras sílaba nasal, Ka'akupe solo es el nombre de la ciudad, sin «en», e Itauguápe es «en Itauguá», otra ciudad.","step":"exam"},"a1u02d3.e3":{"id":"a1u02d3.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Rosa: Amba'apo ko ","after":".","tiles":["tetã","me"],"bank":[1,0],"full":"Rosa: Amba'apo ko {tetãme}.","es":"Rosa: Trabajo en este país.","explain":"tetã («país») va primero y -me pegado atrás: tetãme, «en el país». La ã es nasal, así que no va -pe. El acento sigue en la ã, y la ~ ya lo marca: no se escribe otra tilde.","step":"exam"},"a1u02d3.k1":{"id":"a1u02d3.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana está en la pieza: «Ana oĩ _en la pieza_.» ¿Cómo se escribe en guaraní?","options":["kotýme","kotípe","kotýpe","cotýpe"],"answer":3,"explain":"En la pieza es kotýpe: koty, «pieza», con -pe. El acento queda en la y, que ya no es la última vocal, y lleva tilde. Kotýme lleva -me, que va solo tras sílaba nasal; kotípe cambia la y por i, otra vocal; y cotýpe usa la c, que no es una letra del guaraní: acá va k.","step":"words"},"a1u02d3.r1":{"id":"a1u02d3.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Dónde trabaja Juan?","options":["En la escuela.","En la chacra.","En Itauguá."],"answer":2,"why":["La escuela es de Rosa: ella dice che amba'apo mbo'ehaópe, «yo trabajo en la escuela».","Juan dice amba'apo kokuépe: «trabajo en la chacra». Kokue es «chacra», y -pe, «en».","Itauguápe, «en Itauguá», también lo dice Rosa, de su escuela. Juan solo dice kokuépe."],"script":["Narrador: En la ronda de tereré. ¿Dónde trabaja Juan?","Mujer: Moõpa remba'apo, Juan?","Hombre: Amba'apo kokuépe. Ha nde?","Mujer: Che amba'apo mbo'ehaópe, Itauguápe.","Narrador: ¿Dónde trabaja Juan?"],"step":"skill"},"a1u02d4.c1":{"id":"a1u02d4.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: ^Moõguipa^ reju, Juan?\nJuan: Aju (   ).","options":["Itauguápe","Itauguágui","Itauguagua"],"answer":2,"why":["-pe dice adónde va o dónde está: Aha Itauguápe, «voy a Itauguá». Rosa pregunta de dónde viene.","Moõguipa pregunta «¿de dónde?», y se responde con -gui: Aju Itauguágui, «vengo de Itauguá».","-gua dice de dónde sos: Che Itauguagua, «soy de Itauguá». Rosa pregunta de dónde viene Juan, no de dónde es."],"step":"compare"},"a1u02d4.d1":{"id":"a1u02d4.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa llega a Itauguá. Viene ^de Asunción^.)\nRosa: Aju (   ).","options":["Paraguaýpe","gui Paraguay","Paraguay","Paraguaýgui"],"answer":4,"why":["-pe es «a» o «en»: Aha Paraguaýpe, «voy a Asunción». Rosa viene de ahí: -gui.","A diferencia del «de» castellano, -gui no va delante ni separado: se pega al final del lugar, Paraguaýgui.","Paraguay solo es el nombre: Asunción. Para decir «de Asunción» hay que pegarle -gui atrás.","Rosa viene de Asunción: el lugar lleva -gui, pegado atrás. Paraguay lleva el acento en la y final; como -gui no se lo lleva, se escribe ý: Paraguaýgui."],"step":"drill"},"a1u02d4.d2":{"id":"a1u02d4.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis ^sale de la escuela^ esta tarde.)\nAna: Luis osẽ (   ) ko ka'aru.","options":["mbo'ehaógui","mbo'ehaópe","mbo'ehaóme","mbo'ehaõgui"],"answer":1,"why":["Luis sale de la escuela: el lugar lleva -gui, pegado atrás. Mbo'ehao lleva el acento en la o final; con -gui esa o ya no es la última vocal, y se escribe ó: mbo'ehaógui.","-pe es «a» o «en»: Oho mbo'ehaópe, «va a la escuela». Luis sale de ahí: -gui.","-me es la forma de -pe tras una sílaba nasal, y la última sílaba de mbo'ehao es oral, la o: el mb del principio no cuenta. Además diría «en»; Luis sale de ahí: -gui, que no cambia nunca.","La ~ es la tilde nasal: haría nasal la o y cambiaría el sonido, y mbo'ehao no tiene vocal nasal. El acento se marca con la tilde aguda: mbo'ehaógui."],"step":"drill"},"a1u02d4.d3":{"id":"a1u02d4.d3","kind":"choice","area":"grammar","label":"Elegí la palabra","q":"Ana: (   ) reju, Luis?\nLuis: ^Aju Paraguaýgui^.","options":["Moõpa","Mávapa","Moõguipa","Moõpagui"],"answer":3,"why":["Moõpa pregunta «dónde» o «adónde»: Moõpa reiko?, Moõpa reho? Luis responde de dónde viene, con -gui, y la pregunta también lo lleva.","Mávapa pregunta «¿quién?». Luis responde con un lugar, no con una persona.","Luis responde Aju Paraguaýgui, «vengo de Asunción»: la pregunta es Moõguipa reju?, «¿de dónde venís?», con moõ + -gui + -pa.","-pa cierra la palabra que pregunta, como en Mba'éichapa: moõ + gui + pa. Moõpagui no existe."],"step":"drill"},"a1u02d4.d4":{"id":"a1u02d4.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: ^Moõguipa^ osẽ ko chipa?\nAna: (   )","options":["Tatakuápe.","Tatakuágui.","Tatakuáme.","Gui tatakua."],"answer":2,"why":["Tatakuápe es «en el horno», con -pe: dice dónde está, no de dónde sale.","Luis pregunta de dónde sale el chipá, con -gui, y Ana responde con -gui: Tatakuágui, «del horno de barro».","-me es la forma de -pe tras una sílaba nasal, y kua, la última sílaba de tatakua, es oral. Además diría «en»; el chipá sale de ahí: -gui, que no cambia nunca.","A diferencia del «de» castellano, -gui no va delante ni separado: se pega al final del lugar, tatakuágui."],"step":"drill"},"a1u02d4.d5":{"id":"a1u02d4.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana llega a Caacupé, a la casa de su abuela.)\nAna: Aju ","after":".","tiles":["Itaugua","gui"],"bank":[1,0],"hint":"Itaugua es el lugar y -gui es el sufijo: va después, pegado. Después fijate dónde queda el acento.","full":"(Ana llega a Caacupé, a la casa de su abuela.)\nAna: Aju Itauguá{gui}.","es":"Ana: Vengo de Itauguá.","explain":"Itaugua («Itauguá») + -gui («de») = Itauguágui, «de Itauguá». -gui no se lleva el acento: queda en la a final de Itaugua, que ya no es la última vocal, y se escribe á.","step":"drill"},"a1u02d4.d6":{"id":"a1u02d4.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis llega a la casa de Ana.)\nAna: ","after":" reju, Luis?","tiles":["moõ","gui","pa"],"bank":[2,0,1],"hint":"moõ, «dónde», va primero. -pa cierra la pregunta, como en Mba'éichapa.","full":"(Luis llega a la casa de Ana.)\nAna: {Moõguipa} reju, Luis?","es":"Ana: ¿De dónde venís, Luis?","explain":"moõ («dónde») + -gui («de») + -pa (pregunta) = Moõguipa, «¿de dónde?». -pa va al final, como en Mba'éichapa: moõpagui no existe. Ni -gui ni -pa se llevan el acento: queda en la õ, y la tilde nasal ya lo marca.","step":"drill"},"a1u02d4.e1":{"id":"a1u02d4.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Luis: Moõguipa reju?\nAna: _Aju Itauguágui_.","options":["Voy a Itauguá.","Soy de Itauguá.","Vengo de Itauguá.","Vengo de Asunción."],"answer":3,"explain":"Aju es «vengo» (a-, «yo», + ju, «venir»), y -gui, pegado a Itaugua, es «de»: «vengo de Itauguá». «Voy a Itauguá» sería Aha Itauguápe, con -pe; «soy de Itauguá», Che Itauguagua, con -gua; y Asunción en guaraní es Paraguay, no Itaugua.","step":"exam"},"a1u02d4.e2":{"id":"a1u02d4.e2","kind":"choice","area":"grammar","label":"Elegí la palabra","q":"(Luis y Rosa llegan. Ana les pregunta de dónde vienen.)\nAna: (   ) peju?","options":["Moõpa","Mávapa","Moõpagui","Moõguipa"],"answer":4,"explain":"Ana pregunta «de dónde»: moõ («dónde») + -gui («de») + -pa (pregunta) = Moõguipa. Peju es «ustedes vienen», así que Moõguipa peju? es «¿de dónde vienen?». Moõpa pregunta «dónde» o «adónde», sin el «de»; Mávapa pregunta «quién»; y moõpagui no existe, porque -pa cierra la palabra.","step":"exam"},"a1u02d4.e3":{"id":"a1u02d4.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Rosa quiere saber de dónde viene la mamá de Ana.)\nRosa: ","after":" ou nde sy?","tiles":["moõ","gui","pa"],"bank":[1,2,0],"full":"(Rosa quiere saber de dónde viene la mamá de Ana.)\nRosa: {Moõguipa} ou nde sy?","es":"Rosa: ¿De dónde viene tu mamá?","explain":"moõ («dónde») va primero: es la palabra que pregunta. Después -gui («de»), y al final -pa, que cierra la pregunta, como en Mba'éichapa: Moõguipa, «¿de dónde?». Con ou nde sy, «viene tu mamá», queda «¿de dónde viene tu mamá?».","step":"exam"},"a1u02d4.k1":{"id":"a1u02d4.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa viene de Asunción: Rosa ou _desde Asunción_. ¿Cómo se escribe en guaraní?","options":["Paraguaýgui","Paraguaýgüi","Paraguáigui","Paraguaýpe"],"answer":1,"explain":"Desde Asunción es Paraguaýgui: Paraguay, «Asunción», lleva el acento en la y final, y como -gui no se lo lleva, esa y ya no es la última vocal y se escribe ý. Paraguaýgüi usa la diéresis del castellano: en guaraní la u de gu siempre suena, también delante de i, y la ü no es una letra del alfabeto. Paraguáigui es «desde Paraguay», el país, con ái. Y Paraguaýpe es «a Asunción» o «en Asunción», con -pe.","step":"words"},"a1u02d4.r1":{"id":"a1u02d4.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿De dónde viene Ana?","options":["De Asunción.","De Caacupé.","De Itauguá.","De Ñemby."],"short":["Asunción","Caacupé","Itauguá","Ñemby"],"answer":3,"why":["Paraguaýgui, «de Asunción», lo dice Rosa de ella misma: Che aju Paraguaýgui.","Ka'akupépe lleva -pe: es adónde va Ana, a la casa de su abuela, no de dónde viene.","Ana responde Aju Itauguágui: viene de Itauguá. El lugar lleva -gui, «de».","Ñembýpe lleva -pe, y lo dice Rosa: es adónde va ella."],"explain":"A Moõguipa reju? Ana responde Aju Itauguágui: -gui marca de dónde viene, Itauguá. Ka'akupépe y Ñembýpe llevan -pe, adónde va cada una, y Paraguaýgui es de donde viene Rosa.","step":"skill"},"a1u02d5.c1":{"id":"a1u02d5.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: Reñe'ẽpa guaraníme, Lucas?\nLucas: ^Nahániri^, (   ).","options":["ndañe'ẽi","nañe'ẽi","añe'ẽ"],"answer":2,"why":["ñe'ẽ es una raíz nasal, por la ñ y la ẽ: delante no va nd-, sino n-. Ndañe'ẽi no existe.","Lucas dice que no y lo niega en el verbo: n- + añe'ẽ + -i = nañe'ẽi, «no hablo». Sobre la ẽ no se agrega tilde: la ~ ya marca el acento.","Añe'ẽ es «hablo», sin negación: Lucas diría que sí habla. Pero empieza con Nahániri, «no»."],"step":"compare"},"a1u02d5.d1":{"id":"a1u02d5.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: ^Rehópa^ kokuépe ko pyhareve, Juan?\nJuan: Nahániri, (   ): [oky|llueve].","options":["ndaha","nahái","ndahái","ndohói"],"answer":3,"why":["A ndaha le falta la -i del final. El «no» guaraní tiene dos partes, nd- y -i, y con una sola la palabra queda a medias.","ha, la raíz de «ir» con a-, es oral: delante va nd-, no n-. Nahái no existe.","Luis pregunta con re-, «vos», y Juan responde por él, con a-: aha, «voy». El «no» lo rodea: nd- + aha + -i = ndahái, «no voy». La -i no se lleva el acento, y la a de ha se escribe á.","Ndohói es «no va», con o-: sería otra persona. Juan habla de él mismo, con a-."],"step":"drill"},"a1u02d5.d2":{"id":"a1u02d5.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Llueve, y en la chacra no se trabaja.)\nJuan: ^Che ru^ (   ) ko pyhareve.","options":["nomba'apói","ndomba'apói","namba'apói","omba'apói"],"answer":1,"why":["Che ru, «mi papá», es otra persona: o-. Y mba'apo es una raíz nasal, por la mb: n- + omba'apo + -i = nomba'apói, «no trabaja».","Delante de una raíz nasal como mba'apo no va nd-, sino n-: nomba'apói.","Namba'apói es «no trabajo», con a-, «yo». Juan habla de su papá, con o-.","A omba'apói le falta la n- del principio: la -i sola no niega nada. El «no» necesita las dos partes."],"step":"drill"},"a1u02d5.d3":{"id":"a1u02d5.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana habla guaraní, pero su mamá no.)\nAna: Che añe'ẽ guaraníme, ha ^che sy^ (   ).","options":["nañe'ẽi","ndoñe'ẽi","oñe'ẽ","noñe'ẽi"],"answer":4,"why":["Nañe'ẽi es «no hablo», con a-: Ana hablaría de ella misma, y ella sí habla: añe'ẽ.","ñe'ẽ es una raíz nasal: delante va n-, no nd-. Ndoñe'ẽi no existe.","Oñe'ẽ es «habla», sin negación: diría que su mamá sí habla guaraní, y no es así.","Che sy es otra persona: o-. ñe'ẽ es nasal: n- + oñe'ẽ + -i = noñe'ẽi, «no habla». La ẽ ya lleva la tilde nasal: no se agrega otra."],"step":"drill"},"a1u02d5.d4":{"id":"a1u02d5.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa pregunta si Luis viene esta tarde.)\nAna: Nahániri, ^Luis^ (   ) ko ka'aru.","options":["ndoú","ndoúi","noúi","ou"],"answer":2,"why":["A ndoú le falta la -i del final: el «no» tiene dos partes, y con una sola la palabra queda a medias.","Luis es otra persona, y «viene» es ou. El «no» lo rodea: nd- + ou + -i = ndoúi, «no viene». La -i no se lleva el acento: queda en la u, que se escribe ú.","ou es una raíz oral: delante va nd-, no n-. Noúi no existe.","Ou es «viene», sin negación: diría que Luis sí viene, y Ana acaba de decir Nahániri, «no»."],"step":"drill"},"a1u02d5.d5":{"id":"a1u02d5.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Luis: Ko pyhareve ","after":" mba'eve.","tiles":["nd","a","japo","i"],"bank":[2,0,3,1],"hint":"El «no» rodea al verbo: nd- va primero y -i al final. En el medio, a- («yo») y la raíz japo, «hacer».","full":"Luis: Ko pyhareve {nd}ajapó{i} mba'eve.","es":"Luis: Esta mañana no hago nada.","explain":"nd- + a- («yo») + japo («hacer») + -i = ndajapói, «no hago». Las dos partes del «no» rodean al verbo. La -i no se lleva el acento: queda en la o de japo, que ya no es la última vocal, y se escribe ó. Con mba'eve, «nada»: «no hago nada».","step":"drill"},"a1u02d5.d6":{"id":"a1u02d5.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Lucas recién empieza a estudiar guaraní.)\nLucas: Che ","after":" guaraníme.","tiles":["n","a","ñe'ẽ","i"],"bank":[3,2,0,1],"hint":"ñe'ẽ es nasal: la primera parte del «no» es n-, sin d. Después a- («yo»), la raíz y, al final, -i.","full":"(Lucas recién empieza a estudiar guaraní.)\nLucas: Che {n}añe'ẽ{i} guaraníme.","es":"Lucas: Yo no hablo guaraní.","explain":"n- + a- («yo») + ñe'ẽ («hablar») + -i = nañe'ẽi, «no hablo». Como ñe'ẽ es una raíz nasal, la primera parte del «no» es n-, no nd-. El acento queda en la ẽ, y la tilde nasal ya lo marca: no se agrega otra.","step":"drill"},"a1u02d5.e1":{"id":"a1u02d5.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"(Llueve.)\nLuis: Che ru _nosẽi_ ko pyhareve.","options":["Mi papá sale esta mañana.","Yo no salgo esta mañana.","Mi papá no viene esta mañana.","Mi papá no sale esta mañana."],"answer":4,"explain":"Lo subrayado es sẽ, «salir», con o-, otra persona, mi papá, y con el «no» en dos partes: n- al principio, porque sẽ es una raíz nasal, y -i al final: nosẽi, «no sale». «Sale» sería osẽ, sin negación; «yo no salgo» llevaría a-, «yo»; y «no viene» sería ndoúi.","step":"exam"},"a1u02d5.e2":{"id":"a1u02d5.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Llueve, y la mamá de Ana se queda en casa.)\nAna: Che sy (   ) mbo'ehaópe ko pyhareve.","options":["ndahái","ndohói","nohói","ndoho"],"answer":2,"explain":"Che sy, «mi mamá», es otra persona: o-, y con o- la raíz de «ir» es ho. El «no» la rodea: nd- + oho + -i = ndohói, «no va». Ndahái es «no voy», con a-; nohói lleva n-, que va solo delante de una raíz nasal, y ho es oral; y a ndoho le falta la -i: el «no» necesita las dos partes.","step":"exam"},"a1u02d5.e3":{"id":"a1u02d5.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Llueve.)\nRosa: Juan ","after":" kokuépe ko pyhareve.","tiles":["n","o","mba'apo","i"],"bank":[1,3,0,2],"full":"(Llueve.)\nRosa: Juan {n}omba'apó{i} kokuépe ko pyhareve.","es":"Rosa: Juan no trabaja en la chacra esta mañana.","explain":"n- va primero: mba'apo es una raíz nasal, por la mb, así que la primera parte del «no» es n-, no nd-. Después o- (él: Juan), la raíz mba'apo («trabajar») y, al final, -i: nomba'apói, «no trabaja». La -i no se lleva el acento: queda en la última o de mba'apo, que ya no es la última vocal, y se escribe ó.","step":"exam"},"a1u02d5.k1":{"id":"a1u02d5.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa pregunta algo y Luis no sabe: Luis dice «_No sé_». ¿Cómo se escribe en guaraní?","options":["Ndakuaái","Naikuaái","Ndaikuaái","Ndaikuái"],"answer":3,"explain":"No sé es Ndaikuaái: nd- al principio, porque kuaa es una raíz oral; ai-, el «yo» de kuaa, con su i; la raíz kuaa, con dos aes; y -i al final, que no se lleva el acento: la última a de kuaa ya no es la última vocal, y se escribe á. Ndakuaái pierde la i de ai-, como reikuaa, que no es rekuaa. Naikuaái pone n-, que va solo delante de una raíz nasal. Ndaikuái se come una a de kuaa.","step":"words"},"a1u02d5.r1":{"id":"a1u02d5.r1","kind":"choice","area":"listening","label":"Respuesta rápida","q":"¿Qué responde Luis?","options":["Nahániri, ndahái. Oky.","Nahániri, aha.","Héẽ, ndahái."],"answer":1,"why":["Luis dice que no, Nahániri, y lo niega en el verbo: ndahái, «no voy». Después da la razón: oky, «llueve».","Nahániri, aha se contradice: «no, voy». Aha es «voy», sin negación.","Héẽ, ndahái se contradice al revés: «sí, no voy». Ndahái es «no voy», y pide un Nahániri delante."],"script":["Narrador: Llueve. ¿Qué responde Luis?","Mujer: Rehópa mbo'ehaópe ko ka'aru, Luis?","Narrador: 1","Hombre: Nahániri, ndahái. Oky.","Narrador: 2","Hombre: Nahániri, aha.","Narrador: 3","Hombre: Héẽ, ndahái."],"step":"skill"},"a1u02d6.c1":{"id":"a1u02d6.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa: ^Moõguipa^ reju, Juan?\nJuan: (   ) kokuégui.","options":["Aha","Aju","Ou"],"answer":2,"why":["Aha es «voy», el verbo de ir. Rosa pregunta con reju, «venís», y Juan responde con el mismo verbo, venir, y con a-: aju, «vengo».","Moõguipa reju? es «¿de dónde venís?», y Juan responde por él, con a-: aju, «vengo». Aju kokuégui: vengo de la chacra.","Ou es «viene», con o-: sería otra persona. Juan habla de él mismo: a-."],"step":"compare"},"a1u02d6.d1":{"id":"a1u02d6.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa habla de sus papás: van a Asunción esta mañana.)\nRosa: ^Ha'ekuéra^ (   ) Paraguaýpe ko pyhareve.","options":["aha","reho","roho","oho"],"answer":4,"why":["Aha es «voy», con a-: Rosa hablaría de ella misma, y habla de sus papás.","Reho es «vas», con re-: Rosa le hablaría al que escucha. Ha'ekuéra son otras personas.","Roho es «vamos, sin vos», con ro-: sumaría a Rosa. Ha'ekuéra, «ellos», son solo sus papás.","Ha'ekuéra, «ellos», lleva o-, igual que ha'e, y con o- la raíz de «ir» es ho: oho, «van». Paraguaýpe, con -pe, es adónde: a Asunción."],"step":"drill"},"a1u02d6.d2":{"id":"a1u02d6.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le habla a Luis.)\nAna: ^Ñande^ (   ) guaraníme, Luis.","options":["jañe'ẽ","ñañe'ẽ","roñe'ẽ","oñe'ẽ"],"answer":2,"why":["Ñe'ẽ es nasal, por la ñ y la ẽ, y delante de una raíz nasal ja- se vuelve ña-. Jañe'ẽ no se dice.","Ñande pide ja-, el «nosotros con vos». Como ñe'ẽ es nasal, ja- se vuelve ña-: ñañe'ẽ, «hablamos, vos y yo».","Ro- es el prefijo de ore, «nosotros sin vos». Ñande incluye a Luis, que escucha.","O- es «él, ella» o «ellos»: oñe'ẽ, «habla». Ñande pide el «nosotros con vos»."],"step":"drill"},"a1u02d6.d3":{"id":"a1u02d6.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa cuenta dónde está su papá: ^en el país^.)\nRosa: Che ru oĩ (   ).","options":["tetãpe","tetãgui","tetãme","tetãgua"],"answer":3,"why":["La ã es una vocal nasal: después de una sílaba nasal, -pe se vuelve -me. Tetãpe no se dice.","-gui es «de, desde»: tetãgui diría de dónde viene o sale. Rosa dice dónde está su papá, con oĩ.","Tetã termina en ã, nasal: va -me, no -pe. Y sobre la ã no se agrega tilde: tetãme, «en el país».","-gua es el «de» de origen, como en Paraguaigua: diría de dónde es alguien. Rosa dice dónde está: tetãme."],"step":"drill"},"a1u02d6.d4":{"id":"a1u02d6.d4","kind":"choice","area":"grammar","label":"Elegí la palabra","q":"Ana: (   ) reho, Luis?\nLuis: ^Aha Ka'akupépe^.","options":["Moõpa","Moõguipa","Mávapa","Mba'épa"],"answer":1,"why":["Luis responde adónde va, con -pe: Aha Ka'akupépe. La pregunta es Moõpa reho?, «¿adónde vas?».","Moõguipa pregunta «¿de dónde?» y se responde con -gui, como Aju Itauguágui. Luis responde con -pe: adónde va.","Mávapa pregunta «¿quién?», y Luis responde con un lugar, no con una persona.","Mba'épa pregunta «¿qué?», como en Mba'épa rejapo? Luis responde con un lugar, no con una acción."],"step":"drill"},"a1u02d6.d5":{"id":"a1u02d6.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Llueve.)\nRosa: Che sy ","after":" ko pyhare.","tiles":["nd","ou","i"],"bank":[2,0,1],"hint":"Che sy es otra persona, y «viene» es ou, entera. El «no» la rodea: nd- delante y -i al final.","full":"(Llueve.)\nRosa: Che sy {nd}oú{i} ko pyhare.","es":"Rosa: Mi mamá no viene esta noche.","explain":"nd- (no) + ou (viene) + -i (no) = ndoúi, «no viene». Las dos partes del «no» rodean al verbo, como en ndohói. La -i no se lleva el acento: queda en la u de ou, que ya no es la última vocal, y se escribe ú.","step":"drill"},"a1u02d6.d6":{"id":"a1u02d6.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana cuenta dónde está su mamá: en la pieza.)\nAna: Che sy oĩ ","after":".","tiles":["koty","pe"],"bank":[1,0],"hint":"Koty, «pieza», va primero y el sufijo pegado atrás. La última sílaba de koty es oral: ¿-pe o -me? Después fijate dónde queda el acento.","full":"(Ana cuenta dónde está su mamá: en la pieza.)\nAna: Che sy oĩ {kotýpe}.","es":"Ana: Mi mamá está en la pieza.","explain":"koty («pieza») + -pe («en») = kotýpe, «en la pieza». Ty, la última sílaba de koty, es oral: va -pe, no -me. -pe no se lleva el acento: queda en la y de koty, que ya no es la última vocal, y se escribe ý.","step":"drill"},"a1u02d6.e1":{"id":"a1u02d6.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: Che sy _ndohói_ Itauguápe ko ka'aru.","options":["Mi mamá no va a Itauguá esta tarde.","Mi mamá va a Itauguá esta tarde.","Mi mamá no viene de Itauguá esta tarde.","Yo no voy a Itauguá esta tarde."],"answer":1,"explain":"Ndohói es «no va»: nd- y -i rodean a oho, «va», con o- porque Rosa habla de su mamá. Sin el «no» sería oho; «no viene de» pediría ou y -gui, Itauguágui; y «yo no voy» sería ndahái, con a-.","step":"exam"},"a1u02d6.e2":{"id":"a1u02d6.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le habla a Luis: hacen chipá los dos.)\nAna: Ñande (   ) chipa ko ka'aru.","options":["ñajapo","ajapo","jajapo","ojapo"],"answer":3,"explain":"Ñande, «nosotros con vos», pide ja-, y japo no tiene ninguna letra nasal, así que ja- se queda: jajapo, «hacemos, vos y yo». Ña- va solo delante de una raíz nasal, como en ñañe'ẽ; ajapo es «hago», Ana sola; y ojapo, «hace», otra persona.","step":"exam"},"a1u02d6.e3":{"id":"a1u02d6.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Llueve.)\nJuan: Che ru ","after":" kokuépe ko pyhareve.","tiles":["n","o","mba'apo","i"],"bank":[2,3,1,0],"full":"(Llueve.)\nJuan: Che ru {n}omba'apó{i} kokuépe ko pyhareve.","es":"Juan: Mi papá no trabaja en la chacra esta mañana.","explain":"n- (el «no» delante de una raíz nasal) + o- (él) + mba'apo (trabajar) + -i (la otra parte del «no») = nomba'apói, «no trabaja». Mba'apo es nasal por la mb: por eso no va nd-. La -i no se lleva el acento: queda en la o de mba'apo, que ya no es la última vocal, y se escribe ó. Kokuépe, con -pe, es dónde: en la chacra.","step":"exam"},"a1u02d6.k1":{"id":"a1u02d6.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana le pregunta a Luis si oye la música. Luis: «_Escucho_.» ¿Cómo se escribe en guaraní?","options":["ajendu","ahendu","aendu","ahendy"],"answer":2,"explain":"Escucho es ahendu: a-, «yo», y hendu, «oír». La h suena como la jota suave paraguaya, pero se escribe h: con j sería otra letra, la y fuerte de «yo». Aendu se come la h, que nunca es muda. Y ahendy cambia la u por la y, la sexta vocal: hendy es otra palabra, «arder».","step":"words"},"a1u02d6.r1":{"id":"a1u02d6.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué hace Ana en Caacupé?","options":["Trabaja.","Va a la escuela.","Come y habla guaraní.","Trabaja en Asunción."],"short":["Trabaja","Va a la escuela","Come y habla","Trabaja en Asunción"],"answer":3,"why":["Ana dice Namba'apói: n-…-i rodea a mba'apo. Justamente no trabaja.","Nadie habla de la escuela: mbo'ehao no aparece en el chat.","A Mba'épa rejapo Ka'akupépe? Ana responde Akaru ha añe'ẽ guaraníme: come y habla en guaraní.","El que trabaja en Asunción es su papá: omba'apo Paraguaýpe, con o-."],"explain":"Luis pregunta Mba'épa rejapo Ka'akupépe?, «¿qué hacés en Caacupé?», y Ana responde Akaru ha añe'ẽ guaraníme: come y habla en guaraní. Namba'apói niega el trabajo, y Paraguaýpe, Asunción, es donde trabaja su papá.","step":"skill"},"a1u02t.1":{"id":"a1u02t.1","kind":"choice","area":"vocab","label":"Qué significa","q":"(En la fiesta.)\nLuis: _Ajeroky_ ko pyhare.","options":["Canto esta noche.","Bailo esta noche.","Trabajo esta noche.","Como esta noche."],"answer":2,"explain":"Ajeroky es a-, «yo», más jeroky, «bailar»: «bailo». Canto es apurahéi, trabajo es amba'apo y como es akaru. Ko pyhare es «esta noche».","step":"test","unit":2},"a1u02t.2":{"id":"a1u02t.2","kind":"choice","area":"vocab","label":"Qué significa","q":"Rosa le dice a Juan: «_Jaha_, Juan.»","options":["Venimos, Juan.","Comamos, Juan.","Gracias, Juan.","Vamos, Juan."],"answer":4,"explain":"Jaha es ja-, el «nosotros» de ñande, más ha, «ir»: «vamos», vos y yo. Se dice hasta en castellano paraguayo. Venimos sería Roju: otro verbo, ju, «venir», y el «nosotros» sin vos. Comamos sería Jakaru y gracias es Aguyje.","step":"test","unit":2},"a1u02t.3":{"id":"a1u02t.3","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Luis habla de su papá: «Che ru omba'apo _en el monte_.» ¿Cómo se escribe en guaraní?","options":["ka'aguýpe","ka'aguípe","kaaguýpe","ka'aguýme"],"answer":1,"explain":"En el monte es ka'aguýpe: ka'aguy, «monte», con -pe. La -pe no se lleva el acento: queda en la y, que ya no es la última vocal, y se escribe ý. Ka'aguípe cambia la y por i, que en guaraní es otra vocal; kaaguýpe perdió el puso de ka'aguy; y ka'aguýme lleva -me, que va solo tras una sílaba nasal.","step":"test","unit":2},"a1u02t.4":{"id":"a1u02t.4","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Le escribís a Ana: «Vos y yo _salimos_.» ¿Cómo se escribe en guaraní?","options":["jasẽ","ñase","ñasẽ","ñasen"],"answer":3,"explain":"Salimos, vos y yo, es ñasẽ: sẽ, «salir», es una raíz nasal, por la ẽ, así que el «nosotros con vos» es ña-, no ja-. Ñase perdió la tilde nasal de la ẽ, y ñasen la cambió por una n que la palabra no lleva: la ẽ es una sola vocal, nasal.","step":"test","unit":2},"a1u02t.5":{"id":"a1u02t.5","kind":"choice","area":"vocab","label":"Elegí la palabra","q":"(El gato de Ana sale del horno de barro.)\nAna: Mbarakaja osẽ (   ).","options":["kokuégui","tatakuágui","ñanduti","kotýpe"],"answer":2,"explain":"El gato sale del horno de barro: tatakua, «horno de barro», con -gui, «de»: tatakuágui. Mbarakaja es «gato» y osẽ, «sale». Kokuégui es «de la chacra», ñanduti es el encaje de Itauguá y kotýpe es «en la pieza».","step":"test","unit":2},"a1u02t.6":{"id":"a1u02t.6","kind":"choice","area":"vocab","label":"Qué significa","q":"Rosa le pregunta algo a Ana, y Ana responde: «_Ndaikuaái_.»","options":["No voy.","No hay.","No sé.","Nada."],"answer":3,"explain":"Ndaikuaái es «no sé»: nd- al principio, ai-, el «yo» de kuaa, «saber», y -i al final. No voy es ndahái, no hay es ndaipóri y nada es mba'eve.","step":"test","unit":2},"a1u02t.7":{"id":"a1u02t.7","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa habla de Juan.)\nRosa: Ha'e (   ) kokuépe.","options":["amba'apo","remba'apo","romba'apo","omba'apo"],"answer":4,"explain":"Ha'e, «él», es otra persona: el verbo lleva o-. Omba'apo kokuépe: trabaja en la chacra. Amba'apo es «trabajo», con a-, «yo»; remba'apo, «trabajás», con re-, «vos»; y romba'apo, «trabajamos, sin vos», con ro-.","step":"test","unit":2},"a1u02t.8":{"id":"a1u02t.8","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis y Ana le hablan a la profesora.)\nLuis: Ore (   ) guaraníme.","options":["roñe'ẽ","ñañe'ẽ","peñe'ẽ","oñe'ẽ"],"answer":1,"explain":"Luis habla de él y de Ana, y la profesora, que escucha, no está en el grupo: ore, y su prefijo es ro-. Ore roñe'ẽ guaraníme: hablamos guaraní, sin vos. Ñañe'ẽ es el «nosotros» de ñande e incluiría a la profesora; peñe'ẽ es «ustedes hablan»; y oñe'ẽ, «habla» o «hablan», otras personas.","step":"test","unit":2},"a1u02t.9":{"id":"a1u02t.9","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan les pregunta a Ana y a Rosa adónde van esta mañana.)\nJuan: Moõpa (   ) ko pyhareve?","options":["reho","peho","jaha","oho"],"answer":2,"explain":"Juan les pregunta a dos personas, Ana y Rosa: «ustedes», peẽ, lleva pe-. Moõpa peho ko pyhareve?: ¿adónde van esta mañana? Reho es «vas», para una sola persona; jaha es «vamos» e incluiría a Juan; y oho es «va» o «van», otras personas, no las dos que escuchan.","step":"test","unit":2},"a1u02t.10":{"id":"a1u02t.10","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa cuenta dónde está su papá: en el campo.)\nRosa: Che ru oĩ (   ).","options":["ñúme","ñúpe","ñu","ñúgui"],"answer":1,"explain":"En el campo es ñúme: ñu, «campo», con -me, porque la ñ hace nasal su única sílaba. -me no se lleva el acento, y la u, que ya no es la última vocal, se escribe ú. Ñúpe pone -pe tras una sílaba nasal; ñu solo es «campo», sin el «en»; y ñúgui es «del campo», de donde viene alguien, y Rosa dice dónde está su papá.","step":"test","unit":2},"a1u02t.11":{"id":"a1u02t.11","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis llega de la escuela.)\nAna: Moõguipa reju, Luis?\nLuis: Aju (   ).","options":["mbo'ehaópe","mbo'ehao","mbo'ehaóme","mbo'ehaógui"],"answer":4,"explain":"Moõguipa pregunta «¿de dónde?», y se responde con el lugar y -gui: Aju mbo'ehaógui, «vengo de la escuela». -gui no se lleva el acento: queda en la o de mbo'ehao, que se escribe ó. Mbo'ehaópe es «a la escuela» o «en la escuela», con -pe; mbo'ehao solo es «escuela», sin el «de»; y mbo'ehaóme lleva -me, que va solo tras una sílaba nasal, y además diría «en».","step":"test","unit":2},"a1u02t.12":{"id":"a1u02t.12","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(Llueve. Rosa le pregunta a Ana si va a Caacupé esta tarde.)\nRosa: Rehópa Ka'akupépe ko ka'aru?\nAna: Nahániri, (   ): oky.","options":["ndahái","ndaha","ahái","nahái"],"answer":1,"explain":"Rosa pregunta con re-, «vos», y Ana responde por ella, con a-: aha, «voy». El «no» lo rodea en dos partes, nd- al principio y -i al final: ndahái, «no voy». A ndaha le falta la -i, y a ahái le falta el nd-: con una sola parte la palabra queda a medias. Nahái lleva n-, que va solo delante de una raíz nasal, y ha es oral.","step":"test","unit":2},"a1u02t.13":{"id":"a1u02t.13","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(La abuela de Luis no habla guaraní.)\nLuis: Che jarýi (   ) guaraníme.","options":["ndoñe'ẽi","oñe'ẽi","noñe'ẽi","noñe'ẽ"],"answer":3,"explain":"Che jarýi, «mi abuela», es otra persona: o-. Y ñe'ẽ es una raíz nasal, así que la primera parte del «no» es n-, no nd-: n- + oñe'ẽ + -i = noñe'ẽi, «no habla». Ndoñe'ẽi no existe, porque delante de una raíz nasal no va nd-. A oñe'ẽi le falta la n- del principio, y a noñe'ẽ le falta la -i del final: el «no» necesita las dos partes.","step":"test","unit":2},"a1u02t.14":{"id":"a1u02t.14","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Llueve.)\nRosa: Luis ","after":" mbo'ehaópe ko ka'aru.","tiles":["nd","o","ho","i"],"bank":[2,0,3,1],"full":"(Llueve.)\nRosa: Luis {nd}ohó{i} mbo'ehaópe ko ka'aru.","es":"(Llueve.)\nRosa: Luis no va a la escuela esta tarde.","explain":"nd- va primero: es la primera parte del «no». Después o-, porque Luis es otra persona, y con o- la raíz de «ir» es ho. Al final, -i, la segunda parte del «no»: ndohói, «no va». La -i no se lleva el acento: queda en la o de ho, que ya no es la última vocal, y se escribe ó.","step":"test","unit":2},"a1u02t.15":{"id":"a1u02t.15","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Adónde va Juan?","passage":"Rosa: Mba'éichapa, Juan? Moõpa reho?\nJuan: Aha mbo'ehaópe. Ha nde, moõguipa reju?\nRosa: Aju Itauguágui, che jarýi rógagui.\nJuan: Ha nde sy?\nRosa: Ha'e ndoúi ko pyhareve: omba'apo ógape.","options":["A la chacra.","A la escuela.","A Itauguá.","A su casa."],"short":["Chacra","Escuela","Itauguá","Su casa"],"answer":2,"explain":"Juan responde Aha mbo'ehaópe, «voy a la escuela»: mbo'ehao, «escuela», con -pe. La chacra, kokue, no aparece; Itauguágui es de donde viene Rosa, con -gui; y ógape, «en casa», es donde trabaja la mamá de Rosa.","step":"test","unit":2},"a1u02t.16":{"id":"a1u02t.16","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿De dónde viene Rosa?","passage":"Rosa: Mba'éichapa, Juan? Moõpa reho?\nJuan: Aha mbo'ehaópe. Ha nde, moõguipa reju?\nRosa: Aju Itauguágui, che jarýi rógagui.\nJuan: Ha nde sy?\nRosa: Ha'e ndoúi ko pyhareve: omba'apo ógape.","options":["De Asunción.","De la escuela.","De Caacupé.","De Itauguá."],"short":["Asunción","La escuela","Caacupé","Itauguá"],"answer":4,"explain":"A Moõguipa reju? Rosa responde Aju Itauguágui, che jarýi rógagui: viene de Itauguá, de la casa de su abuela. Las dos palabras terminan en -gui, «de». La escuela es adonde va Juan, con -pe; Asunción y Caacupé no aparecen en el chat.","step":"test","unit":2},"a1u02t.17":{"id":"a1u02t.17","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué hace la mamá de Rosa esta mañana?","passage":"Rosa: Mba'éichapa, Juan? Moõpa reho?\nJuan: Aha mbo'ehaópe. Ha nde, moõguipa reju?\nRosa: Aju Itauguágui, che jarýi rógagui.\nJuan: Ha nde sy?\nRosa: Ha'e ndoúi ko pyhareve: omba'apo ógape.","options":["Va a la escuela.","Viene con Rosa.","Trabaja en casa.","Trabaja en la chacra."],"short":["Va a la escuela","Viene con Rosa","Trabaja en casa","En la chacra"],"answer":3,"explain":"Rosa dice de su mamá: Ha'e ndoúi ko pyhareve: omba'apo ógape. Ndoúi es «no viene», con el «no» en dos partes: no viene esta mañana, así que «viene con Rosa» no va. Omba'apo ógape es «trabaja en casa»: óga, «casa», con -pe. A la escuela va Juan, y la chacra no aparece.","step":"test","unit":2},"a1u02t.18":{"id":"a1u02t.18","kind":"choice","area":"listening","label":"Respuesta rápida","q":"(En la fiesta.)\nAna: Mba'épa rejapo, Luis?\n¿Qué responde Luis?","options":["Apurahéi.","Repurahéi.","Purahéi."],"answer":1,"explain":"Ana pregunta con re-, «vos»: rejapo, «hacés». Luis responde por él, con a-: apurahéi, «canto». Repurahéi es «cantás», con re-: Luis hablaría de Ana. Y purahéi sin prefijo es «canción», la cosa: le falta la persona.","step":"test","unit":2},"a1u02t.19":{"id":"a1u02t.19","kind":"choice","area":"listening","label":"Respuesta rápida","q":"(En la terminal.)\nRosa: Moõguipa reju, Juan?\n¿Qué responde Juan?","options":["Aha Paraguaýpe.","Aju Paraguaýgui.","Ou Paraguaýgui."],"answer":2,"explain":"Rosa pregunta de dónde viene Juan, y él responde por él mismo, con a-, y con el lugar y -gui: Aju Paraguaýgui, «vengo de Asunción». Aha Paraguaýpe es «voy a Asunción»: otro verbo y otro sufijo. Ou Paraguaýgui es «viene de Asunción», con o-: Juan hablaría de otra persona.","step":"test","unit":2},"a1u02t.20":{"id":"a1u02t.20","kind":"choice","area":"listening","label":"Respuesta rápida","q":"Rosa: Rejúpa ko pyhare, Ana?\n¿Qué responde Ana?","options":["Héẽ, reju.","Nahániri, aju.","Héẽ, aju."],"answer":3,"explain":"Rosa pregunta con re-, «vos», si Ana viene esta noche. Ana responde por ella, con a-: Héẽ, aju, «sí, vengo». Héẽ, reju cambia la persona: reju es «venís», y Ana hablaría de Rosa. Nahániri, aju se contradice: «no, vengo».","step":"test","unit":2},"a1u03d1.c1":{"id":"a1u03d1.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa habla de ^su papá^, que está cansado: «Che ru (   ).»","options":["chekane'õ","ikane'õ","kane'õ"],"answer":2,"why":["Chekane'õ es «estoy cansada»: Rosa hablaría de ella misma. Acá habla de su papá, otra persona.","Che ru, «mi papá», es otra persona: el estado lleva i-. Che ru ikane'õ, «mi papá está cansado».","Kane'õ sin marca es solo «cansancio», la cosa: Che ru kane'õ no es una oración. Falta la i-."],"step":"compare"},"a1u03d1.d1":{"id":"a1u03d1.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Termina el partido. ^Juan dice cómo está él mismo^.)\nJuan: (   ).","options":["Akane'õ","Chekane'õ","Ikane'õ","Kane'õ"],"answer":2,"why":["a- es para las acciones, como aguata. Un estado no lleva a-: akane'õ no es «estoy cansado».","Juan habla de él mismo y de un estado: che- pegado a kane'õ. Chekane'õ, «estoy cansado».","Ikane'õ es «está cansado», de otra persona. Juan habla de él mismo.","Kane'õ sin marca es «cansancio», la cosa: no dice de quién es."],"step":"drill"},"a1u03d1.d2":{"id":"a1u03d1.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa ve que Juan está enojado y ^se lo dice a él^: «(   ), Juan.»","options":["Chepochy","Ipochy","Ndepochy","Nepochy"],"answer":3,"why":["Chepochy es «estoy enojada»: Rosa hablaría de ella misma, y le habla a Juan de él.","Ipochy es «está enojado», de otra persona. Rosa le habla a Juan directamente, de vos a vos.","Rosa le habla a Juan: nde- pegado a pochy. Ndepochy, «estás enojado».","ne- reemplaza a nde- solo antes de una palabra nasal, como nekane'õ. Pochy no es nasal: no tiene ~ ni m, n, ñ. Queda nde-: ndepochy."],"step":"drill"},"a1u03d1.d3":{"id":"a1u03d1.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Un nene pide chipa: tiene hambre.)\n^Mitã^ (   ).","options":["ivare'a","chevare'a","ndevare'a","vare'a"],"answer":1,"why":["Mitã, «el niño», es otra persona: el estado lleva i-. Mitã ivare'a, «el niño tiene hambre».","Chevare'a es «tengo hambre»: hablaría de mí. Acá se habla del niño.","Ndevare'a es «tenés hambre», hablándole a vos. Acá se habla del niño, no se le habla a él.","Vare'a sin marca es «hambre», la cosa: mitã vare'a no es una oración. Falta la i-."],"step":"drill"},"a1u03d1.d4":{"id":"a1u03d1.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis habla de ^su mamá^, que está enferma: «Che sy (   ).»","options":["cherasy","irasy","hasy","tasy"],"answer":3,"why":["Cherasy es «estoy enfermo»: Luis hablaría de él mismo. Acá habla de su mamá.","Rasy es de las palabras con tres formas, como téra, che réra, héra: tasy, cherasy, hasy. Para él o ella es hasy: irasy no existe.","Che sy es otra persona, y para él o ella rasy tiene su propia forma, hasy, como réra tiene héra. Che sy hasy, «mi mamá está enferma».","Tasy es la palabra suelta, «dolor, enfermedad», sin marcar a nadie: no dice que la mamá esté enferma."],"step":"drill"},"a1u03d1.d5":{"id":"a1u03d1.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(A Juan le duele la cabeza.)\nJuan: ","after":".","tiles":["che","akã","rasy"],"bank":[2,0,1],"hint":"che- va primero. Después la parte del cuerpo, akã, y al final rasy, «dolor».","full":"(A Juan le duele la cabeza.)\nJuan: {Che}akãrasy.","es":"Juan: Me duele la cabeza.","explain":"che- (yo, me pasa) + akã («cabeza») + rasy («dolor, enfermo») = cheakãrasy, «me duele la cabeza»: en guaraní es un estado, todo en una palabra. No lleva tilde: el acento va en la última vocal, la y. La ~ de akã marca la nasal.","step":"drill"},"a1u03d1.d6":{"id":"a1u03d1.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Rosa: ","after":", Luis.","tiles":["ne","kane'õ"],"bank":[1,0],"hint":"Kane'õ es nasal, lleva ~: el «vos» no es nde- sino ne-, y va primero.","full":"Rosa: {Ne}kane'õ, Luis.","es":"Rosa: Estás cansado, Luis.","explain":"ne- (vos) + kane'õ («cansancio») = nekane'õ, «estás cansado». Antes de una palabra nasal, nde- se vuelve ne-: nekane'õ. Con una palabra oral queda nde-: ndepochy.","step":"drill"},"a1u03d1.e1":{"id":"a1u03d1.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Luis: _Chero'y ha chevare'a_.","options":["Tengo frío y hambre.","Tengo calor y sed.","Tiene frío y hambre.","Estoy cansado y enojado."],"answer":1,"explain":"Che- marca un estado mío: chero'y es «tengo frío» (ro'y, «frío») y chevare'a, «tengo hambre» (vare'a, «hambre»). «Tiene» sería otra persona, con i-: iro'y ha ivare'a. Calor y sed son otras palabras: «tengo sed» es chey'uhéi. Cansado es chekane'õ y enojado, chepochy.","step":"exam"},"a1u03d1.e2":{"id":"a1u03d1.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana habla de su abuela, que está enojada.)\nAna: Che jarýi (   ).","options":["chepochy","ndepochy","ipochy","pochy"],"answer":3,"explain":"Che jarýi, «mi abuela», es otra persona: el estado lleva i-. Che jarýi ipochy, «mi abuela está enojada». Chepochy sería «estoy enojada», ndepochy, «estás enojada», y pochy solo es «enojo», la cosa, sin decir de quién.","step":"exam"},"a1u03d1.e3":{"id":"a1u03d1.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Ana: Mba'éichapa reiko, Rosa?\nRosa: ","after":".","tiles":["che","akã","rasy"],"bank":[2,1,0],"full":"Ana: Mba'éichapa reiko, Rosa?\nRosa: Cheakãrasy.","es":"Ana: ¿Cómo andás, Rosa?\nRosa: Me duele la cabeza.","explain":"che- (yo, me pasa) va primero. Después va akã («cabeza») y al final rasy («dolor»): cheakãrasy, «me duele la cabeza». Es un estado de Rosa: todo junto, en una sola palabra, y sin tilde.","step":"exam"},"a1u03d1.k1":{"id":"a1u03d1.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Después del partido, Juan dice: «_Tengo sed_.» ¿Cómo se escribe en guaraní?","options":["chey'uhẽi","chey'uhéi","chei'uhéi","shey'uhéi"],"answer":2,"explain":"Se escribe chey'uhéi: con ch al principio, con el puso que corta la voz entre la y y la u, y con la tilde en la é, porque el acento no cae en la última vocal. Shey'uhéi escribe el primer sonido con sh, y en guaraní se escribe con la ch. Chey'uhẽi cambia la tilde por una ~, y la e de y'uhéi no es nasal. Chei'uhéi cambia la y por i, otra vocal.","step":"words"},"a1u03d1.r1":{"id":"a1u03d1.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué le pasa al hombre?","options":["Está cansado y tiene sed.","Tiene hambre y frío.","Está enojado."],"answer":1,"why":["El hombre dice Chekane'õ ha chey'uhéi: che- marca sus estados, kane'õ es «cansancio» y y'uhéi, «sed». Por eso ella le propone tereré.","Hambre sería chevare'a, y frío, chero'y. El hombre no dice ninguna de las dos.","Enojado sería chepochy. El hombre habla de cansancio y de sed, y ella lo invita a tomar tereré."],"script":["Narrador: Termina el partido. ¿Qué le pasa al hombre?","Mujer: Mba'éichapa reiko, Luis?","Hombre: Chekane'õ ha chey'uhéi.","Mujer: Jaha, oĩ terere."],"step":"skill"},"a1u03d2.c1":{"id":"a1u03d2.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le cuenta a Luis que ^está en su casa^.)\nAna: (   ) ógape.","options":["Akaru","Chevare'a","Aime"],"answer":3,"why":["Akaru es «como», una acción con a-. Akaru ógape sería «como en casa»: dice qué hace, no que está ahí.","Chevare'a es «tengo hambre», un estado con che-. Tampoco dice dónde está.","Para estar en un lugar hay un verbo, aime, que lleva a- como las acciones: Aime ógape, «estoy en casa»."],"step":"compare"},"a1u03d2.d1":{"id":"a1u03d2.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis cuenta ^qué hace él^ a la mañana.)\nLuis: (   ) ha ^ajahu^.","options":["Chepu'ã","Apu'ã","Ipu'ã","Pu'ã"],"answer":2,"why":["Che- es para los estados, como chekane'õ. Levantarse es una acción: lleva a-. Chepu'ã no es «me levanto».","Levantarse es una acción y Luis habla de él mismo: a- + pu'ã = apu'ã, «me levanto». Después se baña: ajahu, también con a-.","I- marca el estado de otra persona, como en ikane'õ. Pu'ã es una acción, y además Luis habla de él.","Pu'ã sin prefijo no dice quién se levanta: le falta la persona, como guata sin a- en la unidad 2."],"step":"drill"},"a1u03d2.d2":{"id":"a1u03d2.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis comió bien y ^está contento^.)\nLuis: (   ), Ana.","options":["Chevy'a","Ivy'a","Avy'a","Vy'a"],"answer":3,"why":["Parece un estado, pero vy'a se conjuga como acción, con a-. Chevy'a no es «estoy contento».","Ivy'a no es «está contento»: vy'a va como acción, y para otra persona es ovy'a, con o-. Además, Luis habla de él.","Vy'a va como una acción, y Luis habla de él: a- + vy'a = avy'a, «estoy contento».","Vy'a solo es «la alegría», la cosa. Le falta la persona: a-."],"step":"drill"},"a1u03d2.d3":{"id":"a1u03d2.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta que su papá ^trabaja^.)\nAna: Che ru (   ).","options":["amba'apo","chemba'apo","mba'apo","omba'apo"],"answer":4,"why":["A- es «yo»: Ana hablaría de ella misma, y habla de su papá.","Che- es para los estados, como chekane'õ, y además dice «yo». Trabajar es una acción, y la hace otra persona: o-.","Mba'apo solo es «trabajo», la cosa, o la raíz sin persona: che ru mba'apo no dice que trabaje. Falta la persona: o-.","Che ru, «mi papá», es otra persona: o- + mba'apo = omba'apo, «trabaja»."],"step":"drill"},"a1u03d2.d4":{"id":"a1u03d2.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le habla a Luis de la fiesta, y Luis ^se acuerda^.)\nLuis: (   ), Ana.","options":["Chemandu'a","Amandu'a","Imandu'a","Mandu'a"],"answer":1,"why":["Acordarse es un estado, de los que van con che-: chemandu'a, «me acuerdo». Luis habla de él.","Acordarse no se conjuga como acción: amandu'a no es «me acuerdo». Va con che-, como chekane'õ.","Imandu'a es «se acuerda», otra persona, con la i- de ikane'õ. Luis habla de él mismo.","Mandu'a solo es «el recuerdo», la cosa: no dice quién se acuerda. Le falta la persona, che-."],"step":"drill"},"a1u03d2.d5":{"id":"a1u03d2.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis vuelve de la cancha al mediodía.)\nLuis: ","after":" ha akaru.","tiles":["che","vare'a"],"bank":[1,0],"hint":"El hambre es un estado, no una acción: el «yo» de los estados va primero, pegado. La acción de al lado, akaru, lleva a-.","full":"(Luis vuelve de la cancha al mediodía.)\nLuis: {Che}vare'a ha akaru.","es":"Luis: Tengo hambre y como.","explain":"che- (yo, me pasa) + vare'a («hambre») = chevare'a, «tengo hambre». El hambre es un estado: lleva che-, no a-. Comer es una acción: por eso akaru lleva a-. En una sola oración están los dos «yo» del guaraní: che- para lo que te pasa y a- para lo que hacés.","step":"drill"},"a1u03d2.d6":{"id":"a1u03d2.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis ve una víbora.)\nLuis: ","after":".","tiles":["a","kyhyje"],"bank":[1,0],"hint":"Tener miedo se conjuga como una acción, igual que avy'a: el prefijo de «yo» va primero, pegado a la raíz.","full":"(Luis ve una víbora.)\nLuis: {A}kyhyje.","es":"Luis: Tengo miedo.","explain":"a- («yo») + kyhyje («tener miedo») = akyhyje, «tengo miedo». Parece un estado, pero kyhyje va con los prefijos de acción, como vy'a: akyhyje, no chekyhyje. Sin tilde: el acento cae en la última vocal.","step":"drill"},"a1u03d2.e1":{"id":"a1u03d2.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Ana: _Avy'a_, Luis.","options":["Me baño, Luis.","Estoy contenta, Luis.","Tengo miedo, Luis.","Estoy cansada, Luis."],"answer":2,"explain":"Vy'a es «alegrarse» y se conjuga como acción: avy'a, «estoy contenta». «Me baño» es ajahu; «tengo miedo», akyhyje; y «estoy cansada», chekane'õ, con che-.","step":"exam"},"a1u03d2.e2":{"id":"a1u03d2.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis está enojado y se va. Lo cuenta él mismo.)\nLuis: (   ) ha aha.","options":["Apochy","Ipochy","Chepochy","Pochy"],"answer":3,"explain":"Estar enojado es un estado, y Luis habla de él mismo: che- + pochy = chepochy. Chepochy ha aha, «estoy enojado y me voy». Apochy no es «estoy enojado»: a- es para las acciones, como aha. Ipochy es «está enojado», otra persona. Y pochy sin marca es solo «el enojo», la cosa: no dice de quién.","step":"exam"},"a1u03d2.e3":{"id":"a1u03d2.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis cuenta qué hace el lunes a la mañana.)\nLuis: Apu'ã ha ","after":".","tiles":["a","mba'apo"],"bank":[1,0],"full":"(Luis cuenta qué hace el lunes a la mañana.)\nLuis: Apu'ã ha {a}mba'apo.","es":"Luis: Me levanto y trabajo.","explain":"a- («yo») va primero y después la raíz mba'apo, «trabajar»: amba'apo, «trabajo». Trabajar es una acción, como levantarse: las dos llevan a-, no che-.","step":"exam"},"a1u03d2.k1":{"id":"a1u03d2.k1","kind":"choice","area":"vocab","label":"Cuál está bien escrita","q":"Ana anota cuatro palabras de su domingo. Solo una está _bien escrita_. ¿Cuál?","options":["akyhyjé","ko'ag̃a","ajahu","aké"],"answer":3,"explain":"Ajahu está bien: va sin tilde porque el acento cae en la última vocal, la u, y en guaraní eso no se marca. Por lo mismo sobra la tilde de akyhyjé y de aké, que es la costumbre del castellano: se escriben akyhyje y ake. A ko'ag̃a, en cambio, le falta la suya: el acento va antes del final, en la primera a, y ahí sí se escribe, ko'ág̃a.","step":"words"},"a1u03d2.r1":{"id":"a1u03d2.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué hace Ana ahora?","options":["Se baña y come.","Duerme.","Baila y canta.","Va a la escuela."],"short":["Se baña y come","Duerme","Baila y canta","A la escuela"],"answer":1,"why":["Ana escribe ajahu ha akaru: a- es «yo», jahu «bañarse» y karu «comer». Se baña y come.","Dormir es ke: ake, «duermo». Ana no lo escribe; escribe que está muy cansada, chekane'õiterei.","Bailar y cantar son ajeroky ha apurahéi, y no están en el mensaje.","Ir es aha, y la escuela, mbo'ehao: ninguna de las dos está en el mensaje. Ana solo dice que se ven esta noche: Jajotopáta ko pyhare."],"explain":"Ana escribe Ko'ág̃a ajahu ha akaru: «ahora me baño y como». Los verbos con a- dicen lo que hace; chekane'õiterei, con che-, dice cómo está: muy cansada.","step":"skill"},"a1u03d3.c1":{"id":"a1u03d3.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis presenta a Rosa, ^su amiga^: «Rosa (   ) che angirũ.»","options":["ha'e","ndaha'éi","ikatupyry"],"answer":1,"why":["Luis dice quién es Rosa: entre Rosa y che angirũ, ha'e hace de «es». Rosa ha'e che angirũ, «Rosa es mi amiga».","Ndaha'éi es «no es», y Rosa sí es su amiga: Luis la presenta como tal.","Ikatupyry es una cualidad, «es hábil», con la i- del día 1. No dice quién es Rosa, y Luis la presenta como su amiga."],"step":"compare"},"a1u03d3.d1":{"id":"a1u03d3.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la fiesta, Juan dice qué es: ^agricultor^.)\nJuan: Che (   ).","options":["aime chokokue","achokokue","ichokokue","chokokue"],"answer":4,"why":["Aime es «estoy», como en Aime ógape, del día 2. Para decir qué sos no va ningún verbo: ni «soy» ni «estoy».","A- es el prefijo de las acciones, como en amba'apo. Chokokue es un sustantivo y no lleva a-.","I- trae a otra persona, «él, ella», como en ikane'õ. Juan habla de él mismo: después de che, el sustantivo va solo.","Para decir qué sos: che y el sustantivo, nada más. Che chokokue, «soy agricultor»."],"step":"drill"},"a1u03d3.d2":{"id":"a1u03d3.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana habla ^de un señor^ que conoce: él es médico.)\nAna: (   ) pohanohára.","options":["Ndaha'éi","Nde","Ha'e","Peẽ"],"answer":3,"why":["Ndaha'éi pohanohára es «no es médico», y el señor sí es médico.","Nde pohanohára es «vos sos médico», hablándole a él. Ana habla de él, no con él.","Ana habla de otra persona: ha'e, «él». Ha'e pohanohára, «él es médico», sin ningún «es».","Peẽ es «ustedes», varias personas a las que les hablás. Es un solo señor, y Ana habla de él."],"step":"drill"},"a1u03d3.d3":{"id":"a1u03d3.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa señala a un muchacho, ^el compañero de Luis^.)\nRosa: Mávapa ha'e?\nLuis: (   ) che irũ.","options":["Che","Ha'e","Nde","Ndaha'éi"],"answer":2,"why":["Che che irũ sería «yo soy mi compañero»: che es «yo» y che irũ, «mi compañero». Así no se dice quién es el muchacho.","Rosa pregunta quién es él, y Luis responde con ha'e y quién es: Ha'e che irũ, «es mi compañero».","Nde che irũ es «vos sos mi compañero», hablándole a Rosa. Luis habla del muchacho.","Ndaha'éi che irũ es «no es mi compañero», y sí lo es: Rosa señala al compañero de Luis."],"step":"drill"},"a1u03d3.d4":{"id":"a1u03d3.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis muestra una foto. Rosa cree que es su mamá, pero ^es su abuela^.)\nLuis: (   ) che sy, ha'e che jarýi.","options":["Ndaha'éi","Nahániri","Ha'e","Che"],"answer":1,"why":["Para negar un «es», ndaha'éi: el nd-…-i de la unidad 2 alrededor de ha'e. Ndaha'éi che sy, «no es mi mamá».","Nahániri es «no», la respuesta suelta a una pregunta de sí o no. Para decir «no es» hace falta ndaha'éi, una sola palabra.","Ha'e che sy es «es mi mamá», y la de la foto no es su mamá: Luis lo niega.","Che che sy sería «yo soy mi mamá». Luis no habla de él mismo: dice quién es la de la foto."],"step":"drill"},"a1u03d3.d5":{"id":"a1u03d3.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis no es profesor.)\nAna: Luis ","after":" mbo'ehára, ha'e pohanohára.","tiles":["nda","ha'e","i"],"bank":[2,0,1],"hint":"El «no» de la unidad 2 tiene dos partes que rodean la palabra: nda- adelante y -i al final.","full":"(Luis no es profesor.)\nAna: Luis {nda}ha'é{i} mbo'ehára, ha'e pohanohára.","es":"Ana: Luis no es profesor, es médico.","explain":"nda- + ha'e + -i = ndaha'éi, «no es»: el «no» de dos partes rodea a ha'e. La -i no se lleva el acento: queda en la e de ha'e, que ya no es la última vocal, y por eso se escribe é: ndaha'éi. Después, sin negación: ha'e pohanohára, «es médico».","step":"drill"},"a1u03d3.d6":{"id":"a1u03d3.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(En la fiesta, Luis dice qué es.)\nLuis: Che ","after":".","tiles":["pohano","hára"],"bank":[1,0],"hint":"-hára, «el que hace», es un sufijo: va después de la raíz, como en mbo'ehára.","full":"(En la fiesta, Luis dice qué es.)\nLuis: Che pohano{hára}.","es":"Luis: Soy médico.","explain":"pohano («curar») + -hára («el que») = pohanohára, «el que cura», el médico, como mbo'ehára, «el que enseña». Con che adelante y sin verbo: Che pohanohára, «soy médico». -hára se lleva el acento: por eso la tilde va en hára, y pohano no lleva ninguna.","step":"drill"},"a1u03d3.e1":{"id":"a1u03d3.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"(Rosa pregunta por un hombre de la foto.)\nLuis: _Ndaha'éi che irũ_.","options":["Es mi compañero.","No es mi compañero.","No es mi mamá.","Mi compañero no está."],"answer":2,"explain":"Ndaha'éi es «no es»: el nd-…-i de la negación alrededor de ha'e. Che irũ es «mi compañero». «Es mi compañero» sería Ha'e che irũ, sin negar; «mi mamá» es che sy; y «no está» hablaría de un lugar, no de quién es alguien.","step":"exam"},"a1u03d3.e2":{"id":"a1u03d3.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la fiesta, una vecina dice qué es: vendedora.)\nVecina: Che (   ).","options":["añemuhára","oñemuhára","iñemuhára","ñemuhára"],"answer":4,"explain":"Para decir qué sos, che y el sustantivo, nada más: Che ñemuhára, «soy vendedora». Añemuhára y oñemuhára llevan a- y o-, los prefijos de las acciones, y ñemuhára es un sustantivo: va sin prefijo. Iñemuhára lleva i-, que es de otra persona, como en ikane'õ.","step":"exam"},"a1u03d3.e3":{"id":"a1u03d3.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Rosa muestra una foto de un señor.)\nRosa: ","after":" che ru, ha'e che angirũ.","tiles":["nda","ha'e","i"],"bank":[1,2,0],"full":"(Rosa muestra una foto de un señor.)\nRosa: {Nda}ha'é{i} che ru, ha'e che angirũ.","es":"Rosa: No es mi papá, es mi amigo.","explain":"nda- va primero, después ha'e y al final -i: ndaha'éi, «no es». El «no» del guaraní tiene dos partes que rodean la palabra. La tilde va en la é porque -i no se lleva el acento. Después, sin negar: ha'e che angirũ, «es mi amigo».","step":"exam"},"a1u03d3.k1":{"id":"a1u03d3.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"En la fiesta, Ana te presenta a una _señora_, la mamá de Luis. ¿Cómo se escribe en guaraní?","options":["kuñacarai","kunakarai","kuñakarai","kuñakarãi"],"answer":3,"explain":"Se escribe kuñakarai: kuña, «mujer», con ñ, y karai, «señor», con k, porque la c no es una letra del guaraní. Kunakarai pierde la ñ. Kuñakarãi le pone una tilde nasal a la a: karãi es otra palabra, «arañar». Karai, «señor», es todo oral: ka-ra-i, con el acento al final y sin ninguna marca.","step":"words"},"a1u03d3.r1":{"id":"a1u03d3.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué es Lucas?","options":["Médico.","Profesor.","Agricultor."],"answer":1,"why":["Ana dice Lucas ha'e che irũ, «Lucas es mi compañero», y enseguida Ha'e pohanohára: ese ha'e es Lucas, y pohanohára es «médico».","Mbo'ehára, «profesora», es la mamá de Ana: de ella dice Ha'e mbo'ehára, antes de presentar a Lucas.","Agricultor es chokokue, y nadie lo dice en la fiesta."],"script":["Narrador: En la fiesta de San Juan. Ana presenta a dos personas. ¿Qué es Lucas?","Mujer: Ha'e che sy, Luis. Ha'e mbo'ehára.","Hombre: Mba'éichapa, kuñakarai.","Mujer: Ha Lucas ha'e che irũ. Ha'e pohanohára.","Hombre: Maitei, Lucas."],"step":"skill"},"a1u03d4.c1":{"id":"a1u03d4.c1","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(Rosa es ^profesora^.)\nAna: Ndépa pohanohára?\nRosa: (   )","options":["Mba'éichapa?","Nahániri, che mbo'ehára.","Héẽ, chekane'õ."],"answer":2,"why":["Mba'éichapa? es un saludo y una pregunta abierta: no responde a una pregunta de sí o no.","Ndépa pohanohára? pregunta sí o no por lo que es Rosa. Ella responde que no y dice qué es: Nahániri, che mbo'ehára, «no, soy profesora».","Héẽ diría que sí es médica, y Rosa es profesora. Además, chekane'õ habla de cansancio, y Ana preguntó qué es Rosa, no cómo está."],"step":"compare"},"a1u03d4.d1":{"id":"a1u03d4.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis quiere saber si ^el papá de Ana está enfermo^.)\nLuis: (   ) nde ru?","options":["Rasýpa","Pa hasy","Hasýpa","Ikane'õpa"],"answer":3,"why":["Rasy es la forma que va con che- y nde-, como réra en che réra y nde réra: cherasy. Para otra persona, nde ru, va h-: hasy, como héra.","-pa no va delante ni suelto: es un sufijo y se pega al final de la palabra que preguntás, Hasýpa.","Luis pregunta por hasy, «está enfermo», y -pa va pegado a esa palabra: Hasýpa nde ru?, «¿está enfermo tu papá?». Hasy termina en y tónica; con -pa esa y ya no es la última vocal y se escribe la tilde: hasýpa.","Ikane'õpa pregunta si está cansado, y Luis quiere saber si está enfermo: hasy."],"step":"drill"},"a1u03d4.d2":{"id":"a1u03d4.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana quiere saber si Luis es médico. ^Se lo pregunta a él^.)\nAna: (   ) pohanohára?","options":["Ndépa","Ha'épa","Ndéve","Mávapa"],"answer":1,"why":["Ana le pregunta a Luis por él mismo: nde + -pa = Ndépa, con tilde porque la e ya no es la última vocal. Ndépa pohanohára?, «¿vos sos médico?».","Ha'épa pohanohára? pregunta por otra persona: ha'e, «él, ella». Ana le habla a Luis y pregunta por él mismo: nde.","Ndéve es «a vos», como en Aguyje ndéve (unidad 1): lleva -ve, no -pa, y no pregunta nada.","Mávapa pohanohára? es «¿quién es médico?»: una pregunta abierta, que no se responde con sí o no. Ana quiere saber si Luis lo es: Ndépa."],"step":"drill"},"a1u03d4.d3":{"id":"a1u03d4.d3","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"Juan: Nde piko pohanohára?\nAna: (   ), ^che mbo'ehára^.","options":["Héẽ","Nahániri","Upéicha","Aguyje"],"answer":2,"why":["Héẽ es «sí», pero Ana dice che mbo'ehára, «soy profesora»: no es médica. Responde que no.","Juan pregunta, con sorpresa, si Ana es médica. Ella es profesora, así que responde Nahániri, «no», y dice lo que sí es.","Upéicha confirma, como en Héẽ, upéicha, «sí, así es»: diría que Ana es médica, y ella dice que es profesora.","Aguyje es «gracias»: no responde que sí ni que no. Ana corrige a Juan: Nahániri."],"step":"drill"},"a1u03d4.d4":{"id":"a1u03d4.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa le ofrece chipá, pero Juan ^no tiene hambre^.)\nRosa: [Reipotápa|¿querés?] chipa?\nJuan: Nahániri, (   ).","options":["chevare'a","nachevare'ái","ndavare'ái","ndachevare'ái"],"answer":4,"why":["Chevare'a es «tengo hambre»: afirma, y Juan no tiene hambre.","na- va solo delante de una palabra nasal, como en nachemandu'ái. Vare'a es oral: nda-.","Ndavare'ái conjuga vare'a como una acción: nd- + a- + vare'a + -i, con la a- de ndahái, «no voy» (unidad 2). Vare'a es un estado y lleva che-: ndachevare'ái.","Vare'a es oral, sin ~ ni m, n, ñ: el «no» de dos partes es nda-…-i alrededor de chevare'a. Ndachevare'ái, «no tengo hambre». La tilde aparece en la á porque -i no se lleva el acento."],"step":"drill"},"a1u03d4.d5":{"id":"a1u03d4.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana pregunta si llegó el médico.)\nAna: ","after":" pohanohára?","tiles":["o","g̃uahẽ","pa"],"bank":[2,0,1],"hint":"El prefijo de «él, ella» va primero, pegado a g̃uahẽ. -pa cierra la palabra que pregunta.","full":"(Ana pregunta si llegó el médico.)\nAna: {O}g̃uahẽ{pa} pohanohára?","es":"Ana: ¿Llegó el médico?","explain":"o- («él, ella») + g̃uahẽ («llegar») + -pa (pregunta) = Og̃uahẽpa, «¿llegó?». -pa va pegado a la palabra que pregunta, acá la primera, y la persona, pohanohára, viene después. El acento sigue en la ẽ: la ~ ya lo marca y no se agrega tilde.","step":"drill"},"a1u03d4.d6":{"id":"a1u03d4.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Rosa pregunta por la fiesta, y Juan no se acuerda.)\nRosa: Nemandu'ápa?\nJuan: ","after":".","tiles":["na","che","mandu'a","i"],"bank":[3,1,0,2],"hint":"El «no» tiene dos partes: una al principio y otra al final. En el medio van che- y el estado.","full":"(Rosa pregunta por la fiesta, y Juan no se acuerda.)\nRosa: Nemandu'ápa?\nJuan: {Na}chemandu'á{i}.","es":"Rosa: ¿Te acordás?\nJuan: No me acuerdo.","explain":"na- + che- + mandu'a («acordarse») + -i = Nachemandu'ái, «no me acuerdo». Mandu'a es nasal, con m y nd: por eso va na- y no nda-. -i no se lleva el acento: queda en la a final de mandu'a, que ya no es la última vocal, y se escribe á.","step":"drill"},"a1u03d4.e1":{"id":"a1u03d4.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Luis: Og̃uahẽ pohanohára.\nAna: _Añetépa?_","options":["¿Ahora?","¿Quién?","¿De verdad?","¿Dónde está?"],"answer":3,"explain":"Añete es «verdad, cierto», y -pa lo vuelve pregunta: Añetépa?, «¿de verdad?». Ahora es ko'ág̃a, ¿quién? es Mávapa y ¿dónde? es Moõpa: ninguna de esas palabras está en lo subrayado.","step":"exam"},"a1u03d4.e2":{"id":"a1u03d4.e2","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(La mamá de Luis está cansada.)\nAna: Ikane'õpa nde sy?\nLuis: (   )","options":["Héẽ, kane'õ.","Héẽ, nekane'õ.","Nahániri, ikane'õ.","Héẽ, ikane'õ."],"answer":4,"explain":"Ana pregunta por la mamá de Luis, otra persona, y ella sí está cansada: Héẽ, ikane'õ, «sí, está cansada», con la i- de la tercera persona. Héẽ, kane'õ no dice de quién es el cansancio, le falta la i-; Héẽ, nekane'õ le diría a Ana que ella está cansada; y Nahániri, ikane'õ se contradice: dice «no» y después «está cansada».","step":"exam"},"a1u03d4.e3":{"id":"a1u03d4.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis comió hace un rato.)\nLuis: ","after":".","tiles":["nda","che","vare'a","i"],"bank":[2,0,3,1],"full":"(Luis comió hace un rato.)\nLuis: {Nda}chevare'á{i}.","es":"Luis: No tengo hambre.","explain":"nda- + che- + vare'a («hambre») + -i = Ndachevare'ái, «no tengo hambre». El «no» tiene dos partes que rodean a che- y al estado. Vare'a es oral, sin ~ ni m, n, ñ: por eso va nda- y no na-. -i no se lleva el acento: queda en la a final de vare'a y se escribe á.","step":"exam"},"a1u03d4.k1":{"id":"a1u03d4.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana escribe que el médico llegó _ahora_. ¿Cómo se escribe en guaraní?","options":["ko'ág̃a","koág̃a","ko'aga","ko'ãga"],"answer":1,"explain":"Ahora es ko'ág̃a: con puso entre la o y la a, con la tilde en la á, porque el acento no cae en la última vocal, y con la g̃, la g con nariz. Koág̃a perdió el puso y ko'aga no tiene ninguna marca. Ko'ãga pone la ~ en la primera a: ahí va la tilde del acento, y la nariz va después, en la g̃. Los diarios la escriben en la última a: ko'ágã.","step":"words"},"a1u03d4.r1":{"id":"a1u03d4.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quién llega ahora?","options":["Ana.","El médico.","La mamá de Ana.","La abuela."],"short":["Ana","El médico","La mamá","La abuela"],"answer":2,"why":["Ana es la que pregunta Og̃uahẽpa pohanohára?: quiere saber si llegó el médico. No dice que ella llegue a ningún lado.","Ana pregunta Og̃uahẽpa pohanohára?, «¿llegó el médico?», y mamá responde Héẽ, og̃uahẽ ko'ág̃a: sí, llegó ahora. El que llega es el médico.","De la mamá habla la última pregunta, Nekane'õpa?, «¿estás cansada?». Ella responde Nahániri, «no», y agrega Chevare'a, «tengo hambre». No dice que llegue.","La abuela, nde jarýi, está enferma, hasy: por eso viene el médico. La que llega no es ella."],"explain":"Ana pregunta Og̃uahẽpa pohanohára? y mamá responde Héẽ, og̃uahẽ ko'ág̃a: el médico llegó ahora. La abuela, nde jarýi, está enferma (hasy), y la mamá no está cansada: tiene hambre (chevare'a).","step":"skill"},"a1u03d5.c1":{"id":"a1u03d5.c1","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Luis escribe en la pizarra: jaguá, óga, ikatupa. Se dicen ^ja-GUA, Ó-ga, i-ka-TÚ-pa^. ¿Cuál de las tres está _bien escrita_?","options":["jaguá","óga","ikatupa"],"answer":2,"why":["Jagua es aguda, ja-GUA, y en guaraní la aguda no lleva tilde. Esa tilde es la costumbre del castellano.","Óga se dice Ó-ga: el acento va antes de la última vocal, y por eso se escribe la tilde. Está bien.","Ikatu es aguda y va sin tilde, pero con -pa la u tónica ya no es la última vocal y hay que escribir la tilde: ikatúpa."],"step":"compare"},"a1u03d5.d1":{"id":"a1u03d5.d1","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Rosa escribe cuatro palabras que se dicen ^con el acento en la última vocal^: ja-GUA, ka-ra-I, mi-TÃ, te-re-RE. Solo una está _bien escrita_. ¿Cuál?","options":["terere","jaguá","karái","mitá"],"answer":1,"why":["Terere es aguda, te-re-RE, y en guaraní la aguda no lleva tilde. El castellano escribe tereré; el guaraní, terere.","Jagua es aguda, ja-GUA: sin tilde. Jaguá lleva la tilde del castellano, que acá sobra.","Karai se dice ka-ra-I, con el acento al final: sin tilde. Karái movería el acento a la a del medio.","Mitã es aguda, pero su a es nasal: lleva la ~, y una vocal con ~ nunca lleva tilde. Mitá cambia la ~ por la tilde y pierde la nasal."],"step":"drill"},"a1u03d5.d2":{"id":"a1u03d5.d2","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Luis escribe cuatro palabras que se dicen ^con el acento antes de la última vocal^: na-HÁ-ni-ri, mbo-'e-HÁ-ra, TÉ-ra, pu-ra-HÉI. Solo una está _bien escrita_. ¿Cuál?","options":["nahaniri","mbo'éhara","terá","purahéi"],"answer":4,"why":["Sin tilde, nahaniri se leería na-ha-ni-RI, como una aguda. El acento va en la segunda a, y por eso lleva tilde: nahániri.","La tilde está, pero en otra vocal: mbo'éhara se leería mbo-'É-ha-ra. El acento va en la a de hára: mbo'ehára.","Terá lleva la tilde en la última vocal, donde el guaraní no la escribe nunca, y así se leería te-RA. El acento va en la e: téra.","Purahéi se dice pu-ra-HÉI: el acento cae antes de la última vocal y se escribe la tilde, en la e del diptongo. Está bien."],"step":"drill"},"a1u03d5.d3":{"id":"a1u03d5.d3","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Luis escribe cuatro lugares con -pe, «en». ^-pe no se lleva el acento^. Solo uno está _bien escrito_. ¿Cuál?","options":["kotype","ogápe","Itauguápe","mbo'ehaope"],"answer":3,"why":["Koty lleva el acento en la y final (unidad 2). Con -pe esa y ya no es la última vocal y hay que escribir la tilde: kotýpe.","Óga ya tenía su tilde en la o, y con -pe se queda ahí: ógape. Ogápe la mueve a la a, y así se leería o-GÁ-pe.","Itaugua es aguda y va sin tilde. Con -pe, la a tónica ya no es la última vocal y se escribe la tilde: Itauguápe. Está bien.","Mbo'ehao lleva el acento en la o final (unidad 2). Con -pe esa o queda adentro de la palabra y se escribe mbo'ehaópe: acá falta la tilde."],"step":"drill"},"a1u03d5.d4":{"id":"a1u03d5.d4","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"Ana escribe «Aju Paraguáigui», «vengo de Paraguay». ^Paraguái ya tenía tilde^. ¿Qué pasa con la _tilde_ al agregar -gui?","options":["Se queda en la á: -gui no se lleva el acento.","Se mueve a -gui, que ahora es el final de la palabra.","Se borra: con sufijo no hay tilde.","Se escriben dos: Paraguáiguí."],"answer":1,"why":["Paraguái ya lleva su tilde en la á. -gui no se lleva el acento, así que todo queda igual: Paraguáigui. Lo mismo pasa con -pe: Paraguáipe.","-gui nunca se lleva el acento: sigue en la á de Paraguái. El que sí se lo lleva es -gua, y por eso Paraguaigua va sin tilde.","La tilde no se borra: el acento sigue en la á, que no es la última vocal, y por eso se escribe. Solo se pierde con un sufijo que se lleva el acento, como -gua.","Una palabra lleva una sola tilde, en la vocal tónica. Paraguáiguí tendría dos, y -gui no se lleva el acento."],"step":"drill"},"a1u03d5.d5":{"id":"a1u03d5.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis va a Ypacaraí.)\nLuis: Aha ","after":".","tiles":["Ypakarai","pe"],"bank":[1,0],"hint":"-pe va después del lugar, pegado. Después fijate dónde queda el acento: ¿sigue en la última vocal?","full":"(Luis va a Ypacaraí.)\nLuis: Aha {Ypakaraípe}.","es":"Luis: Voy a Ypacaraí.","explain":"Ypakarai («Ypacaraí») + -pe («a») = Ypakaraípe. Ypakarai es aguda, y-pa-ka-ra-I, y sola va sin tilde. -pe no se lleva el acento: queda en esa i, que ya no es la última vocal, y por eso ahora se escribe í.","step":"drill"},"a1u03d5.d6":{"id":"a1u03d5.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana le pregunta a Luis si conoce Caacupé.)\nAna: ","after":" Ka'akupe?","tiles":["reikuaa","pa"],"bank":[1,0],"hint":"-pa cierra la palabra que pregunta y no se lleva el acento. ¿En qué vocal queda?","full":"(Ana le pregunta a Luis si conoce Caacupé.)\nAna: {Reikuaápa} Ka'akupe?","es":"Ana: ¿Conocés Caacupé?","explain":"reikuaa («conocés, sabés») + -pa (pregunta) = Reikuaápa. Reikuaa termina en a tónica, rei-kua-A. -pa no se lleva el acento: queda en esa a, que ya no es la última vocal, y se escribe á. Ka'akupe, sola, sigue sin tilde: es aguda.","step":"drill"},"a1u03d5.e1":{"id":"a1u03d5.e1","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Rosa anota en su cuaderno cuatro palabras que ya conocés. Solo una está _bien escrita_. ¿Cuál?","options":["ndeve","okarú","jarýi","mba'eichapa"],"answer":3,"explain":"Jarýi lleva el acento en la y, antes de la última vocal, y por eso se escribe la tilde. Ndeve y mba'eichapa también lo llevan antes del final y necesitan la suya: ndéve y mba'éichapa. Okaru, en cambio, es aguda, o-ka-RU, y va sin tilde: la de okarú es la costumbre del castellano.","step":"exam"},"a1u03d5.e2":{"id":"a1u03d5.e2","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Cuatro palabras con sufijo. Solo una está _bien escrita_. ¿Cuál?","options":["reikuaapa","tetáme","Paraguaigui","oĩpa"],"answer":4,"explain":"En oĩpa la vocal tónica es la ĩ, con ~: una vocal con ~ nunca lleva tilde, así que con -pa no cambia nada. En reikuaapa y Paraguaigui la vocal tónica es oral y no es la última, así que la tilde tiene que estar: reikuaápa y Paraguáigui, que conserva la de Paraguái. Y tetáme cambia la ~ por una tilde: es tetãme, con la ã nasal.","step":"exam"},"a1u03d5.e3":{"id":"a1u03d5.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis va a Caacupé.)\nAna: Luis oho ","after":".","tiles":["Ka'akupe","pe"],"bank":[1,0],"full":"(Luis va a Caacupé.)\nAna: Luis oho {Ka'akupépe}.","es":"Ana: Luis va a Caacupé.","explain":"Ka'akupe («Caacupé») + -pe («a») = Ka'akupépe. Ka'akupe es aguda, ka-'a-ku-PE, y sola va sin tilde. -pe no se lleva el acento: queda en la e final de Ka'akupe, que ya no es la última vocal, y por eso se escribe é.","step":"exam"},"a1u03d5.k1":{"id":"a1u03d5.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"En el mapa, Ana señala el lago: «_Ypacaraí_». ¿Cómo se escribe en guaraní?","options":["Ipakaraí","Ypacarai","Ypakarai","Ypakarãi"],"answer":3,"explain":"Ypakarai: con y, la sexta vocal, con k y sin tilde, porque es aguda y en guaraní la aguda no lleva tilde; la de Ypacaraí es del castellano, aunque a veces se copia. Ipakaraí cambia la y por i y le pone la tilde castellana. Ypacarai usa la c, que no es una letra del guaraní. Ypakarãi le pone una ~ a una vocal que no es nasal, y la ~ cambia el sonido.","step":"words"},"a1u03d5.r1":{"id":"a1u03d5.r1","kind":"choice","area":"listening","label":"Buscar el dato","q":"¿Adónde va la mujer?","options":["A Itauguá.","A Caacupé.","A Ypacaraí."],"answer":2,"why":["Itauguágui lleva -gui, «de»: Itauguá es de donde viene la mujer, no adónde va.","La mujer dice Ko'ág̃a aha Ka'akupépe: aha es «voy» y -pe, «a». Va a Caacupé.","Ypakaraípe lo dice el hombre, y habla de él: Ha che aha Ypakaraípe, «y yo voy a Ypacaraí»."],"explain":"La mujer dice Aju Itauguágui, «vengo de Itauguá», y Ko'ág̃a aha Ka'akupépe, «ahora voy a Caacupé»: -gui es de donde viene y -pe, adónde va. Ypacaraí es adonde va el hombre.","script":["Narrador: En la terminal. ¿Adónde va la mujer?","Mujer: Aju Itauguágui. Ko'ág̃a aha Ka'akupépe.","Hombre: Ha che aha Ypakaraípe.","Narrador: ¿Adónde va la mujer?"],"step":"skill"},"a1u03d6.c1":{"id":"a1u03d6.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis muestra una foto. Rosa cree que es la mamá de Luis, pero ^es su profesora^.)\nLuis: (   ) che sy, ha'e che mbo'ehára.","options":["Ha'e","Ndaha'éi","Ndaikatúi"],"answer":2,"why":["Ha'e che sy diría «es mi mamá», y la de la foto es su profesora: Luis lo niega.","Rosa se equivoca, y Luis niega el «es» con ndaha'éi, una sola palabra: Ndaha'éi che sy, «no es mi mamá». Después, sin negar: ha'e che mbo'ehára, «es mi profesora».","Ndaikatúi es «no se puede»: el nd-…-i rodea a ikatu, no a ha'e. Ndaikatúi che sy no dice nada. Para negar un «es» va ndaha'éi."],"step":"compare"},"a1u03d6.d1":{"id":"a1u03d6.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana habla de ^su abuela^, que está enferma.)\nAna: Che jarýi (   ).","options":["cherasy","irasy","hasy","nderasy"],"answer":3,"why":["Cherasy es «estoy enferma»: Ana hablaría de ella misma. Acá habla de su abuela.","Rasy es de las palabras con tres formas, como téra, che réra, héra: tasy, cherasy, hasy. Para él o ella es hasy: irasy no existe.","Che jarýi, «mi abuela», es otra persona, y para él o ella rasy tiene su propia forma, hasy, como réra tiene héra. Che jarýi hasy, «mi abuela está enferma».","Nderasy es «estás enferma», hablándole a ella. Ana habla de su abuela, no con ella."],"step":"drill"},"a1u03d6.d2":{"id":"a1u03d6.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis le cuenta a Ana ^qué hace él mismo^: trabaja.)\nLuis: Ko'ág̃a (   ), Ana.","options":["amba'apo","chemba'apo","omba'apo","mba'apo"],"answer":1,"why":["Trabajar es una acción y Luis habla de él mismo: a- + mba'apo = amba'apo, «trabajo». Ko'ág̃a amba'apo, «ahora trabajo».","Che- es para los estados, como chekane'õ. Trabajar es una acción y lleva a-: chemba'apo no es «yo trabajo».","O- es «él, ella»: omba'apo es «trabaja», de otra persona. Luis habla de él mismo.","Mba'apo sin prefijo es «trabajo», la cosa, o la raíz sin persona: no dice quién trabaja."],"step":"drill"},"a1u03d6.d3":{"id":"a1u03d6.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa quiere saber si Juan está enojado. ^Se lo pregunta a él^.)\nRosa: (   ), Juan?","options":["Repochýpa","Ipochýpa","Nepochýpa","Ndepochýpa"],"answer":4,"why":["Re- es el «vos» de las acciones, como en rekaru, «comés». Pochy es un estado, y con los estados el «vos» es nde-, no re-: Repochýpa no va.","I- es «él, ella»: Ipochýpa pregunta si otra persona está enojada. Rosa le pregunta a Juan por él mismo: nde-.","Ne- reemplaza a nde- solo antes de una palabra nasal, como nekane'õ. Pochy es oral, sin ~ ni m, n, ñ: queda nde-.","Rosa le habla a Juan, de vos a vos, y de un estado: nde- + pochy, y -pa pegado al estado, que es lo que Rosa pregunta. La y tónica ya no es la última vocal, así que aparece la tilde: Ndepochýpa?, «¿estás enojado?»."],"step":"drill"},"a1u03d6.d4":{"id":"a1u03d6.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la fiesta, ^Luis dice qué es él mismo^: médico.)\nLuis: (   ) pohanohára.","options":["Aime","Ha'e","Che","Ndaha'éi"],"answer":3,"why":["Aime es «estoy» en un lugar, como en Aime ógape. Para decir qué sos no va ningún verbo: ni «soy» ni «estoy».","Ha'e pohanohára es «él es médico», de otra persona. Luis habla de él mismo: che.","Para decir qué sos: che y el sustantivo, nada más. Che pohanohára, «soy médico».","Ndaha'éi pohanohára niega: «no es médico» o «no soy médico». Luis sí es médico, y eso es lo que dice."],"step":"drill"},"a1u03d6.d5":{"id":"a1u03d6.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis ve que Ana sonríe.)\nLuis: ","after":", Ana?","tiles":["re","vy'a","pa"],"bank":[1,2,0],"hint":"Vy'a va como una acción: el «vos» es re-, y va primero. -pa va al final.","full":"(Luis ve que Ana sonríe.)\nLuis: {Re}vy'á{pa}, Ana?","es":"Luis: ¿Estás contenta, Ana?","explain":"re- («vos») + vy'a («alegrarse») + -pa (pregunta) = Revy'ápa, «¿estás contenta?». Vy'a va como una acción: por eso lleva re-, el «vos» de las acciones, y no nde-. -pa no se lleva el acento: queda en la a de vy'a, que ya no es la última vocal, y se escribe á.","step":"drill"},"a1u03d6.d6":{"id":"a1u03d6.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis pregunta si llegó la mamá de Ana.)\nLuis: ","after":" nde sy?","tiles":["o","g̃uahẽ","pa"],"bank":[2,1,0],"hint":"Nde sy es otra persona: el verbo empieza con el prefijo de «él, ella». -pa va al final.","full":"(Luis pregunta si llegó la mamá de Ana.)\nLuis: {O}g̃uahẽ{pa} nde sy?","es":"Luis: ¿Llegó tu mamá?","explain":"o- («él, ella») + g̃uahẽ («llegar») + -pa (pregunta) = Og̃uahẽpa, «¿llegó?». Nde sy, «tu mamá», es otra persona: por eso el verbo lleva o-. -pa va pegado al verbo, y nde sy viene después. Acá no aparece ninguna tilde: el acento cae en la ẽ, y la ~ ya lo marca. Compará con Revy'ápa, donde la a es oral y recibe la tilde.","step":"drill"},"a1u03d6.e1":{"id":"a1u03d6.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: Nemandu'ápa, Juan?\nJuan: _Nachemandu'ái_.","options":["No me acuerdo.","Me acuerdo.","No sé.","No tengo hambre."],"answer":1,"explain":"Na-…-i es el «no» de dos partes alrededor de che- y mandu'a, «acordarse»: nachemandu'ái, «no me acuerdo». Mandu'a es nasal, por eso va na- y no nda-. «Me acuerdo» sería chemandu'a, sin negar; «no sé» es ndaikuaái; y «no tengo hambre», ndachevare'ái, con nda- porque vare'a es oral.","step":"exam"},"a1u03d6.e2":{"id":"a1u03d6.e2","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Luis repasa cuatro palabras de la semana. Solo una está _bien escrita_. ¿Cuál?","options":["ndaha'ei","Ka'akupé","añetepa","hasýpa"],"answer":4,"explain":"Hasýpa está bien: hasy es aguda, ha-SY, y sola va sin tilde, pero -pa no se lleva el acento, así que la y tónica ya no es la última vocal y se escribe ý. Por lo mismo les falta la tilde a añetepa y a ndaha'ei: son añetépa, con -pa, y ndaha'éi, con -i. Ka'akupé lleva la tilde del castellano: en guaraní es aguda y va sin tilde, Ka'akupe.","step":"exam"},"a1u03d6.e3":{"id":"a1u03d6.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(En la fiesta, Rosa cree que la señora es la abuela de Luis.)\nLuis: ","after":" che jarýi, ha'e che sy.","tiles":["nda","ha'e","i"],"bank":[1,0,2],"full":"(En la fiesta, Rosa cree que la señora es la abuela de Luis.)\nLuis: {Nda}ha'é{i} che jarýi, ha'e che sy.","es":"Luis: No es mi abuela, es mi mamá.","explain":"nda- va primero, después ha'e y al final -i: ndaha'éi, «no es». El «no» del guaraní tiene dos partes que rodean la palabra. La tilde va en la é porque -i no se lleva el acento. Después, sin negar: ha'e che sy, «es mi mamá».","step":"exam"},"a1u03d6.k1":{"id":"a1u03d6.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana escribe que su mamá _llega_ ahora. ¿Cómo se escribe en guaraní?","options":["oguahe","og̃uahẽ","og̃uahe","ogüahẽ"],"answer":2,"explain":"Llega es og̃uahẽ: con la g̃, la g con nariz, y con la ẽ nasal, que marca el acento. Oguahe no tiene ninguna marca. Og̃uahe perdió la ~ de la ẽ, que es la vocal tónica. Ogüahẽ usa la diéresis del castellano, que no es una letra del guaraní. Los diarios escriben oguahẽ, sin la ~ en la g, y también lo aceptamos.","step":"words"},"a1u03d6.r1":{"id":"a1u03d6.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quién está enfermo?","options":["La mamá de Ana.","La abuela de Ana.","Ana.","Luis."],"short":["La mamá","La abuela","Ana","Luis"],"answer":2,"why":["Che sy ikane'õ: la mamá está cansada, con i- y kane'õ, «cansancio». Cansada, no enferma.","Ana escribe che jarýi hasy: hasy es «está enferma», la forma de rasy para él o ella, como héra. La enferma es su abuela.","De ella misma, Ana dice Chey'uhéi, «tengo sed»: ni cansancio ni enfermedad.","Luis pregunta, y al final responde Héẽ, «sí», y Jaha, «vamos». Por el tereré pregunta Ana: Oĩpa terere? De cómo está él, Luis no dice nada."],"explain":"Ana escribe Che sy ikane'õ ha che jarýi hasy: su mamá está cansada (ikane'õ) y su abuela está enferma (hasy). Ella misma solo tiene sed, chey'uhéi.","step":"skill"},"a1u03t.1":{"id":"a1u03t.1","kind":"choice","area":"vocab","label":"Qué significa","q":"(Es domingo a la tarde. Ana invita a Luis a la cancha.)\nLuis: _Chekaigue_, Ana.","options":["Estoy enojado, Ana.","Estoy desganado, Ana.","Tengo frío, Ana.","Tengo sed, Ana."],"answer":2,"explain":"Chekaigue es che-, «yo, me pasa», más kaigue, «desgano»: «estoy desganado, sin ganas». Es muy paraguayo: en castellano también se dice «ando kaigue». Enojado sería chepochy; frío, chero'y; y sed, chey'uhéi.","step":"test","unit":3},"a1u03t.2":{"id":"a1u03t.2","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa oye un ruido de noche y dice: «_Tengo miedo_.» ¿Cómo se escribe en guaraní?","options":["akyjyhe","akihyje","akyyje","akyhyje"],"answer":4,"explain":"Tengo miedo es akyhyje: a-, «yo», más kyhyje, «tener miedo», con h y después j. La h siempre suena, como un soplo, y la j suena como la y de «yo» en boca de un paraguayo. Akyjyhe cambia de lugar la h y la j. Akihyje cambia la primera y por i, que en guaraní es otra vocal. Y akyyje se come la h, que nunca es muda.","step":"test","unit":3},"a1u03t.3":{"id":"a1u03t.3","kind":"choice","area":"vocab","label":"Elegí la palabra","q":"(En la fiesta de San Juan, Rosa presenta a su mamá, que es médica.)\nRosa: Che sy (   ).","options":["pohanohára","chokokue","ñemuhára","mbo'ehára"],"answer":1,"explain":"Médica es pohanohára: pohano, «curar», más -hára, «la que». Che sy pohanohára, «mi mamá es médica», con el sustantivo al lado y sin ningún «es». Chokokue es «agricultora»; ñemuhára, «vendedora»; y mbo'ehára, «profesora».","step":"test","unit":3},"a1u03t.4":{"id":"a1u03t.4","kind":"choice","area":"vocab","label":"Qué significa","q":"(Juan y Rosa esperan al médico. Juan mira por la ventana.)\nJuan: _Og̃uahẽ ko'ág̃a_.","options":["Viene mañana.","Está en casa.","Llega ahora.","Se va ahora."],"answer":3,"explain":"Og̃uahẽ es o-, «él», más g̃uahẽ, «llegar»: «llega». Ko'ág̃a es «ahora»: el médico llega ahora. «Está en casa» sería oĩ ógape, «se va» es oho, y «mañana» no aparece: ko'ág̃a es ahora.","step":"test","unit":3},"a1u03t.5":{"id":"a1u03t.5","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana y su familia van a la peregrinación de _Caacupé_. ¿Cómo se escribe en guaraní?","options":["Kaakupe","Ka'acupe","Ka'akupe","Ka'akupẽ"],"answer":3,"explain":"Ka'akupe: con k, con el puso entre las dos a y sin ninguna marca, porque es aguda, Ka-'a-ku-PE, y en guaraní la aguda no lleva tilde; la tilde de Caacupé es del castellano. Kaakupe pierde el puso, que corta la voz entre las dos a. Ka'acupe usa la c, que no es una letra del guaraní. Y Ka'akupẽ le pone una ~ a una vocal que no es nasal, y la ~ cambia el sonido.","step":"test","unit":3},"a1u03t.6":{"id":"a1u03t.6","kind":"choice","area":"vocab","label":"Qué significa","q":"(Rosa llega del trabajo y apaga la música.)\nRosa: _Cheakãrasy_.","options":["Me duele la cabeza.","Estoy enferma.","Estoy cansada.","Tengo hambre."],"answer":1,"explain":"Cheakãrasy es che-, «yo, me pasa», más akã, «cabeza», y rasy, «dolor»: «me duele la cabeza», todo en una sola palabra. «Estoy enferma» sería cherasy, sin akã; «estoy cansada», chekane'õ; y «tengo hambre», chevare'a.","step":"test","unit":3},"a1u03t.7":{"id":"a1u03t.7","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta por qué su amigo no vino hoy a la escuela: está enfermo.)\nAna: Che angirũ (   ).","options":["nderasy","irasy","tasy","hasy"],"answer":4,"explain":"Che angirũ, «mi amigo», es otra persona, y rasy es de las palabras con tres formas, como téra, che réra, héra: tasy, cherasy, hasy. Para él o ella va hasy: Che angirũ hasy, «mi amigo está enfermo». Irasy no existe: esta palabra no lleva i-. Nderasy es «estás enfermo», hablándole a él, y Ana habla de él. Y tasy es la palabra suelta, «dolor, enfermedad», que no dice de quién.","step":"test","unit":3},"a1u03t.8":{"id":"a1u03t.8","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Es mediodía. Luis cuenta qué hace él a esta hora.)\nLuis: (   ) ha ake.","options":["Chekaru","Akaru","Ikaru","Karu"],"answer":2,"explain":"Comer es una acción y Luis habla de él mismo: a- más karu, «comer». Akaru ha ake, «como y duermo». Che- es para los estados y las cualidades, como chekane'õ: chekaru no es «como». Dice una cualidad, «soy comilón», y no lo que Luis hace a esta hora. Ikaru lleva i-: habla de otra persona, y tampoco dice una acción. Y karu sin prefijo no dice quién come.","step":"test","unit":3},"a1u03t.9":{"id":"a1u03t.9","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis le muestra a Rosa una foto de su mamá, Marta.)\nLuis: Marta (   ) che sy.","options":["ha'e","che","ikane'õ","ndépa"],"answer":1,"explain":"Luis dice quién es Marta: entre Marta y che sy, ha'e hace de «es». Marta ha'e che sy, «Marta es mi mamá». Che es «yo» y no une nada. Ikane'õ es un estado, «está cansada», y acá Luis dice quién es ella, no cómo está. Ndépa, «¿vos…?», pregunta, y Luis afirma.","step":"test","unit":3},"a1u03t.10":{"id":"a1u03t.10","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(En el mercado, Juan conoce a Marta.)\nJuan: Nde piko chokokue, Marta?\nMarta: (   ), che ñemuhára.","options":["Upéicha","Aguyje","Nahániri","Héẽ"],"answer":3,"explain":"Juan pregunta con piko, que suele sumar sorpresa, si Marta es agricultora, chokokue. Ella dice che ñemuhára, «soy vendedora»: es otra cosa, así que responde que no, Nahániri, y dice lo que sí es. Héẽ y Upéicha dirían que sí es agricultora, y Aguyje, «gracias», no responde ni que sí ni que no.","step":"test","unit":3},"a1u03t.11":{"id":"a1u03t.11","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana llega a la casa de su abuela, y la abuela está contenta. Ana se lo cuenta a Luis.)\nAna: Che jarýi (   ).","options":["ivy'a","chevy'a","avy'a","ovy'a"],"answer":4,"explain":"Vy'a, «alegrarse», se conjuga como una acción: para otra persona lleva o-, como okaru. Che jarýi ovy'a, «mi abuela está contenta». Ivy'a le pone la i- de los estados, como en ikane'õ, y vy'a no va así. Chevy'a tampoco va: vy'a no lleva che-, y además Ana habla de su abuela. Y avy'a es «estoy contenta», de Ana misma.","step":"test","unit":3},"a1u03t.12":{"id":"a1u03t.12","kind":"choice","area":"grammar","label":"Elegí la frase","q":"Luis quiere saber si el papá de Ana _está cansado_. ¿Cómo se lo pregunta a ella?","options":["Nde ru ikane'õ.","Ikane'õpa nde ru?","Pa ikane'õ nde ru?","Ikane'õpa che ru?"],"answer":2,"explain":"-pa es un sufijo: va pegado a la palabra que preguntás, acá el estado, y la persona viene después. Ikane'õpa nde ru?, «¿está cansado tu papá?». Nde ru ikane'õ, sin -pa, no pregunta: afirma «tu papá está cansado». Pa ikane'õ pone -pa suelto y adelante, y -pa ni va suelto ni empieza la oración. Ikane'õpa che ru? pregunta por el papá de Luis, che ru, y él quiere saber del papá de Ana: nde ru.","step":"test","unit":3},"a1u03t.13":{"id":"a1u03t.13","kind":"choice","area":"grammar","label":"Cuál está bien escrita","q":"Ana anota cuatro palabras de la semana. Según la regla del acento del guaraní, solo una está _bien escrita_. ¿Cuál?","options":["Ypakaraí","Itauguápe","Paraguaipe","ñandutí"],"answer":2,"explain":"Itauguápe está bien: Itaugua es aguda, I-tau-GUA, y sola va sin tilde, pero -pe no se lleva el acento, así que la a tónica ya no es la última vocal y se escribe á: Itauguápe, «a Itauguá». A Paraguaipe le falta la tilde: Paraguái ya la lleva en la á, y con -pe se queda donde estaba, Paraguáipe. Ypakaraí y ñandutí llevan la tilde del castellano; en guaraní son agudas y van sin marca: Ypakarai, ñanduti.","step":"test","unit":3},"a1u03t.14":{"id":"a1u03t.14","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Rosa le pregunta a Juan cómo se llama el médico. Juan no se acuerda.)\nJuan: ","after":".","tiles":["na","che","mandu'a","i"],"bank":[1,3,0,2],"full":"(Rosa le pregunta a Juan cómo se llama el médico. Juan no se acuerda.)\nJuan: {Na}chemandu'á{i}.","es":"(Rosa le pregunta a Juan cómo se llama el médico. Juan no se acuerda.)\nJuan: No me acuerdo.","explain":"na, che, mandu'a, i. El «no» del guaraní tiene dos partes que rodean la palabra: na- al principio y -i al final. En el medio van che-, «yo, me pasa», y mandu'a, «acordarse»: nachemandu'ái, «no me acuerdo». Va na- y no nda- porque mandu'a es nasal, con m y nd. Y aparece una tilde: -i no se lleva el acento, que queda en la a final de mandu'a; como ya no es la última vocal, se escribe á.","step":"test","unit":3},"a1u03t.15":{"id":"a1u03t.15","kind":"choice","area":"reading","label":"Buscar el dato","q":"(Ana vuelve a casa y encuentra una nota de su mamá.)\n¿Adónde va la mamá?","passage":"Mba'éichapa, Ana?\nAha mbo'ehaópe. Nde ru og̃uahẽ ko'ág̃a: ikane'õ ha ivare'a.\nOĩ chipa ha terere.\nJajotopáta ko ka'aru.\nMamá","options":["A la escuela.","A Caacupé.","Al hospital.","A Itauguá."],"short":["Escuela","Caacupé","Hospital","Itauguá"],"answer":1,"explain":"La nota es de la mamá, y dice Aha mbo'ehaópe: aha es «voy» y mbo'ehaópe, «a la escuela», mbo'ehao con -pe. Caacupé, el hospital e Itauguá no aparecen en la nota.","step":"test","unit":3},"a1u03t.16":{"id":"a1u03t.16","kind":"choice","area":"reading","label":"Texto corto","q":"¿Cómo está el papá de Ana?","passage":"Mba'éichapa, Ana?\nAha mbo'ehaópe. Nde ru og̃uahẽ ko'ág̃a: ikane'õ ha ivare'a.\nOĩ chipa ha terere.\nJajotopáta ko ka'aru.\nMamá","options":["Enojado.","Enfermo.","Cansado y con hambre.","Contento."],"short":["Enojado","Enfermo","Cansado, con hambre","Contento"],"answer":3,"explain":"De nde ru, «tu papá», la nota dice ikane'õ ha ivare'a: i- marca el estado de otra persona, kane'õ es «cansancio» y vare'a, «hambre». Está cansado y tiene hambre. Enojado sería ipochy; enfermo, hasy; y contento, ovy'a.","step":"test","unit":3},"a1u03t.17":{"id":"a1u03t.17","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Qué hay para comer y tomar?","passage":"Mba'éichapa, Ana?\nAha mbo'ehaópe. Nde ru og̃uahẽ ko'ág̃a: ikane'õ ha ivare'a.\nOĩ chipa ha terere.\nJajotopáta ko ka'aru.\nMamá","options":["Mandioca y queso.","Nada.","Carne.","Chipá y tereré."],"short":["Mandioca y queso","Nada","Carne","Chipá y tereré"],"answer":4,"explain":"Oĩ chipa ha terere: oĩ es «hay», como en Oĩpa chipa?, y ha es «y». Hay chipá y tereré. La mandioca, mandi'o, el queso, kesu, y la carne, so'o, no están en la nota.","step":"test","unit":3},"a1u03t.18":{"id":"a1u03t.18","kind":"choice","area":"listening","label":"Respuesta rápida","q":"(Juan perdió el partido.)\nRosa: Ndepochýpa, Juan?\n¿Qué responde Juan?","options":["Héẽ, chepochy.","Héẽ, ndepochy.","Héẽ, ipochy."],"answer":1,"explain":"Rosa le pregunta a Juan por él mismo, con nde-: Ndepochýpa?, «¿estás enojado?». Juan responde por él, con che-: Héẽ, chepochy, «sí, estoy enojado». Héẽ, ndepochy repite el nde- de la pregunta: le diría a Rosa «estás enojada». Y Héẽ, ipochy hablaría de otra persona, «está enojado».","step":"test","unit":3},"a1u03t.19":{"id":"a1u03t.19","kind":"choice","area":"listening","label":"Respuesta rápida","q":"(En la fiesta de San Juan, Rosa conoce a Juan.)\nRosa: Ndépa chokokue, Juan?\n¿Qué responde Juan?","options":["Héẽ, ha'e chokokue.","Héẽ, che chokokue.","Nahániri, che chokokue."],"answer":2,"explain":"Rosa le pregunta a Juan por él, con nde y -pa: Ndépa chokokue?, «¿vos sos agricultor?». Juan responde por él mismo, con che y sin verbo: Héẽ, che chokokue, «sí, soy agricultor». Héẽ, ha'e chokokue habla de otra persona, «él es agricultor». Y Nahániri, che chokokue se contradice: dice «no» y después «soy agricultor».","step":"test","unit":3},"a1u03t.20":{"id":"a1u03t.20","kind":"choice","area":"listening","label":"Respuesta rápida","q":"(En la plaza, Lucas ve a Ana con un señor. No es el papá de Ana.)\nLucas: Ha'épa nde ru?\n¿Qué responde Ana?","options":["Héẽ, ndaha'éi che ru.","Nahániri, ha'e che ru.","Nahániri, ndaha'éi che ru."],"answer":3,"explain":"Lucas pregunta con -pa si el señor es el papá de Ana: Ha'épa nde ru?, «¿es tu papá?». No lo es, así que Ana responde Nahániri, «no», y lo dice entero con ndaha'éi, «no es»: Nahániri, ndaha'éi che ru, «no, no es mi papá». Héẽ, ndaha'éi che ru se contradice: dice «sí» y después «no es mi papá». Nahániri, ha'e che ru también: dice «no» y después «es mi papá».","step":"test","unit":3},"a1u04d1.c1":{"id":"a1u04d1.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan le pregunta a Rosa cómo se llama ^la mamá de ella^.\nJuan: Mba'éichapa héra (   ) sy?","options":["che","nde","ne"],"answer":2,"why":["Che es «mi»: Juan preguntaría por su propia mamá, y pregunta por la de Rosa.","Juan le habla a Rosa de la mamá de ella: nde sy, «tu mamá». Sy es una palabra oral, así que nde no cambia.","Ne es nde delante de una palabra nasal, como en ne memby. Sy no tiene ~ ni m, n, ñ: queda nde sy."],"step":"compare"},"a1u04d1.d1":{"id":"a1u04d1.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana le muestra a Juan una foto de ^la abuela de ella^.)\nJuan: Mávapa ha'e?\nAna: Ha'e (   ) jarýi.","options":["nde","ne","che","héra"],"answer":3,"why":["Nde es «tu»: sería la abuela de Juan, y la foto es de la abuela de Ana.","Ne solo va delante de una palabra nasal, y jarýi es oral. Además sería «tu», no «mi».","Ana habla de su propia abuela: che jarýi, «mi abuela».","Héra es «su nombre», como en Héra Rosa. No dice de quién es la abuela."],"step":"drill"},"a1u04d1.d2":{"id":"a1u04d1.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan: Mba'éichapa héra (   ) ^memby^, Rosa?","options":["nde","ne","che","ñande"],"answer":2,"why":["Nde es «tu», pero memby es una palabra nasal, con m: delante de ella nde pierde la d.","Juan le pregunta a Rosa por el hijo de ella: «tu hijo». Memby empieza con m, es nasal, así que nde se vuelve ne: ne memby.","Che es «mi»: Juan preguntaría por su propio hijo, y le pregunta a Rosa por el de ella.","Ñande es «nuestro» con vos: metería a Juan. Y delante de una palabra nasal sería ñane."],"step":"drill"},"a1u04d1.d3":{"id":"a1u04d1.d3","kind":"choice","area":"grammar","label":"Elegí el orden","q":"Luis habla de ^la casa de su abuela^.\nLuis: (   ) iporã.","options":["Róga che jarýi","Che róga jarýi","Jarýi che róga","Che jarýi róga"],"answer":4,"why":["Róga che jarýi calca el orden del castellano, con la casa primero. En guaraní el dueño va primero, y róga sola, sin dueño delante, no se dice.","Che róga jarýi es «mi casa» y después «abuela». Jarýi tiene que ir antes de róga, porque es la dueña.","Jarýi che róga es «abuela» y después «mi casa»: así la casa es de Luis, no de la abuela.","Primero el dueño, che jarýi, y después la cosa, róga: «la casa de mi abuela», sin «de»."],"step":"drill"},"a1u04d1.d4":{"id":"a1u04d1.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana vive con su hermano Luis. Le muestra la casa a Juan.)\nAna: (   ) róga iporã. ^(nuestra casa)^","options":["Ore","Ñande","Nde","Che"],"answer":1,"why":["La casa es de Ana y de Luis, y Juan, el que escucha, no vive ahí: ore róga, «nuestra casa», sin vos.","Ñande incluye al que escucha: ñande róga sería también la casa de Juan.","Nde es «tu»: nde róga sería la casa de Juan.","Che róga es «mi casa»: deja afuera a Luis, y la casa es de los dos, «nuestra»."],"step":"drill"},"a1u04d1.d5":{"id":"a1u04d1.d5","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Aha","after":".","tiles":["che","ru","rógape"],"bank":[2,0,1],"hint":"Primero el dueño, después la casa. Rógape es róga con -pe, «a».","full":"Aha {che ru} rógape.","es":"Voy a la casa de mi papá.","explain":"Che ru, «mi papá», va primero: es el dueño. Después viene la casa, róga, con -pe, «a»: rógape. Para decir de quién es algo no hace falta «de»: el orden ya lo dice. Ru sola no se dice: siempre lleva un dueño delante.","step":"drill"},"a1u04d1.d6":{"id":"a1u04d1.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Moõpa","after":"?","tiles":["ne","ramói","róga"],"bank":[1,2,0],"hint":"Como Moõpa nde róga?, pero la casa es del abuelo: el dueño va primero. Y delante de ramói, nde cambia.","full":"Moõpa {ne} ramói róga?","es":"¿Dónde queda la casa de tu abuelo?","explain":"Primero el dueño, ne ramói, «tu abuelo», y después róga: «la casa de tu abuelo». Ramói es una palabra nasal, con m, así que nde se vuelve ne. Ramói y róga no van solas: las dos llevan un dueño delante.","step":"drill"},"a1u04d1.e1":{"id":"a1u04d1.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Luis: _Che sy ha che ru_ oñe'ẽ guaraníme.","options":["Tu mamá y tu papá hablan guaraní.","Mi mamá y tu papá hablan guaraní.","Mi mamá y mi papá hablan guaraní.","Mi abuela y mi abuelo hablan guaraní."],"answer":3,"explain":"Che es «mi» y va delante de cada sustantivo: che sy, «mi mamá», ha, «y», che ru, «mi papá». «Tu» sería nde: nde sy, nde ru. Y abuela y abuelo son che jarýi y che ramói.","step":"exam"},"a1u04d1.e2":{"id":"a1u04d1.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa le pregunta a Juan por el amigo de él.)\nRosa: Mba'éichapa héra (   ) angirũ, Juan?","options":["nde","ne","che","héra"],"answer":2,"explain":"Rosa le pregunta a Juan por el amigo de él: «tu amigo». Angirũ es una palabra nasal, con ũ, así que nde pierde la d: ne angirũ. Che sería «mi», y héra ya está en la frase: es «su nombre», no un posesivo.","step":"exam"},"a1u04d1.e3":{"id":"a1u04d1.e3","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"(Juan le pregunta a Rosa por la casa del papá de ella.)\nJuan: Moõpa","after":"?","tiles":["nde","ru","róga"],"bank":[2,0,1],"full":"(Juan le pregunta a Rosa por la casa del papá de ella.)\nJuan: Moõpa nde ru róga?","es":"Juan: ¿Dónde queda la casa de tu papá?","explain":"Nde ru, «tu papá», va primero: es el dueño. Después la casa, róga. Ru es una palabra oral, así que nde no cambia. Sin «de»: el orden dice de quién es la casa, y ni ru ni róga van solas.","step":"exam"},"a1u04d1.k1":{"id":"a1u04d1.k1","kind":"choice","area":"vocab","label":"Cuál está bien escrita","q":"Luis anota quién es quién en la foto. Solo una palabra está _bien escrita_. ¿Cuál?","options":["jaryi","rajý","ramói","membý"],"answer":3,"explain":"Ramói está bien: termina en dos vocales y el acento va en la primera, la o, que no es la última de la palabra, y por eso lleva tilde. A jaryi le falta la suya, por lo mismo: se escribe jarýi. Rajy y memby llevan el acento en la última vocal, y en guaraní eso no se marca: en rajý y en membý la tilde sobra.","step":"words"},"a1u04d1.r1":{"id":"a1u04d1.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Cómo se llama el abuelo de Ana?","options":["Luis.","Pedro.","Marta."],"short":["Luis","Pedro","Marta"],"printed":true,"answer":2,"why":["Luis es el papá de Ana: Ha'e che ru, héra Luis, «él es mi papá, se llama Luis».","Cuando Juan pregunta Mávapa ha'e?, Ana responde Che ramói, héra Pedro: «mi abuelo, se llama Pedro».","Marta es la mamá de Ana: Ha'e che sy, héra Marta, «ella es mi mamá, se llama Marta»."],"script":["Narrador: Ana le muestra a Juan la foto de su familia. ¿Cómo se llama el abuelo de Ana?","Mujer: Ha'e che sy, héra Marta.","Mujer: Ha'e che ru, héra Luis.","Narrador: Juan señala a un señor de la foto.","Hombre: Mávapa ha'e?","Mujer: Che ramói, héra Pedro.","Hombre: Mba'éichapa héra ne memby?","Mujer: Héra Sofía.","Narrador: ¿Cómo se llama el abuelo de Ana?"],"step":"skill"},"a1u04d2.c1":{"id":"a1u04d2.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana habla de ^las mujeres^ del barrio: «(   ) opurahéi.»","options":["Kuñakuéra","Kuñanguéra","Kuñãnguéra"],"answer":2,"why":["Kuña termina en ña, una sílaba nasal por la ñ: ahí no va -kuéra.","La última sílaba de kuña es nasal, por la ñ: va -nguéra. Kuñanguéra opurahéi: las mujeres cantan.","Kuñãnguéra agrega una ~ que la palabra no lleva: junto a la ñ, la a ya suena nasal y no se marca."],"step":"compare"},"a1u04d2.d1":{"id":"a1u04d2.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana habla de ^los pájaros^ del patio: «(   ) opurahéi ko pyhareve.»","options":["Guyrakuéra","Guyranguéra","Guirakuéra","Guyracuéra"],"answer":1,"why":["Guyra termina en ra, sílaba oral: va -kuéra, que se lleva el acento. Guyrakuéra opurahéi ko pyhareve: los pájaros cantan esta mañana.","-nguéra va solo tras una sílaba nasal, y ra es oral.","Guirakuéra cambia la y por i. Guy-ra lleva la y, la sexta vocal.","Guyracuéra escribe el plural con c, y la c no es una letra del guaraní: ese sonido se escribe con k, kuéra."],"step":"drill"},"a1u04d2.d2":{"id":"a1u04d2.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana le pregunta a Rosa dónde están ^los hijos de Rosa^: «Ne (   ) moõpa oĩ?»","options":["membynguéra","mẽmbykuéra","membykuéra","membikuéra"],"answer":3,"why":["-nguéra va tras una sílaba nasal, y la última sílaba de memby, mby, es oral: mb es otra letra, no una m. Para el plural se mira solo la última sílaba.","Mẽmbykuéra agrega una ~ a la e: junto a la m ya suena nasal, y no se marca.","La última sílaba de memby es mby, y es oral: mb es otra letra, no una m. Va -kuéra. Para nde → ne cuenta toda la palabra (ne memby); para el plural, solo la última sílaba (membykuéra). Ne membykuéra moõpa oĩ?: ¿dónde están tus hijos?","Membikuéra cambia la y por i. Memby termina en y, la sexta vocal."],"step":"drill"},"a1u04d2.d3":{"id":"a1u04d2.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis habla de ^sus amigos^: «Che (   ) oĩ [ko'ápe|aquí].»","options":["angirũkuéra","angirũnguéra","angirunguéra","ãngirũnguéra"],"answer":2,"why":["-kuéra va tras una sílaba oral, y angirũ termina en ũ, nasal.","Angirũ termina en ũ, nasal: va -nguéra. Che angirũnguéra oĩ ko'ápe: mis amigos están aquí.","Angirunguéra pierde la ~ de la ũ. La raíz es angirũ, y la ~ se queda.","En ãngirũnguéra sobra la ~ de la a: junto a ng ya suena nasal, y no se marca."],"step":"drill"},"a1u04d2.d4":{"id":"a1u04d2.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa habla de ^las casas^ del barrio: «(   ) iporã.»","options":["Oganguéra","Ogãkuéra","Ogacuéra","Ogakuéra"],"answer":4,"why":["-nguéra es la forma de después de una sílaba nasal, y ga es oral.","Ogãkuéra agrega una ~ que la palabra no lleva: óga no tiene ningún sonido nasal.","Ogacuéra escribe el plural con c, y la c no es una letra del guaraní: ese sonido se escribe con k, kuéra.","Óga pierde su tilde porque -kuéra se lleva el acento: ogakuéra, con una sola tilde. Ogakuéra iporã: las casas son lindas."],"step":"drill"},"a1u04d2.d5":{"id":"a1u04d2.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Mbo'ehára oñe'ẽ ","after":".","tiles":["mitã","nguéra","pe"],"bank":[2,0,1],"hint":"Primero el plural, después -pe, «a». Fijate dónde queda el acento.","full":"Mbo'ehára oñe'ẽ mitã{nguéra}pe.","es":"El profesor les habla a los niños.","explain":"mitã («niño») + -nguéra (plural tras nasal, porque mitã termina en ã) + -pe («a») = mitãnguérape. -nguéra se lleva el acento, y -pe no lo mueve: queda la ~ en la ã y la tilde en la é. Después de -nguéra va -pe, porque ra es sílaba oral.","step":"drill"},"a1u04d2.d6":{"id":"a1u04d2.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" oñe'ẽ guaraníme.","tiles":["mbo'ehára","kuéra"],"bank":[1,0],"hint":"-kuéra va después del sustantivo y se lleva el acento: mirá qué pasa con la tilde de hára.","full":"{Mbo'eharakuéra} oñe'ẽ guaraníme.","es":"Los profesores hablan guaraní.","explain":"mbo'ehára («profesor») + -kuéra = mbo'eharakuéra, «los profesores». -kuéra se lleva el acento, y la tilde de hára desaparece: una palabra, una sola tilde.","step":"drill"},"a1u04d2.e1":{"id":"a1u04d2.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Ana: _Che membykuéra_ oho mbo'ehaópe.","options":["Mi hijo va a la escuela.","Mis hijos van a la escuela.","Tus hijos van a la escuela.","Nuestros hijos van a la escuela."],"answer":2,"explain":"Che es «mi», y -kuéra hace el plural: che membykuéra, «mis hijos». Un solo hijo sería che memby, «tus hijos» sería ne membykuéra, y «nuestros» llevaría ñane u ore, no che: delante de una palabra nasal como memby, ñande se vuelve ñane, igual que nde se vuelve ne.","step":"exam"},"a1u04d2.e2":{"id":"a1u04d2.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa habla de las niñas de la escuela.)\nRosa: (   ) opurahéi mbo'ehaópe.","options":["Mitãkuñakuéra","Mitakuñanguéra","Mitãkuñanguéra","Mitãkuñãnguéra"],"answer":3,"explain":"Mitãkuña («niña») termina en ña, sílaba nasal por la ñ: va -nguéra, que se lleva el acento. Mitãkuñakuéra usa la forma de después de una sílaba oral, mitakuñanguéra pierde la ~ de mitã, que la palabra sí lleva, y mitãkuñãnguéra agrega una ~ junto a la ñ, donde no se escribe.","step":"exam"},"a1u04d2.e3":{"id":"a1u04d2.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Che sy oñe'ẽ ","after":".","tiles":["kuña","nguéra","pe"],"bank":[1,2,0],"full":"Che sy oñe'ẽ kuña{nguéra}pe.","es":"Mi mamá les habla a las mujeres.","explain":"kuña («mujer») + -nguéra (plural tras la ñ, sílaba nasal) + -pe («a») = kuñanguérape. -nguéra se lleva el acento, y -pe va al final sin moverlo: la tilde queda en la é.","step":"exam"},"a1u04d2.k1":{"id":"a1u04d2.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Los chicos del patio: _los niños_. ¿Cómo se escribe en guaraní?","options":["mitãkuéra","mitankuéra","mitãnguéra","mitanguéra"],"answer":3,"explain":"Mitã termina en ã, nasal, así que el plural es -nguéra, con el acento en la é: mitãnguéra. Mitãkuéra usa la forma de después de una sílaba oral. Mitankuéra escribe una n en lugar de la ~, y la nasal de mitã es la ~ de la ã. Mitanguéra pierde esa ~, que la palabra sí lleva.","step":"words"},"a1u04d2.r1":{"id":"a1u04d2.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quiénes cantan esta tarde?","options":["Los niños.","Los profesores.","Los padres.","Los pájaros."],"short":["Niños","Profesores","Padres","Pájaros"],"answer":1,"why":["Mitãnguéra opurahéi ko ka'aru: los niños cantan esta tarde. Mitãnguéra es el plural de mitã.","De los profesores, mbo'eharakuéra, el aviso dice que hablan guaraní (oñe'ẽ guaraníme), no que cantan.","Sy ha tuvakuéra, las madres y los padres, son a quienes saluda el aviso: Maitei, sy ha tuvakuéra. No cantan.","Guyrakuéra, los pájaros, no aparece en el aviso."],"explain":"El aviso saluda a las madres y a los padres (sy ha tuvakuéra) y dice: Mitãnguéra opurahéi ko ka'aru mbo'ehaópe, «los niños cantan esta tarde en la escuela». Los profesores hablan guaraní, no cantan.","step":"skill"},"a1u04d3.c1":{"id":"a1u04d3.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan señala un perro que está ^al lado de Rosa^.)\nJuan: (   ) jagua iporã.","options":["Ko","Pe","Amo"],"answer":2,"why":["Ko es «este»: el perro estaría al lado de Juan, el que habla. Y está al lado de Rosa.","El perro está al lado de Rosa, la que escucha: pe jagua, «ese perro».","Amo es «aquel», para algo lejos de los dos. El perro está al lado de Rosa."],"step":"compare"},"a1u04d3.d1":{"id":"a1u04d3.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana tiene ^un gato en brazos^.)\nAna: (   ) mbarakaja iporã.","options":["Amo","Pe","Umi","Ko"],"answer":4,"why":["Amo es «aquel», para algo lejos de los dos. Ana tiene el gato en brazos.","Pe es «ese»: el gato estaría cerca del que escucha. Lo tiene Ana, la que habla.","Umi es para varios, «esos». Es un solo gato, y además lo tiene Ana.","Ana tiene el gato en brazos, cerca de ella, la que habla: ko mbarakaja, «este gato»."],"step":"drill"},"a1u04d3.d2":{"id":"a1u04d3.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis señala ^una casa lejos, al final de la calle^.)\nLuis: (   ) óga ituicha.","options":["Ko","Pe","Amo","Ko'ã"],"answer":3,"why":["Ko es «esta», para algo cerca de Luis. La casa está al final de la calle.","Pe es «esa», para algo cerca del que escucha. La casa está lejos de los dos.","La casa está lejos de los dos, pero a la vista: amo óga, «aquella casa».","Ko'ã es «estas», para varias cosas cerca de quien habla. Es una sola casa y está lejos."],"step":"drill"},"a1u04d3.d3":{"id":"a1u04d3.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana tiene ^dos libros en la mano^.)\nAna: (   ) aranduka iporã.","options":["Ko'ã","Umi","Ko","Pe"],"answer":1,"why":["Son dos libros y los tiene Ana, la que habla: ko'ã aranduka, «estos libros». Ko'ã es el ko de varios.","Umi es para varios, pero lejos de quien habla: «esos» o «aquellos». Ana los tiene en la mano.","Ko es «este», para uno solo. Ana tiene dos libros.","Pe es «ese»: uno solo, y cerca del que escucha. Son dos y los tiene Ana."],"step":"drill"},"a1u04d3.d4":{"id":"a1u04d3.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan habla de ^los chicos que están con Rosa^.)\nJuan: (   ) mitã oñe'ẽ guaraníme.","options":["Ko'ã","Umi","Ko","Pekuéra"],"answer":2,"why":["Ko'ã es «estos», para varios cerca de quien habla. Los chicos están con Rosa, no con Juan.","Son varios chicos y están con Rosa, no con Juan: umi mitã, «esos chicos». El sustantivo queda como está.","Ko es «este»: uno solo, y cerca de Juan. Son varios y están con Rosa.","El plural de pe no se hace con -kuéra: para varios hay otra palabra, umi."],"step":"drill"},"a1u04d3.d5":{"id":"a1u04d3.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Umi kavaju oĩ ","after":".","tiles":["korapy","pe"],"bank":[1,0],"hint":"Primero el lugar, korapy, y después -pe, «en». -pe no se lleva el acento: fijate dónde queda la tilde.","full":"Umi kavaju oĩ korapý{pe}.","es":"Esos caballos están en el patio.","explain":"korapy («patio») + -pe («en») = korapýpe, «en el patio». -pe no se lleva el acento: queda en la y de korapy. Como esa y ya no es la última vocal, se escribe la tilde: korapýpe. Umi, «esos», va delante de kavaju.","step":"drill"},"a1u04d3.d6":{"id":"a1u04d3.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"","after":"umi mbarakaja iporã.","tiles":["ko'ã","jagua","ha"],"bank":[2,0,1],"hint":"Ko'ã va delante del sustantivo, como ko. Ha, «y», une las dos partes.","full":"{Ko'ã} jagua ha umi mbarakaja iporã.","es":"Estos perros y esos gatos son lindos.","explain":"Ko'ã, «estos», va delante de jagua: ko'ã jagua, «estos perros». Después ha, «y», une con umi mbarakaja, «esos gatos». El demostrativo va siempre primero, y el sustantivo queda sin -kuéra: ko'ã y umi ya dicen que son varios.","step":"drill"},"a1u04d3.e1":{"id":"a1u04d3.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: _Amo óga_ ituicha.","options":["Esta casa","Esa casa","Aquella casa","Aquellas casas"],"answer":3,"explain":"Amo es «aquel, aquella»: algo lejos de los dos, a la vista. Amo óga ituicha: aquella casa es grande. «Esta casa» sería ko óga; «esa casa», pe óga; y para varias casas lejos se usa umi: umi óga.","step":"exam"},"a1u04d3.e2":{"id":"a1u04d3.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan señala dos gallinas que tiene al lado.)\nJuan: (   ) ryguasu ituicha.","options":["Ko","Umi","Pe","Ko'ã"],"answer":4,"explain":"Son dos gallinas y están al lado de Juan, el que habla: ko'ã ryguasu, «estas gallinas». Ko y pe son para una sola, y umi es para varias pero lejos de quien habla, «esas» o «aquellas».","step":"exam"},"a1u04d3.e3":{"id":"a1u04d3.e3","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"","after":"ko'ã vaka oĩ korapýpe.","tiles":["umi","kavaju","ha"],"bank":[1,2,0],"full":"Umi kavaju ha ko'ã vaka oĩ korapýpe.","es":"Esos caballos y estas vacas están en el patio.","explain":"Umi, «esos», va delante de kavaju: umi kavaju, «esos caballos». Después ha, «y», une con ko'ã vaka, «estas vacas». El demostrativo va siempre primero, y el sustantivo queda sin -kuéra: umi y ko'ã ya dicen que son varios. Oĩ korapýpe: están en el patio.","step":"exam"},"a1u04d3.k1":{"id":"a1u04d3.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Juan señala un animal: Amo _caballo_ ituicha. ¿Cómo se escribe «caballo» en guaraní?","options":["cavaju","kavaju","kabaju","kavallu"],"answer":2,"explain":"Se escribe kavaju: la c de «caballo» se escribe k, porque la c no es una letra del guaraní, y la ll se escribe j. Cavaju deja la c; kabaju escribe b, que sola no es una letra del guaraní, acá va v; y kavallu deja la ll del castellano.","step":"words"},"a1u04d3.r1":{"id":"a1u04d3.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Qué animal está lejos de los dos?","options":["El perro.","El gato.","El caballo."],"short":["Perro","Gato","Caballo"],"printed":true,"answer":3,"why":["Rosa dice pe jagua, «ese perro»: pe es para algo cerca del que escucha, Juan. El perro está al lado de Juan, no lejos.","Rosa dice ko mbarakaja, «este gato»: ko es para algo cerca de quien habla. Rosa tiene el gato al lado.","Juan dice amo kavaju ituicha, «aquel caballo es grande»: amo es para algo lejos de los dos, a la vista."],"script":["Narrador: En el patio de la casa de Juan. Rosa habla de los animales. ¿Qué animal está lejos de los dos?","Mujer: Pe jagua iporã, Juan.","Hombre: Héẽ. Ha amo kavaju ituicha.","Mujer: Ha ko mbarakaja?","Hombre: Che rajy mbarakaja.","Narrador: ¿Qué animal está lejos de los dos?"],"step":"skill"},"a1u04d4.c1":{"id":"a1u04d4.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa quiere saber quién es ^la mujer de la foto^.\nRosa: (   ) pe kuña?","options":["Mba'épa","Moõpa","Mávapa"],"answer":3,"why":["Mba'épa pregunta por una cosa: Mba'épa pe kuña? sería «¿qué es esa mujer?». Por una persona se pregunta con mávapa.","Moõpa pregunta «¿dónde?», por un lugar. Rosa no quiere saber dónde está la mujer: quiere saber quién es.","Rosa pregunta por una persona, la mujer de la foto: Mávapa pe kuña?, «¿quién es esa mujer?»."],"step":"compare"},"a1u04d4.d1":{"id":"a1u04d4.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan: (   ) ha'e?\nRosa: ^Che sy.^","options":["Moõpa","Mávapa","Mba'épa","Mboýpa"],"answer":2,"why":["Moõpa pregunta «¿dónde?». Che sy no es un lugar: para decir dónde, Rosa respondería con un lugar, como che rógape.","Rosa responde con una persona, che sy, «mi mamá»: Juan preguntó quién es. Mávapa ha'e?, «¿quién es?».","Mba'épa pregunta «¿qué?», por una cosa. Che sy es una persona.","Mboýpa pregunta «¿cuánto?», como en Mboýpa ovale? Che sy no es una cantidad."],"step":"drill"},"a1u04d4.d2":{"id":"a1u04d4.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Ana: (   ) reipota?\nLuis: ^Mandi'o.^","options":["Mávapa","Moõpa","Mba'éichapa","Mba'épa"],"answer":4,"why":["Mávapa pregunta «¿quién?», por una persona, y mandi'o es una cosa.","Moõpa pregunta «¿dónde?». Mandi'o no es un lugar.","Mba'éichapa pregunta «¿cómo?», como en Mba'éichapa reiko? Luis no dice cómo: dice qué quiere.","Luis responde con una cosa, mandi'o: Ana preguntó qué quiere. Mba'épa reipota?, «¿qué querés?»."],"step":"drill"},"a1u04d4.d3":{"id":"a1u04d4.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: (   ) [he'ise|significa] «korapy»?\nAna: ^«Patio».^","options":["Mboýpa","Mba'éichapa","Mba'épa","Mávapa"],"answer":3,"why":["Mboýpa pregunta «¿cuánto?». «Patio» no es una cantidad.","Mba'éichapa pregunta «¿cómo?». He'ise es «significa», y lo que Luis pide es un significado: un «qué».","Luis pregunta el significado de una palabra: Mba'épa he'ise «korapy»?, «¿qué significa korapy?». Ana se lo dice: «patio».","Mávapa pregunta «¿quién?», y una palabra no es una persona."],"step":"drill"},"a1u04d4.d4":{"id":"a1u04d4.d4","kind":"choice","area":"grammar","label":"Cómo se escribe","q":"Rosa pregunta ^quién^ es el muchacho de allá.\nRosa: (   ) amo [karia'y|muchacho]?","options":["Mãvapa","Mávapa","Mábapa","Mávapã"],"answer":2,"why":["Mãvapa pone una ~ en la primera a, como si fuera nasal. Máva es oral: su marca es la tilde de acento, á.","Máva lleva la tilde de acento en la primera a, y -pa va pegado sin moverla: Mávapa amo karia'y?, «¿quién es aquel muchacho?».","Mábapa escribe con b: la b sola no es una letra del guaraní, solo está en mb. El sonido de máva se escribe con v.","Mávapã agrega una ~ a la a de -pa. Esa a es oral: -pa se escribe siempre igual, sin ~."],"step":"drill"},"a1u04d4.d5":{"id":"a1u04d4.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" he'ise «ramói»?","tiles":["mba'e","pa"],"bank":[1,0],"hint":"-pa va al final y no se lleva el acento: fijate qué pasa con la tilde.","full":"{Mba'épa} he'ise «ramói»?","es":"¿Qué significa «ramói»?","explain":"mba'e («qué») + -pa (pregunta) = Mba'épa. -pa no se lleva el acento: queda en la e de mba'e, que ya no es la última vocal, y por eso se escribe la tilde. Mba'épa he'ise «ramói»?: ¿qué significa «ramói»?","step":"drill"},"a1u04d4.d6":{"id":"a1u04d4.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" ko mitã?","tiles":["máva","pa"],"bank":[1,0],"hint":"Máva ya tiene su tilde, y -pa no la mueve.","full":"{Mávapa} ko mitã?","es":"¿Quién es este chico?","explain":"máva («quién») + -pa (pregunta) = Mávapa. La tilde ya estaba en la primera a de máva y se queda ahí: -pa no se lleva el acento. Mávapa ko mitã?: ¿quién es este chico?","step":"drill"},"a1u04d4.e1":{"id":"a1u04d4.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: _Mba'épa he'ise «kuñataĩ»?_","options":["¿Quién es esa chica?","¿Qué significa «kuñataĩ»?","¿Dónde está la chica?","¿Cómo se escribe «kuñataĩ»?"],"answer":2,"explain":"Mba'épa es «¿qué?» y he'ise, «significa»: Rosa pregunta qué significa la palabra kuñataĩ. «Quién» sería mávapa, «dónde» sería moõpa y «cómo» sería mba'éichapa.","step":"exam"},"a1u04d4.e2":{"id":"a1u04d4.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan: (   ) amo kuña?\nRosa: Che jarýi.","options":["Mba'épa","Moõpa","Mboýpa","Mávapa"],"answer":4,"explain":"Rosa responde con una persona, che jarýi, «mi abuela»: Juan preguntó quién es aquella mujer, Mávapa amo kuña? Mba'épa pregunta por una cosa, moõpa por un lugar y mboýpa por una cantidad.","step":"exam"},"a1u04d4.e3":{"id":"a1u04d4.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Vendedor: ","after":" reipota?","tiles":["mba'e","pa"],"bank":[1,0],"full":"Vendedor: Mba'épa reipota?","es":"Vendedor: ¿Qué querés?","explain":"mba'e («qué») + -pa (pregunta) = Mba'épa. -pa no se lleva el acento: queda en la e, que ya no es la última vocal, y se escribe la tilde. Mba'épa reipota? es la pregunta del vendedor: «¿qué querés?».","step":"exam"},"a1u04d4.k1":{"id":"a1u04d4.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"En el cumpleaños hay un _hombre_ que no conocés. ¿Cómo se escribe «hombre» en guaraní?","options":["kuimbae","cuimba'e","kuimba'e","küimba'e"],"answer":3,"explain":"Hombre es kuimba'e: con k, con la u, que en guaraní siempre suena, y con puso antes de la e. Kuimbae pierde el puso. Cuimba'e usa la c, que sola no es una letra del guaraní: ese sonido se escribe k. Küimba'e le pone la diéresis del castellano: en guaraní la u suena sin ninguna marca, y la ü no es una letra del alfabeto.","step":"words"},"a1u04d4.r1":{"id":"a1u04d4.r1","kind":"choice","area":"reading","label":"Texto corto","q":"¿Quién es el señor de la foto?","options":["El papá de Rosa.","El abuelo de Rosa.","El hijo de Rosa.","Un amigo de Rosa."],"short":["Su papá","Su abuelo","Su hijo","Un amigo"],"answer":2,"why":["Para el papá, Rosa diría che ru, y no lo dice en el chat.","Juan pregunta Ha pe karai?, «¿y ese señor?», y Rosa responde Che ramói, «mi abuelo». Después se lo traduce: ramói es «abuelo».","Che memby es Sofía, la kuñataĩ de la foto: la hija de Rosa, no el señor.","Un amigo sería che angirũ, y esa palabra no aparece en el chat."],"explain":"Juan pregunta por el señor con Ha pe karai?, y Rosa contesta Che ramói, «mi abuelo». Cuando Juan pregunta Mba'épa he'ise «ramói»?, Rosa lo traduce: «abuelo».","step":"skill"},"a1u04d5.c1":{"id":"a1u04d5.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis cuenta las sillas del patio: ^tres^.\nLuis: Oĩ (   ).","options":["mbohapy apyka","mbohapy apykakuéra","mbohapykuéra apyka"],"answer":1,"why":["Tres sillas: mbohapy apyka. El número va delante, y apyka queda en singular, porque el número ya dice cuántas son.","Apykakuéra es «las sillas», sin número. Con mbohapy delante, el plural -kuéra sobra.","-kuéra es el plural del sustantivo, no del número: mbohapy no lo lleva."],"step":"compare"},"a1u04d5.d1":{"id":"a1u04d5.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa tiene ^dos^ hijos.)\nAna: Mboýpa ne memby, Rosa?\nRosa: Areko (   ) memby.","options":["mbohapy","mokõi","peteĩ","po"],"answer":2,"why":["Mbohapy es «tres», y Rosa tiene dos hijos.","Rosa tiene dos hijos: mokõi memby. El número va delante de memby, que queda en singular.","Peteĩ es «uno», y son dos.","Po es «cinco». Y acordate: también es «mano»."],"step":"drill"},"a1u04d5.d2":{"id":"a1u04d5.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana cuenta las gallinas del patio: ^cinco^.)\nAna: Oĩ (   ) ryguasu korapýpe.","options":["irundy","mbohapy","po","pa"],"answer":3,"why":["Irundy es «cuatro»: una menos.","Mbohapy es «tres».","Cinco gallinas: po ryguasu. Po va delante, y ryguasu queda en singular.","Pa es «diez», el numeral de la escuela. Ana cuenta cinco."],"step":"drill"},"a1u04d5.d3":{"id":"a1u04d5.d3","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(El chipá cuesta ^dos mil^ guaraníes.)\nRosa: Mboýpa ovale ko chipa?\nVendedor: (   )","options":["Mokõi chipa.","Pa mil.","Héẽ.","Dos mil."],"answer":4,"why":["Mokõi chipa es «dos chipás»: dice cuántos hay, no cuánto cuestan.","Pa mil mezcla los dos sistemas, y además pa es «diez», no «dos». El precio se dice entero en castellano.","Héẽ, «sí», contesta preguntas de sí o no. Mboýpa pide una cantidad.","El precio se dice en castellano: dos mil. Mboýpa ovale? pregunta cuánto cuesta."],"step":"drill"},"a1u04d5.d4":{"id":"a1u04d5.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa habla de ^sus dos hijos^.\nRosa: Areko mokõi (   ).","options":["membykuéra","memby","ra'y","membynguéra"],"answer":2,"why":["Membykuéra es «hijos», en plural, pero detrás de mokõi el sustantivo va sin -kuéra: el número ya dice que son dos.","Detrás del número, memby queda en singular: mokõi memby, «dos hijos». Lo dice la mamá.","Ra'y es «hijo» cuando lo dice el papá. Rosa es la mamá: memby.","Membynguéra falla dos veces: lleva el plural, que no va tras el número, y usa la forma de después de una sílaba nasal, cuando by es oral."],"step":"drill"},"a1u04d5.d5":{"id":"a1u04d5.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Ana: Mboy ","after":" rereko, Luis?","tiles":["ary","pa"],"bank":[1,0],"hint":"-pa va pegado a ary y no se lleva el acento: fijate qué pasa con la tilde.","full":"Ana: Mboy arý{pa} rereko, Luis?","es":"Ana: ¿Cuántos años tenés, Luis?","explain":"ary («año») + -pa (pregunta) = arýpa. -pa no se lleva el acento: queda en la y de ary, que ya no es la última vocal, y por eso se escribe la tilde: ý. Mboy arýpa rereko?: ¿cuántos años tenés?","step":"drill"},"a1u04d5.d6":{"id":"a1u04d5.d6","kind":"build","area":"grammar","label":"Armá la oración","join":"sentence","before":"Rosa:","after":" kesu?\nVendedor: Diez mil.","tiles":["mboýpa","ovale","ko"],"bank":[1,2,0],"hint":"Empezá por la palabra que pregunta. Ko va pegado a kesu, como en ko ka'aru.","full":"Rosa: {Mboýpa} ovale ko kesu?\nVendedor: Diez mil.","es":"Rosa: ¿Cuánto cuesta este queso?\nVendedor: Diez mil.","explain":"Mboýpa, «¿cuánto?», va primero: es la palabra que pregunta, como Mba'éichapa en Mba'éichapa nde réra?. Después el verbo, ovale, «cuesta», y al final ko kesu, «este queso», con ko delante del sustantivo, como el día 3. El vendedor contesta el precio entero en castellano: diez mil. La moneda de Paraguay se llama guaraní, como la lengua: el precio va en guaraníes.","step":"drill"},"a1u04d5.e1":{"id":"a1u04d5.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: _Areko mbohapy memby._","options":["Tengo dos hijos.","Tengo tres años.","Tengo muchos hijos.","Tengo tres hijos."],"answer":4,"explain":"Areko es «tengo», mbohapy, «tres», y memby, «hijo» o «hija» cuando lo dice la mamá: «tengo tres hijos». Dos sería mokõi, y «tres años» llevaría ary: mbohapy ary. Mbohapy es un número exacto, no «muchos».","step":"exam"},"a1u04d5.e2":{"id":"a1u04d5.e2","kind":"choice","area":"grammar","label":"Elegí la respuesta","q":"(En la despensa.)\nAna: Mboýpa ovale ko so'o?\nVendedor: (   )","options":["Pa.","Mokõi so'o.","Veinte mil.","Oĩ so'o."],"answer":3,"explain":"Mboýpa ovale? pregunta el precio, y el precio se dice en castellano y entero: veinte mil. Pa es «diez» en guaraní, el numeral de la escuela, y no es un precio; mokõi so'o, «dos» de carne, dice una cantidad, no un precio; y Oĩ so'o, «hay carne», contesta Oĩpa so'o?, no cuánto cuesta.","step":"exam"},"a1u04d5.e3":{"id":"a1u04d5.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Juan le pregunta a Rosa por el hijo de ella.)\nJuan: Mboy ","after":" oguereko ne memby?","tiles":["ary","pa"],"bank":[1,0],"full":"(Juan le pregunta a Rosa por el hijo de ella.)\nJuan: Mboy arýpa oguereko ne memby?","es":"Juan: ¿Cuántos años tiene tu hijo?","explain":"ary («año») + -pa (pregunta) = arýpa. -pa no se lleva el acento: queda en la y de ary, que ya no es la última vocal, y se escribe la tilde. Oguereko es «tiene», y ne memby, «tu hijo»: ¿cuántos años tiene tu hijo?","step":"exam"},"a1u04d5.k1":{"id":"a1u04d5.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa lleva _dos_ chipás. ¿Cómo se escribe «dos» en guaraní?","options":["mocõi","mokoi","mokõi","mokõĩ"],"answer":3,"explain":"Dos es mokõi: con k, porque en guaraní no hay c, y con la õ nasal. Mocõi usa la c del castellano. Mokoi pierde la tilde nasal, y la o de mokõi es nasal. Mokõĩ marca también la i: en mokõi la tilde nasal va solo en la õ, la vocal del acento, y la i va sin marca.","step":"words"},"a1u04d5.r1":{"id":"a1u04d5.r1","kind":"choice","area":"listening","label":"Qué escuchaste","q":"¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?","options":["Tres, y el queso cuesta diez mil.","Dos, y el queso cuesta diez mil.","Dos, y el queso cuesta veinte mil."],"short":["Tres, diez mil","Dos, diez mil","Dos, veinte mil"],"printed":true,"answer":2,"why":["Rosa pide mokõi kesu, «dos quesos», no mbohapy, «tres». El precio sí es diez mil.","Rosa pregunta el precio, Mboýpa ovale?, y el vendedor dice diez mil. Después ella pide mokõi kesu, «dos quesos».","Dos quesos sí, pero el vendedor dice diez mil, no veinte mil."],"script":["Narrador: En la despensa. ¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?","Mujer: Mba'éichapa? Oĩpa kesu?","Hombre: Héẽ, oĩ.","Mujer: Mboýpa ovale?","Hombre: Diez mil.","Mujer: Mokõi kesu, aguyje.","Narrador: ¿Cuántos quesos lleva Rosa y cuánto cuesta el queso?"],"step":"skill"},"a1u04d6.c1":{"id":"a1u04d6.c1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa pregunta por ^el muchacho de la foto^.\nRosa: (   ) amo karia'y?\nJuan: ^Che ra'y.^","options":["Mba'épa","Mávapa","Moõpa"],"answer":2,"why":["Mba'épa pregunta por una cosa: Mba'épa amo karia'y? sería «¿qué es aquel muchacho?». Juan responde con una persona.","Rosa pregunta por una persona, el muchacho: Mávapa amo karia'y?, «¿quién es aquel muchacho?». Juan responde Che ra'y, «mi hijo».","Moõpa pregunta «¿dónde?», por un lugar. Juan no dice un lugar: dice quién es."],"step":"compare"},"a1u04d6.d1":{"id":"a1u04d6.d1","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis le pregunta a Juan cómo se llama ^la esposa de él^.\nLuis: Mba'éichapa héra (   ) rembireko, Juan?","options":["nde","che","ne","ñande"],"answer":3,"why":["Nde es «tu», pero rembireko es una palabra nasal: tiene mb (re-mbi-re-ko). Delante de una palabra nasal, nde pierde la d: ne rembireko.","Che es «mi»: Luis preguntaría por su propia esposa, y pregunta por la de Juan.","Luis le pregunta a Juan por la esposa de él, «tu esposa». Rembireko tiene mb, una letra nasal, así que nde se vuelve ne: ne rembireko.","Ñande es «nuestro» con vos: sumaría a Luis. Y delante de una palabra nasal sería ñane."],"step":"drill"},"a1u04d6.d2":{"id":"a1u04d6.d2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Rosa habla de ^las gallinas^ del patio.\nRosa: (   ) oĩ korapýpe.","options":["Ryguasunguéra","Riguasukuéra","Ryguasucuéra","Ryguasukuéra"],"answer":4,"why":["-nguéra va solo tras una sílaba nasal, y ryguasu termina en su, una sílaba oral.","Riguasukuéra cambia la y por i. La primera sílaba de ry-gua-su lleva la y, la sexta vocal.","Ryguasucuéra escribe el plural con c, y la c no es una letra del guaraní: ese sonido se escribe con k, kuéra.","Ryguasu termina en su, sílaba oral: va -kuéra, que se lleva el acento. Ryguasukuéra oĩ korapýpe: las gallinas están en el patio."],"step":"drill"},"a1u04d6.d3":{"id":"a1u04d6.d3","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Juan y Rosa están en la puerta. Juan señala ^un caballo al fondo del patio, lejos de los dos^.)\nJuan: (   ) kavaju ituicha.","options":["Amo","Ko","Pe","Umi"],"answer":1,"why":["El caballo está lejos de los dos, pero a la vista: amo kavaju, «aquel caballo». Amo kavaju ituicha: aquel caballo es grande.","Ko es «este», para algo cerca de Juan, el que habla. El caballo está al fondo del patio.","Pe es «ese», para algo cerca de Rosa, la que escucha. El caballo está lejos de los dos.","Umi es para varios, «esos» o «aquellos». Es un solo caballo."],"step":"drill"},"a1u04d6.d4":{"id":"a1u04d6.d4","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis cuenta ^a los chicos^ del patio: son ^cuatro^.\nLuis: Oĩ irundy (   ).","options":["mitãnguéra","mitã","mitãkuéra","mitakuéra"],"answer":2,"why":["Mitãnguéra es «los niños», el plural de mitã, pero después de un número el sustantivo va solo: irundy ya dice que son cuatro.","Después del número, el sustantivo va en singular: irundy mitã, «cuatro chicos». El número ya dice cuántos son.","Mitãkuéra usa la forma de después de una sílaba oral, y mitã termina en ã, nasal. Y después de un número no va plural.","Mitakuéra pierde la ~ de mitã, que la palabra sí lleva, y además pone un plural después del número."],"step":"drill"},"a1u04d6.d5":{"id":"a1u04d6.d5","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Che sy oñe'ẽ ","after":".","tiles":["mitã","nguéra","pe"],"bank":[2,1,0],"hint":"Primero el plural, que se lleva el acento, y al final -pe, «a».","full":"Che sy oñe'ẽ mitã{nguéra}pe.","es":"Mi mamá les habla a los niños.","explain":"mitã («niño») + -nguéra (plural tras nasal, porque mitã termina en ã) + -pe («a») = mitãnguérape. -nguéra se lleva el acento, y -pe no lo mueve: la ~ queda en la ã y la tilde en la é. Después de -nguéra va -pe, porque ra es una sílaba oral.","step":"drill"},"a1u04d6.d6":{"id":"a1u04d6.d6","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"","after":" oĩ korapýpe?","tiles":["mba'e","pa"],"bank":[1,0],"hint":"-pa va al final y no se lleva el acento: mirá dónde aparece la tilde.","full":"{Mba'épa} oĩ korapýpe?","es":"¿Qué hay en el patio?","explain":"mba'e («qué») + -pa (pregunta) = Mba'épa. -pa no se lleva el acento: queda en la e de mba'e, que ya no es la última vocal, y por eso se escribe la tilde. Mba'épa oĩ korapýpe?: ¿qué hay en el patio?","step":"drill"},"a1u04d6.e1":{"id":"a1u04d6.e1","kind":"choice","area":"grammar","label":"Qué significa","q":"Rosa: _Ne membykuéra moõpa oĩ?_","options":["¿Dónde están tus hijos?","¿Dónde está tu hijo?","¿Quiénes son tus hijos?","¿Dónde están mis hijos?"],"answer":1,"explain":"Ne es «tu» delante de una palabra nasal, y -kuéra hace el plural: ne membykuéra, «tus hijos». Moõpa es «¿dónde?» y oĩ, «están». Un solo hijo sería ne memby, «mis» sería che, y «quiénes» se pregunta con mávapa.","step":"exam"},"a1u04d6.e2":{"id":"a1u04d6.e2","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Ana tiene dos chipá en la mano y se los muestra a Luis.)\nAna: (   ) chipa iporã.","options":["Umi","Ko","Pe","Ko'ã"],"answer":4,"explain":"Son dos chipá y los tiene Ana, la que habla: ko'ã chipa, «estos chipá». Ko'ã es el ko de varios. Umi es para varios pero lejos de quien habla; ko y pe son para uno solo, y pe, además, para algo cerca del que escucha.","step":"exam"},"a1u04d6.e3":{"id":"a1u04d6.e3","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"Mboy ","after":" rereko?","tiles":["ary","pa"],"bank":[1,0],"full":"Mboy arýpa rereko?","es":"¿Cuántos años tenés?","explain":"ary («año») + -pa (pregunta) = arýpa. -pa se pega a la última palabra de lo que se pregunta, mboy ary, «cuántos años», y no se lleva el acento: queda en la y de ary, que ya no es la última vocal, y por eso se escribe la tilde. Rereko es «tenés»: Mboy arýpa rereko?, ¿cuántos años tenés?","step":"exam"},"a1u04d6.k1":{"id":"a1u04d6.k1","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Ana saluda a _los padres_ de los chicos: Maitei, (   ). ¿Cómo se escribe en guaraní?","options":["tuvanguéra","tuvacuéra","tuvakuéra","tubakuéra"],"answer":3,"explain":"«Los padres» es tuvakuéra: túva, «padre», más -kuéra, que se lleva el acento, así que la tilde de túva desaparece. Va es una sílaba oral: por eso -kuéra y no -nguéra. Tuvacuéra escribe el plural con c, que no es una letra del guaraní: ese sonido se escribe con k. Tubakuéra escribe con b, que sola tampoco es una letra del guaraní: acá va v.","step":"words"},"a1u04d6.r1":{"id":"a1u04d6.r1","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Cuántos hijos de Rosa hay en la foto?","options":["Uno.","Dos.","Cuatro.","No lo dice."],"short":["Uno","Dos","Cuatro","No lo dice"],"answer":2,"why":["Un solo hijo sería che memby. Rosa escribe che membykuéra, con -kuéra: más de uno, y da dos nombres.","Ko'ã mitã che membykuéra: Sofía ha Tomás, «estos chicos son mis hijos: Sofía y Tomás». En la foto hay dos hijos de Rosa.","En la foto hay cuatro chicos, pero las dos nenas, umi mokõi mitãkuña, son che angirũ memby: las hijas de la amiga de Rosa, no de Rosa.","Sí lo dice: después de che membykuéra, «mis hijos», vienen los nombres, Sofía ha Tomás."],"explain":"Rosa escribe Ko'ã mitã che membykuéra: Sofía ha Tomás, «estos chicos son mis hijos: Sofía y Tomás»: en la foto hay dos hijos de Rosa. Las otras dos, umi mokõi mitãkuña, son che angirũ memby: las hijas de su amiga.","step":"skill"},"a1u04t.1":{"id":"a1u04t.1","kind":"choice","area":"vocab","label":"Qué significa","q":"(Rosa le muestra a Juan una foto.)\nRosa: Ha'e _che jarýi_.","options":["mi mamá","mi abuela","mi hija","tu abuela"],"answer":2,"explain":"Che es «mi» y jarýi, «abuela»: Ha'e che jarýi, «ella es mi abuela». Mi mamá sería che sy; mi hija, che memby si lo dice la mamá o che rajy si lo dice el papá; y tu abuela, nde jarýi.","step":"test","unit":4},"a1u04t.2":{"id":"a1u04t.2","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Rosa habla de los chicos del barrio: _los niños_ cantan en la escuela. ¿Cómo se escribe «los niños» en guaraní?","options":["mitãkuéra","mitakuéra","mitãnguéra","mitãnguẽra"],"answer":3,"explain":"Mitã termina en ã, sílaba nasal: el plural es -nguéra, que se lleva el acento. Mitãkuéra usa la forma de después de una sílaba oral. Mitakuéra además pierde la ~ de mitã, que la palabra sí lleva. Mitãnguẽra pone una ~ en la e, y esa e es oral: lleva la tilde de acento, é.","step":"test","unit":4},"a1u04t.3":{"id":"a1u04t.3","kind":"choice","area":"vocab","label":"Qué significa","q":"(En el patio.)\nJuan: Amo _kavaju_ ituicha.","options":["caballo","vaca","perro","gallina"],"answer":1,"explain":"Kavaju es «caballo», del castellano y escrito a la guaraní: la c se escribe k y la ll se escribe j. Amo kavaju ituicha: aquel caballo es grande. Vaca es vaka, perro es jagua y gallina, ryguasu.","step":"test","unit":4},"a1u04t.4":{"id":"a1u04t.4","kind":"choice","area":"vocab","label":"Elegí la palabra","q":"(Rosa, la mamá, le muestra a Juan una foto de su hija.)\nRosa: Che (   ).","options":["ra'y","rajy","ru","memby"],"answer":4,"explain":"Rosa es la mamá, y la mamá dice che memby de su hijo o de su hija. Ra'y, «hijo», y rajy, «hija», las dice el papá. Che ru es «mi papá», y en la foto está su hija.","step":"test","unit":4},"a1u04t.5":{"id":"a1u04t.5","kind":"choice","area":"vocab","label":"Cómo se escribe","q":"Luis pregunta qué significa una palabra: (   ) he'ise «mymba»? ¿Cómo se escribe «qué»?","options":["Mba'ẽpa","Mba'épa","Mbaépa","Mba'épã"],"answer":2,"explain":"«¿Qué?» es Mba'épa: mba'e lleva el puso entre la a y la e, y con -pa esa e deja de ser la última vocal, así que se escribe la tilde de acento, é. Mba'ẽpa pone una ~ en la e, y esa e es oral. Mbaépa pierde el puso. Mba'épã agrega una ~ a la a de -pa, que se escribe siempre igual, sin ~.","step":"test","unit":4},"a1u04t.6":{"id":"a1u04t.6","kind":"choice","area":"vocab","label":"Qué significa","q":"(Luis cuenta las sillas del patio.)\nLuis: Oĩ _irundy_ apyka.","options":["tres","cinco","cuatro","dos"],"answer":3,"explain":"Irundy es «cuatro»: Oĩ irundy apyka, «hay cuatro sillas». Tres es mbohapy, cinco es po y dos, mokõi. Después del número, apyka queda en singular.","step":"test","unit":4},"a1u04t.7":{"id":"a1u04t.7","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Juan: Mba'éichapa héra (   ) ramói, Rosa?","options":["che","nde","ne","héra"],"answer":3,"explain":"Juan le pregunta a Rosa por el abuelo de ella: «tu abuelo». Ramói es una palabra nasal, con m, y delante de ella nde pierde la d: ne ramói. Che sería «mi», el abuelo de Juan. Nde queda igual solo ante una palabra oral, como nde sy. Y héra ya está en la pregunta: es «su nombre», no un posesivo.","step":"test","unit":4},"a1u04t.8":{"id":"a1u04t.8","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(En la despensa.)\nVendedor: (   ) reipota?\nAna: Kamby ha kesu.","options":["Mba'épa","Mávapa","Mba'éichapa","Mboýpa"],"answer":1,"explain":"Ana responde con dos cosas: kamby ha kesu, «leche y queso». El vendedor le preguntó qué quiere: Mba'épa reipota? Mávapa pregunta por una persona, mba'éichapa pregunta cómo y mboýpa, cuánto.","step":"test","unit":4},"a1u04t.9":{"id":"a1u04t.9","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa señala un árbol lejos, al final de la calle.)\nRosa: (   ) yvyra ituicha.","options":["Ko","Amo","Pe","Ko'ã"],"answer":2,"explain":"El árbol está lejos de los dos, pero a la vista: amo yvyra, «aquel árbol». Ko es «este», para algo cerca de Rosa, la que habla; pe es «ese», para algo cerca del que escucha; y ko'ã es «estos», para varios y cerca de quien habla.","step":"test","unit":4},"a1u04t.10":{"id":"a1u04t.10","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Luis toca dos sillas que tiene al lado. Al fondo del patio hay otras.)\nLuis: (   ) apyka iporã.","options":["Ko","Umi","Pe","Ko'ã"],"answer":4,"explain":"Son dos sillas y Luis las toca: están al lado del que habla. Por eso va ko'ã apyka, «estas sillas». Ko y pe son para una sola cosa. Umi es para varias, pero lejos de quien habla: «esas» o «aquellas», como las del fondo. El sustantivo puede quedar como está: ko'ã ya dice que son varias.","step":"test","unit":4},"a1u04t.11":{"id":"a1u04t.11","kind":"choice","area":"grammar","label":"Elegí la forma","q":"Luis: (   ) pe karia'y?\nAna: Che memby.","options":["Mávapa","Mba'épa","Moõpa","Mboýpa"],"answer":1,"explain":"Ana responde con una persona, che memby, «mi hijo»: Luis preguntó quién es ese muchacho, Mávapa pe karia'y? Mba'épa pregunta por una cosa, moõpa por un lugar y mboýpa por una cantidad.","step":"test","unit":4},"a1u04t.12":{"id":"a1u04t.12","kind":"choice","area":"grammar","label":"Elegí la forma","q":"(Rosa habla de su hija, que tiene cinco años.)\nRosa: Che memby oguereko po (   ).","options":["arykuéra","arynguéra","ary","arýpa"],"answer":3,"explain":"Ary es «año»: oguereko po ary, «tiene cinco años». Después de un número el sustantivo va sin plural: no van arykuéra ni arynguéra. Arynguéra, además, usa la forma de después de una sílaba nasal, y ry es oral. Arýpa lleva la -pa de pregunta, y Rosa no pregunta: cuenta.","step":"test","unit":4},"a1u04t.13":{"id":"a1u04t.13","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Ana le escribe a la escuela de sus hijos.)\nAna: Aguyje ","after":".","tiles":["mbo'ehára","kuéra","pe"],"bank":[2,0,1],"full":"(Ana le escribe a la escuela de sus hijos.)\nAna: Aguyje mbo'eharakuérape.","es":"Ana: Gracias a los profesores.","explain":"mbo'ehára, kuéra, pe. Mbo'ehára («profesor») + -kuéra (plural, porque ra es una sílaba oral) + -pe («a») = mbo'eharakuérape, «a los profesores». -kuéra se lleva el acento y la tilde de hára desaparece: una palabra, una sola tilde. -pe va al final y no lo mueve: la tilde queda en la é. Es como Aguyje ndéve, «gracias a vos», pero con un sustantivo y -pe.","step":"test","unit":4},"a1u04t.14":{"id":"a1u04t.14","kind":"build","area":"grammar","label":"Armá la palabra","join":"word","before":"(Luis le pregunta a Ana por el papá de ella.)\nLuis: Mboy ","after":" oguereko nde ru?","tiles":["ary","pa"],"bank":[1,0],"full":"(Luis le pregunta a Ana por el papá de ella.)\nLuis: Mboy arýpa oguereko nde ru?","es":"Luis: ¿Cuántos años tiene tu papá?","explain":"ary, pa. Ary («año») + -pa (pregunta) = arýpa. -pa no se lleva el acento: queda en la y de ary, que ya no es la última vocal, y por eso se escribe la tilde, ý. Oguereko es «tiene», y nde ru, «tu papá»: ru es oral, así que nde no cambia.","step":"test","unit":4},"a1u04t.15":{"id":"a1u04t.15","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Quiénes son Lucía y Mateo?","passage":"Ana: Mba'éichapa, Luis? Ko'ã mitã che membykuéra, Lucía ha Mateo.\nLuis: Iporã. Ha pe karai?\nAna: Che ru, héra Carlos. Oguereko 60 ary.\nLuis: Mboýpa ne memby?\nAna: Mokõi.","options":["Los papás de Ana.","Los hijos de Ana.","Los hijos de Luis.","Los abuelos de Ana."],"short":["Sus papás","Sus hijos","Hijos de Luis","Sus abuelos"],"answer":2,"explain":"Ana escribe Ko'ã mitã che membykuéra, Lucía ha Mateo: «estos chicos son mis hijos, Lucía y Mateo». Che es «mi» y membykuéra, «hijos», en plural. Lo dice Ana, no Luis. El papá de Ana es Carlos, y de abuelos no habla.","step":"test","unit":4},"a1u04t.16":{"id":"a1u04t.16","kind":"choice","area":"reading","label":"Buscar el dato","q":"¿Cuántos años tiene el papá de Ana?","passage":"Ana: Mba'éichapa, Luis? Ko'ã mitã che membykuéra, Lucía ha Mateo.\nLuis: Iporã. Ha pe karai?\nAna: Che ru, héra Carlos. Oguereko 60 ary.\nLuis: Mboýpa ne memby?\nAna: Mokõi.","options":["Veinte.","Dos.","Seis.","Sesenta."],"short":["Veinte","Dos","Seis","Sesenta"],"answer":4,"explain":"Luis pregunta Ha pe karai?, «¿y ese señor?», y Ana responde Che ru, héra Carlos. Oguereko 60 ary: «mi papá, se llama Carlos. Tiene 60 años». Oguereko es «tiene» y ary, «año»; la edad está escrita en cifras: 60, sesenta. Mokõi, «dos», es la cantidad de hijos de Ana, no una edad. Y en el chat no hay ningún seis ni ningún veinte.","step":"test","unit":4},"a1u04t.17":{"id":"a1u04t.17","kind":"choice","area":"reading","label":"Texto corto","q":"¿Qué le pregunta Luis a Ana al final?","passage":"Ana: Mba'éichapa, Luis? Ko'ã mitã che membykuéra, Lucía ha Mateo.\nLuis: Iporã. Ha pe karai?\nAna: Che ru, héra Carlos. Oguereko 60 ary.\nLuis: Mboýpa ne memby?\nAna: Mokõi.","options":["Cuántos hijos tiene.","Cómo se llama su papá.","Dónde vive.","Cuántos años tiene."],"short":["Cuántos hijos","El nombre del papá","Dónde vive","Cuántos años"],"answer":1,"explain":"Al final Luis pregunta Mboýpa ne memby?, «¿cuántos hijos tenés?», y Ana responde Mokõi, «dos». El nombre del papá y su edad los dice Ana sin que Luis los pregunte, y nadie pregunta dónde vive.","step":"test","unit":4},"a1u04t.18":{"id":"a1u04t.18","kind":"choice","area":"listening","label":"Respuesta rápida","q":"Juan: Mávapa pe kuña?\n¿Qué le responde Rosa?","options":["Che róga.","Mokõi.","Che sy."],"answer":3,"explain":"Mávapa pe kuña? pregunta quién es esa mujer, y se responde con una persona: Che sy, «mi mamá». Che róga es «mi casa», una cosa, y Mokõi, «dos», es una cantidad: respondería a Mboýpa?","step":"test","unit":4},"a1u04t.19":{"id":"a1u04t.19","kind":"choice","area":"listening","label":"Respuesta rápida","q":"(En la despensa.)\nAna: Mboýpa ovale ko kamby?\n¿Qué le responde el vendedor?","options":["Cinco mil.","Po mil.","Héẽ."],"answer":1,"explain":"Mboýpa ovale? pregunta el precio, y en la charla el precio se dice entero en castellano: cinco mil. Po mil mezcla los dos sistemas en una misma cifra: po es «cinco» en guaraní, pero cinco mil se dice cinco mil. Héẽ, «sí», responde preguntas de sí o no, como Oĩpa kamby?","step":"test","unit":4},"a1u04t.20":{"id":"a1u04t.20","kind":"choice","area":"listening","label":"Respuesta rápida","q":"Luis: Mba'éichapa héra ne memby?\n¿Qué le responde Rosa?","options":["Che réra Rosa.","Héra Tomás.","Mokõi memby."],"answer":2,"explain":"Luis pregunta el nombre del hijo de Rosa, ne memby, y ella dice el nombre de él: Héra Tomás, «se llama Tomás». Che réra Rosa sería el nombre de ella misma, y Mokõi memby, «dos hijos», responde cuántos son, no cómo se llama.","step":"test","unit":4}}};
